/**
 * Org-Scoped Route Component
 * 
 * Wrapper component that resolves org from URL slug and provides org context
 * to child routes. Handles redirects, error states, and org context injection.
 */

import { useEffect, useState } from 'react'
import { useParams, Navigate, useLocation } from 'react-router-dom'
import { resolveOrgFromSlug, type OrgContext } from '../utils/orgResolution'
import { usePublicOrgTheme } from '../hooks/usePublicOrgTheme'
import { getLink, RouteKeys } from '@/utils/routes'

interface OrgScopedRouteProps {
  children: (org: OrgContext) => React.ReactNode
  fallback?: React.ReactNode
}

function PublicThemeApplicator({ orgId, children }: { orgId: string, children: React.ReactNode }) {
  usePublicOrgTheme(orgId)
  return <>{children}</>
}

export function OrgScopedRoute({ children, fallback }: OrgScopedRouteProps) {
  const { orgSlug } = useParams<{ orgSlug: string }>()
  const location = useLocation()
  const [org, setOrg] = useState<OrgContext | null>(null)
  const [redirectToSlug, setRedirectToSlug] = useState<string | null>(null)
  const [error, setError] = useState<'not_found' | 'suspended' | 'deactivated' | 'deleted' | null>(null)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!orgSlug) {
      setError('not_found')
      setLoading(false)
      return
    }

    let cancelled = false

    async function resolveOrg() {
      setLoading(true)
      const result = await resolveOrgFromSlug(orgSlug || '')

      if (cancelled) return

      setOrg(result.org)
      setRedirectToSlug(result.redirectToSlug)
      setError(result.error)
      setLoading(false)
    }

    resolveOrg()

    return () => {
      cancelled = true
    }
  }, [orgSlug])

  // Handle redirects (old slug -> new slug)
  if (redirectToSlug && orgSlug) {
    const oldBase = getLink(RouteKeys.PORTAL_ORG_LANDING, { orgSlug })
    const newBase = getLink(RouteKeys.PORTAL_ORG_LANDING, { orgSlug: redirectToSlug })
    const newPath = location.pathname.replace(oldBase, newBase)
    return <Navigate to={newPath + location.search} replace />
  }

  // Handle error states
  if (error) {
    if (error === 'not_found' || error === 'deleted') {
      return (
        <div className="min-h-screen bg-[#f6f7f8] dark:bg-[#101922] flex items-center justify-center">
          <div className="text-center max-w-md px-6">
            <h1 className="text-3xl font-black text-[#111418] dark:text-white mb-4">Organization Not Found</h1>
            <p className="text-[#617589] dark:text-gray-400">
              The organization you're looking for doesn't exist or has been removed.
            </p>
          </div>
        </div>
      )
    }

    if (error === 'suspended') {
      return (
        <div className="min-h-screen bg-[#f6f7f8] dark:bg-[#101922] flex items-center justify-center">
          <div className="text-center max-w-md px-6">
            <h1 className="text-3xl font-black text-[#111418] dark:text-white mb-4">Organization Temporarily Unavailable</h1>
            <p className="text-[#617589] dark:text-gray-400 mb-4">
              This organization's public pages are temporarily unavailable.
            </p>
            <p className="text-sm text-[#617589] dark:text-gray-500">
              If you believe this is an error, please contact support.
            </p>
          </div>
        </div>
      )
    }

    if (error === 'deactivated') {
      return (
        <div className="min-h-screen bg-[#f6f7f8] dark:bg-[#101922] flex items-center justify-center">
          <div className="text-center max-w-md px-6">
            <h1 className="text-3xl font-black text-[#111418] dark:text-white mb-4">Organization No Longer Active</h1>
            <p className="text-[#617589] dark:text-gray-400">
              This organization is no longer active on the platform.
            </p>
          </div>
        </div>
      )
    }
  }

  // Loading state
  if (loading || !org) {
    return (
      fallback || (
        <div className="min-h-screen bg-[#f6f7f8] dark:bg-[#101922] flex items-center justify-center">
          <div className="text-center">
            <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-[#137fec]"></div>
            <p className="mt-4 text-[#617589] dark:text-gray-400">Loading...</p>
          </div>
        </div>
      )
    )
  }

  // Render children with org context
  return (
    <PublicThemeApplicator orgId={org.id}>
      {children(org)}
    </PublicThemeApplicator>
  )
}

/**
 * Hook to get org context from route params
 * Must be used within OrgScopedRoute
 */
export function useOrgContext(): OrgContext {
  const { orgSlug } = useParams<{ orgSlug: string }>()
  if (!orgSlug) {
    throw new Error('useOrgContext must be used within an OrgScopedRoute')
  }
  // The org context is provided by OrgScopedRoute, but we need to resolve it
  // For now, components should receive org as a prop from OrgScopedRoute
  throw new Error('useOrgContext: Org context should be passed as prop from OrgScopedRoute')
}

/**
 * Add Existing Athlete Modal
 * 
 * Modal for adding existing athletes to a team with search and filter capabilities.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { useUserContext } from '../../hooks/useUserContext'
import { searchAthletes } from '../../data/services/familyService'
import { addAthletesToTeam } from '../../data/services/teamsService'
import type {
  AddExistingAthleteModalProps,
  FilterState,
  AthleteWithTeams
} from '../../types/athletes'
import { Input, EmptyState } from '../platformAdmin'
import { OrgAdminButton } from './OrgAdminButton'

/**
 * Debounce utility function
 */
function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): ((...args: Parameters<T>) => void) & { cancel: () => void } {
  let timeout: NodeJS.Timeout | null = null

  const debounced = function executedFunction(...args: Parameters<T>) {
    const later = () => {
      timeout = null
      func(...args)
    }

    if (timeout) {
      clearTimeout(timeout)
    }
    timeout = setTimeout(later, wait)
  }

  debounced.cancel = () => {
    if (timeout) {
      clearTimeout(timeout)
      timeout = null
    }
  }

  return debounced
}

export function AddExistingAthleteModal({
  open,
  onClose,
  teamId,
  seasonId,
  onSuccess,
}: AddExistingAthleteModalProps) {
  const { context, isReady } = useUserContext()

  // State declarations (compile-clean)
  const [filters, setFilters] = useState<FilterState>({ search: '' })
  const [athletes, setAthletes] = useState<AthleteWithTeams[]>([])
  const [selectedAthletes, setSelectedAthletes] = useState<Set<string>>(new Set())
  const [loading, setLoading] = useState<boolean>(false)
  const [error, setError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState<boolean>(false)

  // Refs (compile-clean)
  const isMountedRef = useRef<boolean>(true)
  const abortControllerRef = useRef<AbortController | null>(null)
  const requestIdRef = useRef<number>(0)
  const selectedAthletesRef = useRef<Set<string>>(new Set())
  const debouncedSearchRef = useRef<ReturnType<typeof debounce> | null>(null)

  // Initial filter state
  const initialFilters: FilterState = { search: '' }

  // Setup cleanup effect (Bug #1 solution)
  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
        abortControllerRef.current = null
      }
      if (debouncedSearchRef.current) {
        debouncedSearchRef.current.cancel()
      }
    }
  }, [])

  // Reset state when modal closes (Bug #7 solution)
  useEffect(() => {
    if (!open) {
      setFilters(initialFilters)
      setSelectedAthletes(new Set<string>())
      selectedAthletesRef.current = new Set<string>()
      setError(null)
      setLoading(false)
      setSubmitting(false)
      setAthletes([])
    }
  }, [open])

  // Fetch athletes with request ID tracking (Bug #2 solution)
  const fetchAthletes = useCallback(async (currentFilters: FilterState): Promise<void> => {
    if (!isReady || !context.orgId) return

    const currentRequestId = ++requestIdRef.current

    // Abort previous request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort()
    }

    const controller = new AbortController()
    abortControllerRef.current = controller

    // Only search if search term is at least 2 characters (Issue #8 solution)
    if (currentFilters.search && currentFilters.search.length < 2) {
      if (isMountedRef.current && currentRequestId === requestIdRef.current) {
        setAthletes([])
        setLoading(false)
        setError(null)
      }
      return
    }

    if (isMountedRef.current && currentRequestId === requestIdRef.current) {
      setLoading(true)
      setError(null)
    }

    try {
      const { data, error: searchError } = await searchAthletes(context, {
        search: currentFilters.search || undefined,
        ageMin: currentFilters.ageMin,
        ageMax: currentFilters.ageMax,
        levelId: currentFilters.levelId,
        programId: currentFilters.programId,
        excludeTeamId: teamId,
        excludeSeasonId: seasonId,
      })

      // Only update if this is still the latest request and component is mounted
      if (currentRequestId === requestIdRef.current && isMountedRef.current) {
        if (searchError) {
          setError(searchError.message)
          setAthletes([])
        } else {
          setAthletes(data || [])
          setError(null)
        }
        setLoading(false)
      }
    } catch (err) {
      if (currentRequestId === requestIdRef.current && isMountedRef.current) {
        setError(err instanceof Error ? err.message : 'Failed to search athletes')
        setAthletes([])
        setLoading(false)
      }
    }
  }, [context, isReady, teamId, seasonId])

  // Debounced search effect (Issue #8 solution)
  useEffect(() => {
    if (!open || !isReady) return

    // Cancel previous debounced call
    if (debouncedSearchRef.current) {
      debouncedSearchRef.current.cancel()
    }

    // Create new debounced function
    const debouncedFn = debounce(() => {
      fetchAthletes(filters)
    }, 350)

    debouncedSearchRef.current = debouncedFn

    // Trigger search
    debouncedFn()

    // Cleanup
    return () => {
      if (debouncedSearchRef.current) {
        debouncedSearchRef.current.cancel()
      }
    }
  }, [filters, open, isReady, fetchAthletes])

  // Handlers (Bug #3, #6 solution - useCallback with functional updates)
  const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>): void => {
    setFilters(prev => ({ ...prev, search: e.target.value }))
  }, [])

  const toggleSelection = useCallback((athleteId: string): void => {
    setSelectedAthletes(prev => {
      const next = new Set<string>(prev)
      if (next.has(athleteId)) {
        next.delete(athleteId)
      } else {
        next.add(athleteId)
      }
      selectedAthletesRef.current = next
      return next
    })
  }, [])

  const handleSelectAll = useCallback((): void => {
    setSelectedAthletes(() => {
      const next = new Set<string>(athletes.map(a => a.id))
      selectedAthletesRef.current = next
      return next
    })
  }, [athletes])

  const handleDeselectAll = useCallback((): void => {
    setSelectedAthletes(() => {
      const next = new Set<string>()
      selectedAthletesRef.current = next
      return next
    })
  }, [])

  const handleClearFilters = useCallback((): void => {
    setFilters(initialFilters)
  }, [])

  const handleSubmit = useCallback(async (): Promise<void> => {
    if (submitting) return // Bug #8 solution - early return guard

    const current = selectedAthletesRef.current
    if (current.size === 0) return

    setSubmitting(true)
    setError(null)

    try {
      const athleteIds = Array.from(current)
      const result = await addAthletesToTeam(context, teamId, seasonId, athleteIds)

      if (result.error) {
        setError(result.error.message)
        setSubmitting(false)
        return
      }

      if (result.data) {
        // Show success message
        const { added, skipped, errors } = result.data
        let message = `Successfully added ${added.length} athlete${added.length !== 1 ? 's' : ''} to the team.`
        if (skipped.length > 0) {
          message += ` ${skipped.length} athlete${skipped.length !== 1 ? 's were' : ' was'} already on the team.`
        }
        if (errors.length > 0) {
          message += ` ${errors.length} athlete${errors.length !== 1 ? 's' : ''} could not be added.`
        }

        // Close modal and refresh roster
        onSuccess()
        onClose()
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to add athletes to team')
    } finally {
      if (isMountedRef.current) {
        setSubmitting(false)
      }
    }
  }, [submitting, context, teamId, seasonId, onSuccess, onClose])

  if (!open) return null

  const selectedCount = selectedAthletes.size
  const hasActiveFilters = filters.search.length > 0 || 
    filters.ageMin !== undefined || 
    filters.ageMax !== undefined || 
    filters.levelId !== undefined || 
    filters.programId !== undefined

  return (
    <>
      {/* Backdrop */}
      <div
        onClick={onClose}
        style={{
          position: 'fixed',
          inset: 0,
          background: 'rgba(11, 15, 20, 0.5)',
          zIndex: 1000,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        {/* Dialog */}
        <div
          onClick={(e) => e.stopPropagation()}
          className="pa-card"
          style={{
            width: '100%',
            maxWidth: '800px',
            maxHeight: '90vh',
            margin: 'var(--pa-space-4)',
            padding: 0,
            display: 'flex',
            flexDirection: 'column',
          }}
        >
          {/* Header */}
          <div style={{ padding: 'var(--pa-space-5)', borderBottom: '1px solid var(--pa-n100)' }}>
            <h2 className="pa-h2" style={{ margin: 0 }}>
              Add Existing Athletes to Team
            </h2>
            <p className="pa-body-m" style={{ margin: 'var(--pa-space-2) 0 0 0', color: 'var(--pa-n700)' }}>
              Search and select athletes to add to this team
            </p>
          </div>

          {/* Content */}
          <div style={{ padding: 'var(--pa-space-5)', flex: 1, overflow: 'auto' }}>
            {/* Search Input */}
            <div style={{ marginBottom: 'var(--pa-space-4)' }}>
              <Input
                type="text"
                placeholder="Search by name (minimum 2 characters)..."
                value={filters.search}
                onChange={handleSearchChange}
                disabled={loading || submitting}
              />
            </div>

            {/* Error Message */}
            {error && (
              <div
                className="pa-card pa-mb-4"
                style={{
                  background: 'var(--pa-danger-bg)',
                  border: '1px solid var(--pa-danger)',
                  padding: 'var(--pa-space-3)',
                  marginBottom: 'var(--pa-space-4)',
                }}
              >
                <p className="pa-body-m" style={{ margin: 0, color: 'var(--pa-danger)' }}>
                  {error}
                </p>
              </div>
            )}

            {/* Loading State */}
            {loading && (
              <div style={{ textAlign: 'center', padding: 'var(--pa-space-6)' }}>
                <p className="pa-body-m" style={{ color: 'var(--pa-n500)' }}>
                  Searching athletes...
                </p>
              </div>
            )}

            {/* Athlete List */}
            {!loading && athletes.length > 0 && (
              <div style={{ marginBottom: 'var(--pa-space-4)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 'var(--pa-space-3)' }}>
                  <p className="pa-body-m" style={{ margin: 0, fontWeight: 700 }}>
                    {athletes.length} athlete{athletes.length !== 1 ? 's' : ''} found
                  </p>
                  <div style={{ display: 'flex', gap: 'var(--pa-space-2)' }}>
                    <OrgAdminButton
                      variant="secondary"
                      size="compact"
                      onClick={handleSelectAll}
                      disabled={submitting}
                    >
                      Select All
                    </OrgAdminButton>
                    <OrgAdminButton
                      variant="secondary"
                      size="compact"
                      onClick={handleDeselectAll}
                      disabled={submitting}
                    >
                      Deselect All
                    </OrgAdminButton>
                  </div>
                </div>

                <div
                  style={{
                    border: '1px solid var(--pa-n200)',
                    borderRadius: 'var(--pa-radius-m)',
                    maxHeight: '400px',
                    overflow: 'auto',
                  }}
                >
                  {athletes.map((athlete) => {
                    const isSelected = selectedAthletes.has(athlete.id)
                    const isDisabled = false // Could check if already on team

                    return (
                      <div
                        key={athlete.id}
                        style={{
                          padding: 'var(--pa-space-4)',
                          borderBottom: '1px solid var(--pa-n100)',
                          display: 'flex',
                          alignItems: 'center',
                          gap: 'var(--pa-space-3)',
                          cursor: isDisabled ? 'not-allowed' : 'pointer',
                          opacity: isDisabled ? 0.5 : 1,
                          background: isSelected ? 'var(--pa-n50)' : 'transparent',
                        }}
                        onClick={() => !isDisabled && toggleSelection(athlete.id)}
                      >
                        <input
                          type="checkbox"
                          checked={isSelected}
                          disabled={isDisabled || submitting}
                          onChange={() => !isDisabled && toggleSelection(athlete.id)}
                          onClick={(e) => e.stopPropagation()}
                        />
                        <div style={{ flex: 1 }}>
                          <p className="pa-body-m" style={{ margin: 0, fontWeight: 700 }}>
                            {athlete.first_name} {athlete.last_name}
                          </p>
                          <p className="pa-body-s" style={{ margin: 'var(--pa-space-1) 0 0 0', color: 'var(--pa-n500)' }}>
                            {athlete.age !== null ? `Age ${athlete.age}` : 'Age unknown'}
                            {athlete.currentTeams && athlete.currentTeams.length > 0 && (
                              <> • Current teams: {athlete.currentTeams.map(t => t.teamName).join(', ')}</>
                            )}
                          </p>
                        </div>
                      </div>
                    )
                  })}
                </div>
              </div>
            )}

            {/* Empty State */}
            {!loading && athletes.length === 0 && (
              <EmptyState
                icon="person_search"
                title={hasActiveFilters ? "No athletes match your filters" : "Start searching"}
                description={
                  hasActiveFilters
                    ? "Try adjusting your search or filters to find athletes."
                    : "Type at least 2 characters to search for athletes."
                }
                action={
                  hasActiveFilters
                    ? {
                        label: 'Clear Filters',
                        onClick: handleClearFilters,
                      }
                    : undefined
                }
              />
            )}
          </div>

          {/* Footer */}
          <div
            style={{
              padding: 'var(--pa-space-5)',
              borderTop: '1px solid var(--pa-n100)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
            }}
          >
            <p className="pa-body-m" style={{ margin: 0, color: 'var(--pa-n500)' }}>
              {selectedCount > 0 ? `${selectedCount} athlete${selectedCount !== 1 ? 's' : ''} selected` : 'No athletes selected'}
            </p>
            <div style={{ display: 'flex', gap: 'var(--pa-space-3)' }}>
              <OrgAdminButton
                variant="secondary"
                onClick={onClose}
                disabled={submitting}
              >
                Cancel
              </OrgAdminButton>
              <OrgAdminButton
                variant="primary"
                onClick={handleSubmit}
                disabled={submitting || selectedCount === 0}
                loading={submitting}
              >
                {submitting ? 'Adding...' : 'Add to Team'}
              </OrgAdminButton>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

import { describe, test, expect, vi, beforeEach } from 'vitest'
import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { BillingHistoryTimeline } from './BillingHistoryTimeline'
import type { BillingEvent } from '@/api/billing'
import { TestWrapper } from '@/test/helpers/renderWithProviders'

const mockEvent: BillingEvent = {
  id: 'evt-1',
  created_at: '2026-01-01T12:00:00Z',
  event_type: 'invoice.paid',
  stripe_event_id: null,
  stripe_object_id: null,
  processed_at: null,
  amount: 2999,
  currency: 'usd',
  description: 'Subscription',
}

describe('BillingHistoryTimeline', () => {
  let user: ReturnType<typeof userEvent.setup>

  beforeEach(() => {
    user = userEvent.setup()
    vi.clearAllMocks()
  })

  describe('rendering', () => {
    test('renders without crashing with empty events', () => {
      const { container } = render(
        <BillingHistoryTimeline events={[]} hasSubscription />,
        { wrapper: TestWrapper }
      )
      expect(container).toBeInTheDocument()
    })

    test('renders events when provided', () => {
      render(<BillingHistoryTimeline events={[mockEvent]} />, { wrapper: TestWrapper })
      expect(screen.getByText('Subscription')).toBeInTheDocument()
    })
  })
})

import { describe, test, expect, vi, beforeEach } from 'vitest'
import { render, screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import TravelFilters from './TravelFilters'
import type { TravelFilters as TravelFiltersType } from '@/types/travelManagement'

describe('TravelFilters', () => {
  let user: ReturnType<typeof userEvent.setup>

  const defaultFilters: TravelFiltersType = {
    search: '',
    teamIds: [],
    status: [],
    dateFrom: '',
    dateTo: '',
  }

  const defaultTeams = [
    { id: 'team-1', name: 'U10 Basketball' },
    { id: 'team-2', name: 'U12 Soccer' },
  ]

  const defaultProps = {
    filters: defaultFilters,
    onFiltersChange: vi.fn(),
    teams: defaultTeams,
    onClearAll: vi.fn(),
  }

  beforeEach(() => {
    user = userEvent.setup()
    vi.clearAllMocks()
  })

  describe('rendering', () => {
    test('renders without crashing with minimal props', () => {
      render(<TravelFilters {...defaultProps} />)
      expect(screen.getByText('Filters')).toBeInTheDocument()
    })

    test('shows filter panel header with Filters text', () => {
      render(<TravelFilters {...defaultProps} />)
      expect(screen.getByText('Filters')).toBeInTheDocument()
    })

    test('shows search input with placeholder', () => {
      render(<TravelFilters {...defaultProps} />)
      expect(screen.getByPlaceholderText('Search plans...')).toBeInTheDocument()
    })

    test('shows status filter buttons', () => {
      render(<TravelFilters {...defaultProps} />)
      expect(screen.getByRole('button', { name: 'Draft' })).toBeInTheDocument()
      expect(screen.getByRole('button', { name: 'Published' })).toBeInTheDocument()
      expect(screen.getByRole('button', { name: 'Cancelled' })).toBeInTheDocument()
    })

    test('shows team filter buttons when teams provided', () => {
      render(<TravelFilters {...defaultProps} />)
      expect(screen.getByRole('button', { name: 'U10 Basketball' })).toBeInTheDocument()
      expect(screen.getByRole('button', { name: 'U12 Soccer' })).toBeInTheDocument()
    })

    test('shows active filter count badge when filters applied', () => {
      render(
        <TravelFilters
          {...defaultProps}
          filters={{ ...defaultFilters, search: 'test', status: ['draft'] }}
        />
      )
      // activeFilterCount = search.length + teamIds.length + status.length + (dateFrom?1:0) + (dateTo?1:0) = 4+0+1+0+0 = 5
      expect(screen.getByText('5')).toBeInTheDocument()
    })
  })

  describe('user interactions', () => {
    test('calls onFiltersChange when search input changes', async () => {
      render(<TravelFilters {...defaultProps} />)
      const searchInput = screen.getByPlaceholderText('Search plans...')
      await user.type(searchInput, 'x')
      expect(defaultProps.onFiltersChange).toHaveBeenCalled()
      expect(defaultProps.onFiltersChange).toHaveBeenCalledWith(
        expect.objectContaining({ search: 'x' })
      )
    })

    test('calls onFiltersChange when status toggle clicked', async () => {
      render(<TravelFilters {...defaultProps} />)
      await user.click(screen.getByRole('button', { name: 'Draft' }))
      expect(defaultProps.onFiltersChange).toHaveBeenCalledWith(
        expect.objectContaining({ status: ['draft'] })
      )
    })

    test('calls onFiltersChange when team toggle clicked', async () => {
      render(<TravelFilters {...defaultProps} />)
      await user.click(screen.getByRole('button', { name: 'U10 Basketball' }))
      expect(defaultProps.onFiltersChange).toHaveBeenCalledWith(
