import { useEffect, useMemo, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Button, Card, EmptyState, Modal } from '@/components/platformAdmin'
import { ConfirmDialog } from '@/components/admin/ConfirmDialog'
import {
  deleteGallery,
  getGalleriesForUser,
  mapEntityToGalleryType,
  type Gallery,
  type GalleryEntityType,
} from '@/data/services/galleryService'
import { useUserContext } from '@/hooks/useUserContext'
import { useI18n } from '@/i18n/useI18n'
import { USE_FAKE_DATA } from '@/data/config'
import { showError, showSuccess } from '@/utils/toast'
import { GalleryCreateModal } from './GalleryCreateModal'
import { GalleryEditModal } from './GalleryEditModal'
import { getLink } from '@/utils/routes'

interface Props {
  entityType?: GalleryEntityType
  entityId?: string
  orgId?: string
  title?: string
  allowCreate?: boolean
  onGalleriesLoaded?: (galleries: Gallery[]) => void
  onLoadingChange?: (loading: boolean) => void
}

export function GalleryManagementSection({
  entityType,
  entityId,
  orgId,
  title = 'Galleries',
  allowCreate = true,
  onGalleriesLoaded,
  onLoadingChange,
}: Props) {
  const { context } = useUserContext()
  const { t } = useI18n()
  const [galleries, setGalleries] = useState<Gallery[]>([])
  const [loading, setLoading] = useState(true)
  const [showCreate, setShowCreate] = useState(false)
  const [editing, setEditing] = useState<Gallery | null>(null)
  const [pendingDeleteGalleryId, setPendingDeleteGalleryId] = useState<string | null>(null)
  const [showDemoModal, setShowDemoModal] = useState(false)
  const navigate = useNavigate()

  const galleryTypeFilter = useMemo(() => (entityType ? mapEntityToGalleryType(entityType) : undefined), [entityType])

  const load = async () => {
    if (!context) return
    setLoading(true)
    onLoadingChange?.(true)
    try {
      const { data, error } = await getGalleriesForUser(context, {
      org_id: orgId || context.orgId,
      gallery_type: galleryTypeFilter,
      entity_id: entityId,
    })
    if (error) {
      showError(error.message)
        return
      }
      const fetchedGalleries = data || []
      setGalleries(fetchedGalleries)
      onGalleriesLoaded?.(fetchedGalleries)
    } finally {
      setLoading(false)
      onLoadingChange?.(false)
    }
  }

  useEffect(() => {
    load()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [entityId, entityType, orgId, onGalleriesLoaded, onLoadingChange])

  const handleDelete = (galleryId: string) => {
    if (USE_FAKE_DATA) {
      setShowDemoModal(true)
      return
    }

    setPendingDeleteGalleryId(galleryId)
  }

  const confirmDeleteGallery = async (galleryId: string) => {
    if (!context) return
    const { error } = await deleteGallery(context, galleryId)
    if (error) {
      showError(error.message)
      return
    }
    showSuccess(t('photos.success.galleryDeleted'))
    load()
  }

  const handleCreateClick = () => {
    if (USE_FAKE_DATA) {
      setShowDemoModal(true)
      return
    }
    // Navigate to create page instead of showing modal
    navigate(getLink('admin.photos.create'))
  }

  const handleEditClick = (gallery: Gallery) => {
    if (USE_FAKE_DATA) {
      setShowDemoModal(true)
      return
    }
    setEditing(gallery)
  }

  const renderGalleryCard = (gallery: Gallery) => (
    <Card key={gallery.id} className="oa-gallery-card">
      <div className="oa-gallery-card-image">
        {gallery.cover_url ? (
          <img
            src={gallery.cover_url}
            alt={gallery.name}
            className="oa-gallery-card-img"
            onError={(e) => {
              e.currentTarget.style.display = 'none'
            }}
          />
        ) : (
          <div className="oa-gallery-card-placeholder">
            <span className="material-symbols-outlined">photo_library</span>
          </div>
        )}
        <div className="oa-gallery-card-overlay" />
        {gallery.visibility === 'public' && (
          <div className="oa-gallery-card-badge">
            <span className="material-symbols-outlined">public</span>
            <span>Public</span>
          </div>
        )}
      </div>

      <div className="oa-gallery-card-body">
        <div className="oa-gallery-card-header">
          <h3 className="oa-gallery-card-title">{gallery.name}</h3>
          <p className="oa-gallery-card-meta">
            {(gallery.photo_count ?? 0) === 0
              ? t('photos.addFirstPhoto')
              : `${gallery.photo_count} ${gallery.photo_count === 1 ? t('photos.photo') : t('photos.photos')}`
            } • {new Date(gallery.created_at).toLocaleDateString()}
          </p>
        </div>

        <div className="oa-gallery-card-footer">
          <div className="oa-gallery-card-actions">
            <button
              className="oa-gallery-card-icon-btn"
              onClick={(e) => { e.stopPropagation(); handleEditClick(gallery) }}
              title={t('common.edit')}
            >
              <span className="material-symbols-outlined">edit</span>
            </button>
            {!gallery.is_system_generated && (
              <button
                className="oa-gallery-card-icon-btn oa-gallery-card-icon-btn--danger"
                onClick={(e) => { e.stopPropagation(); handleDelete(gallery.id) }}
                title={t('common.delete')}
              >
                <span className="material-symbols-outlined">delete</span>
              </button>
            )}
          </div>
          <button
            className="oa-gallery-card-browse"
            onClick={() => navigate(getLink('admin.photos.detail', { id: gallery.id }))}
          >
            {t('photos.viewGallery')}
            <span className="material-symbols-outlined">arrow_forward</span>
          </button>
        </div>
      </div>
    </Card>
  )

  return (
    <div className="oa-gallery-section">
      <div className="oa-gallery-section-header">
        <div>
          <h3 className="oa-gallery-section-title">{title}</h3>
          <p className="oa-gallery-section-subtitle">
            {entityType 
              ? `${t('photos.title')} ${t('photos.linkedTo')} ${t(`photos.galleryType.${entityType}` as any).toLowerCase()}`
              : t('photos.subtitle')}
          </p>
        </div>
        {allowCreate && (
          <Button variant="primary" onClick={handleCreateClick}>
            {t('photos.createGallery')}
          </Button>
        )}
      </div>

      {loading ? (
        <div className="oa-gallery-grid">
          <Card className="oa-gallery-card oa-gallery-card--loading" />
          <Card className="oa-gallery-card oa-gallery-card--loading" />
          <Card className="oa-gallery-card oa-gallery-card--loading" />
        </div>
      ) : galleries.length === 0 ? (
        <EmptyState
          title={t('photos.empty.title')}
          description={t('photos.empty.message')}
          action={allowCreate ? { 
            label: t('photos.createGallery'), 
            onClick: handleCreateClick 
          } : undefined}
        />
      ) : (
        <div className="oa-gallery-grid">{galleries.map(renderGalleryCard)}</div>
      )}

      {showCreate && (
        <GalleryCreateModal
          open={showCreate}
          onClose={() => setShowCreate(false)}
          defaultEntityId={entityId}
          defaultEntityType={entityType}
          entityLabel={entityType ? `${t('photos.createGallerySubtitle')} ${t(`photos.galleryType.${entityType}` as any)}` : t('photos.createGallerySubtitle')}
          onCreated={() => load()}
        />
      )}

      {editing && (
        <GalleryEditModal
          open={!!editing}
          gallery={editing}
          onClose={() => setEditing(null)}
          onSaved={() => {
            setEditing(null)
            load()
          }}
          onDelete={() => {
            if (!editing) return
            handleDelete(editing.id)
            setEditing(null)
          }}
        />
      )}

      {/* Demo Mode Modal */}
      <Modal
        open={showDemoModal}
        onClose={() => setShowDemoModal(false)}
        title={t('photos.demoMode.title')}
      >
        <p className="pa-text-sm pa-text-muted pa-mb-4">
          {t('photos.demoMode.message')}
        </p>
        <div className="pa-flex pa-justify-end">
          <Button variant="primary" onClick={() => setShowDemoModal(false)}>
            {t('common.ok')}
          </Button>
        </div>
      </Modal>

      <ConfirmDialog
        open={pendingDeleteGalleryId !== null}
        title={t('common.delete')}
        description={t('photos.confirmDeletePhotos', { count: 1 })}
        confirmLabel={t('common.delete')}
        cancelLabel={t('common.cancel')}
        variant="danger"
        onConfirm={() => {
          const galleryId = pendingDeleteGalleryId
          setPendingDeleteGalleryId(null)
          if (galleryId) {
            void confirmDeleteGallery(galleryId)
          }
        }}
        onCancel={() => setPendingDeleteGalleryId(null)}
      />
    </div>
  )
}

/**
 * FieldRenderer Component
 * 
 * Universal field renderer that handles all field types dynamically.
 * Renders appropriate input based on field definition.
 * 
 * Design: Clean, breathable inputs with clear labels and helpful guidance.
 */

import { useState } from 'react'
import type { SportFieldDefinition } from '../../types/athleteSportProfiles'

interface FieldRendererProps {
  /** Field definition from database */
  field: SportFieldDefinition
  /** Current field value */
  value: unknown
  /** Change handler */
  onChange: (value: unknown) => void
  /** Whether field is required (considers org overrides) */
  isRequired?: boolean
  /** Whether field is disabled */
  disabled?: boolean
  /** Custom help text (org override) */
  customHelpText?: string
  /** Error message */
  error?: string
}

/**
 * FieldRenderer - Renders any field type dynamically
 */
export function FieldRenderer({
  field,
  value,
  onChange,
  isRequired = !field.is_optional,
  disabled = false,
  customHelpText,
  error,
}: FieldRendererProps) {
  const helpText = customHelpText || field.help_text

  // Render based on field type
  switch (field.field_type) {
    case 'text':
      return (
        <TextFieldInput
          field={field}
          value={value as string | null}
          onChange={onChange}
          isRequired={isRequired}
          disabled={disabled}
          helpText={helpText}
          error={error}
        />
      )

    case 'int':
    case 'numeric':
      return (
        <NumberFieldInput
          field={field}
          value={value as number | null}
          onChange={onChange}
          isRequired={isRequired}
          disabled={disabled}
          helpText={helpText}
          error={error}
          isInteger={field.field_type === 'int'}
        />
      )

    case 'bool':
      return (
        <BooleanFieldInput
          field={field}
          value={value as boolean | null}
          onChange={onChange}
          disabled={disabled}
          helpText={helpText}
          error={error}
        />
      )

    case 'enum':
      return (
        <EnumFieldInput
          field={field}
          value={value as string | null}
          onChange={onChange}
          isRequired={isRequired}
          disabled={disabled}
          helpText={helpText}
          error={error}
        />
      )

    case 'multi_enum':
      return (
        <MultiEnumFieldInput
          field={field}
          value={value as string[] | null}
          onChange={onChange}
          isRequired={isRequired}
          disabled={disabled}
          helpText={helpText}
          error={error}
        />
      )

    case 'time':
      return (
        <TimeFieldInput
          field={field}
          value={value as string | null}
          onChange={onChange}
          isRequired={isRequired}
          disabled={disabled}
          helpText={helpText}
          error={error}
        />
      )

    case 'object':
      return (
        <ObjectFieldInput
          field={field}
          value={value as Record<string, unknown> | null}
          onChange={onChange}
          isRequired={isRequired}
          disabled={disabled}
          helpText={helpText}
          error={error}
        />
      )

    default:
      console.warn(`[FieldRenderer] Unknown field type: ${field.field_type}`)
      return null
  }
}

/**
 * Text Field Input
 */
function TextFieldInput({
  field,
  value,
  onChange,
  isRequired,
  disabled,
  helpText,
  error,
}: {
  field: SportFieldDefinition
  value: string | null
  onChange: (value: string | null) => void
  isRequired: boolean
  disabled: boolean
  helpText: string | null
  error?: string
}) {
  return (
    <div className="field-group">
      <label htmlFor={field.field_key} className="form-label">
        {field.field_label}
        {isRequired && <span className="field-required">*</span>}
        {field.unit && <span className="field-unit">({field.unit})</span>}
      </label>
      
      <input
        id={field.field_key}
        type="text"
        value={value || ''}
        onChange={(e) => onChange(e.target.value || null)}
        disabled={disabled}
        className={`form-input ${error ? 'form-input-error' : ''}`}
        placeholder={`Enter ${field.field_label.toLowerCase()}`}
      />
      
      {helpText && <p className="field-help">{helpText}</p>}
      {error && <p className="field-error">{error}</p>}
    </div>
  )
}

/**
 * Number Field Input
 */
function NumberFieldInput({
  field,
  value,
  onChange,
  isRequired,
  disabled,
  helpText,
  error,
  isInteger,
}: {
  field: SportFieldDefinition
  value: number | null
  onChange: (value: number | null) => void
  isRequired: boolean
  disabled: boolean
  helpText: string | null
  error?: string
  isInteger: boolean
}) {
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value
    if (val === '') {
      onChange(null)
      return
    }
    
    const num = isInteger ? parseInt(val, 10) : parseFloat(val)
    if (!isNaN(num)) {
      onChange(num)
    }
  }

  return (
    <div className="field-group">
      <label htmlFor={field.field_key} className="form-label">
        {field.field_label}
        {isRequired && <span className="field-required">*</span>}
        {field.unit && <span className="field-unit">({field.unit})</span>}
      </label>
      
      <input
        id={field.field_key}
        type="number"
        value={value ?? ''}
        onChange={handleChange}
        disabled={disabled}
        step={isInteger ? '1' : '0.01'}
        className={`form-input ${error ? 'form-input-error' : ''}`}
        placeholder={`Enter ${field.field_label.toLowerCase()}`}
      />
      
      {helpText && <p className="field-help">{helpText}</p>}
      {error && <p className="field-error">{error}</p>}
    </div>
  )
}

/**
 * Boolean Field Input (Toggle)
 */
function BooleanFieldInput({
  field,
  value,
  onChange,
  disabled,
  helpText,
  error,
}: {
  field: SportFieldDefinition
  value: boolean | null
  onChange: (value: boolean | null) => void
  disabled: boolean
  helpText: string | null
  error?: string
}) {
  return (
      <div className="field-group">
        <label htmlFor={field.field_key} className="form-checkbox-label">
          <input
            id={field.field_key}
            type="checkbox"
            className="form-checkbox"
            checked={value ?? false}
            onChange={(e) => onChange(e.target.checked)}
            disabled={disabled}
          />
          <span>{field.field_label}</span>
        </label>
        
        {helpText && <p className="field-help">{helpText}</p>}
        {error && <p className="field-error">{error}</p>}
      </div>
  )
}

/**
 * Enum Field Input (Select)
 */
function EnumFieldInput({
  field,
  value,
  onChange,
  isRequired,
  disabled,
  helpText,
  error,
}: {
  field: SportFieldDefinition
  value: string | null
  onChange: (value: string | null) => void
  isRequired: boolean
  disabled: boolean
  helpText: string | null
  error?: string
}) {
  const enumValues = field.enum_values || []

  return (
    <div className="field-group">
      <label htmlFor={field.field_key} className="form-label">
        {field.field_label}
        {isRequired && <span className="field-required">*</span>}
      </label>
      
      <select
        id={field.field_key}
        value={value || ''}
        onChange={(e) => onChange(e.target.value || null)}
        disabled={disabled}
        className={`form-select ${error ? 'form-input-error' : ''}`}
      >
        <option value="">Select {field.field_label.toLowerCase()}</option>
        {enumValues.map((option) => (
          <option key={option} value={option}>
            {formatEnumValue(option)}
          </option>
        ))}
      </select>
      
      {helpText && <p className="field-help">{helpText}</p>}
      {error && <p className="field-error">{error}</p>}
    </div>
  )
}

/**
 * Multi-Enum Field Input (Checkboxes)
 */
function MultiEnumFieldInput({
  field,
  value,
  onChange,
  isRequired,
  disabled,
  helpText,
  error,
}: {
  field: SportFieldDefinition
  value: string[] | null
  onChange: (value: string[] | null) => void
  isRequired: boolean
  disabled: boolean
  helpText: string | null
  error?: string
}) {
  const enumValues = field.enum_values || []
  const selectedValues = value || []

  const handleToggle = (option: string) => {
    const newValues = selectedValues.includes(option)
      ? selectedValues.filter((v) => v !== option)
      : [...selectedValues, option]
    
    onChange(newValues.length > 0 ? newValues : null)
  }

  return (
    <div className="field-group">
      <label className="form-label">
        {field.field_label}
        {isRequired && <span className="field-required">*</span>}
      </label>
      
      <div className="checkbox-row">
        {enumValues.map((option) => (
          <label key={option} className="form-checkbox-label">
            <input
              type="checkbox"
              className="form-checkbox"
              checked={selectedValues.includes(option)}
              onChange={() => handleToggle(option)}
              disabled={disabled}
            />
            <span>{formatEnumValue(option)}</span>
          </label>
        ))}
      </div>
      
      {helpText && <p className="field-help">{helpText}</p>}
      {error && <p className="field-error">{error}</p>}
    </div>
  )
}

/**
 * Time Field Input
 */
function TimeFieldInput({
  field,
  value,
  onChange,
  isRequired,
  disabled,
  helpText,
  error,
}: {
  field: SportFieldDefinition
  value: string | null
  onChange: (value: string | null) => void
  isRequired: boolean
  disabled: boolean
  helpText: string | null
  error?: string
}) {
  return (
    <div className="field-group">
      <label htmlFor={field.field_key} className="form-label">
        {field.field_label}
        {isRequired && <span className="field-required">*</span>}
      </label>
      
      <input
        id={field.field_key}
        type="time"
        value={value || ''}
        onChange={(e) => onChange(e.target.value || null)}
        disabled={disabled}
        className={`form-input ${error ? 'form-input-error' : ''}`}
      />
      
      {helpText && <p className="field-help">{helpText}</p>}
      {error && <p className="field-error">{error}</p>}
    </div>
  )
}

/**
 * Object Field Input (JSON textarea for now - can be enhanced)
 */
function ObjectFieldInput({
  field,
  value,
  onChange,
  isRequired,
  disabled,
  helpText,
  error,
}: {
  field: SportFieldDefinition
  value: Record<string, unknown> | null
  onChange: (value: Record<string, unknown> | null) => void
  isRequired: boolean
  disabled: boolean
  helpText: string | null
  error?: string
}) {
  const [jsonError, setJsonError] = useState<string | null>(null)

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value
    if (val === '') {
      onChange(null)
      setJsonError(null)
      return
    }

    try {
      const parsed = JSON.parse(val)
      onChange(parsed)
      setJsonError(null)
    } catch (err) {
      setJsonError('Invalid JSON format')
    }
  }

  return (
    <div className="field-group">
      <label htmlFor={field.field_key} className="form-label">
        {field.field_label}
        {isRequired && <span className="field-required">*</span>}
      </label>
      
      <textarea
        id={field.field_key}
        value={value ? JSON.stringify(value, null, 2) : ''}
        onChange={handleChange}
        disabled={disabled}
        rows={4}
        className={`form-textarea ${error || jsonError ? 'form-input-error' : ''}`}
        placeholder={`Enter ${field.field_label.toLowerCase()} as JSON`}
      />
      
      {helpText && <p className="field-help">{helpText}</p>}
      {jsonError && <p className="field-error">{jsonError}</p>}
      {error && <p className="field-error">{error}</p>}
    </div>
  )
}

/**
 * Helper: Format enum value for display
 */
function formatEnumValue(value: string): string {
  return value
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ')
}

/**
 * LocationAutocomplete Component
 * 
 * Google Places API autocomplete input with structured address parsing.
 * Provides real-time location suggestions, keyboard navigation, and accessibility.
 */

import { useState, useEffect, useRef, useCallback } from 'react'
import { createPortal } from 'react-dom'
import type { LocationAutocompleteProps as BaseProps, StructuredAddress } from '../../types/location'
import { parsePlace, validateStructuredAddress, isPlaceResult, hasAddressComponents } from '../../types/location'
import { loadGoogleMapsScript, isGoogleMapsLoaded } from '../../utils/googleMapsLoader'
import { Input } from '../platformAdmin/Input'
import { USE_FAKE_DATA } from '../../data/config'

// Extend the props to include the callback with place result
interface LocationAutocompleteProps extends Omit<BaseProps, 'onChange'> {
  onChange: (address: StructuredAddress, placeResult?: google.maps.places.PlaceResult) => void
}

/**
 * Debounce function with cancel capability
 */
function debounce<T extends (...args: any[]) => any>(
  func: T,
  wait: number
): ((...args: Parameters<T>) => void) & { cancel: () => void } {
  let timeout: NodeJS.Timeout | null = null

  const debounced = function executedFunction(...args: Parameters<T>) {
    const later = () => {
      timeout = null
      func(...args)
    }

    if (timeout) {
      clearTimeout(timeout)
    }
    timeout = setTimeout(later, wait)
  }

  debounced.cancel = () => {
    if (timeout) {
      clearTimeout(timeout)
      timeout = null
    }
  }

  return debounced
}

/**
 * Get adaptive debounce delay based on input length
 */
function getDebounceDelay(inputLength: number): number {
  if (inputLength < 3) return 300
  if (inputLength < 7) return 500
  return 700
}

/**
 * Check browser compatibility for Google Maps API
 */
function checkBrowserCompatibility(): { supported: boolean; reason?: string } {
  if (typeof window === 'undefined') {
    return { supported: false, reason: 'Server-side rendering' }
  }

  if (!window.Promise) {
    return { supported: false, reason: 'Promise not supported' }
  }

  // Check CSP (basic check)
  try {
    const testScript = document.createElement('script')
    testScript.src = 'data:text/javascript,void(0)'
    document.head.appendChild(testScript)
    document.head.removeChild(testScript)
  } catch (e) {
    return { supported: false, reason: 'Content Security Policy may block external scripts' }
  }

  return { supported: true }
}

interface AutocompleteSuggestion {
  place_id: string
  description: string
  structured_formatting?: {
    main_text: string
    secondary_text: string
  }
  placePrediction?: google.maps.places.PlacePrediction
  mockAddress?: StructuredAddress
}

const MOCK_VENUES: Array<{
  place_id: string
  name: string
  address_line1: string
  city: string
  state: string
  postal_code: string
  country: string
  latitude: number
  longitude: number
  distance: string
}> = [
