    country: 'US',
    latitude: 32.71574,
    longitude: -117.16109,
    distance: '8.4 miles away',
  },
]

function buildMockAddressSuggestion(venue: typeof MOCK_VENUES[number]): AutocompleteSuggestion {
  const formatted_address = `${venue.address_line1}, ${venue.city}, ${venue.state} ${venue.postal_code}`
  return {
    place_id: venue.place_id,
    description: `${venue.name}, ${formatted_address}`,
    structured_formatting: {
      main_text: venue.name,
      secondary_text: `${formatted_address} • ${venue.distance}`,
    },
    mockAddress: {
      place_id: venue.place_id,
      formatted_address,
      address_line1: venue.address_line1,
      city: venue.city,
      state: venue.state,
      postal_code: venue.postal_code,
      country: venue.country,
      latitude: venue.latitude,
      longitude: venue.longitude,
    },
  }
}

function getMockSuggestions(query: string): AutocompleteSuggestion[] {
  const normalizedQuery = query.trim().toLowerCase()
  if (normalizedQuery.length < 3) return []
  return MOCK_VENUES
    .filter((venue) => {
      const haystack = `${venue.name} ${venue.address_line1} ${venue.city} ${venue.state} ${venue.postal_code}`.toLowerCase()
      return haystack.includes(normalizedQuery)
    })
    .slice(0, 5)
    .map(buildMockAddressSuggestion)
}

export function LocationAutocomplete({
  value,
  onChange,
  onInputChange,
  placeholder = 'Enter an address',
  label,
  required = false,
  error,
  helper,
  disabled = false,
  countryRestrictions,
  types = ['address'],
}: LocationAutocompleteProps) {
  // State
  const [inputValue, setInputValue] = useState(value || '')
  const [suggestions, setSuggestions] = useState<AutocompleteSuggestion[]>([])
  const [showSuggestions, setShowSuggestions] = useState(false)
  const [selectedIndex, setSelectedIndex] = useState(-1)
  const [isLoading, setIsLoading] = useState(false)
  const [isLoaded, setIsLoaded] = useState(false)
  const [apiError, setApiError] = useState<string | null>(null)
  const [fallbackMode, setFallbackMode] = useState(false)
  const [selectedPlace, setSelectedPlace] = useState<StructuredAddress | null>(null)

  // Refs
  const inputRef = useRef<HTMLInputElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)
  const suggestionsRef = useRef<HTMLUListElement>(null)
  const requestIdRef = useRef(0)
  const previousValueRef = useRef<string>('')
  const debouncedSearchRef = useRef<ReturnType<typeof debounce> | null>(null)
  const sessionTokenRef = useRef<google.maps.places.AutocompleteSessionToken | null>(null)
  const placesLibraryRef = useRef<typeof google.maps.places | null>(null)
  const mountedRef = useRef(true)
  const [dropdownPosition, setDropdownPosition] = useState({ top: 0, left: 0, width: 0 })

  // Update dropdown position
  const updatePosition = useCallback(() => {
    if (!inputRef.current) return

    const rect = inputRef.current.getBoundingClientRect()
    setDropdownPosition({
      top: rect.bottom + window.scrollY,
      left: rect.left + window.scrollX,
      width: rect.width,
    })
  }, [])

  // Sync with external value changes
  useEffect(() => {
    // Always sync when external value changes
    // This allows parent to control the display value after selection
    if (value !== previousValueRef.current) {
      setInputValue(value || '')
      previousValueRef.current = value || ''
      // Clear selectedPlace when syncing to allow future syncs
      if (selectedPlace && value !== selectedPlace.formatted_address) {
        setSelectedPlace(null)
      }
    }
  }, [value, selectedPlace])

  // Load Google Maps API
  useEffect(() => {
    mountedRef.current = true

    // Check browser compatibility
    const compatibility = checkBrowserCompatibility()
    if (!compatibility.supported) {
      setFallbackMode(true)
      setApiError(compatibility.reason || 'Browser not supported')
      return
    }

    // Check if already loaded
    if (isGoogleMapsLoaded()) {
      // Import places library
      google.maps.importLibrary('places')
        .then((places) => {
          if (mountedRef.current) {
            placesLibraryRef.current = places as typeof google.maps.places
            setIsLoaded(true)
            setApiError(null)
          }
        })
        .catch((err) => {
          if (mountedRef.current) {
            setFallbackMode(true)
            setApiError(err instanceof Error ? err.message : 'Failed to load Places library')
          }
        })
      return
    }

    // Get API key
    const apiKey = import.meta.env.VITE_GOOGLE_PLACES_API_KEY
    if (!apiKey || apiKey.length < 20) {
      if (USE_FAKE_DATA) {
        setIsLoaded(true)
        setFallbackMode(false)
        setApiError(null)
        return
      }
      setFallbackMode(true)
      setApiError('Google Places API key not configured')
      return
    }

    // Load script
    loadGoogleMapsScript(apiKey)
      .then(async () => {
        if (!mountedRef.current) return
        
        // Check if Google Maps API is available
        if (!window.google?.maps) {
          if (mountedRef.current) {
            setFallbackMode(true)
            setApiError('Google Maps API not available')
          }
          return
        }

        // Check if places is already available
        if (window.google.maps.places) {
          if (mountedRef.current) {
            placesLibraryRef.current = window.google.maps.places
            setIsLoaded(true)
            setApiError(null)
          }
          return
        }

        // Try to import places library
        if (window.google.maps.importLibrary) {
          try {
            const places = await window.google.maps.importLibrary('places')
            if (mountedRef.current) {
              placesLibraryRef.current = places as typeof google.maps.places
              setIsLoaded(true)
              setApiError(null)
            }
          } catch (err) {
            if (mountedRef.current) {
              setFallbackMode(true)
              setApiError('Places library could not be loaded. You can enter the address manually below.')
            }
          }
        } else {
          // importLibrary not available, check if places becomes available
          let attempts = 0
          const maxAttempts = 50 // 5 seconds
          const checkInterval = setInterval(() => {
            attempts++
            if (window.google?.maps?.places) {
              clearInterval(checkInterval)
              if (mountedRef.current) {
                placesLibraryRef.current = window.google.maps.places
                setIsLoaded(true)
                setApiError(null)
              }
            } else if (attempts >= maxAttempts) {
              clearInterval(checkInterval)
              if (mountedRef.current) {
                setFallbackMode(true)
                setApiError('Places library could not be loaded. You can enter the address manually below.')
              }
            }
          }, 100)
        }
      })
      .catch((err) => {
        if (mountedRef.current) {
          if (USE_FAKE_DATA) {
            setIsLoaded(true)
            setFallbackMode(false)
            setApiError(null)
            return
          }
          setFallbackMode(true)
          setApiError(err instanceof Error ? err.message : 'Failed to load Google Maps API')
        }
      })

    return () => {
      mountedRef.current = false
    }
  }, [])

  // Handle input change with adaptive debounce
  const handleInputChange = useCallback((newValue: string) => {
    // Skip if value hasn't actually changed
    if (newValue === previousValueRef.current) {
      return
    }

    previousValueRef.current = newValue
    setInputValue(newValue)
    setSelectedIndex(-1)
    setSelectedPlace(null)
    onInputChange?.(newValue)

    // Cancel previous debounced call
    if (debouncedSearchRef.current) {
      debouncedSearchRef.current.cancel()
    }

    // Clear suggestions if input is too short
    if (newValue.length < 2) {
      setSuggestions([])
      setShowSuggestions(false)
      setIsLoading(false)
      return
    }

    if (USE_FAKE_DATA && !placesLibraryRef.current) {
      const mockResults = getMockSuggestions(newValue)
      setSuggestions(mockResults)
      setShowSuggestions(true)
      setIsLoading(false)
      updatePosition()
      return
    }

    // Increment request ID
    const currentRequestId = ++requestIdRef.current
    setIsLoading(true)

    // Create new debounced function with adaptive delay
    const delay = getDebounceDelay(newValue.length)
    const debouncedFn = debounce(async (searchValue: string) => {
      if (!placesLibraryRef.current || !mountedRef.current) return

      try {
        // Create or reuse session token
        if (!sessionTokenRef.current) {
          sessionTokenRef.current = new placesLibraryRef.current.AutocompleteSessionToken()
        }

        const request: google.maps.places.AutocompleteRequest = {
          input: searchValue,
          sessionToken: sessionTokenRef.current,
          includedPrimaryTypes: types.length > 0 ? types.map(t => t === 'address' ? 'geocode' : t) as string[] : undefined,
          includedRegionCodes: countryRestrictions && countryRestrictions.length > 0
            ? countryRestrictions.map(code => code.toUpperCase())
            : undefined,
        }

        // Use the new AutocompleteSuggestion API
        const { suggestions: apiSuggestions } = await placesLibraryRef.current.AutocompleteSuggestion.fetchAutocompleteSuggestions(request)

        // Only update if this is still the latest request
        if (currentRequestId !== requestIdRef.current || !mountedRef.current) {
          return
        }

        if (apiSuggestions && apiSuggestions.length > 0) {
          const formattedResults = apiSuggestions
            .map((suggestion) => {
              const prediction = suggestion.placePrediction
              if (!prediction) {
                // Skip suggestions without placePrediction
                return null
              }
              // Use mainText and secondaryText from the new API
              const mainText = prediction.mainText?.text || prediction.text.text
              const secondaryText = prediction.secondaryText?.text || ''
              const fullText = prediction.text.text
              
              return {
                place_id: prediction.placeId,
                description: fullText,
                structured_formatting: {
                  main_text: mainText,
                  secondary_text: secondaryText,
                },
                placePrediction: prediction,
              } as AutocompleteSuggestion
            })
            .filter((result): result is AutocompleteSuggestion => result !== null)
          setSuggestions(formattedResults)
          setShowSuggestions(true)
          setIsLoading(false)
          updatePosition()
        } else {
          setSuggestions([])
          setShowSuggestions(true)
          setIsLoading(false)
          updatePosition()
        }
      } catch (err: any) {
        if (currentRequestId === requestIdRef.current && mountedRef.current) {
          console.error('Autocomplete error:', err)
          // Check for specific error types
          if (err?.code === 'OVER_QUERY_LIMIT' || err?.code === 'REQUEST_DENIED') {
            setFallbackMode(true)
            setApiError('Autocomplete temporarily unavailable')
          } else {
            setApiError('Failed to fetch suggestions')
          }
          setIsLoading(false)
        }
      }
    }, delay)

    debouncedSearchRef.current = debouncedFn
    debouncedFn(newValue)
  }, [types, countryRestrictions, onInputChange, updatePosition])

  // Handle place selection
  const handlePlaceSelect = useCallback(
    async (suggestion: AutocompleteSuggestion) => {
      if (suggestion.mockAddress) {
        const placeResult: google.maps.places.PlaceResult = {
          place_id: suggestion.mockAddress.place_id,
          name: suggestion.structured_formatting?.main_text || suggestion.description,
          formatted_address: suggestion.mockAddress.formatted_address,
          address_components: [
            {
              long_name: suggestion.mockAddress.address_line1,
              short_name: suggestion.mockAddress.address_line1,
              types: ['route'],
            } as google.maps.GeocoderAddressComponent,
            {
              long_name: suggestion.mockAddress.city,
              short_name: suggestion.mockAddress.city,
              types: ['locality'],
            } as google.maps.GeocoderAddressComponent,
            {
              long_name: suggestion.mockAddress.state,
              short_name: suggestion.mockAddress.state,
              types: ['administrative_area_level_1'],
            } as google.maps.GeocoderAddressComponent,
            {
              long_name: suggestion.mockAddress.postal_code,
              short_name: suggestion.mockAddress.postal_code,
              types: ['postal_code'],
            } as google.maps.GeocoderAddressComponent,
            {
              long_name: suggestion.mockAddress.country,
              short_name: suggestion.mockAddress.country,
              types: ['country'],
            } as google.maps.GeocoderAddressComponent,
          ],
          geometry: {
            location: {
              lat: () => suggestion.mockAddress!.latitude,
              lng: () => suggestion.mockAddress!.longitude,
            } as unknown as google.maps.LatLng,
          },
        }

        setSelectedPlace(suggestion.mockAddress)
        setShowSuggestions(false)
        setSelectedIndex(-1)
        setIsLoading(false)
        setApiError(null)
        onChange(suggestion.mockAddress, placeResult)
        previousValueRef.current = ''
        return
      }

      if (!placesLibraryRef.current || !mountedRef.current || !suggestion.placePrediction) return

      try {
        setIsLoading(true)

        // Convert PlacePrediction to Place using the new API
        const place = suggestion.placePrediction.toPlace()
        
        // Fetch required fields including displayName
        await place.fetchFields({
          fields: ['id', 'formattedAddress', 'addressComponents', 'location', 'displayName'],
        })

        if (!mountedRef.current) return

        // Extract displayName - it might be a LocalizedText object with a text property
        let placeName = ''
        if (place.displayName) {
          // displayName can be a string or a LocalizedText object with a text property
          placeName = typeof place.displayName === 'string' 
            ? place.displayName 
            : (place.displayName as any)?.text || ''
        }
        
        // Fallback to main_text from suggestion if displayName is not available
        // main_text from autocomplete should be the place name (e.g., "Hilton Hotel")
        // not the address (e.g., "515 15th St NW")
        if (!placeName && suggestion.structured_formatting?.main_text) {
          placeName = suggestion.structured_formatting.main_text
        }

        // Convert new Place object to legacy PlaceResult format for compatibility
        // The new Place API uses different property names and structures
        // Place.location is a LatLng object with lat() and lng() methods
        const location = place.location
        const formattedAddress = place.formattedAddress || ''
        
        // Only use placeName if it's different from the formatted address
        // Also check if placeName looks like an address (contains numbers and common address words)
        // This prevents using the address as the name
        const looksLikeAddress = placeName && (
          placeName === formattedAddress ||
          /^\d+\s+[A-Za-z\s]+(?:St|Street|Ave|Avenue|Rd|Road|Blvd|Boulevard|Dr|Drive|Ln|Lane|Ct|Court|Pl|Place|Way|Cir|Circle)/i.test(placeName)
        )
        const finalName = placeName && !looksLikeAddress ? placeName : ''
        
        const placeResult: google.maps.places.PlaceResult = {
          place_id: place.id || suggestion.place_id,
          name: finalName,
          formatted_address: formattedAddress,
          address_components: place.addressComponents?.map((comp) => ({
            long_name: comp.longText || '',
            short_name: comp.shortText || '',
            types: comp.types || [],
          })) || [],
          geometry: location
            ? {
                location: location, // LatLng object is compatible
              }
            : undefined,
        }

        // Validate place has required data
        if (!isPlaceResult(placeResult) || !placeResult.place_id) {
          setApiError('Invalid place data received')
          setIsLoading(false)
          return
        }

        // Fetch details if missing
        if (!hasAddressComponents(placeResult)) {
          setApiError('Place details incomplete')
          setIsLoading(false)
          return
        }

        // Parse address
        const address = parsePlace(placeResult)
        if (!address || !validateStructuredAddress(address)) {
          setApiError('Could not parse address components')
          setIsLoading(false)
          return
        }

        // Validate country restrictions
        if (countryRestrictions && countryRestrictions.length > 0) {
          const countryComponent = placeResult.address_components?.find((c) =>
            c.types.includes('country')
          )
          if (
            countryComponent &&
            !countryRestrictions.includes(countryComponent.short_name.toLowerCase())
          ) {
            setApiError(`This location is outside the allowed countries`)
            setIsLoading(false)
            return
          }
        }

        // Reset session token after successful selection
        sessionTokenRef.current = null

        // Update state
        setSelectedPlace(address)
        // Don't set inputValue here - let the parent control it via onChange callback
        // The parent can call onInputChange with whatever display value they want
        setShowSuggestions(false)
        setSelectedIndex(-1)
        setIsLoading(false)
        setApiError(null)

        // Call onChange - parent is responsible for setting the display value
        // via calling onInputChange with their desired value (name or address)
        onChange(address, placeResult)
        
        // Update previousValueRef to prevent sync effect from overwriting
        // after parent sets the value
        previousValueRef.current = ''
      } catch (err) {
        if (mountedRef.current) {
          console.error('Place selection error:', err)
          setApiError(err instanceof Error ? err.message : 'Failed to select place')
          setIsLoading(false)
        }
      }
    },
    [onChange, onInputChange, countryRestrictions]
  )

  // Keyboard navigation
  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (!showSuggestions || suggestions.length === 0) {
        if (e.key === 'ArrowDown' && inputValue.length >= 2) {
          e.preventDefault()
          setShowSuggestions(true)
          setSelectedIndex(0)
        }
        return
      }

      if (e.key === 'ArrowDown') {
        e.preventDefault()
        setSelectedIndex((prev) => {
          if (suggestions.length === 0) return -1
          return Math.min(prev + 1, suggestions.length - 1)
        })
      } else if (e.key === 'ArrowUp') {
        e.preventDefault()
        setSelectedIndex((prev) => Math.max(prev - 1, -1))
      } else if (e.key === 'Enter') {
        e.preventDefault()
        if (selectedIndex >= 0 && selectedIndex < suggestions.length) {
          handlePlaceSelect(suggestions[selectedIndex])
        }
      } else if (e.key === 'Escape') {
        e.preventDefault()
        setShowSuggestions(false)
        setSelectedIndex(-1)
      }
    },
    [showSuggestions, suggestions, selectedIndex, inputValue, handlePlaceSelect]
  )

  // Reset selected index when suggestions change
  useEffect(() => {
    setSelectedIndex(-1)
  }, [suggestions])

  // Click outside handler
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (
        containerRef.current &&
        !containerRef.current.contains(e.target as Node) &&
        suggestionsRef.current &&
        !suggestionsRef.current.contains(e.target as Node)
      ) {
        setShowSuggestions(false)
        setSelectedIndex(-1)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => {
      document.removeEventListener('mousedown', handleClickOutside)
    }
  }, [])

  // Update dropdown position on scroll/resize
  useEffect(() => {
    if (showSuggestions) {
      updatePosition()
      window.addEventListener('scroll', updatePosition, true)
      window.addEventListener('resize', updatePosition)

      return () => {
        window.removeEventListener('scroll', updatePosition, true)
        window.removeEventListener('resize', updatePosition)
      }
    }
  }, [showSuggestions, updatePosition])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      mountedRef.current = false
      if (debouncedSearchRef.current) {
        debouncedSearchRef.current.cancel()
      }
    }
  }, [])

  // Fallback mode: render as regular input
  if (fallbackMode) {
    return (
      <>
        {apiError && (
          <div
            className="pa-card pa-mb-2"
            style={{
              background: 'var(--pa-warning-bg, #fff3cd)',
              padding: '12px',
              borderRadius: '8px',
              fontSize: '14px',
            }}
          >
            {apiError}. You can enter the address manually below.
          </div>
        )}
        <Input
          label={label}
          helper={helper}
          error={error}
          required={required}
          disabled={disabled}
          placeholder={placeholder}
          value={inputValue}
          onChange={(e) => {
            setInputValue(e.target.value)
            onInputChange?.(e.target.value)
          }}
        />
      </>
    )
  }

  // Render autocomplete
  return (
    <div ref={containerRef} className="pa-form-group" style={{ position: 'relative' }}>
      {label && (
        <label className={`oa-label ${required ? 'oa-label--required' : ''}`}>{label}</label>
      )}

      <div style={{ position: 'relative' }}>
        <input
          ref={inputRef}
          className={`pa-input ${error ? 'pa-input--error' : ''}`.trim()}
          type="text"
          value={inputValue}
          onChange={(e) => handleInputChange(e.target.value)}
          onKeyDown={handleKeyDown}
          onFocus={() => {
            if (suggestions.length > 0) {
              setShowSuggestions(true)
              updatePosition()
            }
          }}
          onBlur={() => {
            // Delay to allow click on suggestion
            setTimeout(() => {
              if (
                !suggestionsRef.current?.contains(document.activeElement) &&
                !containerRef.current?.contains(document.activeElement)
              ) {
                setShowSuggestions(false)
              }
            }, 200)
          }}
          placeholder={placeholder}
          disabled={disabled || !isLoaded}
          required={required}
          role="combobox"
          aria-expanded={showSuggestions}
          aria-activedescendant={selectedIndex >= 0 ? `suggestion-${selectedIndex}` : undefined}
          aria-controls="suggestions-list"
          aria-label={label || placeholder}
          aria-autocomplete="list"
        />

        {isLoading && (
          <span
            style={{
              position: 'absolute',
              right: '12px',
              top: '50%',
              transform: 'translateY(-50%)',
              color: 'var(--pa-n500)',
            }}
          >
            <span className="material-symbols-outlined" style={{ fontSize: '20px' }}>
              hourglass_empty
            </span>
          </span>
        )}

        {inputValue && !isLoading && (
          <button
            type="button"
            onClick={() => {
              setInputValue('')
              setSuggestions([])
              setShowSuggestions(false)
              setSelectedPlace(null)
              onInputChange?.('')
            }}
            style={{
              position: 'absolute',
              right: '12px',
              top: '50%',
              transform: 'translateY(-50%)',
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              color: 'var(--pa-n500)',
              padding: '4px',
              display: 'flex',
              alignItems: 'center',
            }}
            aria-label="Clear input"
          >
            <span className="material-symbols-outlined" style={{ fontSize: '20px' }}>
              close
            </span>
          </button>
        )}
      </div>

      {(helper || error || apiError) && (
        <div className={`pa-helper ${error || apiError ? 'pa-helper--error' : ''}`}>
          {error || apiError || helper}
        </div>
      )}

      {/* Suggestions dropdown via portal */}
      {showSuggestions &&
        (suggestions.length > 0 || isLoading) &&
        createPortal(
          <ul
            ref={suggestionsRef}
            id="suggestions-list"
            role="listbox"
            aria-live="polite"
            style={{
              position: 'absolute',
              top: `${dropdownPosition.top}px`,
              left: `${dropdownPosition.left}px`,
              width: `${dropdownPosition.width}px`,
              zIndex: 1500,
              background: 'white',
              border: '1px solid var(--pa-n200, #e0e0e0)',
              borderRadius: '8px',
              marginTop: '4px',
              maxHeight: '300px',
              overflowY: 'auto',
              boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
              listStyle: 'none',
              padding: '4px 0',
              margin: 0,
            }}
          >
            {isLoading && (
              <li
                style={{
                  padding: '12px 16px',
                  color: 'var(--pa-n500)',
                  fontSize: '14px',
                }}
              >
                Searching...
              </li>
            )}
            {!isLoading && suggestions.length === 0 && (
              <li
                style={{
                  padding: '12px 16px',
                  color: 'var(--pa-n500)',
                  fontSize: '14px',
                }}
              >
                {USE_FAKE_DATA ? 'No venues found. Enter address manually.' : 'No results found'}
              </li>
            )}
            {suggestions.map((suggestion, index) => (
              <li
                key={suggestion.place_id}
                id={`suggestion-${index}`}
                role="option"
                aria-selected={index === selectedIndex}
                onClick={() => handlePlaceSelect(suggestion)}
                onMouseEnter={() => setSelectedIndex(index)}
                style={{
                  padding: '12px 16px',
                  cursor: 'pointer',
                  backgroundColor: index === selectedIndex ? 'var(--pa-n100, #f5f5f5)' : 'transparent',
                  fontSize: '14px',
                }}
              >
                <div style={{ fontWeight: 500, color: 'var(--pa-n900, #212121)' }}>
                  {suggestion.structured_formatting?.main_text || suggestion.description}
                </div>
                {suggestion.structured_formatting?.secondary_text && (
                  <div
                    style={{
                      fontSize: '12px',
                      color: 'var(--pa-n600, #757575)',
                      marginTop: '2px',
                    }}
                  >
                    {suggestion.structured_formatting.secondary_text}
                  </div>
                )}
              </li>
            ))}
          </ul>,
          document.body
        )}
    </div>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { cn } from '../../utils/cn'
import { useUserContext } from '../../hooks/useUserContext'
import { useT } from '../../i18n/useI18n'
import { notificationService } from '../../data/services/notificationService'
import type { NotificationRecord, NotificationPresentation } from '../../types/notifications'
import { showError } from '../../utils/toast'

interface NotificationBellProps {
  viewAllPath?: string
}

export default function NotificationBell({ viewAllPath = '/dashboard' }: NotificationBellProps) {
  // All hooks must be called unconditionally at the top
  const userContextResult = useUserContext()
  const context = userContextResult.context
  const isReady = userContextResult.isReady
  const hasReadyContext = Boolean(isReady && context?.userId && context?.orgId)
  const t = useT()
  const navigate = useNavigate()
  const [open, setOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [notifications, setNotifications] = useState<NotificationRecord[]>([])
  const [error, setError] = useState<string | null>(null)
  const containerRef = useRef<HTMLDivElement | null>(null)

  const unreadCount = useMemo(() => notifications.filter((n) => !n.read_at).length, [notifications])

  const fetchNotifications = async () => {
    if (!hasReadyContext) return
    setLoading(true)
    setError(null)
    const { data, error: fetchError } = await notificationService.getNotifications(context, 10)
    if (fetchError) {
      const message = fetchError.message || t('common.error.label')
      setError(message)
      showError(message)
      setLoading(false)
      return
    }
    setNotifications(data || [])
    setLoading(false)
  }

  useEffect(() => {
    fetchNotifications()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [hasReadyContext])

  useEffect(() => {
    if (!hasReadyContext) return

    import('../../lib/supabase').then(({ supabase }) => {
      supabase
        .channel('notifications')
        .on(
          'postgres_changes',
          {
            event: 'INSERT',
            schema: 'public',
            table: 'user_notifications',
            filter: `user_id=eq.${context.userId}`
          },
          (payload: any) => {
            setNotifications((prev) => [payload.new, ...prev])
          }
        )
        .subscribe()
    })

    return () => {
      import('../../lib/supabase').then(({ supabase }) => {
         supabase.channel('notifications').unsubscribe()
        })
    }
  }, [context.userId, hasReadyContext])

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (!open) return
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [open])

  const handleToggle = () => {
    if (!open && !loading && notifications.length === 0) {
      fetchNotifications()
    }
    setOpen((prev) => !prev)
  }

  const handleOpenNotification = async (notification: NotificationRecord) => {
    if (notification.link_url) {
      navigate(notification.link_url)
    }
    if (!notification.read_at && hasReadyContext) {
      const { error } = await notificationService.markAsRead(context, notification.id)
      if (!error) {
        setNotifications((prev) =>
          prev.map((n) => (n.id === notification.id ? { ...n, read_at: new Date().toISOString() } : n))
        )
      }
    }
    setOpen(false)
  }

  // Early return after all hooks are called
  if (!hasReadyContext) {
    return null
  }

  const presentationTone = (presentation: NotificationPresentation) => {
    switch (presentation) {
      case 'urgent':
        return 'notif-chip--urgent'
      case 'warning':
        return 'notif-chip--warn'
      default:
        return 'notif-chip--info'
    }
  }

  return (
    <div className="gn-notif" ref={containerRef}>
      <button
        className={cn('gn-util-btn', unreadCount > 0 && 'gn-util-btn--active')}
        aria-label={t('portal.settings.notifications.title')}
        title={t('portal.settings.notifications.title')}
        onClick={handleToggle}
        type="button"
      >
        <span className="material-symbols-outlined">notifications</span>
        {unreadCount > 0 && <span className="gn-notif-badge">{unreadCount}</span>}
      </button>

      <div className={cn('gn-notif-panel', open && 'open')} role="menu" aria-label={t('portal.settings.notifications.title')}>
        <div className="gn-notif-header">
          <span className="gn-notif-title">{t('portal.settings.notifications.title')}</span>
          <button
            className="gn-notif-link"
            type="button"
            onClick={() => navigate(viewAllPath)}
          >
            {t('portal.settings.notifications.viewAll')}
          </button>
        </div>

        {loading && <div className="gn-notif-empty">{t('portal.settings.notifications.loading')}</div>}
        {error && !loading && <div className="gn-notif-empty">{error}</div>}
        {!loading && !error && notifications.length === 0 && (
          <div className="gn-notif-empty">{t('portal.settings.notifications.empty')}</div>
        )}

        {!loading && !error && notifications.length > 0 && (
          <ul className="gn-notif-list">
            {notifications.map((notif) => (
              <li key={notif.id} className={cn('gn-notif-item', !notif.read_at && 'gn-notif-item--unread')}>
                <button className="gn-notif-row" type="button" onClick={() => handleOpenNotification(notif)}>
                  <div className={cn('notif-chip', presentationTone(notif.presentation_type))}>{notif.presentation_type}</div>
                  <div className="gn-notif-content">
                    <div className="gn-notif-title-row">
                      <span className="gn-notif-text gn-notif-text--title">{notif.title}</span>
                      {notif.entity_type && (
                        <span className="gn-notif-entity">{notif.entity_type}</span>
                      )}
                    </div>
                    <span className="gn-notif-text gn-notif-text--body">{notif.body}</span>
                  </div>
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useI18n } from '../../i18n/useI18n'
import { showError, showSuccess } from '../../utils/toast'
import { ConfirmDialog } from '../admin/ConfirmDialog'
import {
  createGalleryAlbum,
  deleteGalleryAlbum,
  getAlbumsForGallery,
  updateGalleryAlbum,
  type GalleryAlbum,
} from '../../data/services/galleryService'
import { useUserContext } from '../../hooks/useUserContext'

interface AlbumManagerProps {
  galleryId: string
  onAlbumsUpdated?: (albums: GalleryAlbum[]) => void
}

export function AlbumManager({ galleryId, onAlbumsUpdated }: AlbumManagerProps) {
  const { context } = useUserContext()
  const { t } = useI18n()
  const [albums, setAlbums] = useState<GalleryAlbum[]>([])
  const [loading, setLoading] = useState(true)
  const [creating, setCreating] = useState(false)
  const [newName, setNewName] = useState('')
  const [newDescription, setNewDescription] = useState('')
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editingName, setEditingName] = useState('')
  const [editingDescription, setEditingDescription] = useState('')
  const [albumToDeleteId, setAlbumToDeleteId] = useState<string | null>(null)

  const loadAlbums = async () => {
    if (!context) return
    setLoading(true)
    const { data, error } = await getAlbumsForGallery(context, galleryId)
    if (error) {
      showError(error.message)
    } else {
      setAlbums(data)
      onAlbumsUpdated?.(data)
    }
    setLoading(false)
  }

  useEffect(() => {
    loadAlbums()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [galleryId])

  const handleCreate = async () => {
    if (!context) return
    if (!newName.trim()) {
      showError(t('photos.albums.nameRequired'))
      return
    }
    setCreating(true)
    const { data, error } = await createGalleryAlbum(context, galleryId, newName.trim(), newDescription)
    if (error || !data) {
      showError(error?.message || t('photos.albums.createError'))
      setCreating(false)
      return
    }
    showSuccess(t('photos.albums.created'))
    setNewName('')
    setNewDescription('')
    await loadAlbums()
    setCreating(false)
  }

  const startEdit = (album: GalleryAlbum) => {
    setEditingId(album.id)
    setEditingName(album.name)
    setEditingDescription(album.description || '')
  }

  const handleSaveEdit = async () => {
    if (!context || !editingId) return
    if (!editingName.trim()) {
      showError(t('photos.albums.nameRequired'))
      return
    }
    const { data, error } = await updateGalleryAlbum(context, editingId, {
      name: editingName.trim(),
      description: editingDescription,
    })
    if (error || !data) {
      showError(error?.message || t('photos.albums.updateError'))
      return
    }
    showSuccess(t('photos.albums.updated'))
    setEditingId(null)
    await loadAlbums()
  }

  const handleDelete = (albumId: string) => {
    setAlbumToDeleteId(albumId)
  }

  const confirmDelete = async (albumId: string) => {
    if (!context) return
    const { error } = await deleteGalleryAlbum(context, albumId)
    if (error) {
      showError(error.message)
      return
    }
    showSuccess(t('photos.albums.deleted'))
    await loadAlbums()
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-bold">{t('photos.albums.title')}</h3>
      </div>

      <div className="rounded-lg border border-slate-200 dark:border-slate-700 p-4 space-y-3">
        <div className="grid gap-3 md:grid-cols-3">
          <div className="md:col-span-1">
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-1">
              {t('photos.albums.nameLabel')}
            </label>
            <input
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              className="w-full h-10 rounded-md border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 px-3 text-sm"
              placeholder={t('photos.albums.namePlaceholder')}
            />
          </div>
          <div className="md:col-span-2">
            <label className="block text-xs font-semibold uppercase tracking-wider text-slate-500 mb-1">
              {t('photos.albums.descriptionLabel')}
            </label>
            <input
              value={newDescription}
              onChange={(e) => setNewDescription(e.target.value)}
              className="w-full h-10 rounded-md border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 px-3 text-sm"
              placeholder={t('photos.albums.descriptionPlaceholder')}
            />
          </div>
        </div>
        <button
          type="button"
          onClick={handleCreate}
          disabled={creating}
          className="px-4 py-2 rounded-md bg-slate-900 text-white text-sm font-semibold disabled:opacity-60"
        >
          {creating ? t('photos.albums.creating') : t('photos.albums.create')}
        </button>
      </div>

      <div className="space-y-2">
        {loading ? (
          <div className="text-sm text-slate-500">{t('common.loading')}</div>
        ) : albums.length === 0 ? (
          <div className="text-sm text-slate-500">{t('photos.albums.empty')}</div>
        ) : (
          albums.map((album) => (
            <div key={album.id} className="rounded-lg border border-slate-200 dark:border-slate-700 p-3">
              {editingId === album.id ? (
                <div className="space-y-2">
                  <input
                    value={editingName}
                    onChange={(e) => setEditingName(e.target.value)}
                    className="w-full h-10 rounded-md border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 px-3 text-sm"
                  />
                  <input
                    value={editingDescription}
                    onChange={(e) => setEditingDescription(e.target.value)}
                    className="w-full h-10 rounded-md border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 px-3 text-sm"
                  />
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={handleSaveEdit}
                      className="px-3 py-2 rounded-md bg-slate-900 text-white text-xs font-semibold"
                    >
                      {t('common.save')}
                    </button>
                    <button
                      type="button"
                      onClick={() => setEditingId(null)}
                      className="px-3 py-2 rounded-md border border-slate-300 text-xs font-semibold"
                    >
                      {t('common.cancel')}
                    </button>
                  </div>
                </div>
              ) : (
                <div className="flex flex-col gap-2 md:flex-row md:items-center md:justify-between">
                  <div>
                    <div className="text-sm font-semibold text-slate-900 dark:text-white">{album.name}</div>
                    {album.description && (
                      <div className="text-xs text-slate-500">{album.description}</div>
                    )}
                  </div>
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={() => startEdit(album)}
                      className="px-3 py-1.5 rounded-md border border-slate-300 text-xs font-semibold"
                    >
                      {t('common.edit')}
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDelete(album.id)}
                      className="px-3 py-1.5 rounded-md border border-red-300 text-red-600 text-xs font-semibold"
                    >
                      {t('common.delete')}
                    </button>
                  </div>
                </div>
              )}
            </div>
          ))
        )}
      </div>

      <ConfirmDialog
        open={albumToDeleteId !== null}
        title={t('common.delete')}
        description={t('photos.albums.deleteConfirm')}
        confirmLabel={t('common.delete')}
        cancelLabel={t('common.cancel')}
        variant="danger"
        onConfirm={() => {
          const albumId = albumToDeleteId
          setAlbumToDeleteId(null)
          if (albumId) {
            void confirmDelete(albumId)
          }
        }}
        onCancel={() => setAlbumToDeleteId(null)}
      />
    </div>
  )
}

/**
 * Moderation Queue Component
 * 
 * Displays pending photos for moderation with approve/reject actions.
 */

import { useEffect, useState } from 'react'
import { useUserContext } from '../../hooks/useUserContext'
import { useT } from '../../i18n/useI18n'
import { supabase } from '../../lib/supabase'
import {
  getPhotosForGallery,
  moderatePhotos,
  getGalleryPhotoUrl,
  type GalleryPhoto,
} from '../../data/services/galleryService'
import Card from '../portal/Card'
import Button from '../portal/Button'
import Icon from '../portal/Icon'
import { showError, showSuccess } from '../../utils/toast'

interface ModerationQueueProps {
  galleryId: string
  onModerationComplete?: () => void
}

export function ModerationQueue({ galleryId, onModerationComplete }: ModerationQueueProps) {
  const { context, isReady } = useUserContext()
  const t = useT()
  const [pendingPhotos, setPendingPhotos] = useState<GalleryPhoto[]>([])
  const [loading, setLoading] = useState(true)
  const [selectedPhotos, setSelectedPhotos] = useState<Set<string>>(new Set())
  const [moderating, setModerating] = useState(false)

  useEffect(() => {
    if (!isReady || !galleryId) return

    const loadPendingPhotos = async () => {
      setLoading(true)
      const { data, error } = await getPhotosForGallery(context, {
        gallery_id: galleryId,
        status: 'pending',
      })

      if (error) {
        showError(t('gallery.moderationQueue.loadingError', { message: error.message }))
        setLoading(false)
        return
      }

      setPendingPhotos(data || [])
      setLoading(false)
    }

    loadPendingPhotos()
  }, [context, isReady, galleryId])

  const togglePhotoSelection = (photoId: string) => {
    setSelectedPhotos((prev) => {
      const next = new Set(prev)
      if (next.has(photoId)) {
        next.delete(photoId)
      } else {
        next.add(photoId)
      }
      return next
    })
  }

  const handleModerate = async (action: 'approve' | 'reject') => {
    if (selectedPhotos.size === 0) {
      showError('Please select at least one photo')
      return
    }

    setModerating(true)
    
    try {
      // Call Edge Function for moderation (which handles email notifications)
      const { error: functionError } = await supabase.functions.invoke(
        'moderate-photo-submission',
        {
          body: {
            photoIds: Array.from(selectedPhotos),
            action,
            galleryId,
          },
        }
      )

      if (functionError) {
        // Fallback to direct DB update if Edge Function fails
        const { error } = await moderatePhotos(context, Array.from(selectedPhotos), action)
        if (error) {
          throw error
        }
      }

      showSuccess(t(`gallery.moderationQueue.${action}Success`))
      setSelectedPhotos(new Set())
      
      // Reload pending photos
      const { data } = await getPhotosForGallery(context, {
        gallery_id: galleryId,
        status: 'pending',
      })
      setPendingPhotos(data || [])
      
      onModerationComplete?.()
    } catch (err) {
      showError(t(`gallery.moderationQueue.${action}Error`))
    } finally {
      setModerating(false)
    }
  }

  if (loading) {
    return (
      <Card>
        <div className="text-center py-8">
          <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-500 mx-auto"></div>
          <p className="text-sm text-slate-500 dark:text-slate-400 mt-4">Loading pending photos...</p>
        </div>
      </Card>
    )
  }

  if (pendingPhotos.length === 0) {
    return (
      <Card>
        <div className="text-center py-12">
          <Icon name="check_circle" size="text-6xl" className="text-green-500 mb-4 mx-auto" />
          <p className="text-lg font-semibold mb-2">All caught up!</p>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            No photos pending moderation.
          </p>
        </div>
      </Card>
    )
  }

  return (
    <div className="space-y-4">
      {/* Bulk actions */}
      {selectedPhotos.size > 0 && (
        <Card className="bg-blue-50 dark:bg-blue-900/20 border-blue-200 dark:border-blue-800">
          <div className="flex items-center justify-between">
            <span className="font-semibold">
              {t('gallery.moderationQueue.selectedPhotos', { 
                count: selectedPhotos.size, 
                plural: selectedPhotos.size !== 1 ? 's' : '' 
              })}
            </span>
            <div className="flex gap-2">
              <Button
                variant="primary"
                onClick={() => handleModerate('approve')}
                disabled={moderating}
              >
                <Icon name="check" size="text-sm" className="mr-2" />
                {t('gallery.moderationQueue.approve')}
              </Button>
              <Button
                variant="primary"
                onClick={() => handleModerate('reject')}
                disabled={moderating}
              >
                <Icon name="close" size="text-sm" className="mr-2" />
                {t('gallery.moderationQueue.reject')}
              </Button>
              <Button
                variant="secondary"
                onClick={() => setSelectedPhotos(new Set())}
              >
                {t('gallery.moderationQueue.clear')}
              </Button>
            </div>
          </div>
        </Card>
      )}

      {/* Photo grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
        {pendingPhotos.map((photo) => {
          const photoUrl = getGalleryPhotoUrl(photo.storage_path)
          const isSelected = selectedPhotos.has(photo.id)
          
          return (
            <Card
              key={photo.id}
              className={`cursor-pointer transition-all ${
                isSelected ? 'ring-2 ring-blue-500' : ''
              }`}
              onClick={() => togglePhotoSelection(photo.id)}
            >
              <div className="relative aspect-square rounded-lg overflow-hidden mb-2 bg-slate-100 dark:bg-slate-800">
                <img
                  src={photoUrl}
                  alt={`Pending photo ${photo.id}`}
                  className="w-full h-full object-cover"
                  loading="lazy"
                />
                {isSelected && (
                  <div className="absolute inset-0 bg-blue-500/20 flex items-center justify-center">
                    <div className="bg-blue-500 text-white rounded-full p-2">
                      <Icon name="check" size="text-xl" />
                    </div>
                  </div>
                )}
              </div>
              <div className="text-xs text-slate-500 dark:text-slate-400">
                Uploaded {new Date(photo.created_at).toLocaleDateString()}
              </div>
            </Card>
          )
        })}
      </div>
    </div>
  )
}

/**
 * QRCodeScanner Component
 * 
 * Camera-based QR code scanner using html5-qrcode library.
 * Handles camera lifecycle, iOS permissions, adaptive FPS, and cleanup.
 */

import { useEffect, useRef, useState, useCallback, useMemo, useImperativeHandle, forwardRef } from 'react'
import { Html5Qrcode, Html5QrcodeScannerState } from 'html5-qrcode'
import { Camera, AlertCircle, Loader2, RotateCcw, ArrowDown } from 'lucide-react'
import { useT } from '@/i18n/useI18n'

export interface QRCodeScannerHandle {
  resume: () => void
}

interface QRCodeScannerProps {
  onScan: (decodedText: string) => void
  onError?: (error: string) => void
  isEnabled: boolean
}

/**
 * QRCodeScanner Component
 * 
 * Manages camera lifecycle and QR code scanning with:
 * - iOS permission handling
 * - Adaptive FPS based on device performance
 * - Multiple cleanup triggers
 * - Graceful degradation
 */
export const QRCodeScanner = forwardRef<QRCodeScannerHandle, QRCodeScannerProps>(
  ({ onScan, onError, isEnabled }, ref) => {
    const t = useT()
    const scannerRef = useRef<Html5Qrcode | null>(null)
    const containerIdRef = useRef(`qr-scanner-${Date.now()}-${Math.random().toString(36).slice(2)}`)
    
    const [cameraState, setCameraState] = useState<'idle' | 'starting' | 'active' | 'error'>('idle')
    const [facingMode, setFacingMode] = useState<'environment' | 'user'>('environment')
    const [fps, setFps] = useState(10)
    const [showManualPrompt, setShowManualPrompt] = useState(false)
    const [lastScanTime, setLastScanTime] = useState(0)
    
    // Refs to prevent double-start issues (React Strict Mode, effect re-runs)
    const isStartingRef = useRef(false)
    const isStoppingRef = useRef(false)
    const mountedRef = useRef(true)
    
    // Detect iOS for special handling
    const isIOS = useMemo(() => {
      if (typeof window === 'undefined') return false
      return /iPad|iPhone|iPod/.test(navigator.userAgent) && !(window as any).MSStream
    }, [])
    
    // Recently scanned tokens (debounce)
    const recentlyScanned = useRef(new Set<string>())
    
    // Performance monitoring for adaptive FPS
    const decodeTimes = useRef<number[]>([])
    
    // Start camera function
    const startCamera = useCallback(async () => {
      // Guard against double-start (Strict Mode, effect re-runs, race conditions)
      if (isStartingRef.current || isStoppingRef.current || scannerRef.current) {
        return
      }
      
      isStartingRef.current = true
      setCameraState('starting')
      
      try {
        // Create scanner instance
        const scanner = new Html5Qrcode(containerIdRef.current)
        scannerRef.current = scanner
        
        // Configuration
        const config = {
          fps: fps,
          qrbox: { width: 250, height: 250 },
          aspectRatio: 1.0,
          disableFlip: false,
        }
        
        // Success callback with debounce and performance tracking
        const onScanSuccess = (decodedText: string, result: any) => {
          const decodeTime = result?.decodeDurationInMs || 0
          
          // Track decode times for adaptive FPS
          if (decodeTime > 0) {
            decodeTimes.current.push(decodeTime)
            if (decodeTimes.current.length > 5) {
              decodeTimes.current.shift()
            }
            
            const avgTime = decodeTimes.current.reduce((a, b) => a + b, 0) / decodeTimes.current.length
            if (avgTime > 150 && fps > 5) {
              setFps(5) // Reduce FPS on slow devices
            }
          }
          
          // Debounce: skip if scanned in last 5 seconds
          if (recentlyScanned.current.has(decodedText)) {
            return
          }
          
          // Add to recently scanned with TTL
          recentlyScanned.current.add(decodedText)
          setTimeout(() => {
            recentlyScanned.current.delete(decodedText)
          }, 5000)
          
          // Reset manual prompt timer
          setLastScanTime(Date.now())
          setShowManualPrompt(false)
          
          // Pause scanner during validation
          scanner.pause(true) // true = show paused frame
          
          // Call parent handler
          onScan(decodedText)
        }
        
        // Error callback (ignore "QR not found" - expected during scanning)
        const onScanError = (errorMessage: string) => {
          // Only log actual errors, not "QR code not found"
          if (!errorMessage.includes('No QR code found') && !errorMessage.includes('NotFoundException')) {
            console.warn('Scan error:', errorMessage)
          }
        }
        
        // Start scanning
        await scanner.start(
          { facingMode: facingMode },
          config,
          onScanSuccess,
          onScanError
        )
        
        // Only update state if still mounted
        if (mountedRef.current) {
          setCameraState('active')
          setLastScanTime(Date.now())
        }
        
      } catch (error: any) {
        if (mountedRef.current) {
          setCameraState('error')
          
          // Parse error for user-friendly message
          let errorMessage = 'Camera unavailable'
          if (error?.message?.includes('Permission') || error?.message?.includes('permission')) {
            errorMessage = 'Camera permission denied'
          } else if (error?.message?.includes('NotFound') || error?.message?.includes('not found')) {
            errorMessage = 'No camera found'
          } else if (error?.message?.includes('NotReadable') || error?.message?.includes('in use')) {
            errorMessage = 'Camera in use by another app'
          }
          
          onError?.(errorMessage)
        }
      } finally {
        isStartingRef.current = false
      }
    }, [facingMode, fps, onScan, onError])
    
    // Stop camera function
    const stopCamera = useCallback(async () => {
      // Guard against concurrent stop calls
      if (isStoppingRef.current) {
        return
      }
      
      isStoppingRef.current = true
      
      const scanner = scannerRef.current
      if (scanner) {
        try {
          const state = scanner.getState()
          if (state === Html5QrcodeScannerState.SCANNING || 
              state === Html5QrcodeScannerState.PAUSED) {
            await scanner.stop()
          }
        } catch {
          // Ignore stop errors
        } finally {
          scannerRef.current = null
        }
      }
      
      if (mountedRef.current) {
        setCameraState('idle')
      }
      
      isStoppingRef.current = false
    }, [])
    
    // Resume scanner (called after validation completes)
    const resumeScanner = useCallback(() => {
      const scanner = scannerRef.current
      if (scanner && scanner.getState() === Html5QrcodeScannerState.PAUSED) {
        scanner.resume()
        setLastScanTime(Date.now())
      }
    }, [])
    
    // Expose resume function to parent
    useImperativeHandle(ref, () => ({
      resume: resumeScanner
    }), [resumeScanner])
    
    // Toggle camera facing mode
    const toggleCamera = useCallback(async () => {
      await stopCamera()
      setFacingMode(prev => prev === 'environment' ? 'user' : 'environment')
      // Will restart via useEffect
    }, [stopCamera])
    
    // Manual prompt timer
    useEffect(() => {
      if (cameraState !== 'active') {
        return
      }
      
      const timer = setInterval(() => {
        const timeSinceLastScan = Date.now() - lastScanTime
        if (timeSinceLastScan > 8000 && !showManualPrompt) {
          setShowManualPrompt(true)
        }
      }, 1000)
      
      return () => clearInterval(timer)
    }, [cameraState, lastScanTime, showManualPrompt])
    
    // Track mounted state for cleanup
    useEffect(() => {
      mountedRef.current = true
      return () => {
        mountedRef.current = false
      }
    }, [])
    
    // Start/stop camera based on isEnabled and facingMode
    // Using refs in guards means we don't need startCamera/stopCamera in deps
    useEffect(() => {
      if (isEnabled && !isIOS) {
        // Only start if idle and not already starting/stopping
        if (cameraState === 'idle' && !isStartingRef.current && !isStoppingRef.current) {
          startCamera()
        }
      } else if (!isEnabled && cameraState === 'active') {
        stopCamera()
      }
      // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isEnabled, facingMode, isIOS, cameraState])
    
    // Visibility change handler
    useEffect(() => {
      const handleVisibilityChange = () => {
        const scanner = scannerRef.current
        if (!scanner) return
        
        try {
          if (document.visibilityState === 'hidden') {
            if (scanner.getState() === Html5QrcodeScannerState.SCANNING) {
              scanner.pause(true)
            }
          } else {
            if (scanner.getState() === Html5QrcodeScannerState.PAUSED) {
              scanner.resume()
              setLastScanTime(Date.now())
            }
          }
        } catch {
          // Ignore errors
        }
      }
      
      document.addEventListener('visibilitychange', handleVisibilityChange)
      return () => document.removeEventListener('visibilitychange', handleVisibilityChange)
    }, [])
    
    // Beforeunload cleanup
    useEffect(() => {
      const handleBeforeUnload = () => {
        // Synchronous - just clear the ref, browser will release camera
        scannerRef.current = null
      }
      
      window.addEventListener('beforeunload', handleBeforeUnload)
      return () => window.removeEventListener('beforeunload', handleBeforeUnload)
    }, [])
    
    // Component unmount cleanup
    useEffect(() => {
      return () => {
        // Mark as unmounted first to prevent state updates
        mountedRef.current = false
        // Then stop camera
        const scanner = scannerRef.current
        if (scanner) {
          try {
            const state = scanner.getState()
            if (state === Html5QrcodeScannerState.SCANNING || 
                state === Html5QrcodeScannerState.PAUSED) {
              scanner.stop().catch(() => {})
            }
          } catch {
            // Ignore errors during cleanup
          }
          scannerRef.current = null
        }
      }
    }, [])
    
    return (
      <div className="qr-scanner-wrapper relative w-full">
        {/* Camera viewport */}
        <div 
          id={containerIdRef.current}
          className="qr-scanner-viewport w-full"
        />
        
        {/* iOS: Explicit start button */}
        {isIOS && cameraState === 'idle' && isEnabled && (
          <div className="absolute inset-0 flex items-center justify-center bg-gray-900/80 z-10">
            <button 
              onClick={startCamera} 
              className="bg-[#137fec] text-white px-6 py-3 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-700 transition-colors"
            >
              <Camera className="w-5 h-5" />
              {t('ticketing.scanner.tapToStartCamera')}
            </button>
          </div>
        )}
        
        {/* Starting state */}
        {cameraState === 'starting' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900/80 z-10">
            <Loader2 className="w-8 h-8 text-white animate-spin mb-2" />
            <p className="text-white text-sm">{t('ticketing.scanner.startingCamera')}</p>
          </div>
        )}
        
        {/* Error state */}
        {cameraState === 'error' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-gray-900/80 z-10">
            <AlertCircle className="w-8 h-8 text-red-400 mb-2" />
            <p className="text-white text-sm mb-1">{t('ticketing.scanner.cameraUnavailable')}</p>
            <p className="text-gray-400 text-xs">{t('ticketing.scanner.useManualEntry')}</p>
          </div>
        )}
        
        {/* Active scanning indicator */}
        {cameraState === 'active' && (
          <>
            <div className="absolute top-4 left-1/2 transform -translate-x-1/2 bg-[#137fec] text-white px-4 py-2 rounded-full text-sm font-bold flex items-center gap-2 z-10">
              <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
              {t('ticketing.scanner.scanning')}
            </div>
            
            {/* Camera flip button */}
            <button 
              onClick={toggleCamera}
              className="absolute top-4 right-4 bg-gray-900/80 text-white p-2 rounded-full hover:bg-gray-800 transition-colors z-10"
              aria-label={t('ticketing.scanner.switchCamera')}
            >
              <RotateCcw className="w-5 h-5" />
            </button>
            
            {/* Low performance indicator */}
            {fps < 10 && (
              <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 bg-amber-500/80 text-white px-3 py-1 rounded-full text-xs z-10">
                {t('ticketing.scanner.lowPerformanceMode')}
              </div>
            )}
          </>
        )}
        
        {/* Manual entry prompt after timeout */}
        {showManualPrompt && cameraState === 'active' && (
          <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 bg-white/90 dark:bg-gray-800/90 text-gray-900 dark:text-white px-4 py-3 rounded-lg shadow-lg z-10 max-w-xs text-center">
            <p className="text-sm font-semibold mb-1">{t('ticketing.scanner.troubleScanning')}</p>
            <p className="text-xs text-gray-600 dark:text-gray-400 mb-2">{t('ticketing.scanner.enterManually')}</p>
            <ArrowDown className="w-4 h-4 mx-auto animate-bounce" />
          </div>
        )}
      </div>
    )
  }
)

QRCodeScanner.displayName = 'QRCodeScanner'

/**
 * VideoPlayer Component
 * 
 * Mux-powered video player with signed playback support.
 * Wraps the Mux Player web component with React integration.
 */

import { useEffect, useRef, useState, useCallback, useImperativeHandle, forwardRef } from 'react'
import { usePlaybackToken } from '@/hooks/useVideos'
import { useOrganization } from '@/contexts/OrganizationContext'
import Icon from '@/components/portal/Icon'
import { cn } from '@/utils/cn'

export interface VideoPlayerRef {
  seekTo: (seconds: number) => void
  getCurrentTime: () => number
  play: () => void
  pause: () => void
}

interface VideoPlayerProps {
  videoId: string
  /** Video processing status — if not 'ready', shows a placeholder instead of the player */
  status?: string
  autoPlay?: boolean
  muted?: boolean
  loop?: boolean
  controls?: boolean
  startTime?: number
  poster?: string
  title?: string
  chapters?: Array<{
    startTime: number
    endTime?: number
    value: string
  }>
  onReady?: () => void
  onPlay?: () => void
  onPause?: () => void
  onTimeUpdate?: (currentTime: number) => void
  onEnded?: () => void
  onError?: (error: Error) => void
  className?: string
  markers?: Array<{
    time: number
    label?: string
    color?: string
  }>
  onMarkerClick?: (marker: { time: number; label?: string }) => void
}

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace JSX {
    interface IntrinsicElements {
      'mux-player': React.DetailedHTMLProps<
        React.HTMLAttributes<HTMLElement> & {
          'playback-id'?: string
          'playback-token'?: string
          'thumbnail-token'?: string
          'storyboard-token'?: string
          'stream-type'?: 'on-demand' | 'live'
          'start-time'?: number
          autoplay?: boolean
          muted?: boolean
          loop?: boolean
          poster?: string
          title?: string
          'primary-color'?: string
          'secondary-color'?: string
          'accent-color'?: string
        },
        HTMLElement
      >
    }
  }
}

/** Map our chapter shape to Mux Player API. Pass both title and value so any player version works; never pass undefined. */
function toMuxChapters(
  ch: Array<{ startTime: number; endTime?: number; value: string }>
): Array<{ startTime: number; endTime?: number; title: string; value: string }> {
  return ch.map((c) => {
    const label = c.value ?? ''
    return { startTime: c.startTime, endTime: c.endTime, title: label, value: label }
  })
}

// Load Mux Player script
function loadMuxPlayerScript(): Promise<void> {
  return new Promise((resolve, reject) => {
    if (document.querySelector('script[src*="mux-player"]')) {
      resolve()
      return
    }
    
    const script = document.createElement('script')
    script.src = 'https://cdn.jsdelivr.net/npm/@mux/mux-player@2'
    script.async = true
    script.onload = () => resolve()
    script.onerror = () => reject(new Error('Failed to load Mux Player script'))
    document.head.appendChild(script)
  })
}

const VideoPlayer = forwardRef<VideoPlayerRef, VideoPlayerProps>(({
  videoId,
  status,
  autoPlay = false,
  muted = false,
  loop = false,
  controls: _controls = true,
  startTime,
  poster,
  title,
  chapters = [],
  onReady,
  onPlay,
  onPause,
  onTimeUpdate,
  onEnded,
  onError,
  className,
  markers = [],
  onMarkerClick
}, ref) => {
  const playerRef = useRef<HTMLElement>(null)
  const nativeVideoRef = useRef<HTMLVideoElement>(null)
  const [isScriptLoaded, setIsScriptLoaded] = useState(false)
  const [playerError, setPlayerError] = useState<string | null>(null)
  const [currentTime, setCurrentTime] = useState(0)
  const [duration, setDuration] = useState(0)
  const [_isPlaying, setIsPlaying] = useState(false)
  
  // Track the latest chapters in a ref so the loadedmetadata callback always sees them
  const chaptersRef = useRef(chapters)
  chaptersRef.current = chapters
  
  // Get organization theme color
  const { currentOrganization } = useOrganization()
  const accentColor = (currentOrganization as { primary_color?: string } | null)?.primary_color || '#137fec'
  
  // Get playback token from edge function
  const isReady = !status || status === 'ready'
  const { playbackData, isLoading, error: tokenError } = usePlaybackToken({
    videoId,
    type: 'video',
    enabled: !!videoId && isReady
  })
  const directStreamUrl = playbackData?.stream_url || ''
  const isDirectVideoSource =
    directStreamUrl.startsWith('/demo-assets/videos/') || /\.mp4($|\?)/i.test(directStreamUrl)
  
  // Load Mux Player script on mount
  useEffect(() => {
    if (isDirectVideoSource) {
      setPlayerError(null)
      return
    }

    loadMuxPlayerScript()
      .then(() => setIsScriptLoaded(true))
      .catch((err) => {
        setPlayerError(err.message)
        onError?.(err)
      })
  }, [onError, isDirectVideoSource])
  
  // Set up player event listeners and chapters
  useEffect(() => {
    if (isDirectVideoSource) return
    const player = playerRef.current as any
    if (!player || !isScriptLoaded) return
    
    const handleLoadedMetadata = () => {
      setDuration(player.duration || 0)
      onReady?.()
      
      // Add chapters once metadata is loaded (per Mux docs; API expects title, not value)
      const ch = chaptersRef.current
      if (ch.length > 0 && typeof player.addChapters === 'function') {
        try {
          player.addChapters(toMuxChapters(ch))
        } catch (err) {
          console.warn('Failed to add chapters on loadedmetadata:', err)
        }
      }
    }
    
    const handlePlay = () => {
      setIsPlaying(true)
      onPlay?.()
    }
    
    const handlePause = () => {
      setIsPlaying(false)
      onPause?.()
      if (player?.currentTime !== undefined) {
        onTimeUpdate?.(player.currentTime)
      }
    }
    
    const handleTimeUpdate = () => {
      const time = player.currentTime || 0
      setCurrentTime(time)
      onTimeUpdate?.(time)
    }
    
    const handleEnded = () => {
      setIsPlaying(false)
      onEnded?.()
    }
    
    const handleError = () => {
      const err = new Error('Video playback error')
      setPlayerError(err.message)
      onError?.(err)
    }
    
    // mux-player dispatches standard media events on itself, so listen directly
    player.addEventListener('loadedmetadata', handleLoadedMetadata)
    player.addEventListener('play', handlePlay)
    player.addEventListener('pause', handlePause)
    player.addEventListener('timeupdate', handleTimeUpdate)
    player.addEventListener('ended', handleEnded)
    player.addEventListener('error', handleError)
    
    // If metadata was already loaded before this effect ran, handle immediately
    if (player.readyState >= 1) {
      handleLoadedMetadata()
    }
    
    return () => {
      player.removeEventListener('loadedmetadata', handleLoadedMetadata)
      player.removeEventListener('play', handlePlay)
      player.removeEventListener('pause', handlePause)
      player.removeEventListener('timeupdate', handleTimeUpdate)
      player.removeEventListener('ended', handleEnded)
      player.removeEventListener('error', handleError)
    }
  }, [isScriptLoaded, onReady, onPlay, onPause, onTimeUpdate, onEnded, onError, isDirectVideoSource])
  
  // Re-add chapters when the chapters prop changes after initial load (e.g. bookmarks loaded late)
  useEffect(() => {
    if (isDirectVideoSource) return
    const player = playerRef.current as any
    if (!player || !isScriptLoaded || chapters.length === 0) return

    const applyChapters = () => {
      if (typeof player.addChapters !== 'function') return
      try {
        player.addChapters(toMuxChapters(chapters))
      } catch (err) {
        console.warn('Failed to update chapters:', err)
      }
    }

    if (player.readyState >= 1) {
      applyChapters()
    } else {
      // Chapters arrived before metadata; apply once the player is ready
      player.addEventListener('loadedmetadata', applyChapters, { once: true })
      return () => player.removeEventListener('loadedmetadata', applyChapters)
    }
  }, [isScriptLoaded, chapters, isDirectVideoSource])

  // Seek to a specific time
  const seekTo = useCallback((time: number) => {
    const player = (nativeVideoRef.current as any) || (playerRef.current as any)
    if (player) {
      player.currentTime = time
    }
  }, [])

  // Get current time
  const getCurrentTime = useCallback((): number => {
    const player = (nativeVideoRef.current as any) || (playerRef.current as any)
    return player?.currentTime ?? currentTime
  }, [currentTime])

  // Play
  const play = useCallback(() => {
    const player = (nativeVideoRef.current as any) || (playerRef.current as any)
    if (player && typeof player.play === 'function') {
      player.play()
    }
  }, [])

  // Pause
  const pause = useCallback(() => {
    const player = (nativeVideoRef.current as any) || (playerRef.current as any)
    if (player && typeof player.pause === 'function') {
      player.pause()
    }
  }, [])

  // Expose API via ref
  useImperativeHandle(ref, () => ({
    seekTo,
    getCurrentTime,
    play,
    pause
  }), [seekTo, getCurrentTime, play, pause])
  
  // Handle marker click
  const handleMarkerClick = useCallback((marker: { time: number; label?: string }) => {
    seekTo(marker.time)
    onMarkerClick?.(marker)
  }, [seekTo, onMarkerClick])
  
  // Show status message for non-ready videos (after all hooks)
  if (!isReady) {
    const statusMessages: Record<string, { icon: string; title: string; subtitle: string }> = {
      pending_upload: {
        icon: 'cloud_upload',
        title: 'Upload Pending',
        subtitle: 'This video is waiting to be uploaded.'
      },
      uploading: {
        icon: 'cloud_upload',
        title: 'Uploading...',
        subtitle: 'This video is currently being uploaded.'
      },
      processing: {
        icon: 'hourglass_top',
        title: 'Processing...',
        subtitle: 'This video is being processed by Mux. This usually takes a few minutes.'
      },
      errored: {
        icon: 'error',
        title: 'Processing Failed',
        subtitle: 'There was an error processing this video.'
      },
    }
    const msg = statusMessages[status] || statusMessages.pending_upload
    
    return (
      <div className="relative w-full bg-black" style={{ aspectRatio: '16/9' }}>
        <div className="absolute inset-0 flex flex-col items-center justify-center text-white text-center p-8">
          {status === 'processing' || status === 'uploading' ? (
            <div className="size-12 border-4 border-white/30 border-t-white rounded-full animate-spin mb-4" />
          ) : (
            <Icon name={msg.icon} size="text-5xl" className="mb-4 text-white/70" />
          )}
          <h3 className="text-lg font-bold mb-1">{msg.title}</h3>
          <p className="text-sm text-white/60">{msg.subtitle}</p>
        </div>
      </div>
    )
  }
  
  // Loading state (after all hooks)
  if (isLoading || (!isDirectVideoSource && !isScriptLoaded)) {
    return (
      <div className={cn(
        "relative w-full aspect-video rounded-2xl overflow-hidden bg-slate-900 flex items-center justify-center",
        className
      )}>
        <div className="flex flex-col items-center gap-4 text-white">
          <div className="size-12 border-4 border-white/20 border-t-white rounded-full animate-spin" />
          <span className="text-sm font-medium">Loading player...</span>
        </div>
      </div>
    )
  }
  
  // Error state
  if (tokenError || playerError) {
    return (
      <div className={cn(
        "relative w-full aspect-video rounded-2xl overflow-hidden bg-slate-900 flex items-center justify-center",
        className
      )}>
        <div className="flex flex-col items-center gap-4 text-white text-center p-8">
          <Icon name="error" size="text-4xl" className="text-red-400" />
          <span className="text-sm font-medium">
            {tokenError?.message || playerError || 'Failed to load video'}
          </span>
        </div>
      </div>
    )
  }
  
  if (!playbackData) {
    return (
      <div className={cn(
        "relative w-full aspect-video rounded-2xl overflow-hidden bg-slate-900 flex items-center justify-center",
        className
      )}>
        <div className="flex flex-col items-center gap-4 text-white">
          <Icon name="videocam_off" size="text-4xl" className="text-slate-400" />
          <span className="text-sm font-medium">Video not available</span>
        </div>
      </div>
    )
  }

  if (isDirectVideoSource) {
    return (
      <div className={cn("relative w-full", className)}>
        <video
          ref={nativeVideoRef}
          src={directStreamUrl}
          poster={poster || playbackData.thumbnail_url}
          autoPlay={autoPlay}
          muted={muted}
          loop={loop}
          controls={_controls}
          playsInline
          className="w-full"
          style={{
            aspectRatio: '16/9',
            borderRadius: '12px',
            overflow: 'hidden',
            background: 'black',
          }}
          onLoadedMetadata={(event) => {
            const element = event.currentTarget
            setDuration(element.duration || 0)
            onReady?.()
          }}
          onPlay={() => {
            setIsPlaying(true)
            onPlay?.()
          }}
          onPause={(event) => {
            setIsPlaying(false)
            onPause?.()
            onTimeUpdate?.(event.currentTarget.currentTime)
          }}
          onTimeUpdate={(event) => {
            const time = event.currentTarget.currentTime || 0
            setCurrentTime(time)
            onTimeUpdate?.(time)
          }}
          onEnded={() => {
            setIsPlaying(false)
            onEnded?.()
          }}
          onError={() => {
            const err = new Error('Video playback error')
