// Export a simple function to format time
export function formatTime(seconds: number): string {
  const mins = Math.floor(seconds / 60)
  const secs = Math.floor(seconds % 60)
  return `${mins}:${String(secs).padStart(2, '0')}`
}

import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react'
import type { DemoSessionSnapshot } from '@/types/demoManagement'
import { normalizeDemoCode } from '@/types/demoManagement'
import {
  clearStoredDemoCode,
  getCurrentDemoSessionSnapshot,
  setStoredDemoCode,
} from '@/data/services/demoSessionService'
import { clearDemoSessionSnapshot } from '@/data/fake/demoDataStore'

interface DemoSessionContextValue {
  session: DemoSessionSnapshot
  loading: boolean
  setPendingDemoCode: (code: string) => void
  clearPendingDemoCode: () => void
  refreshSession: () => void
}

const emptySnapshot: DemoSessionSnapshot = {
  is_demo_session: false,
  demo_org_id: null,
  demo_code: null,
  expires_at: null,
}

const DemoSessionContext = createContext<DemoSessionContextValue | undefined>(undefined)

export function DemoSessionProvider({ children }: { children: ReactNode }) {
  const [session, setSession] = useState<DemoSessionSnapshot>(emptySnapshot)
  const [loading, setLoading] = useState(true)

  const refreshSession = useCallback(() => {
    const snapshot = getCurrentDemoSessionSnapshot()

    if (!snapshot.is_demo_session || !snapshot.expires_at) {
      setSession(emptySnapshot)
      return
    }

    const expiresMs = new Date(snapshot.expires_at).getTime()
    if (Number.isNaN(expiresMs) || expiresMs <= Date.now()) {
      clearStoredDemoCode()
      clearDemoSessionSnapshot()
      setSession(emptySnapshot)
      return
    }

    setSession(snapshot)
  }, [])

  useEffect(() => {
    refreshSession()
    setLoading(false)
  }, [refreshSession])

  const setPendingDemoCode = useCallback((code: string) => {
    const normalized = normalizeDemoCode(code)
    if (!normalized) {
      clearStoredDemoCode()
      return
    }

    setStoredDemoCode(normalized)
  }, [])

  const clearPendingDemoCode = useCallback(() => {
    clearStoredDemoCode()
    clearDemoSessionSnapshot()
    setSession(emptySnapshot)
  }, [])

  const value = useMemo<DemoSessionContextValue>(
    () => ({
      session,
      loading,
      setPendingDemoCode,
      clearPendingDemoCode,
      refreshSession,
    }),
    [session, loading, setPendingDemoCode, clearPendingDemoCode, refreshSession],
  )

  return <DemoSessionContext.Provider value={value}>{children}</DemoSessionContext.Provider>
}

export function useDemoSession(): DemoSessionContextValue {
  const context = useContext(DemoSessionContext)
  if (!context) {
    throw new Error('useDemoSession must be used within a DemoSessionProvider')
  }
  return context
}

import { createContext, useContext, useReducer, useMemo, useCallback, ReactNode } from 'react'

interface LoadingStateContextValue {
  isLoading: boolean
  setLoading: (loading: boolean) => void
}

const LoadingStateContext = createContext<LoadingStateContextValue | undefined>(undefined)

type Action = { type: 'increment' } | { type: 'decrement' }

const reducer = (count: number, action: Action): number => {
  switch (action.type) {
    case 'increment':
      return count + 1
    case 'decrement':
      return Math.max(0, count - 1) // Never go below 0
    default:
      return count
  }
}

interface LoadingStateProviderProps {
  children: ReactNode
}

export function LoadingStateProvider({ children }: LoadingStateProviderProps) {
  const [count, dispatch] = useReducer(reducer, 0)

  const setLoading = useCallback((loading: boolean) => {
    dispatch({ type: loading ? 'increment' : 'decrement' })
  }, [])

  const value = useMemo(() => ({
    isLoading: count > 0,
    setLoading,
  }), [count, setLoading])

  return (
    <LoadingStateContext.Provider value={value}>
      {children}
    </LoadingStateContext.Provider>
  )
}

export function useLoadingState(): LoadingStateContextValue {
  const context = useContext(LoadingStateContext)
  if (context === undefined) {
    throw new Error(
      'useLoadingState must be used within a LoadingStateProvider. ' +
      'Make sure LoadingStateProvider wraps your app in App.tsx'
    )
  }
  return context
}

import { createContext, useContext, useEffect, useState, ReactNode, useCallback } from 'react'
import { supabase } from '@/lib/supabase'
import { useDemoSession } from './DemoSessionContext'
import { readDemoManagementStore } from '@/data/services/demoOrgService'
import { getOrganizationById } from '@/data/fake/fakeOrganizations'

export type OrgMemberRole = 'parent' | 'coach' | 'org_admin' | 'staff' | 'athlete'

export interface Organization {
  id: string
  name: string
  roles: OrgMemberRole[] // NEW: Array of roles user has in this org
  slug?: string
  org_type?: 'school' | 'club' | 'league' | 'academy' | 'aau' | null
  
  // Contact information
  website?: string | null
  phone?: string | null
  email?: string | null
  address?: string | null
  city?: string | null
  state?: string | null
  zip?: string | null
  
  /** @deprecated Use roles array instead. Returns roles[0] or 'parent'. Will be removed in v2.0. */
  get role(): OrgMemberRole
}

interface OrganizationContextType {
  currentOrganization: Organization | null
  organizations: Organization[]
  setOrganizations: (orgs: Organization[]) => void
  setCurrentOrganization: (org: Organization | null) => void
  switchOrganization: (orgId: string) => void
  isLoading: boolean
}

export const OrganizationContext = createContext<OrganizationContextType | undefined>(undefined)

const STORAGE_KEY = 'teamhub_current_org'

export function OrganizationProvider({ children }: { children: ReactNode }) {
  const [organizations, setOrganizationsState] = useState<Organization[]>([])
  const [currentOrganization, setCurrentOrganizationState] = useState<Organization | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [userId, setUserId] = useState<string | null>(null)
  const { session: demoSession } = useDemoSession()

  const isDemoSessionActive = demoSession.is_demo_session && Boolean(demoSession.demo_org_id)

  const buildDemoOrganization = useCallback((orgId: string): Organization => {
    const store = readDemoManagementStore()
    const demoOrg = store.organizations.find((org) => org.id === orgId)
    const fallback = getOrganizationById(orgId)

    const name = demoOrg?.name ?? fallback?.name ?? 'Demo Organization'
    return {
      id: orgId,
      name,
      roles: ['org_admin'],
      get role(): OrgMemberRole {
        return this.roles[0] ?? 'parent'
      },
    }
  }, [])

  // Auto-select current org when organizations change
  useEffect(() => {
    if (isDemoSessionActive && demoSession.demo_org_id) {
      const demoOrganization = buildDemoOrganization(demoSession.demo_org_id)
      setOrganizationsState([demoOrganization])
      setCurrentOrganizationState(demoOrganization)
      sessionStorage.setItem(STORAGE_KEY, demoOrganization.id)
      setIsLoading(false)
      return
    }

    if (organizations.length === 0) {
      // No organizations - clear current org but don't stay in loading
      setCurrentOrganizationState(null)
      return
    }

    // If we already have a current org that's still in the list, keep it
    if (currentOrganization && organizations.some(o => o.id === currentOrganization.id)) {
      return
    }

    // Otherwise, select from storage or use first available
    const storedOrgId = sessionStorage.getItem(STORAGE_KEY)
    const org = storedOrgId ? organizations.find(o => o.id === storedOrgId) : null
    const selectedOrg = org || organizations[0]
    
    setCurrentOrganizationState(selectedOrg)
    sessionStorage.setItem(STORAGE_KEY, selectedOrg.id)
  }, [organizations, currentOrganization, isDemoSessionActive, demoSession.demo_org_id, buildDemoOrganization])

  const setOrganizations = useCallback((orgs: Organization[]) => {
    if (isDemoSessionActive && demoSession.demo_org_id) {
      const demoOrganization = buildDemoOrganization(demoSession.demo_org_id)
      setOrganizationsState([demoOrganization])
      setCurrentOrganizationState(demoOrganization)
      setIsLoading(false)
      return
    }

    setOrganizationsState(orgs)
    // Mark as loaded once organizations are set (even if empty array)
    setIsLoading(false)
  }, [isDemoSessionActive, demoSession.demo_org_id, buildDemoOrganization])

  const setCurrentOrganization = useCallback((org: Organization | null) => {
    setCurrentOrganizationState(org)
    if (org) {
      sessionStorage.setItem(STORAGE_KEY, org.id)
    } else {
      sessionStorage.removeItem(STORAGE_KEY)
    }
  }, [])

  const switchOrganization = useCallback((orgId: string) => {
    if (isDemoSessionActive) return
    const org = organizations.find(o => o.id === orgId)
    if (org) {
      setCurrentOrganization(org)
    }
  }, [organizations, setCurrentOrganization, isDemoSessionActive])

  // Set up realtime subscription for organization_members changes
  useEffect(() => {
    if (isDemoSessionActive) return
    if (!userId) return

    let refreshTimeout: NodeJS.Timeout | null = null

    const handleRoleChange = () => {
      // Debounce: wait 500ms after last change before refreshing
      if (refreshTimeout) clearTimeout(refreshTimeout)

      refreshTimeout = setTimeout(async () => {
        // Fetch updated organizations from RPC
        const { data } = await supabase.rpc('get_user_organizations', { check_user_id: userId } as any) as { data: Array<{ org_id: string; org_name: string; roles: OrgMemberRole[] }> | null; error: unknown }
        if (data) {
          const updatedOrgs: Organization[] = data.map((org) => {
            // Normalize roles to always be an array
            const roles = org.roles || []
            return {
              id: org.org_id,
              name: org.org_name,
              roles: Array.isArray(roles) ? roles : [],
              get role() {
                return this.roles[0] ?? 'parent'
              },
            }
          })
          setOrganizationsState(updatedOrgs)
        }
        refreshTimeout = null
      }, 500)
    }

    // Subscribe to organization_members changes for current user
    const channel = supabase
      .channel('org_members_changes')
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'organization_members',
        filter: `user_id=eq.${userId}`,
      }, handleRoleChange)
      .subscribe()

    return () => {
      if (refreshTimeout) clearTimeout(refreshTimeout)
      supabase.removeChannel(channel)
    }
  }, [userId, isDemoSessionActive])

  // Get user ID from auth session
  useEffect(() => {
    if (isDemoSessionActive) {
      setUserId(null)
      return
    }

    supabase.auth.getSession().then(({ data: { session } }) => {
      setUserId(session?.user?.id ?? null)
    })

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setUserId(session?.user?.id ?? null)
    })

    return () => subscription.unsubscribe()
  }, [isDemoSessionActive])

  const value: OrganizationContextType = {
    currentOrganization,
    organizations,
    setOrganizations,
    setCurrentOrganization,
    switchOrganization,
    isLoading,
  }

  return (
    <OrganizationContext.Provider value={value}>
      {children}
    </OrganizationContext.Provider>
  )
}

// eslint-disable-next-line react-refresh/only-export-components
export function useOrganization() {
  const context = useContext(OrganizationContext)
  if (context === undefined) {
    throw new Error('useOrganization must be used within an OrganizationProvider')
  }
  return context
}

/**
 * Organization Structure - Context & Routing
 *
 * Manages the navigation and state for the organizational hierarchy view.
 * Each section (Sports, Programs, Levels, Teams, Seasons, People) has:
 * - Contextual breadcrumbs
 * - Inherited upstream selections
 * - Guided empty states
 */

import { createContext, ReactNode, useState } from 'react'

export interface OrganizationStructureContext {
  // Current selections in the hierarchy
  selectedSportId?: string
  selectedProgramId?: string
  selectedLevelId?: string
  selectedTeamId?: string
  selectedSeasonId?: string

  // Setters
  selectSport: (id?: string) => void
  selectProgram: (id?: string) => void
  selectLevel: (id?: string) => void
  selectTeam: (id?: string) => void
  selectSeason: (id?: string) => void

  // Reset to specific level
  resetTo: (level: 'sport' | 'program' | 'level' | 'team' | 'season') => void
}

export const Context = createContext<OrganizationStructureContext | undefined>(undefined)

export function OrganizationStructureProvider({ children }: { children: ReactNode }) {
  const [selectedSportId, setSelectedSportId] = useState<string>()
  const [selectedProgramId, setSelectedProgramId] = useState<string>()
  const [selectedLevelId, setSelectedLevelId] = useState<string>()
  const [selectedTeamId, setSelectedTeamId] = useState<string>()
  const [selectedSeasonId, setSelectedSeasonId] = useState<string>()

  const selectSport = (id?: string) => {
    setSelectedSportId(id)
    // Reset downstream selections
    setSelectedProgramId(undefined)
    setSelectedLevelId(undefined)
    setSelectedTeamId(undefined)
  }

  const selectProgram = (id?: string) => {
    setSelectedProgramId(id)
    // Reset downstream selections
    setSelectedLevelId(undefined)
    setSelectedTeamId(undefined)
  }

  const selectLevel = (id?: string) => {
    setSelectedLevelId(id)
    // Reset downstream selections
    setSelectedTeamId(undefined)
  }

  const selectTeam = (id?: string) => {
    setSelectedTeamId(id)
  }

  const selectSeason = (id?: string) => {
    setSelectedSeasonId(id)
  }

  const resetTo = (level: 'sport' | 'program' | 'level' | 'team' | 'season') => {
    switch (level) {
      case 'sport':
        selectSport()
        break
      case 'program':
        selectProgram()
        break
      case 'level':
        selectLevel()
        break
      case 'team':
        selectTeam()
        break
      case 'season':
        selectSeason()
        break
    }
  }

  return (
    <Context.Provider
      value={{
        selectedSportId,
        selectedProgramId,
        selectedLevelId,
        selectedTeamId,
        selectedSeasonId,
        selectSport,
        selectProgram,
        selectLevel,
        selectTeam,
        selectSeason,
        resetTo,
      }}
    >
      {children}
    </Context.Provider>
  )
}

