      await act(async () => {
        await result.current.signOut()
      })

      expect(supabase.auth.signOut).toHaveBeenCalled()
    })
  })
})

import {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
  useCallback,
  useRef,
} from 'react'
import { User, Session, AuthError } from '@supabase/supabase-js'
import { supabase } from '../lib/supabase'
import { useOrganization, Organization } from '../contexts/OrganizationContext'
import { useDemoSession } from '../contexts/DemoSessionContext'
import type { PlatformAdminRole } from '../types/platformAdmin.types'
import type { HomeLocation } from '../types/location'
import { geocodeZipToHomeLocation } from '../utils/homeLocation'
import { DEMO_ORG_A_ID, USE_FAKE_DATA } from '../data/config'
import { generateDemoData } from '../data/fake/demoDataEngine'
import { getDemoUserContext } from '../data/fake/userContext'
import { getOrganizationById } from '../data/fake/fakeOrganizations'
import { validateDemoCode } from '../data/services/demoCodeService'
import { getDemoOrg } from '../data/services/demoOrgService'
import {
  clearStoredDemoCode,
  createDemoSession,
  endDemoSession,
  getStoredDemoCode,
} from '../data/services/demoSessionService'
import { debug } from '../lib/debug'

// Role types - now per organization (must match OrganizationContext.OrgMemberRole)
type OrgMemberRole = 'parent' | 'coach' | 'org_admin' | 'staff' | 'athlete'
type LegacyUserRole = 'parent' | 'coach' | 'admin'

interface UserProfile {
  id: string
  email: string | null
  phone: string
  first_name: string
  last_name: string
  display_name: string | null
  home_location?: HomeLocation | null
  home_zipcode?: string
  // Legacy fields (deprecated, use organizations instead)
  role?: LegacyUserRole
  family_id?: string | null
  org_id?: string | null
  organizations: Organization[]
  isPlatformAdmin: boolean
  platformAdminRole: PlatformAdminRole | null
  // Organization setup requirement flag
  requiresOrgSetup: boolean
}

interface AuthContextType {
  user: User | null
  profile: UserProfile | null
  session: Session | null
  loading: boolean
  signInWithEmail: (email: string, password: string, demoCode?: string) => Promise<{ error: AuthError | null }>
  signInWithGoogle: () => Promise<{ error: AuthError | null }>
  signUp: (email: string, password: string, firstName: string, lastName: string, phone: string, zipcode: string, requiresOrgSetup?: boolean, signupMode?: 'fan' | 'parent') => Promise<{ error: AuthError | null }>
  signOut: () => Promise<void>
  resetPassword: (email: string) => Promise<{ error: AuthError | null }>
  updatePassword: (password: string) => Promise<{ error: AuthError | null }>
  updateEmail: (newEmail: string, redirectTo?: string) => Promise<{ error: AuthError | null }>
  refreshProfile: () => Promise<void>
  // Role helpers (UX-only, not security - RLS handles authorization)
  hasRole: (orgId: string, role: OrgMemberRole) => boolean
  hasAnyRole: (role: OrgMemberRole) => boolean
  isOrgAdmin: (orgId?: string) => boolean
}

/* ===================== CONTEXT ===================== */

const AuthContext = createContext<AuthContextType | undefined>(undefined)

const FAKE_AUTH_STORAGE_KEY = 'teamhub_fake_auth_state'

interface FakeAuthState {
  userId: string
  email: string
  orgId: string
  orgName: string
  roles: OrgMemberRole[]
  isPlatformAdmin: boolean
}

function readFakeAuthState(): FakeAuthState | null {
  if (typeof window === 'undefined') return null

  try {
    const raw = window.sessionStorage.getItem(FAKE_AUTH_STORAGE_KEY)
    if (!raw) return null

    const parsed = JSON.parse(raw) as Partial<FakeAuthState>
    if (!parsed || typeof parsed.email !== 'string' || parsed.email.trim().length === 0) {
      return null
    }

    const roles = Array.isArray(parsed.roles)
      ? parsed.roles.filter(
          (role): role is OrgMemberRole =>
            role === 'parent' || role === 'coach' || role === 'org_admin' || role === 'staff' || role === 'athlete',
        )
      : []

    const safeEmail = parsed.email.trim().toLowerCase()
    const safeUserId = typeof parsed.userId === 'string' && parsed.userId.trim().length > 0
      ? parsed.userId.trim()
      : ''
    const safeOrgId = typeof parsed.orgId === 'string' && parsed.orgId.trim().length > 0
      ? parsed.orgId.trim()
      : DEMO_ORG_A_ID
    const safeOrgName = typeof parsed.orgName === 'string' && parsed.orgName.trim().length > 0
      ? parsed.orgName.trim()
      : (getOrganizationById(safeOrgId)?.name ?? 'Demo Organization')

    return {
      userId: safeUserId,
      email: safeEmail,
      orgId: safeOrgId,
      orgName: safeOrgName,
      roles,
      isPlatformAdmin: parsed.isPlatformAdmin === true,
    }
  } catch {
    return null
  }
}

function writeFakeAuthState(state: FakeAuthState): void {
  if (typeof window === 'undefined') return
  window.sessionStorage.setItem(FAKE_AUTH_STORAGE_KEY, JSON.stringify(state))
}

function clearFakeAuthState(): void {
  if (typeof window === 'undefined') return
  window.sessionStorage.removeItem(FAKE_AUTH_STORAGE_KEY)
}

/* ===================== PROVIDER ===================== */

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [profile, setProfile] = useState<UserProfile | null>(null)
  const [session, setSession] = useState<Session | null>(null)
  const [loading, setLoading] = useState(true)

  const { setOrganizations, currentOrganization } = useOrganization()
  const { refreshSession } = useDemoSession()

  // Prevent duplicate profile fetches (Bug Prevention #1 & #7)
  const profileFetchRef = useRef<Set<string>>(new Set())

  // Track last processed auth event timestamp for debouncing (Bug Prevention #3)
  const lastAuthEventRef = useRef<{ event: string; timestamp: number } | null>(null)

  // Mounted flag for cleanup (Bug Prevention #2)
  const mountedRef = useRef(true)

  /* ===================== FETCH PROFILE ===================== */

  const fetchProfile = useCallback(
    async (userId: string) => {
      // Prevent duplicate fetches for same user (Bug Prevention #1 & #7)
      if (profileFetchRef.current.has(userId)) {
        debug.flow('Auth', 'Profile fetch skipped (already in progress)', { userId })
        return
      }

      debug.flow('Auth', 'Profile fetch started', { userId })
      debug.perf.start(`auth.fetchProfile-${userId}`)

      profileFetchRef.current.add(userId)
      setLoading(true)

      try {
        /* ---- user table ---- */
        // Try to select with home_zipcode/home_location first (if migration has been applied)
        let { data: userData, error: userError } = await supabase
          .from('users')
          .select(
            'id, email, phone, display_name, first_name, last_name, home_zipcode, home_location, role, family_id, org_id, requires_org_setup'
          )
          .eq('id', userId)
          .single()

        // If column doesn't exist yet (migration not applied), retry without it
        if (userError?.code === '42703') {
          const retryResult = await supabase
            .from('users')
            .select(
            'id, email, phone, display_name, first_name, last_name, role, family_id, org_id, requires_org_setup'
          )
            .eq('id', userId)
            .single()
          userData = retryResult.data as any
          userError = retryResult.error
        }

        // Simplified error handling (Bug Prevention #4 & #9)
        if (userError || !userData) {
          const userErrorMessage = (userError?.message || '').toLowerCase()
          const isNetworkError =
            userErrorMessage.includes('networkerror') ||
            userErrorMessage.includes('failed to fetch') ||
            userErrorMessage.includes('network request failed')

          if (isNetworkError) {
            console.warn('Profile fetch network error:', userError)
            const { data: sessionData } = await supabase.auth.getSession()
            const sessionUser = sessionData.session?.user

            if (mountedRef.current && sessionUser?.id === userId) {
              const metadata = sessionUser.user_metadata ?? {}
              const fallbackProfile: UserProfile = {
                id: sessionUser.id,
                email: sessionUser.email ?? null,
                phone: typeof metadata.phone === 'string' ? metadata.phone : '',
                first_name: '',
                last_name: '',
                display_name:
                  typeof metadata.display_name === 'string' ? metadata.display_name : null,
                home_location: null,
                home_zipcode:
                  typeof metadata.home_zipcode === 'string' ? metadata.home_zipcode : undefined,
                role: undefined,
                family_id: null,
                org_id: null,
                organizations: [],
                isPlatformAdmin: false,
                platformAdminRole: null,
                requiresOrgSetup: Boolean(metadata.requires_org_setup),
              }
              setProfile((prev) => prev ?? fallbackProfile)
              setOrganizations([])
            }
            return
          }

          console.error('Profile fetch error:', userError)
          await supabase.auth.signOut()
          setProfile(null)
          return
        }

        // Type guard: ensure userData is not an error type
        if (!('id' in userData) || !userData.id) {
          console.error('Invalid user data structure')
          await supabase.auth.signOut()
          setProfile(null)
          return
        }

        // Type assertion: userData is now confirmed to be the correct type
        // home_zipcode/home_location may not exist if migration hasn't been applied yet
        const validUserData = userData as unknown as {
          id: string
          email: string | null
          phone: string | null
          display_name: string | null
          first_name?: string
          last_name?: string
          home_location?: HomeLocation | null
          home_zipcode?: string | null
          role: string | null
          family_id: string | null
          org_id: string | null
          requires_org_setup: boolean | null
        }

        /* ---- organizations ---- */
        let orgs: Organization[] = []
        let data: Array<{ org_id: string; org_name: string; roles: OrgMemberRole[] }> | null = null

        try {
          let orgError: any = null
          // Use real Supabase RPC
          const result = await supabase.rpc('get_user_organizations', {
            check_user_id: userId,
          })
          data = result.data as any
          orgError = result.error

          // Log RPC errors for debugging (this is likely the "profit data" / "profile data" error)
          if (orgError) {
            console.error('Error fetching user organizations:', orgError)
            // Continue with empty orgs - don't block profile creation
          }

          // Debug logging for organization loading
          if (process.env.NODE_ENV === 'development') {
            console.log('[useAuth] RPC result:', { userId, dataCount: data?.length ?? 0, hasError: !!orgError, data })
          }

          // Type-safe organization mapping (Bug Prevention #5 & #8)
          if (Array.isArray(data)) {
            orgs = data.map((o: any) => {
              // Normalize and validate roles array
              const roles = Array.isArray(o.roles)
                ? o.roles.filter(
                  (r: unknown): r is OrgMemberRole =>
                    r === 'parent' || r === 'coach' || r === 'org_admin' || r === 'staff' || r === 'athlete'
                )
                : []

              return {
                id: o.org_id,
                name: o.org_name || '',
                roles,
                // Compatibility getter for deprecated 'role' property
                get role(): OrgMemberRole {
                  return roles[0] ?? 'parent'
                },
              }
            })
            
            // Debug logging for mapped organizations
            if (process.env.NODE_ENV === 'development') {
              console.log('[useAuth] Mapped organizations:', orgs)
            }
          } else {
            if (process.env.NODE_ENV === 'development') {
              console.warn('[useAuth] RPC data is not an array:', data)
            }
          }
        } catch (err) {
          // Continue with empty orgs on error
          console.error('Exception fetching user organizations:', err)
          orgs = []
        }

        /* ---- platform admin ---- */
        const { data: admin } = await supabase
          .from('platform_admins')
          .select('role')
          .eq('user_id', userId)
          .maybeSingle()

        // Bug Prevention #10: Default to 'support_admin' if NULL
        let platformAdminRole: PlatformAdminRole | null = null
        if (admin) {
          platformAdminRole = admin.role ?? 'support_admin'
          if (!admin.role) {
            console.warn(`Platform admin ${userId} has NULL role, defaulting to support_admin`)
          }
        }

        // Guard against auth state changes during fetch (Bug Prevention #8)
        // Check if user is still the same before setting profile
        if (!mountedRef.current) return

        const profileData: UserProfile = {
          id: validUserData.id,
          email: validUserData.email,
          phone: validUserData.phone ?? '',
          first_name: validUserData.first_name ?? '',
          last_name: validUserData.last_name ?? '',
          display_name: validUserData.display_name,
          home_location: (validUserData.home_location as HomeLocation | null) ?? null,
          home_zipcode: validUserData.home_zipcode ?? undefined,
          role: (validUserData.role === 'parent' || validUserData.role === 'coach' || validUserData.role === 'admin') 
            ? (validUserData.role as LegacyUserRole) 
            : undefined,
          family_id: validUserData.family_id,
          org_id: validUserData.org_id,
          organizations: orgs,
          isPlatformAdmin: !!admin,
          platformAdminRole,
          requiresOrgSetup: validUserData.requires_org_setup ?? false,
        }

        // Guard against state updates after unmount (Bug Prevention #2)
        if (!mountedRef.current) return

        // Debug logging before setting organizations
        if (process.env.NODE_ENV === 'development') {
          console.log('[useAuth] Setting organizations:', { orgCount: orgs.length, orgs })
        }

        setProfile(profileData)
        setOrganizations(orgs)
        debug.perf.end(`auth.fetchProfile-${userId}`)
        debug.flow('Auth', 'Profile fetch completed', {
          userId,
          orgCount: orgs.length,
          isPlatformAdmin: profileData.isPlatformAdmin,
          requiresOrgSetup: profileData.requiresOrgSetup
        })
      } catch (err) {
        debug.perf.end(`auth.fetchProfile-${userId}`)
        const message = err instanceof Error ? err.message.toLowerCase() : ''
        const isNetworkError =
          message.includes('networkerror') ||
          message.includes('failed to fetch') ||
          message.includes('network request failed')

        if (isNetworkError) {
          debug.error('Auth', 'Profile fetch failed (network)', { userId, error: err })
          return
        }

        debug.error('Auth', 'Profile fetch failed', { userId, error: err })
        if (mountedRef.current) {
          setProfile(null)
        }
      } finally {
        profileFetchRef.current.delete(userId)
        if (mountedRef.current) {
          setLoading(false)
        }
      }
    },
    [setOrganizations]
  )

  /* ===================== AUTH BOOTSTRAP ===================== */

  useEffect(() => {
    mountedRef.current = true

    if (USE_FAKE_DATA) {
      const persisted = readFakeAuthState()
      if (persisted) {
        const resolvedContext = getDemoUserContext(persisted.email)
        const resolvedOrgId = persisted.orgId || resolvedContext?.orgId || DEMO_ORG_A_ID
        const resolvedOrgName =
          persisted.orgName ||
          getOrganizationById(resolvedOrgId)?.name ||
          'Demo Organization'
        const resolvedRoles: OrgMemberRole[] =
          persisted.roles.length > 0
            ? persisted.roles
            : resolvedContext?.roles && resolvedContext.roles.length > 0
              ? resolvedContext.roles
              : ['parent']
        const resolvedUserId = persisted.userId || resolvedContext?.userId || `demo-${persisted.email}`

        const organizations: Organization[] = [
          {
            id: resolvedOrgId,
            name: resolvedOrgName,
            roles: resolvedRoles,
            get role(): OrgMemberRole {
              return this.roles[0] ?? 'parent'
            },
          },
        ]

        const demoUser = {
          id: resolvedUserId,
          email: persisted.email,
          user_metadata: { signup_mode: 'parent' },
        } as unknown as User

        const legacyRole: LegacyUserRole | undefined = resolvedRoles.includes('org_admin')
          ? 'admin'
          : resolvedRoles.includes('coach')
            ? 'coach'
            : resolvedRoles.includes('parent')
              ? 'parent'
              : undefined

        const demoProfile: UserProfile = {
          id: resolvedUserId,
          email: persisted.email,
          phone: '',
          first_name: '',
          last_name: '',
          display_name: persisted.email.split('@')[0] ?? null,
          home_location: null,
          home_zipcode: undefined,
          role: legacyRole,
          family_id: null,
          org_id: resolvedOrgId,
          organizations,
          isPlatformAdmin: persisted.isPlatformAdmin,
          platformAdminRole: null,
          requiresOrgSetup: false,
        }

        if (mountedRef.current) {
          setUser(demoUser)
          setSession(null)
          setProfile(demoProfile)
          setOrganizations(organizations)
        }
      } else {
        clearFakeAuthState()
      }

      setLoading(false)
      return () => {
        mountedRef.current = false
      }
    }

    supabase.auth.getSession().then(({ data }) => {
      if (!mountedRef.current) return

      // Handle session/user mismatch (Bug Prevention #10)
      const session = data.session
      if (!mountedRef.current) return
      setSession(session)
      setUser(session?.user ?? null)

      // If session exists but user is null, clear state
      if (session && !session.user) {
        if (!mountedRef.current) return
        setSession(null)
        setUser(null)
        setProfile(null)
        setOrganizations([])
        setLoading(false)
        return
      }

      if (session?.user) {
        fetchProfile(session.user.id)
      } else {
        if (!mountedRef.current) return
        setLoading(false)
      }
    })

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((event, session) => {
      if (!mountedRef.current) return

      // Ignore TOKEN_REFRESHED events - they fire on tab focus and cause unnecessary re-renders
      // The session is still valid, no need to trigger loading states or re-fetch profile
      if (event === 'TOKEN_REFRESHED') {
        // Silently update session without triggering loading states
        if (session) {
          setSession(session)
          // Don't update user or trigger profile fetch - nothing meaningful changed
          debug.flow('Auth', 'Token refreshed', { userId: session.user.id })
        }
        return
      }

      // Log auth state changes
      debug.flow('Auth', `State change: ${event}`, {
        event,
        userId: session?.user?.id,
        hasSession: !!session,
        email: session?.user?.email
      })

      // Event debouncing (Bug Prevention #3)
      const now = Date.now()
      const lastEvent = lastAuthEventRef.current
      if (
        lastEvent &&
        lastEvent.event === event &&
        now - lastEvent.timestamp < 100
      ) {
        return // Skip duplicate event within 100ms
      }
      lastAuthEventRef.current = { event, timestamp: now }

      // Handle session/user mismatch (Bug Prevention #10)
      if (session && !session.user) {
        if (!mountedRef.current) return
        setSession(null)
        setUser(null)
        setProfile(null)
        setOrganizations([])
        setLoading(false)
        return
      }

      if (!mountedRef.current) return
      setSession(session)
      setUser(session?.user ?? null)

      if (event === 'SIGNED_IN') {
        debug.flow('Auth', 'User signed in', { userId: session?.user?.id, email: session?.user?.email })
      } else if (event === 'SIGNED_OUT') {
        debug.flow('Auth', 'User signed out', { previousUserId: user?.id })
        if (!mountedRef.current) return
        setProfile(null)
        setOrganizations([])
        setLoading(false)
        return
      }

      if (event === 'SIGNED_IN' && session?.user) {
        fetchProfile(session.user.id)
      }
    })

    return () => {
      mountedRef.current = false
      subscription.unsubscribe()
    }
  }, [fetchProfile, setOrganizations])

  /* ===================== LOADING STATE TIMEOUT FALLBACK ===================== */

  // Bug Prevention #4: Ensure loading state doesn't get stuck
  useEffect(() => {
    if (!loading) return

    const timeout = setTimeout(() => {
      if (loading) {
        console.warn('Loading state stuck, forcing reset')
        setLoading(false)
      }
    }, 5000)

    return () => clearTimeout(timeout)
  }, [loading])

  /* ===================== AUTH ACTIONS ===================== */

  async function signInWithEmail(email: string, password: string, demoCode?: string) {
    return debug.group(`Auth.signInWithEmail: ${email}`, async () => {
        debug.flow('Auth', 'Login attempt', { email, method: 'email' })
        debug.perf.start('auth.signInWithEmail')

        const toAuthError = (message: string): AuthError => ({ name: 'AuthError', message } as AuthError)

        if (USE_FAKE_DATA) {
      const demoContext = getDemoUserContext(email)
      if (!demoContext) {
        return { error: toAuthError('Invalid login credentials') }
      }

      const normalizedDemoCode = (demoCode ?? getStoredDemoCode() ?? '').trim().toUpperCase()
      let resolvedDemoOrgId = demoContext.orgId
      let resolvedDemoOrgName = getOrganizationById(demoContext.orgId)?.name ?? 'Demo Organization'

      if (normalizedDemoCode) {
        const validation = await validateDemoCode(normalizedDemoCode)
        if (!validation.valid || !validation.demoOrgId) {
          const messageByReason: Record<string, string> = {
            missing: 'Demo code is required.',
            not_found: 'Invalid demo code.',
            revoked: 'This demo code has been revoked.',
            expired: 'This demo code has expired.',
            inactive_org: 'This demo organization is inactive.',
          }
          const reason = validation.reason ?? 'not_found'
          return { error: toAuthError(messageByReason[reason] ?? 'Invalid demo code.') }
        }

        const demoOrg = await getDemoOrg(validation.demoOrgId)
        await generateDemoData(demoOrg, demoOrg.sports_sponsored, normalizedDemoCode)
        await createDemoSession(normalizedDemoCode, demoContext.userId)
        refreshSession()
        resolvedDemoOrgId = validation.demoOrgId
        resolvedDemoOrgName = getOrganizationById(validation.demoOrgId)?.name ?? demoOrg.name ?? 'Demo Organization'
      }

      const roles: OrgMemberRole[] = demoContext.roles
      const organizations: Organization[] = [
        {
          id: resolvedDemoOrgId,
          name: resolvedDemoOrgName,
          roles,
          get role(): OrgMemberRole {
            return roles[0] ?? 'parent'
          },
        },
      ]

      const legacyRole: LegacyUserRole | undefined = roles.includes('org_admin')
        ? 'admin'
        : roles.includes('coach')
          ? 'coach'
          : roles.includes('parent')
            ? 'parent'
            : undefined

      const demoUser = {
        id: demoContext.userId,
        email: demoContext.email,
        user_metadata: { signup_mode: 'parent' },
      } as unknown as User

      const demoProfile: UserProfile = {
        id: demoContext.userId,
        email: demoContext.email,
        phone: '',
        first_name: '',
        last_name: '',
        display_name: demoContext.email?.split('@')[0] ?? null,
        home_location: null,
        home_zipcode: undefined,
        role: legacyRole,
        family_id: null,
        org_id: resolvedDemoOrgId,
        organizations,
        isPlatformAdmin: demoContext.isPlatformAdmin,
        platformAdminRole: null,
        requiresOrgSetup: false,
      }

      writeFakeAuthState({
        userId: demoContext.userId,
        email: demoContext.email ?? email.toLowerCase().trim(),
        orgId: resolvedDemoOrgId,
        orgName: resolvedDemoOrgName,
        roles,
        isPlatformAdmin: demoContext.isPlatformAdmin,
      })

      setUser(demoUser)
      setSession(null)
            setProfile(demoProfile)
            setOrganizations(organizations)
            setLoading(false)
            clearStoredDemoCode()
            debug.perf.end('auth.signInWithEmail')
            debug.flow('Auth', 'Login successful (demo)', {
              email,
              userId: demoContext.userId,
              roles: demoContext.roles,
              demoOrgId: resolvedDemoOrgId,
            })
            return { error: null }
        }

        try {
            const { error } = await supabase.auth.signInWithPassword({ email, password })
            debug.perf.end('auth.signInWithEmail')
            if (error) {
                debug.error('Auth', 'Login failed', { email, error: error.message })
            } else {
                debug.flow('Auth', 'Login initiated', { email })
            }
            return { error }
        } catch (err) {
            debug.perf.end('auth.signInWithEmail')
            debug.error('Auth', 'Login exception', { email, error: err })
            return { error: err as AuthError }
        }
    })
  }

  async function signInWithGoogle() {
    // Import getBaseUrl to get current origin (supports localhost and production)
    const { getBaseUrl } = await import('../utils/host')
    const baseUrl = getBaseUrl()
    
    const { error } = await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: {
        // Use current base URL for OAuth redirect
        // This works for localhost development and production
        redirectTo: `${baseUrl}/portal/auth/callback`,
      },
    })
    return { error }
  }

  async function signUp(email: string, password: string, firstName: string, lastName: string, phone: string, zipcode: string, requiresOrgSetup?: boolean, signupMode?: 'fan' | 'parent', tosAccepted?: boolean, privacyAccepted?: boolean) {
    return debug.group(`Auth.signUp: ${email}`, async () => {
        debug.flow('Auth', 'Signup attempt', { email, signupMode, requiresOrgSetup })
        debug.perf.start('auth.signUp')

        // Import getBaseUrl to get current origin (supports localhost and production)
        const { getBaseUrl } = await import('../utils/host')
        const baseUrl = getBaseUrl()
        const trimmedZip = zipcode.trim()
    
    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        // Use current base URL for email verification links
        // This works for localhost development and production
        emailRedirectTo: `${baseUrl}/portal/auth/callback`,
        data: {
          first_name: firstName.trim(),
          last_name: lastName.trim(),
          phone: phone.trim(),
          home_zipcode: trimmedZip || undefined, // Only include if not empty
          // Derive display_name from first+last for backward compatibility
          display_name: `${firstName.trim()} ${lastName.trim()}`.trim(),
          // Pass requires_org_setup to metadata - the database trigger will read this
          requires_org_setup: requiresOrgSetup ?? false,
          // Pass signup_mode to metadata for tracking user intent
          signup_mode: signupMode || 'parent',
        },
      },
    })

        if (!error && data?.user) {
          const userId = data.session?.user?.id || data.user.id
          const now = new Date().toISOString()
          const consentVersion = '1.0' // Update this when ToS/Privacy Policy versions change

          try {
            // Update user with consent and home location
            const updateData: any = {}
            
            if (tosAccepted) {
              updateData.tos_accepted_at = now
            }
            if (privacyAccepted) {
              updateData.privacy_policy_accepted_at = now
            }
            if (tosAccepted || privacyAccepted) {
              updateData.consent_version = consentVersion
            }
            if (trimmedZip) {
              updateData.home_zipcode = trimmedZip
            }

            if (Object.keys(updateData).length > 0) {
              if (trimmedZip) {
                try {
                  const homeLocation = await geocodeZipToHomeLocation(trimmedZip)
                  if (homeLocation) {
                    updateData.home_location = homeLocation
                  }
                } catch (err) {
                  debug.error('Auth', 'Failed to geocode zipcode', { email, error: err })
                }
              }

              await supabase
                .from('users')
                .update(updateData)
                .eq('id', userId)
            }
          } catch (err) {
            debug.error('Auth', 'Failed to save consent/home location after signup', { email, error: err })
          }
        }

        debug.perf.end('auth.signUp')
        if (error) {
          debug.error('Auth', 'Signup failed', { email, error: error.message })
        } else {
          debug.flow('Auth', 'Signup successful', { email, userId: data?.user?.id, signupMode })
        }
        return { error }
    })
  }

  async function signOut() {
    return debug.group('Auth.signOut', async () => {
        debug.flow('Auth', 'Logout started', { userId: user?.id })
        debug.perf.start('auth.signOut')

        if (USE_FAKE_DATA) {
          if (user?.id) {
            await endDemoSession(user.id)
          } else {
            clearStoredDemoCode()
            refreshSession()
          }
          clearFakeAuthState()
          setUser(null)
          setProfile(null)
          setSession(null)
          setOrganizations([])
          setLoading(false)
          debug.perf.end('auth.signOut')
          debug.flow('Auth', 'Logout completed (demo)', { userId: user?.id })
          return
        }

        try {
          await supabase.auth.signOut()
          setUser(null)
          setProfile(null)
          setSession(null)
          setOrganizations([])
          debug.perf.end('auth.signOut')
          debug.flow('Auth', 'Logout completed', { userId: user?.id })
        } catch (err) {
          debug.perf.end('auth.signOut')
          debug.error('Auth', 'Logout failed', { userId: user?.id, error: err })
        }
    })
  }

  async function resetPassword(email: string) {
    // Import getBaseUrl to get current origin (supports localhost and production)
    const { getBaseUrl } = await import('../utils/host')
    const baseUrl = getBaseUrl()
    
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      // Use current base URL for password reset links
      // This works for localhost development and production
      redirectTo: `${baseUrl}/reset-password`,
    })
    return { error }
  }

  async function updatePassword(password: string) {
    const { error } = await supabase.auth.updateUser({ password })
    return { error }
  }

  async function updateEmail(newEmail: string, redirectTo?: string) {
    // Import getBaseUrl to get current origin (supports localhost and production)
    const { getBaseUrl } = await import('../utils/host')
    const baseUrl = getBaseUrl()
    
    // Use provided redirectTo or default to current path (settings page)
    const emailRedirectTo = redirectTo 
      ? `${baseUrl}${redirectTo}` 
      : `${baseUrl}${window.location.pathname}`
    
    const { error } = await supabase.auth.updateUser(
      { email: newEmail },
      { emailRedirectTo }
    )
    return { error }
  }

  async function refreshProfile() {
    if (USE_FAKE_DATA) {
      return
    }

    if (user?.id) {
      await fetchProfile(user.id)
    }
  }

  /* ===================== ROLE HELPERS ===================== */

  function hasRole(orgId: string, role: OrgMemberRole) {
    if (profile?.isPlatformAdmin) return true
    return profile?.organizations.some(
      (o) => o.id === orgId && o.roles.includes(role)
    ) ?? false
  }

  function hasAnyRole(role: OrgMemberRole) {
    if (profile?.isPlatformAdmin) return true
    return profile?.organizations.some((o) => o.roles.includes(role)) ?? false
  }

  function isOrgAdmin(orgId?: string) {
    if (profile?.isPlatformAdmin) return true
    if (orgId) return hasRole(orgId, 'org_admin')
    return currentOrganization
      ? hasRole(currentOrganization.id, 'org_admin')
      : false
  }

  /* ===================== CONTEXT VALUE ===================== */

  const value: AuthContextType = {
    user,
    profile,
    session,
    loading,
    signInWithEmail,
    signInWithGoogle,
    signUp,
    signOut,
    resetPassword,
    updatePassword,
    updateEmail,
    refreshProfile,
    hasRole,
    hasAnyRole,
    isOrgAdmin,
  }

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

/* ===================== HOOK ===================== */

export function useAuth() {
  const context = useContext(AuthContext)
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}

/** Returns auth context or undefined when outside AuthProvider. Use when component may render outside provider. */
export function useOptionalAuth() {
  return useContext(AuthContext)
}

/**
 * useCopyToClipboard Hook
 * 
 * Provides copy-to-clipboard functionality with state management and fallback.
 * Returns copy function that accepts value at call time (prevents stale closures).
 * 
 * @example
 * const { copy, copied, error } = useCopyToClipboard()
 * 
 * <button onClick={() => copy(currentUrl)}>
 *   {copied ? 'Copied!' : 'Copy'}
 * </button>
 */

import { useState, useCallback } from 'react'

interface UseCopyToClipboardResult {
  copy: (value: string) => Promise<boolean>
  copied: boolean
  error: Error | null
}

const COPIED_TIMEOUT_MS = 2000

export function useCopyToClipboard(): UseCopyToClipboardResult {
  const [copied, setCopied] = useState(false)
  const [error, setError] = useState<Error | null>(null)

  const copy = useCallback(async (value: string): Promise<boolean> => {
    if (!value) {
      const err = new Error('Cannot copy empty value')
      setError(err)
      return false
    }

    setError(null)

    // Try modern clipboard API first
    if (navigator.clipboard && navigator.clipboard.writeText) {
      try {
        await navigator.clipboard.writeText(value)
        setCopied(true)
        setTimeout(() => setCopied(false), COPIED_TIMEOUT_MS)
        return true
      } catch (err) {
        // Fall through to fallback
      }
    }

    // Fallback: textarea + execCommand (for non-secure contexts)
    try {
      const textArea = document.createElement('textarea')
      textArea.value = value
      textArea.style.position = 'fixed'
      textArea.style.left = '-999999px'
      textArea.style.top = '-999999px'
      document.body.appendChild(textArea)
      textArea.focus()
      textArea.select()

      const success = document.execCommand('copy')
      document.body.removeChild(textArea)

      if (success) {
        setCopied(true)
        setTimeout(() => setCopied(false), COPIED_TIMEOUT_MS)
        return true
      } else {
        throw new Error('execCommand copy failed')
      }
    } catch (err) {
      const error = err instanceof Error ? err : new Error('Failed to copy to clipboard')
      setError(error)
      return false
    }
  }, [])

  return { copy, copied, error }
}

/**
 * useOrgSportSettings Hook
 * 
 * Manages org-level sport profile field customization.
 * Only accessible to org admins (enforced by RLS).
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useIsMounted } from './useIsMounted'
import {
    getOrgSportSettings,
    upsertOrgSportSettings,
    updateFieldOverride,
    removeFieldOverride,
} from '../data/services/orgSportSettingsService'
import type { OrgSportProfileSettings, FieldOverride } from '../types/athleteSportProfiles'
import type { SportCode } from '../types/sports'

interface UseOrgSportSettingsResult {
    settings: OrgSportProfileSettings | null
    loading: boolean
    error: Error | null
    updating: boolean
    updateSettings: (overrides: Record<string, FieldOverride>) => Promise<boolean>
    updateField: (fieldKey: string, override: FieldOverride) => Promise<boolean>
    removeField: (fieldKey: string) => Promise<boolean>
    refetch: () => void
}

/**
 * Hook to fetch and manage org sport settings
 * 
 * @param orgId - Organization ID
 * @param sportCode - Sport code
 * @returns Object containing settings, loading states, and mutation functions
 */
export function useOrgSportSettings(
    orgId: string | null,
    sportCode: SportCode | null
): UseOrgSportSettingsResult {
    const isMounted = useIsMounted()

    const [settings, setSettings] = useState<OrgSportProfileSettings | null>(null)
    const [loading, setLoading] = useState(true)
    const [updating, setUpdating] = useState(false)
    const [error, setError] = useState<Error | null>(null)
    const [trigger, setTrigger] = useState(0)

    const abortControllerRef = useRef<AbortController | null>(null)

    const refetch = useCallback(() => {
        setTrigger(prev => prev + 1)
    }, [])

    // Fetch settings
    useEffect(() => {
        if (!orgId || !sportCode) {
            if (isMounted.current) {
                setLoading(false)
                setSettings(null)
                setError(null)
            }
            return
        }

        if (abortControllerRef.current) {
            abortControllerRef.current.abort()
        }

        const controller = new AbortController()
        abortControllerRef.current = controller

        if (!isMounted.current) return

        setLoading(true)
        setError(null)

        const loadSettings = async () => {
            try {
                const { data, error: fetchError } = await getOrgSportSettings(orgId, sportCode)

                if (controller.signal.aborted) return
                if (!isMounted.current) return

                if (fetchError) {
                    throw fetchError
                }

                // null data means org uses defaults (not an error)
                setSettings(data)
                setError(null)
            } catch (err) {
                if (controller.signal.aborted) return
                if (!isMounted.current) return

                const error = err instanceof Error ? err : new Error('Failed to load org sport settings')
                setError(error)
                setSettings(null)
            } finally {
                if (controller.signal.aborted) return
                if (!isMounted.current) return

                setLoading(false)
            }
        }

        loadSettings()

        return () => {
            controller.abort()
            abortControllerRef.current = null
        }
    }, [orgId, sportCode, trigger, isMounted])

    // Update all settings (optimistic update)
    const updateSettings = useCallback(async (
        overrides: Record<string, FieldOverride>
    ): Promise<boolean> => {
        if (!orgId || !sportCode) {
            console.error('[useOrgSportSettings] Cannot update: missing orgId or sportCode')
            return false
        }

        setUpdating(true)
        setError(null)

        // Optimistic update
        const previousSettings = settings
        if (settings) {
            setSettings({
                ...settings,
                overrides,
                version: settings.version + 1,
                updated_at: new Date().toISOString(),
            })
        } else {
            // Create optimistic new settings
            setSettings({
                id: 'temp-id',
                org_id: orgId,
                sport_code: sportCode,
                overrides,
                version: 1,
                updated_by: null,
                updated_at: new Date().toISOString(),
                created_at: new Date().toISOString(),
            })
        }

        try {
            const { data, error: updateError } = await upsertOrgSportSettings(orgId, sportCode, overrides)

            if (!isMounted.current) return false

            if (updateError) {
                throw updateError
            }

            setSettings(data)
            setError(null)
            return true
        } catch (err) {
            if (!isMounted.current) return false

            // Rollback optimistic update
            setSettings(previousSettings)

            const error = err instanceof Error ? err : new Error('Failed to update org sport settings')
            setError(error)
            console.error('[useOrgSportSettings] Update failed:', error)
            return false
        } finally {
            if (isMounted.current) {
                setUpdating(false)
            }
        }
    }, [orgId, sportCode, settings, isMounted])

    // Update single field override
    const updateField = useCallback(async (
        fieldKey: string,
        override: FieldOverride
    ): Promise<boolean> => {
        if (!orgId || !sportCode) {
            console.error('[useOrgSportSettings] Cannot update field: missing orgId or sportCode')
            return false
        }

        setUpdating(true)
        setError(null)

        // Optimistic update
        const previousSettings = settings
        const currentOverrides = settings?.overrides || {}
        const updatedOverrides = {
            ...currentOverrides,
            [fieldKey]: override,
        }

        if (settings) {
            setSettings({
                ...settings,
                overrides: updatedOverrides,
                version: settings.version + 1,
                updated_at: new Date().toISOString(),
            })
        } else {
            setSettings({
                id: 'temp-id',
                org_id: orgId,
                sport_code: sportCode,
                overrides: updatedOverrides,
                version: 1,
                updated_by: null,
                updated_at: new Date().toISOString(),
                created_at: new Date().toISOString(),
            })
        }

        try {
            const { data, error: updateError } = await updateFieldOverride(orgId, sportCode, fieldKey, override)

            if (!isMounted.current) return false

            if (updateError) {
                throw updateError
            }

            setSettings(data)
            setError(null)
            return true
        } catch (err) {
            if (!isMounted.current) return false

            // Rollback optimistic update
            setSettings(previousSettings)

            const error = err instanceof Error ? err : new Error('Failed to update field override')
            setError(error)
            console.error('[useOrgSportSettings] Field update failed:', error)
            return false
        } finally {
            if (isMounted.current) {
                setUpdating(false)
            }
        }
    }, [orgId, sportCode, settings, isMounted])

    // Remove field override
    const removeField = useCallback(async (fieldKey: string): Promise<boolean> => {
        if (!orgId || !sportCode) {
            console.error('[useOrgSportSettings] Cannot remove field: missing orgId or sportCode')
            return false
        }

        if (!settings) {
            // No settings exist, nothing to remove
            return true
        }

        setUpdating(true)
        setError(null)

        // Optimistic update
        const previousSettings = settings
        const { [fieldKey]: removed, ...remainingOverrides } = settings.overrides

        if (Object.keys(remainingOverrides).length === 0) {
            // If no overrides remain, settings will be deleted
            setSettings(null)
        } else {
            setSettings({
                ...settings,
                overrides: remainingOverrides,
                version: settings.version + 1,
                updated_at: new Date().toISOString(),
            })
        }

        try {
            const { data, error: removeError } = await removeFieldOverride(orgId, sportCode, fieldKey)

            if (!isMounted.current) return false

            if (removeError) {
                throw removeError
            }

            setSettings(data)
            setError(null)
            return true
        } catch (err) {
            if (!isMounted.current) return false

            // Rollback optimistic update
            setSettings(previousSettings)

            const error = err instanceof Error ? err : new Error('Failed to remove field override')
            setError(error)
            console.error('[useOrgSportSettings] Field removal failed:', error)
            return false
        } finally {
            if (isMounted.current) {
                setUpdating(false)
            }
        }
    }, [orgId, sportCode, settings, isMounted])

    return {
        settings,
        loading,
        error,
        updating,
        updateSettings,
        updateField,
        removeField,
        refetch,
    }
}

/**
 * Organization Theme Hook
 *
 * Applies organization-specific theme colors to CSS variables.
 * Loads theme from organization settings and applies semantic tokens to :root element.
 */

import { useLayoutEffect, useMemo, useState } from 'react'
import { useLocation } from 'react-router-dom'
import { useOrganization } from '../contexts/OrganizationContext'
import { useUserContext } from './useUserContext'
import { useTheme } from './useTheme'
import { getOrganizationThemeSettings } from '../data/services/organizationSettingsService'
import { getTheme, getDefaultTheme } from '../config/themes'
import { generateTokens, getPlatformAdminFixedTokens, type ThemeTokens } from '../utils/themeTokens'

// Global theme version counter for triggering refetches
let globalThemeVersion = 0

/**
 * Trigger a refetch of the organization theme
 * Call this after updating theme settings to apply changes immediately
 */
export function refreshOrganizationTheme(newThemeId?: string | null): void {
  globalThemeVersion++
  // Dispatch custom event to notify all hooks
  window.dispatchEvent(new CustomEvent('organization-theme-changed', { detail: { themeId: newThemeId } }))
}

/**
 * Apply theme tokens to CSS variables on :root element
 * Batches all updates in a single DOM operation to prevent flicker
 */
function applyThemeTokens(tokens: ThemeTokens): void {
  const root = document.documentElement
  // Apply all tokens in a single synchronous operation
  Object.entries(tokens).forEach(([key, value]) => {
    root.style.setProperty(key, value)
  })
}

/**
 * Hook to apply organization theme
 *
 * Loads organization's theme_id from settings and applies semantic tokens.
 * Falls back to platform default theme if no theme selected or theme not found.
 * Applies default theme immediately on mount to prevent FOUC.
 * 
 * @returns { ready: boolean } - Indicates when theme is loaded and ready
 */
const PLATFORM_ADMIN_PATH_PREFIX = '/platform-admin'

/** Paths where org theme must never be shown (login, signup, etc.) */
const NO_ORG_THEME_PATHS: readonly string[] = [
  '/portal/login',
  '/portal/signup',
  '/portal/forgot-password',
  '/portal/reset-password',
  '/portal/accept-invite',
  '/portal/join/link',
  '/portal/auth/callback',
  '/portal/confirm-email',
  '/portal/unauthorized',
]

function isNoOrgThemePath(pathname: string): boolean {
  return NO_ORG_THEME_PATHS.some((p) => pathname === p || pathname.startsWith(p + '/'))
}

export function useOrganizationTheme(): { ready: boolean } {
  const location = useLocation()
  const { currentOrganization } = useOrganization()
  const { context } = useUserContext()
  const { resolvedTheme } = useTheme()
  const [themeId, setThemeId] = useState<string | null>(null)
  const [_, setIsLoading] = useState(false) // Start as false - theme is ready by default
  const [themeVersion, setThemeVersion] = useState(0)
  // Track if we've loaded the org theme
  const [, setHasLoadedOrgTheme] = useState(false)

  const isPlatformAdminRoute = location.pathname.startsWith(PLATFORM_ADMIN_PATH_PREFIX)
  const isNoOrgThemeRoute = isNoOrgThemePath(location.pathname)
  const useDefaultThemeOnly = isPlatformAdminRoute || isNoOrgThemeRoute

  // Listen for theme change events (do not apply org theme when on platform admin or auth routes)
  useLayoutEffect(() => {
    const handleThemeChanged = (e: Event) => {
      const customEvent = e as CustomEvent<{ themeId?: string | null }>
      if (customEvent.detail?.themeId !== undefined) {
        const newThemeId = customEvent.detail.themeId
        setThemeId(newThemeId)
        if (location.pathname.startsWith(PLATFORM_ADMIN_PATH_PREFIX)) {
          applyThemeTokens(getPlatformAdminFixedTokens())
        } else if (isNoOrgThemePath(location.pathname)) {
          applyThemeTokens(generateTokens(getDefaultTheme(), resolvedTheme === 'dark'))
        } else {
          const theme = newThemeId ? getTheme(newThemeId) : getDefaultTheme()
          applyThemeTokens(generateTokens(theme, resolvedTheme === 'dark'))
        }
        setHasLoadedOrgTheme(true)
        // themeId was provided directly — no need to re-fetch from server
      } else {
        // No themeId in event — bump version to trigger a re-fetch
        setThemeVersion(v => v + 1)
      }
    }
    window.addEventListener('organization-theme-changed', handleThemeChanged)
    return () => window.removeEventListener('organization-theme-changed', handleThemeChanged)
  }, [resolvedTheme, location.pathname])

  // Memoize token generation - only recalculate when theme ID or mode changes
  // When on platform admin route, use fixed PA tokens; on auth routes use default theme (no org colors)
  const tokens = useMemo(() => {
    if (isPlatformAdminRoute) {
      return getPlatformAdminFixedTokens()
    }
    if (isNoOrgThemeRoute) {
      return generateTokens(getDefaultTheme(), resolvedTheme === 'dark')
    }
    const theme = themeId ? getTheme(themeId) : getDefaultTheme()
    return generateTokens(theme, resolvedTheme === 'dark')
  }, [themeId, resolvedTheme, isPlatformAdminRoute, isNoOrgThemeRoute])

  // Apply default theme immediately on mount to prevent FOUC
  useLayoutEffect(() => {
    const tokensToApply = isPlatformAdminRoute
      ? getPlatformAdminFixedTokens()
      : generateTokens(getDefaultTheme(), resolvedTheme === 'dark')
    applyThemeTokens(tokensToApply)
  }, [resolvedTheme, isPlatformAdminRoute])

  // Apply tokens whenever they change - this ensures theme toggles work immediately
  // On platform admin route we always use fixed PA tokens (no org customization)
  useLayoutEffect(() => {
    applyThemeTokens(tokens)
  }, [tokens])

  // Re-apply tokens when tab becomes visible (fixes potential loss during background checks)
  useLayoutEffect(() => {
    const handleVisibilityChange = () => {
      if (!document.hidden) {
        applyThemeTokens(tokens)
      }
    }

    document.addEventListener('visibilitychange', handleVisibilityChange)
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange)
  }, [tokens])

  // Load and apply organization theme (skip when on platform admin or auth routes)
  useLayoutEffect(() => {
    const abortController = new AbortController()

    const loadAndApplyTheme = async () => {
      if (useDefaultThemeOnly) {
        setThemeId(null)
        setHasLoadedOrgTheme(true)
        setIsLoading(false)
        return
      }
      if (!context || !currentOrganization) {
        // No organization - clear any previous org theme and use default
        setThemeId(null)
        setHasLoadedOrgTheme(true)
        setIsLoading(false)
        return
      }

      // Only set loading if we're actually going to fetch
      setIsLoading(true)

      try {
        const start = performance.now()
        const result = await getOrganizationThemeSettings(context)

        if (abortController.signal.aborted) return

        if (process.env.NODE_ENV === 'development') {
          const duration = performance.now() - start
          if (duration > 500) {
            console.warn(`Theme fetch took ${duration.toFixed(2)}ms`)
          }
        }

        if (result.error) {
          console.warn('Failed to load organization theme settings:', result.error)
          // Keep default theme applied
          setThemeId(null)
          setHasLoadedOrgTheme(true)
          setIsLoading(false)
          return
        }

        // Get theme ID from settings
        const orgThemeId = result.data?.theme_id || null
        setThemeId(orgThemeId)
        setHasLoadedOrgTheme(true)
        setIsLoading(false)
      } catch (error) {
        if (abortController.signal.aborted) return
        console.warn('Failed to load organization theme settings:', error)
        // Keep default theme applied
        setThemeId(null)
        setHasLoadedOrgTheme(true)
        setIsLoading(false)
      }
    }

    loadAndApplyTheme()

    return () => {
      abortController.abort()
    }
  }, [context, currentOrganization?.id, themeVersion, useDefaultThemeOnly])

  // Return ready state - theme is always ready (default theme is applied immediately)
  // Loading state is only for background updates, doesn't block rendering
  const ready = useMemo(() => {
    // Theme is always ready - default theme is applied immediately
    // Loading only affects background theme updates
    return true
  }, [])

  return { ready }
}

/**
 * Theme Management Hook
 * 
 * Provides theme state management with:
 * - localStorage persistence (instant, works offline)
 * - Supabase sync (for cross-device consistency)
 * - System preference detection
 * - Demo mode support
 */

import { useState, useEffect, useCallback } from 'react'
import { useAuth } from './useAuth'
import { updateUserPreference, getUserPreferences } from '../data/services/preferencesService'

export type ThemeMode = 'light' | 'dark' | 'system'

interface ThemeState {
  mode: ThemeMode
  resolvedTheme: 'light' | 'dark' // Actual theme being applied
  loading: boolean
  error: Error | null
}

/**
 * Get system preference (light/dark)
 */
function getSystemTheme(): 'light' | 'dark' {
  if (typeof window === 'undefined') return 'light'
  
  try {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
  } catch {
    return 'light'
  }
}

/**
 * Get theme from localStorage
 */
function getStoredTheme(): ThemeMode | null {
  if (typeof window === 'undefined') return null
  
  try {
    const stored = localStorage.getItem('theme-preference')
    if (stored === 'light' || stored === 'dark' || stored === 'system') {
      return stored as ThemeMode
    }
  } catch (error) {
    // Silently fail
  }
  
  return null
}

/**
 * Store theme to localStorage
 */
function setStoredTheme(theme: ThemeMode): void {
  if (typeof window === 'undefined') return
  
  try {
    localStorage.setItem('theme-preference', theme)
  } catch (error) {
    // Silently fail
  }
}

/**
 * Apply theme class to document
 */
function applyTheme(theme: 'light' | 'dark'): void {
  if (typeof document === 'undefined') return
  
  const html = document.documentElement
  if (theme === 'dark') {
    html.classList.add('dark')
  } else {
    html.classList.remove('dark')
  }
}

/**
 * Resolve actual theme from mode
 */
function resolveTheme(mode: ThemeMode): 'light' | 'dark' {
  if (mode === 'system') {
    return getSystemTheme()
  }
  return mode
}

export function useTheme() {
  const { user, profile } = useAuth()
  const [state, setState] = useState<ThemeState>(() => {
    // Initialize from localStorage (instant)
    const stored = getStoredTheme()
    const initialMode = stored || 'system'
    const resolved = resolveTheme(initialMode)
    
    // Apply immediately (before React hydration)
    if (typeof document !== 'undefined') {
      applyTheme(resolved)
    }
    
    return {
      mode: initialMode,
      resolvedTheme: resolved,
      loading: true, // Will load from Supabase if authenticated
      error: null,
    }
  })

  // Load from Supabase on mount (if authenticated)
  // CRITICAL: localStorage is the source of truth - only use Supabase if localStorage is empty
  useEffect(() => {
    if (!user || !profile) {
      // Not authenticated - use localStorage only
      setState(prev => ({ ...prev, loading: false }))
      return
    }

    let cancelled = false

    const loadFromSupabase = async () => {
      try {
        // Check localStorage first - it's the source of truth for user's current preference
        const storedLocal = getStoredTheme()
        
        // If localStorage has a value, use it and sync to Supabase (localStorage wins)
        if (storedLocal) {
          // Sync localStorage value to Supabase in background (non-blocking)
          updateUserPreference(user.id, 'theme', storedLocal).catch(() => {
            // Silently fail - non-critical
          })
          
          // Keep using localStorage value
          setState(prev => ({ ...prev, loading: false }))
          return
        }

        // localStorage is empty - try Supabase (first-time user or cleared storage)
        const { data, error } = await getUserPreferences(user.id)
        
        if (cancelled) return

        if (error) {
          setState(prev => ({ ...prev, loading: false }))
          return
        }

        // If Supabase has a preference and localStorage is empty, use Supabase
        if (data?.theme) {
          const supabaseTheme = data.theme as ThemeMode
          if (supabaseTheme === 'light' || supabaseTheme === 'dark' || supabaseTheme === 'system') {
            setStoredTheme(supabaseTheme)
            const resolved = resolveTheme(supabaseTheme)
            applyTheme(resolved)
            setState({
              mode: supabaseTheme,
              resolvedTheme: resolved,
              loading: false,
              error: null,
            })
            return
          }
        }

        // No preference anywhere - keep current state (system default)
        setState(prev => ({ ...prev, loading: false }))
      } catch (err) {
        if (cancelled) return
        setState(prev => ({ ...prev, loading: false, error: err instanceof Error ? err : new Error('Unknown error') }))
      }
    }

    loadFromSupabase()

    return () => {
      cancelled = true
    }
  }, [user, profile])

  // Listen to system preference changes (when mode is 'system')
  useEffect(() => {
    if (state.mode !== 'system') return

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)')
    
    const handleChange = () => {
      const resolved = resolveTheme('system')
      applyTheme(resolved)
      setState(prev => ({ ...prev, resolvedTheme: resolved }))
    }

    // Modern browsers
    if (mediaQuery.addEventListener) {
      mediaQuery.addEventListener('change', handleChange)
      return () => mediaQuery.removeEventListener('change', handleChange)
    }
    
    // Fallback for older browsers
    mediaQuery.addListener(handleChange)
    return () => mediaQuery.removeListener(handleChange)
  }, [state.mode])

  // Toggle theme
  const setTheme = useCallback(async (mode: ThemeMode) => {
    // Update local state immediately
    const resolved = resolveTheme(mode)
    applyTheme(resolved)
    setStoredTheme(mode)
    
    setState({
      mode,
      resolvedTheme: resolved,
      loading: false,
      error: null,
    })

    // Sync to Supabase (if authenticated, non-blocking)
    if (user && profile) {
      try {
        await updateUserPreference(user.id, 'theme', mode)
      } catch (error) {
        // Don't update state - localStorage is already updated
        setState(prev => ({ ...prev, error: error instanceof Error ? error : new Error('Unknown error') }))
      }
    }
  }, [user, profile])

  return {
    mode: state.mode,
    resolvedTheme: state.resolvedTheme,
    loading: state.loading,
    error: state.error,
    setTheme,
    toggle: useCallback(() => {
      // Toggle between light and dark (skip system)
      const nextMode = state.resolvedTheme === 'dark' ? 'light' : 'dark'
      setTheme(nextMode)
    }, [state.resolvedTheme, setTheme]),
  }
}

/**
 * Extended Video Library Hooks
 * 
 * Additional hooks for video library features:
 * - Video sharing with expiration
 * - Video favorites (bookmarks)
 * - Full-text search
 * - Bulk operations
 * - Real-time status updates
 * 
 * NOTE: video_shares and video_favorites tables are created by migration
 * 20260410000020_video_library_features.sql. Run the migration and regenerate
 * types to remove type errors.
 */

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import { supabase } from '@/lib/supabase'
import type { Video } from '@/types/video'
import { useAuth } from './useAuth'

// Type assertion helper for new tables not yet in generated types
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const db = supabase as any

// ============================================================================
// Types
