// ============================================================================
// Video Share Hooks
// ============================================================================

interface UseVideoSharesOptions {
  videoId?: string
  enabled?: boolean
}

interface UseVideoSharesReturn {
  shares: VideoShare[]
  isLoading: boolean
  error: Error | null
  createShare: (options: Omit<CreateShareOptions, 'videoId' | 'orgId'>) => Promise<VideoShare | null>
  revokeShare: (shareId: string) => Promise<boolean>
  refresh: () => Promise<void>
}

function generateSecureToken(): string {
  const array = new Uint8Array(32)
  crypto.getRandomValues(array)
  return Array.from(array, byte => byte.toString(16).padStart(2, '0')).join('')
}

function getExpirationDate(expiration: ShareExpiration): string | null {
  const now = new Date()
  switch (expiration) {
    case '1h':
      return new Date(now.getTime() + 60 * 60 * 1000).toISOString()
    case '24h':
      return new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString()
    case '7d':
      return new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString()
    case '30d':
      return new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString()
    case 'never':
      return null
    default:
      return new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString()
  }
}

export function useVideoShares({ videoId, enabled = true }: UseVideoSharesOptions): UseVideoSharesReturn {
  const { user } = useAuth()
  const [shares, setShares] = useState<VideoShare[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)

  const fetchShares = useCallback(async () => {
    if (!videoId || !enabled) return

    setIsLoading(true)
    setError(null)

    try {
      const { data, error: fetchError } = await db
        .from('video_shares')
        .select('*')
        .eq('video_id', videoId)
        .order('created_at', { ascending: false })

      if (fetchError) throw fetchError

      setShares((data || []) as VideoShare[])
    } catch (err) {
      console.error('Error fetching video shares:', err)
      setError(err instanceof Error ? err : new Error('Failed to fetch shares'))
    } finally {
      setIsLoading(false)
    }
  }, [videoId, enabled])

  useEffect(() => {
    fetchShares()
  }, [fetchShares])

  const createShare = useCallback(async (
    options: Omit<CreateShareOptions, 'videoId' | 'orgId'>
  ): Promise<VideoShare | null> => {
    if (!videoId || !user?.id) return null

    try {
      // Get org_id from the video
      const { data: video, error: videoError } = await supabase
        .from('videos')
        .select('org_id')
        .eq('id', videoId)
        .single()

      if (videoError || !video) throw new Error('Video not found')

      const token = generateSecureToken()
      const expiresAt = getExpirationDate(options.expiration)

      const { data, error: createError } = await db
        .from('video_shares')
        .insert({
          video_id: videoId,
          org_id: video.org_id,
          token,
          created_by: user.id,
          expires_at: expiresAt,
          allow_download: options.allowDownload ?? false,
          email_recipients: options.emailRecipients ?? null,
        })
        .select()
        .single()

      if (createError) throw createError

      const newShare = data as VideoShare
      setShares(prev => [newShare, ...prev])
      return newShare
    } catch (err) {
      console.error('Error creating share:', err)
      return null
    }
  }, [videoId, user?.id])

  const revokeShare = useCallback(async (shareId: string): Promise<boolean> => {
    try {
      const { error: updateError } = await db
        .from('video_shares')
        .update({ revoked_at: new Date().toISOString() })
        .eq('id', shareId)

      if (updateError) throw updateError

      setShares(prev => prev.map(s => 
        s.id === shareId ? { ...s, revoked_at: new Date().toISOString() } : s
      ))
      return true
    } catch (err) {
      console.error('Error revoking share:', err)
      return false
    }
  }, [])

  return { shares, isLoading, error, createShare, revokeShare, refresh: fetchShares }
}

// ============================================================================
// Video Favorites Hook
// ============================================================================

interface UseVideoFavoritesOptions {
  orgId?: string
  enabled?: boolean
}

interface UseVideoFavoritesReturn {
  favorites: VideoFavorite[]
  favoriteVideoIds: Set<string>
  isLoading: boolean
  error: Error | null
  toggleFavorite: (videoId: string) => Promise<boolean>
  isFavorite: (videoId: string) => boolean
  refresh: () => Promise<void>
}

export function useVideoFavorites({ orgId, enabled = true }: UseVideoFavoritesOptions): UseVideoFavoritesReturn {
  const { user } = useAuth()
  const [favorites, setFavorites] = useState<VideoFavorite[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)

  const favoriteVideoIds = useMemo(() => 
    new Set(favorites.map(f => f.video_id)),
    [favorites]
  )

  const fetchFavorites = useCallback(async () => {
    if (!user?.id || !enabled) return

    setIsLoading(true)
    setError(null)

    try {
      let query = db
        .from('video_favorites')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })

      if (orgId) {
        query = query.eq('org_id', orgId)
      }

      const { data, error: fetchError } = await query

      if (fetchError) throw fetchError

      setFavorites((data || []) as VideoFavorite[])
    } catch (err) {
      console.error('Error fetching favorites:', err)
      setError(err instanceof Error ? err : new Error('Failed to fetch favorites'))
    } finally {
      setIsLoading(false)
    }
  }, [user?.id, orgId, enabled])

  useEffect(() => {
    fetchFavorites()
  }, [fetchFavorites])

  const toggleFavorite = useCallback(async (videoId: string): Promise<boolean> => {
    if (!user?.id) return false

    const isCurrentlyFavorite = favoriteVideoIds.has(videoId)

    try {
      if (isCurrentlyFavorite) {
        // Remove favorite
        const { error: deleteError } = await db
          .from('video_favorites')
          .delete()
          .eq('video_id', videoId)
          .eq('user_id', user.id)

        if (deleteError) throw deleteError

        setFavorites(prev => prev.filter(f => f.video_id !== videoId))
      } else {
        // Get video's org_id first
        const { data: video, error: videoError } = await supabase
          .from('videos')
          .select('org_id')
          .eq('id', videoId)
          .single()

        if (videoError || !video) throw new Error('Video not found')

        // Add favorite
        const { data, error: insertError } = await db
          .from('video_favorites')
          .insert({
            video_id: videoId,
            user_id: user.id,
            org_id: video.org_id,
          })
          .select()
          .single()

        if (insertError) throw insertError

        setFavorites(prev => [data as VideoFavorite, ...prev])
      }

      return true
    } catch (err) {
      console.error('Error toggling favorite:', err)
      return false
    }
  }, [user?.id, favoriteVideoIds])

  const isFavorite = useCallback((videoId: string) => {
    return favoriteVideoIds.has(videoId)
  }, [favoriteVideoIds])

  return { 
    favorites, 
    favoriteVideoIds, 
    isLoading, 
    error, 
    toggleFavorite, 
    isFavorite, 
    refresh: fetchFavorites 
  }
}

// ============================================================================
// Full-Text Search Hook
// ============================================================================

type VideoFilters = Record<string, any>

interface UseVideoSearchOptions {
  orgId?: string
  query?: string
  filters?: VideoFilters
  limit?: number
  enabled?: boolean
}

interface UseVideoSearchReturn {
  videos: Video[]
  total: number
  isLoading: boolean
  error: Error | null
  search: (query: string) => Promise<void>
  refresh: () => Promise<void>
}

export function useVideoSearch({ 
  orgId, 
  query: initialQuery = '', 
  filters = {},
  limit = 20,
  enabled = true 
}: UseVideoSearchOptions): UseVideoSearchReturn {
  const [videos, setVideos] = useState<Video[]>([])
  const [total, setTotal] = useState(0)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)
  const [currentQuery, setCurrentQuery] = useState(initialQuery)

  const performSearch = useCallback(async (searchQuery: string) => {
    if (!orgId || !enabled) return

    setIsLoading(true)
    setError(null)
    setCurrentQuery(searchQuery)

    try {
      let query = supabase
        .from('videos')
        .select(`
          *,
          team:teams!videos_team_id_fkey(id, name),
          video_tag_links(id, tag_id, tag:video_tags(id, name, tag_type, color))
        `, { count: 'exact' })
        .eq('org_id', orgId)
        .neq('status', 'deleted')

      // Full-text search if query provided
      if (searchQuery.trim()) {
        // Use plainto_tsquery for user input
        query = query.textSearch('search_vector', searchQuery.trim(), {
          type: 'websearch',
          config: 'english'
        })
      }

      // Apply filters
      if (filters.category) {
        const categories = Array.isArray(filters.category) ? filters.category : [filters.category]
        query = query.in('category', categories)
      }

      if (filters.team_id) {
        query = query.eq('team_id', filters.team_id)
      }

      if (filters.status) {
        const statuses = Array.isArray(filters.status) ? filters.status : [filters.status]
        query = query.in('status', statuses)
      }

      if (filters.date_from) {
        query = query.gte('recorded_at', filters.date_from)
      }

      if (filters.date_to) {
        query = query.lte('recorded_at', filters.date_to)
      }

      // Note: Tag filtering requires video_tag_links table
      // For now, tag filtering should be done via the main videos hook
      // which already supports tag filtering through video_tags join

      query = query
        .order('created_at', { ascending: false })
        .limit(limit)

      const { data, error: fetchError, count } = await query

      if (fetchError) throw fetchError

      setVideos((data || []) as unknown as Video[])
      setTotal(count || 0)
    } catch (err) {
      console.error('Error searching videos:', err)
      setError(err instanceof Error ? err : new Error('Failed to search videos'))
    } finally {
      setIsLoading(false)
    }
  }, [orgId, filters, limit, enabled])

  useEffect(() => {
    performSearch(currentQuery)
  }, [performSearch, currentQuery])

  const search = useCallback(async (query: string) => {
    await performSearch(query)
  }, [performSearch])

  return { 
    videos, 
    total, 
    isLoading, 
    error, 
    search, 
    refresh: () => performSearch(currentQuery) 
  }
}

// ============================================================================
// Bulk Operations Hook
// ============================================================================

interface UseBulkVideoOperationsOptions {
  orgId?: string
}

interface UseBulkVideoOperationsReturn {
  isProcessing: boolean
  progress: { current: number; total: number }
  bulkDelete: (videoIds: string[]) => Promise<BulkOperationResult>
  bulkAddTags: (videoIds: string[], tagIds: string[]) => Promise<BulkOperationResult>
  bulkRemoveTags: (videoIds: string[], tagIds: string[]) => Promise<BulkOperationResult>
  bulkMove: (videoIds: string[], teamId: string | null) => Promise<BulkOperationResult>
}

export function useBulkVideoOperations({ orgId: _orgId }: UseBulkVideoOperationsOptions): UseBulkVideoOperationsReturn {
  const { user } = useAuth()
  const [isProcessing, setIsProcessing] = useState(false)
  const [progress, setProgress] = useState({ current: 0, total: 0 })

  const bulkDelete = useCallback(async (videoIds: string[]): Promise<BulkOperationResult> => {
    if (!user?.id) return { succeeded: [], failed: videoIds.map(id => ({ id, error: 'Not authenticated' })) }

    setIsProcessing(true)
    setProgress({ current: 0, total: videoIds.length })

    const result: BulkOperationResult = { succeeded: [], failed: [] }

    for (let i = 0; i < videoIds.length; i++) {
      const videoId = videoIds[i]
      try {
        const { error } = await supabase
          .from('videos')
          .update({ 
            status: 'deleted',
            deleted_at: new Date().toISOString(),
          })
          .eq('id', videoId)

        if (error) throw error

        result.succeeded.push(videoId)
      } catch (err) {
        result.failed.push({ 
          id: videoId, 
          error: err instanceof Error ? err.message : 'Unknown error' 
        })
      }

      setProgress({ current: i + 1, total: videoIds.length })
    }

    setIsProcessing(false)
    return result
  }, [user?.id])

  const bulkAddTags = useCallback(async (videoIds: string[], tagIds: string[]): Promise<BulkOperationResult> => {
    if (!user?.id) return { succeeded: [], failed: videoIds.map(id => ({ id, error: 'Not authenticated' })) }

    setIsProcessing(true)
    setProgress({ current: 0, total: videoIds.length })

    const result: BulkOperationResult = { succeeded: [], failed: [] }

    for (let i = 0; i < videoIds.length; i++) {
      const videoId = videoIds[i]
      try {
        // Insert all tags for this video
        const { error } = await supabase
          .from('video_tag_links')
          .upsert(
            tagIds.map(tagId => ({
              video_id: videoId,
              tag_id: tagId,
              created_by: user.id,
            })),
            { onConflict: 'video_id,tag_id' }
          )

        if (error) throw error

        result.succeeded.push(videoId)
      } catch (err) {
        result.failed.push({ 
          id: videoId, 
          error: err instanceof Error ? err.message : 'Unknown error' 
        })
      }

      setProgress({ current: i + 1, total: videoIds.length })
    }

    setIsProcessing(false)
    return result
  }, [user?.id])

  const bulkRemoveTags = useCallback(async (videoIds: string[], tagIds: string[]): Promise<BulkOperationResult> => {
    if (!user?.id) return { succeeded: [], failed: videoIds.map(id => ({ id, error: 'Not authenticated' })) }

    setIsProcessing(true)
    setProgress({ current: 0, total: videoIds.length })

    const result: BulkOperationResult = { succeeded: [], failed: [] }

    for (let i = 0; i < videoIds.length; i++) {
      const videoId = videoIds[i]
      try {
        const { error } = await supabase
          .from('video_tag_links')
          .delete()
          .eq('video_id', videoId)
          .in('tag_id', tagIds)

        if (error) throw error

        result.succeeded.push(videoId)
      } catch (err) {
        result.failed.push({ 
          id: videoId, 
          error: err instanceof Error ? err.message : 'Unknown error' 
        })
      }

      setProgress({ current: i + 1, total: videoIds.length })
    }

    setIsProcessing(false)
    return result
  }, [user?.id])

  const bulkMove = useCallback(async (videoIds: string[], teamId: string | null): Promise<BulkOperationResult> => {
    if (!user?.id) return { succeeded: [], failed: videoIds.map(id => ({ id, error: 'Not authenticated' })) }

    setIsProcessing(true)
    setProgress({ current: 0, total: videoIds.length })

    const result: BulkOperationResult = { succeeded: [], failed: [] }

    for (let i = 0; i < videoIds.length; i++) {
      const videoId = videoIds[i]
      try {
        const { error } = await supabase
          .from('videos')
          .update({ team_id: teamId })
          .eq('id', videoId)

        if (error) throw error

        result.succeeded.push(videoId)
      } catch (err) {
        result.failed.push({ 
          id: videoId, 
          error: err instanceof Error ? err.message : 'Unknown error' 
        })
      }

      setProgress({ current: i + 1, total: videoIds.length })
    }

    setIsProcessing(false)
    return result
  }, [user?.id])

  return { isProcessing, progress, bulkDelete, bulkAddTags, bulkRemoveTags, bulkMove }
}

// ============================================================================
// Real-Time Video Status Hook
// ============================================================================

interface UseVideoStatusRealtimeOptions {
  videoId?: string
  enabled?: boolean
}

interface UseVideoStatusRealtimeReturn {
  status: string | null
  thumbnailUrl: string | null
  isSubscribed: boolean
}

export function useVideoStatusRealtime({ videoId, enabled = true }: UseVideoStatusRealtimeOptions): UseVideoStatusRealtimeReturn {
  const [status, setStatus] = useState<string | null>(null)
  const [thumbnailUrl, setThumbnailUrl] = useState<string | null>(null)
  const [isSubscribed, setIsSubscribed] = useState(false)
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null)

  useEffect(() => {
    if (!videoId || !enabled) {
      setIsSubscribed(false)
      return
    }

    // Subscribe to video status changes
    channelRef.current = supabase
      .channel(`video-status-${videoId}`)
      .on('postgres_changes', {
        event: 'UPDATE',
        schema: 'public',
        table: 'videos',
        filter: `id=eq.${videoId}`,
      }, (payload) => {
        const newData = payload.new as { status?: string; thumbnail_url?: string }
        if (newData.status) {
          setStatus(newData.status)
        }
        if (newData.thumbnail_url) {
          setThumbnailUrl(newData.thumbnail_url)
        }
      })
      .subscribe((status) => {
        setIsSubscribed(status === 'SUBSCRIBED')
      })

    return () => {
      if (channelRef.current) {
        supabase.removeChannel(channelRef.current)
        channelRef.current = null
      }
      setIsSubscribed(false)
    }
  }, [videoId, enabled])

  return { status, thumbnailUrl, isSubscribed }
}

// ============================================================================
// Download URL Hook
// ============================================================================

interface UseVideoDownloadOptions {
  videoId?: string
}

interface UseVideoDownloadReturn {
  getDownloadUrl: () => Promise<string | null>
  isLoading: boolean
  error: Error | null
}

export function useVideoDownload({ videoId }: UseVideoDownloadOptions): UseVideoDownloadReturn {
  const { session } = useAuth()
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<Error | null>(null)

  const getDownloadUrl = useCallback(async (): Promise<string | null> => {
    if (!videoId || !session?.access_token) {
      setError(new Error('Not authenticated or no video specified'))
      return null
    }

    setIsLoading(true)
    setError(null)

    try {
      // Get the Mux playback ID
      const { data: video, error: videoError } = await supabase
        .from('videos')
        .select('mux_playback_id, title')
        .eq('id', videoId)
        .single()

      if (videoError || !video?.mux_playback_id) {
        throw new Error('Video not found or not ready for download')
      }

      // Get a signed playback token for download
      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
      const response = await fetch(`${supabaseUrl}/functions/v1/mux-signed-playback`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${session.access_token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          video_id: videoId,
          type: 'video',
          expiration: 300, // 5 minutes
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to get download URL')
      }

      const data = await response.json()
      return data.stream_url || null
    } catch (err) {
      console.error('Error getting download URL:', err)
      setError(err instanceof Error ? err : new Error('Failed to get download URL'))
      return null
    } finally {
      setIsLoading(false)
    }
  }, [videoId, session?.access_token])

  return { getDownloadUrl, isLoading, error }
}

import { createContext, useState, useEffect, type ReactNode } from 'react'
import { setLocale as setModuleLocale, type Locale, type TranslationKey, format } from './index'
import { translations } from './translations'

/**
 * Context value shape for I18n.
 */
interface I18nContextValue {
  locale: Locale
  setLocale: (locale: Locale) => void
  t: (key: TranslationKey, params?: Record<string, string | number>) => string
}

/**
 * React context for i18n state.
 * Do not use directly - use the useT() or useLocale() hooks instead.
 */
export const I18nContext = createContext<I18nContextValue | undefined>(undefined)

interface I18nProviderProps {
  children: ReactNode
}

const STORAGE_KEY = 'teamhub_locale'

/**
 * Detect the user's preferred locale from browser settings.
 * Maps browser language codes to our supported locales.
 * 
 * @returns Detected locale or 'en' as fallback
 */
function detectBrowserLocale(): Locale {
  // Guard against non-browser environments (SSR, tests)
  if (typeof navigator === 'undefined') return 'en'

  const browserLang = navigator.language || 'en'
  
  // Map browser language codes to our supported locales
  // es-ES, es-MX, es-419, etc. -> 'es'
  if (browserLang.startsWith('es')) return 'es'
  
  // Default to English
  return 'en'
}

/**
 * Get the initial locale from localStorage or browser settings.
 * 
 * Precedence:
 * 1. localStorage (user's explicit choice)
 * 2. navigator.language (browser preference)
 * 3. 'en' (default fallback)
 */
function getInitialLocale(): Locale {
  // Guard against non-browser environments
  if (typeof window === 'undefined') return 'en'

  try {
    // Try localStorage first
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored && stored in translations) {
      return stored as Locale
    }
  } catch (error) {
    // localStorage might be unavailable (private browsing, etc.)
    console.warn('Failed to read locale from localStorage:', error)
  }

  // Fall back to browser detection
  return detectBrowserLocale()
}

/**
 * I18nProvider - App-wide localization provider.
 * 
 * Features:
 * - Persists locale to localStorage
 * - Detects browser locale on first visit
 * - Re-renders UI when locale changes
 * - Provides t() function via context
 * 
 * Usage:
 * Wrap your app root with this provider, then use useT() or useLocale() hooks.
 */
export function I18nProvider({ children }: I18nProviderProps) {
  const [locale, setLocaleState] = useState<Locale>(getInitialLocale)

  // Sync locale changes to module-level state and localStorage
  useEffect(() => {
    // Update module-level locale (for non-React code)
    setModuleLocale(locale)

    // Persist to localStorage
    try {
      localStorage.setItem(STORAGE_KEY, locale)
    } catch (error) {
      console.warn('Failed to persist locale to localStorage:', error)
    }
  }, [locale])

  /**
   * Change the active locale.
   * This will trigger a re-render of all components using i18n hooks.
   */
  const setLocale = (newLocale: Locale) => {
    if (newLocale in translations) {
      setLocaleState(newLocale)
    } else {
      console.warn(`Attempted to set unsupported locale: ${newLocale}`)
    }
  }

  /**
   * Translate function bound to current locale.
   * Automatically re-renders when locale changes.
   */
  const t = (key: TranslationKey, params?: Record<string, string | number>): string => {
    const dict = translations[locale]
    const defaultDict = translations['en']

    // Lookup in current locale, fall back to English, then show key
    const segments = key.split('.')
    let current: unknown = dict
    let fallback: unknown = defaultDict

    for (const segment of segments) {
      if (current && typeof current === 'object' && segment in (current as Record<string, unknown>)) {
        current = (current as Record<string, unknown>)[segment]
      } else {
        current = undefined
      }

      if (fallback && typeof fallback === 'object' && segment in (fallback as Record<string, unknown>)) {
        fallback = (fallback as Record<string, unknown>)[segment]
      } else {
        fallback = undefined
      }
    }

    const template = 
      (typeof current === 'string' ? current : undefined) ??
      (typeof fallback === 'string' ? fallback : undefined) ??
      String(key)

    // Apply parameter interpolation if provided
    if (!params) return template
    return format(template, params)
  }

  const value: I18nContextValue = {
    locale,
    setLocale,
    t,
  }

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

/**
 * Debug Logging System - Route Logger
 *
 * React component that automatically logs route changes
 * for navigation debugging. Only active in development mode.
 */

import { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { debug } from '../index';

/**
 * RouteLogger component - automatically logs route changes
 *
 * This component has no visual output and should be placed
 * early in the component tree to capture all navigation.
 */
export function RouteLogger(): null {
  const location = useLocation();
  const previousLocationRef = useRef<string | null>(null);

  useEffect(() => {
    const currentPath = location.pathname + location.search + location.hash;

    if (previousLocationRef.current === null) {
      // First mount - log initial route
      debug.flow('Router', `Initial route: ${currentPath}`, {
        pathname: location.pathname,
        search: location.search,
        hash: location.hash,
      });
    } else if (previousLocationRef.current !== currentPath) {
      // Route changed - log navigation
      const prevPath = previousLocationRef.current;
      debug.flow('Router', `Navigated: ${prevPath} → ${currentPath}`, {
        from: prevPath,
        to: currentPath,
        pathname: location.pathname,
        search: location.search,
        hash: location.hash,
      });
    }

    // Update the ref for next comparison
    previousLocationRef.current = currentPath;
  }, [location]);

  // This component renders nothing
  return null;
}

// Export a conditional version that only renders in development
export const ConditionalRouteLogger = import.meta.env.DEV ? RouteLogger : (): null => null;

/**
 * FeatureGateProvider
 * 
 * React context provider that:
 * 1. Prefetches all navigation-relevant feature gates on mount
 * 2. Re-fetches when the org or license changes
 * 3. Listens for cache invalidation events (e.g. license upgrade) and refetches
 * 4. Shares prefetched results via context so child hooks can read warm-cache values
 * 5. Runs dev-mode registry validation on first mount
 *
 * Place inside OrganizationProvider + AuthProvider but outside route tree.
 */

import {
    createContext,
    useContext,
    useEffect,
    useRef,
    useCallback,
    useMemo,
    type ReactNode,
} from 'react';
import { useOrganization } from '@/contexts/OrganizationContext';
import { useAuth } from '@/hooks/useAuth';
import {
    fetchFeatureGates,
    onCacheInvalidation,
    clearFeatureGateCache,
} from './api';
import { getAllRouteFeatureKeys, validateRegistry } from './registry';
import type { FeatureGateContext } from './types';

// ---------------------------------------------------------------------------
// Context
// ---------------------------------------------------------------------------

interface FeatureGateProviderContextValue {
    /** Whether the initial prefetch has completed */
    prefetched: boolean;
    /** Trigger a full re-prefetch (e.g. after a plan change) */
    invalidate: () => void;
}

const FeatureGateProviderContext = createContext<FeatureGateProviderContextValue>({
    prefetched: false,
    invalidate: () => {},
});

export function useFeatureGateProvider(): FeatureGateProviderContextValue {
    return useContext(FeatureGateProviderContext);
}

// ---------------------------------------------------------------------------
// Provider
// ---------------------------------------------------------------------------

interface FeatureGateProviderProps {
    children: ReactNode;
}

export function FeatureGateProvider({ children }: FeatureGateProviderProps) {
    const { currentOrganization } = useOrganization();
    const { user, profile } = useAuth();
    const prefetchedRef = useRef(false);
    const abortRef = useRef<AbortController | null>(null);

    // Run dev-mode registry validation once
    useEffect(() => {
        if (import.meta.env.DEV) {
            const errors = validateRegistry();
            if (errors.length > 0) {
                console.warn(
                    '[FeatureGateProvider] Registry validation issues:\n' +
                    errors.join('\n')
                );
            }
        }
    }, []);

    // Build the RPC context
    const context: FeatureGateContext | null = useMemo(() => {
        if (!user?.id || !profile) return null;

        const currentOrg = profile.organizations.find(
            (org) => org.id === currentOrganization?.id
        );
        const currentOrgRole = currentOrg?.roles?.[0] ?? 'parent';

        return {
            org_id: currentOrganization?.id ?? null,
            user_id: user.id,
            role: currentOrgRole as 'parent' | 'coach' | 'org_admin',
            license_tier: null,
            is_platform_admin: profile.isPlatformAdmin ?? false,
        };
    }, [user?.id, profile, currentOrganization?.id]);

    // Prefetch all route feature keys so the cache is warm
    const prefetch = useCallback(
        async (signal?: AbortSignal) => {
            if (!context) return;

            const featureKeys = getAllRouteFeatureKeys();
            if (featureKeys.length === 0) return;

            try {
                await fetchFeatureGates(featureKeys, context, signal);
                if (!signal?.aborted) {
                    prefetchedRef.current = true;
                }
            } catch (err) {
                if (err instanceof DOMException && err.name === 'AbortError') return;
                console.error('[FeatureGateProvider] Prefetch error:', err);
            }
        },
        [context]
    );

    // Prefetch whenever context changes (login, org switch)
    useEffect(() => {
        abortRef.current?.abort();
        const ac = new AbortController();
        abortRef.current = ac;
        prefetchedRef.current = false;
        prefetch(ac.signal);
        return () => ac.abort();
    }, [prefetch]);

    // Listen for cache invalidation events (fired by clearFeatureGateCache*)
    useEffect(() => {
        const unsubscribe = onCacheInvalidation(() => {
            abortRef.current?.abort();
            const ac = new AbortController();
            abortRef.current = ac;
            prefetchedRef.current = false;
            prefetch(ac.signal);
        });
        return unsubscribe;
    }, [prefetch]);

    const invalidate = useCallback(() => {
        clearFeatureGateCache();
    }, []);

    const value = useMemo<FeatureGateProviderContextValue>(
        () => ({ prefetched: prefetchedRef.current, invalidate }),
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [invalidate, context]
    );

    return (
        <FeatureGateProviderContext.Provider value={value}>
            {children}
        </FeatureGateProviderContext.Provider>
    );
}

export default FeatureGateProvider;

/**
 * useFeatureGateBatch Hook
 * 
 * React hook to check feature gates for multiple features at once.
 * Useful for navigation filtering where many features need to be checked.
 *
 * Improvements:
 *  - AbortController cancels in-flight batch requests on unmount / dependency change
 *  - Context validation logs warnings in dev when org_id is missing
 *  - AbortError is silently swallowed (component unmounted)
 */

import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useOrganization } from '@/contexts/OrganizationContext';
import { useAuth } from '@/hooks/useAuth';
import { fetchFeatureGates } from './api';
import type { FeatureGateResult, FeatureGateContext, UseFeatureGateBatchResult } from './types';

// Warn only once per session
let _batchContextWarned = false;

/**
 * Hook to check feature gates for multiple features at once
 * 
 * @param featureKeys - Array of feature keys to check
 * @returns Map of feature key to gate result, with loading state
 */
export function useFeatureGateBatch(featureKeys: string[]): UseFeatureGateBatchResult {
    const { currentOrganization, organizations, isLoading: isOrganizationLoading } = useOrganization();
    const { user, profile } = useAuth();

    const [gates, setGates] = useState<Map<string, FeatureGateResult>>(new Map());
    const [loading, setLoading] = useState(true);

    // Track if component is mounted
    const isMountedRef = useRef(true);
    useEffect(() => {
        isMountedRef.current = true;
        return () => {
            isMountedRef.current = false;
        };
    }, []);

    const skipOrgScopedChecks = useMemo(() => {
        if (!user?.id || !profile) return false;
        return !profile.isPlatformAdmin && !isOrganizationLoading && !currentOrganization?.id;
    }, [user?.id, profile, isOrganizationLoading, currentOrganization?.id]);

    // Build context — with dev-mode validation
    const context: FeatureGateContext | null = useMemo(() => {
        if (!user?.id || !profile) {
            return null;
        }

        const currentOrg = profile.organizations.find(
            org => org.id === currentOrganization?.id
        );
        const currentOrgRole = currentOrg?.roles?.[0] ?? 'parent';

        const orgId = currentOrganization?.id ?? null;

        if (
            import.meta.env.DEV &&
            featureKeys.length > 0 &&
            !orgId &&
            organizations.length > 0 &&
            !isOrganizationLoading &&
            !profile.isPlatformAdmin
        ) {
            if (!_batchContextWarned) {
                _batchContextWarned = true;
                console.warn(
                    `[useFeatureGateBatch] Checking ${featureKeys.length} features without an org_id. ` +
                    'Ensure OrganizationContext is set.'
                );
            }
        }

        return {
            org_id: orgId,
            user_id: user.id,
            role: currentOrgRole as 'parent' | 'coach' | 'org_admin',
            license_tier: null,
            is_platform_admin: profile.isPlatformAdmin ?? false,
        };
    }, [user?.id, profile, currentOrganization?.id, organizations.length, isOrganizationLoading, featureKeys.length]);

    // Stable key string for dependency checking (sorted to avoid re-renders from order changes)
    const keysString = useMemo(() =>
        [...featureKeys].sort().join(','),
        [featureKeys]
    );

    const refetch = useCallback(async (signal?: AbortSignal) => {
        // No keys to fetch
        if (featureKeys.length === 0) {
            if (isMountedRef.current) {
                setGates(new Map());
                setLoading(false);
            }
            return;
        }

        // No context yet — still loading
        if (!context) {
            if (isMountedRef.current) {
                setLoading(true);
            }
            return;
        }

        // User has no organization context yet; skip org-scoped checks until org is selected/available
        if (skipOrgScopedChecks) {
            if (isMountedRef.current) {
                setGates(new Map());
                setLoading(false);
            }
            return;
        }

        if (isMountedRef.current) {
            setLoading(true);
        }

        try {
            const results = await fetchFeatureGates(featureKeys, context, signal);

            if (isMountedRef.current && !signal?.aborted) {
                const newMap = new Map<string, FeatureGateResult>();
                for (const [key, value] of Object.entries(results)) {
                    newMap.set(key, value);
                }
                setGates(newMap);
            }
        } catch (err) {
            // Silently ignore AbortError — component unmounted or deps changed
            if (err instanceof DOMException && err.name === 'AbortError') {
                return;
            }
            console.error('[useFeatureGateBatch] Error:', err);
            // Keep existing gates on error
        } finally {
            if (isMountedRef.current && !signal?.aborted) {
                setLoading(false);
            }
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [keysString, context, skipOrgScopedChecks]);

    // Fetch on mount and when dependencies change, with abort on cleanup
    useEffect(() => {
        const abortController = new AbortController();
        refetch(abortController.signal);
        return () => {
            abortController.abort();
        };
    }, [refetch]);

    return {
        gates,
        loading,
        refetch: () => refetch(),
    };
}

/**
 * Hook that returns a function to check if a feature is allowed
 * Useful when you have the gates map and need to check multiple features
 */
export function useFeatureGateChecker(featureKeys: string[]): {
    isAllowed: (featureKey: string) => boolean;
    getGate: (featureKey: string) => FeatureGateResult | undefined;
    loading: boolean;
} {
    const { gates, loading } = useFeatureGateBatch(featureKeys);

    const isAllowed = useCallback(
        (featureKey: string): boolean => {
            const gate = gates.get(featureKey);
            return gate?.allowed ?? false;
        },
        [gates]
    );

    const getGate = useCallback(
        (featureKey: string): FeatureGateResult | undefined => {
            return gates.get(featureKey);
        },
        [gates]
    );

    return {
        isAllowed,
        getGate,
        loading,
    };
}

