export default function JoinTeam() {
  useDebugLifecycle('JoinTeam')
  const t = useT()
  const [searchParams] = useSearchParams()
  const [inviteCode, setInviteCode] = useState(searchParams.get('code') || sessionStorage.getItem('pending_join_team_code') || '')
  const [team, setTeam] = useState<Team | null>(null)
  const [seasons, setSeasons] = useState<Season[]>([])
  const [children, setChildren] = useState<Child[]>([])
  const [selectedChild, setSelectedChild] = useState('')
  const [selectedSeason, setSelectedSeason] = useState('')
  const [step, setStep] = useState<'code' | 'select' | 'success' | 'signin'>('code')
  const [loading, setLoading] = useState(false)
  const [joining, setJoining] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const { context, isReady } = useUserContext()
  const { user, loading: authLoading } = useAuth()
  const navigate = useNavigate()

  const fetchChildren = useCallback(async () => {
    if (!isReady) return
    
    const { data } = await getAthletes(context)
    setChildren(data.map(c => ({
      id: c.id,
      first_name: c.first_name,
      last_name: c.last_name,
    })))
  }, [context, isReady])

  const handleLookup = useCallback(async () => {
    if (!inviteCode.trim()) return
    
    setLoading(true)
    setError(null)

    // Store code in sessionStorage for persistence across signup
    sessionStorage.setItem('pending_join_team_code', inviteCode.trim().toUpperCase())

    // Look up team by invite code using real database query (works without auth)
    const { data: teamData, error: teamError } = await getTeamByInviteCode(inviteCode)

    if (teamError || !teamData) {
      // Provide more specific error messages
      let errorMessage = teamError?.message || t('portal.joinTeam.invalidCode')
      
      // Check for rate limiting errors
      if (teamError?.message?.includes('Too many requests')) {
        errorMessage = 'Too many requests. Please wait a minute and try again.'
      } else if (teamError?.message?.includes('Invalid invite code')) {
        errorMessage = t('portal.joinTeam.invalidCode')
      }
      
      setError(errorMessage)
      setLoading(false)
      return
    }

    setTeam({
      id: teamData.id,
      name: teamData.name,
    })

    // If user is not authenticated, show sign in/sign up prompt
    if (!user && !authLoading) {
      setStep('signin')
      setLoading(false)
      return
    }

    // If authenticated but context not ready, wait
    if (!isReady) {
      setLoading(false)
      return
    }

    // Fetch team details with seasons (requires auth)
    const { data: teamDetails, error: detailsError } = await getTeamDetails(context!, teamData.id)

    if (detailsError || !teamDetails) {
      // Provide more specific error messages
      let errorMessage = t('portal.joinTeam.failedToLoad')
      
      if (detailsError?.message?.includes('not found') || detailsError?.message?.includes('permission')) {
        errorMessage = 'Unable to access team details. Please ensure you have permission to view this team.'
      } else if (detailsError?.message?.includes('network') || detailsError?.message?.includes('timeout')) {
        errorMessage = 'Network error. Please check your connection and try again.'
      }
      
      setError(errorMessage)
      setLoading(false)
      return
    }

    // Extract seasons from team details
    if (teamDetails.seasons) {
      const seasonList = teamDetails.seasons.map((s: any) => ({
        id: s.id,
        name: s.name,
      }))
      setSeasons(seasonList)
      if (seasonList.length > 0) {
        setSelectedSeason(seasonList[0].id)
      }
    } else {
      setSeasons([])
    }
    
    setStep('select')
    setLoading(false)
  }, [inviteCode, context, isReady, user, authLoading, t])

  useEffect(() => {
    if (isReady && user) fetchChildren()
  }, [isReady, user, fetchChildren])

  // Auto-lookup if code is in URL or sessionStorage
  useEffect(() => {
    const codeFromUrl = searchParams.get('code')
    const codeFromStorage = sessionStorage.getItem('pending_join_team_code')
    const codeToUse = codeFromUrl || codeFromStorage
    
    if (codeToUse && codeToUse !== inviteCode) {
      setInviteCode(codeToUse)
    }
    
    // If we have a code and user is authenticated and ready, lookup team
    if (codeToUse && user && isReady && !team) {
      handleLookup()
    } else if (codeToUse && !user && !authLoading && !team) {
      // If not authenticated, lookup team info (public) and show sign in prompt
      handleLookup()
    }
  }, [searchParams, isReady, user, authLoading, handleLookup, inviteCode, team])

  async function handleJoin() {
    if (!selectedChild || !selectedSeason || !team || !isReady) return
    
    setJoining(true)
    setError(null)

    try {
      // Create team membership using real database operation
      const { data: membershipData, error: membershipError } = await createTeamMembership(
        context,
        selectedChild,
        team.id,
        selectedSeason
      )

      if (membershipError) {
        // Map specific error messages
        let errorMessage = membershipError.message || t('portal.joinTeam.failedToJoin')
        if (membershipError.message?.includes('full')) {
          errorMessage = t('portal.joinTeam.teamFull')
        } else if (membershipError.message?.includes('already')) {
          errorMessage = t('portal.joinTeam.alreadyMember')
        }
        setError(errorMessage)
        setJoining(false)
        return
      }

      if (!membershipData) {
        setError('Failed to create membership. Please try again.')
        setJoining(false)
        return
      }

      // Check if this is user's first team join and profile not completed
      if (membershipData.isNew && context?.userId) {
      }

      // Success - show success step
      setStep('success')
      setJoining(false)
    } catch (err) {
      setError('An unexpected error occurred. Please try again.')
      setJoining(false)
    }
  }

  // Use minimal layout for unauthenticated users, portal layout for authenticated
  const Layout = user ? PortalLayout : MinimalLayout

  const handleSignIn = () => {
    const returnTo = `/portal/join?code=${encodeURIComponent(inviteCode)}`
    navigate('/portal/login', { state: { returnTo } })
  }

  const handleSignUp = () => {
    const returnTo = `/portal/join?code=${encodeURIComponent(inviteCode)}`
    navigate('/portal/signup', { state: { returnTo } })
  }

  return (
      <Layout
        breadcrumbs={user ? [
          { label: 'Home', path: '/portal/dashboard' },
          { label: 'Join Team' },
        ] : undefined}
      >
        <div className="max-w-md mx-auto">
          <div className="mb-12 text-center">
            <PageTitle>{t('portal.joinTeam.title')}</PageTitle>
            <p className="text-slate-500 dark:text-slate-400 text-lg font-light tracking-wide mt-2">
              {t('portal.joinTeam.description')}
            </p>
          </div>

          <Card className="p-8">
            {error && (
              <Card className="mb-6 border-red-500/50 bg-red-50 dark:bg-red-950/20 p-4">
                <p className="text-red-600 dark:text-red-400 text-sm font-bold mb-3">{error}</p>
                <div className="flex gap-2">
                  {step === 'code' && (
                    <Button
                      variant="secondary"
                      onClick={handleLookup}
                      disabled={loading || !inviteCode.trim()}
                    >
                      {t('common.retry')}
                    </Button>
                  )}
                  {step === 'select' && (
                    <Button
                      variant="secondary"
                      onClick={handleJoin}
                      disabled={joining || !selectedChild || !selectedSeason}
                    >
                      {t('common.retry')}
                    </Button>
                  )}
                  <Button
                    variant="secondary"
                    onClick={() => {
                      setError(null)
                      if (step === 'select') {
                        setStep('code')
                        setTeam(null)
                        setSeasons([])
                        setSelectedChild('')
                        setSelectedSeason('')
                      }
                    }}
                  >
                    {t('common.back')}
                  </Button>
                </div>
              </Card>
            )}

            {step === 'code' && (
              <>
                <SectionHeader className="mb-6">{t('portal.joinTeam.enterCode')}</SectionHeader>
                <div className="mb-6">
                  <input
                    type="text"
                    value={inviteCode}
                    onChange={(e) => setInviteCode(e.target.value.toUpperCase())}
                    className="w-full bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded px-4 py-3 text-center text-2xl tracking-widest font-black text-slate-900 dark:text-white placeholder:text-slate-400"
                    placeholder="XXXXXXXX"
                    maxLength={8}
                    autoFocus
                  />
                </div>
                <Button variant="primary" onClick={handleLookup} disabled={loading || !inviteCode.trim()} className="w-full">
                  {loading ? t('portal.joinTeam.lookingUp') : t('portal.joinTeam.findTeam')}
                </Button>
              </>
            )}

            {step === 'signin' && team && (
              <>
                <Card className="mb-6 border-[var(--org-btn-primary-bg, #137fec)]/30 bg-[var(--org-btn-primary-bg)]/10 p-4 text-center">
                  <p className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-1">{t('portal.joinTeam.joiningTeam')}</p>
                  <CardTitle className="text-lg">{team.name}</CardTitle>
                </Card>
                <div className="text-center py-4">
                  <p className="text-slate-500 dark:text-slate-400 mb-6">{t('portal.joinTeam.signInToJoin')}</p>
                  <div className="space-y-3">
                    <Button variant="primary" onClick={handleSignIn} className="w-full">
                      {t('portal.joinTeam.signIn')}
                    </Button>
                    <Button variant="secondary" onClick={handleSignUp} className="w-full">
                      {t('portal.joinTeam.createAccount')}
                    </Button>
                  </div>
                </div>
                <Button variant="secondary" onClick={() => { setStep('code'); setTeam(null) }} className="w-full mt-3">
                  {t('portal.joinTeam.back')}
                </Button>
              </>
            )}

            {step === 'select' && team && (
              <>
                <Card className="mb-6 border-[var(--org-btn-primary-bg, #137fec)]/30 bg-[var(--org-btn-primary-bg)]/10 p-4 text-center">
                  <p className="text-xs font-bold uppercase tracking-widest text-slate-400 mb-1">{t('portal.joinTeam.joiningTeam')}</p>
                  <CardTitle className="text-lg">{team.name}</CardTitle>
                </Card>

                {children.length === 0 ? (
                  <div className="text-center py-4">
                    <p className="text-slate-500 dark:text-slate-400 mb-6">{t('portal.joinTeam.addChildFirst')}</p>
                    <Link to="/portal/athletes">
                      <Button variant="primary">
                        {t('portal.joinTeam.add')}
                      </Button>
                    </Link>
                  </div>
                ) : (
                  <>
                    <div className="space-y-4 mb-6">
                      <div>
                        <label className="block text-xs font-bold uppercase tracking-widest text-slate-400 mb-2">{t('portal.joinTeam.selectChild')}</label>
                        <select
                          value={selectedChild}
                          onChange={(e) => setSelectedChild(e.target.value)}
                          className="w-full bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded px-4 py-2 text-sm text-slate-900 dark:text-white"
                        >
                          <option value="">{t('portal.joinTeam.chooseChild')}</option>
                          {children.map((c) => (
                            <option key={c.id} value={c.id}>{c.first_name} {c.last_name}</option>
                          ))}
                        </select>
                      </div>

                      {seasons.length > 0 && (
                        <div>
                          <label className="block text-xs font-bold uppercase tracking-widest text-slate-400 mb-2">{t('portal.joinTeam.selectSeason')}</label>
                          <select
                            value={selectedSeason}
                            onChange={(e) => setSelectedSeason(e.target.value)}
                            className="w-full bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-700 rounded px-4 py-2 text-sm text-slate-900 dark:text-white"
                          >
                            {seasons.map((s) => (
                              <option key={s.id} value={s.id}>{s.name}</option>
                            ))}
                          </select>
                        </div>
                      )}
                    </div>

                    <Button variant="primary" onClick={handleJoin} disabled={joining || !selectedChild || !selectedSeason} className="w-full">
                      {joining ? t('portal.joinTeam.joining') : t('portal.joinTeam.joinTeam')}
                    </Button>
                  </>
                )}

                <Button variant="secondary" onClick={() => { setStep('code'); setTeam(null) }} className="w-full mt-3">
                  {t('portal.joinTeam.back')}
                </Button>
              </>
            )}

            {step === 'success' && (
              <div className="text-center py-4">
                <div className="inline-flex items-center justify-center w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-full mb-6">
                  <Icon name="check_circle" size="text-4xl" className="text-emerald-500 dark:text-emerald-400" />
                </div>
                <CardTitle className="mb-2">{t('portal.joinTeam.teamJoined')}</CardTitle>
                <p className="text-slate-500 dark:text-slate-400 mb-6">{t('portal.joinTeam.success')} {team?.name}.</p>
                <Button variant="primary" onClick={() => {
                  sessionStorage.removeItem('pending_join_team_code')
                  navigate('/portal/dashboard')
                }}>
                  {t('portal.joinTeam.goToDashboard')}
                </Button>
              </div>
            )}
          </Card>

          {user && (
            <div className="mt-6 text-center">
              <Link to="/portal/dashboard" className="text-sm font-bold text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
                {t('portal.joinTeam.backToDashboard')}
              </Link>
            </div>
          )}
        </div>
      </Layout>
  )
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useUserContext } from '../hooks/useUserContext'
import { getFeeAssignmentById, formatCurrency, generateReceiptPDF } from '../data/services/paymentsService'
import { getOrganizationDetails } from '../data/services/organizationService'
import { getContactForCategory } from '../data/services/organizationContactsService'
import PortalLayout from '../components/portal/PortalLayout'
import { PageTitle, SectionHeader } from '../components/portal/Typography'
import Card from '../components/portal/Card'
import Button from '../components/portal/Button'
import Icon from '../components/portal/Icon'
import { getLink } from '../utils/routes'
import { showSuccess, showError } from '../utils/toast'

interface PaymentDetailData {
  id: string
  amount_cents: number
  balance_cents: number
  paid_cents_total: number
  status: 'unpaid' | 'partial' | 'paid' | 'waived' | 'overdue'
  due_date: string | null
  created_at: string
  fee?: {
    id: string
    title: string
    description: string | null
    amount_cents: number
  } | null
  athlete?: {
    id: string
    first_name: string
    last_name: string
  } | null
  parent?: {
    id: string
    email: string
    display_name: string | null
  } | null
  payments?: Array<{
    id: string
    amount_cents: number
    status: string
    created_at: string
    stripe_payment_intent_id: string | null
  }>
}

export default function PaymentDetail() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { context, isReady } = useUserContext()
  const componentIdRef = useRef(`PaymentDetail-${Date.now()}-${Math.random()}`)
  const renderCountRef = useRef(0)
  const effectRunCountRef = useRef(0)
  const fetchDataCountRef = useRef(0)

  renderCountRef.current++
  console.log(`[PaymentDetail:${componentIdRef.current}] RENDER #${renderCountRef.current}`, {
    timestamp: new Date().toISOString(),
    id,
    isReady,
    contextOrgId: context?.orgId,
    contextUserId: context?.userId,
  })

  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [assignment, setAssignment] = useState<PaymentDetailData | null>(null)
  const [actionLoading, setActionLoading] = useState<string | null>(null)
  const isMountedRef = useRef(true)

  useEffect(() => {
    const mountTime = new Date().toISOString()
    console.log(`[PaymentDetail:${componentIdRef.current}] MOUNT`, { timestamp: mountTime })
    isMountedRef.current = true
    return () => {
      const unmountTime = new Date().toISOString()
      console.log(`[PaymentDetail:${componentIdRef.current}] UNMOUNT`, {
        timestamp: unmountTime,
        mountTime,
        renderCount: renderCountRef.current,
        effectRuns: effectRunCountRef.current,
        fetchDataCalls: fetchDataCountRef.current,
      })
      isMountedRef.current = false
    }
  }, [])

  const fetchData = useCallback(async () => {
    fetchDataCountRef.current++
    const fetchId = fetchDataCountRef.current
    const fetchStartTime = Date.now()
    console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} START`, {
      timestamp: new Date().toISOString(),
      id,
      isReady,
      contextOrgId: context?.orgId,
      isMounted: isMountedRef.current,
    })

    if (!id || !isReady) {
      console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - Early return`, {
        reason: !id ? 'no id' : 'not ready',
      })
      if (!isReady) return
      if (isMountedRef.current) {
        setLoading(false)
        navigate(getLink('portal.payments'), { replace: true })
      }
      return
    }

    if (!isMountedRef.current) {
      console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - Aborted (unmounted)`)
      return
    }

    setLoading(true)
    setError(null)

    try {
      console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - Calling getFeeAssignmentById`)
      const apiStartTime = Date.now()
      const { data, error: fetchError } = await getFeeAssignmentById(context, id)
      const apiDuration = Date.now() - apiStartTime
      console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - getFeeAssignmentById completed`, {
        duration: `${apiDuration}ms`,
        hasData: !!data,
        hasError: !!fetchError,
        errorMessage: fetchError?.message,
      })

      if (!isMountedRef.current) {
        console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - Aborted after API (unmounted)`)
        return
      }

      if (fetchError || !data) {
        console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - Error or no data`, {
          hasError: !!fetchError,
          hasData: !!data,
        })
        if (isMountedRef.current) {
          setLoading(false)
          if (fetchError?.message?.includes('Access denied') || fetchError?.message?.includes('not found')) {
            navigate(getLink('portal.payments'), { replace: true })
          } else {
            setError(fetchError?.message || 'Failed to load payment details')
          }
        }
        return
      }

      // Transform to component format
      const transformed: PaymentDetailData = {
        id: data.id,
        amount_cents: (data as any).amount_cents ?? (data as any).amount_due_cents ?? 0,
        balance_cents: (data as any).balance_cents ?? 0,
        paid_cents_total: (data as any).paid_cents_total ?? (data as any).amount_paid_cents ?? 0,
        status: data.status as PaymentDetailData['status'],
        due_date: data.due_date ?? null,
        created_at: data.created_at,
        fee: data.fee ? {
          id: data.fee.id,
          title: data.fee.title,
          description: data.fee.description ?? null,
          amount_cents: data.fee.amount_cents ?? 0,
        } : null,
        athlete: (data as any).athlete ? {
          id: (data as any).athlete.id,
          first_name: (data as any).athlete.first_name,
          last_name: (data as any).athlete.last_name,
        } : null,
        parent: (data as any).parent ? {
          id: (data as any).parent.id,
          email: (data as any).parent.email,
          display_name: (data as any).parent.display_name,
        } : null,
        payments: data.payments ?? [],
      }

      console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - Setting assignment state`)
      if (isMountedRef.current) {
        setAssignment(transformed)
        setLoading(false)
      }
    } catch (err) {
      if (!isMountedRef.current) return
      console.error(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - Caught error:`, err)
      setError(err instanceof Error ? err.message : 'Failed to load payment details')
      setLoading(false)
    } finally {
      const totalDuration = Date.now() - fetchStartTime
      console.log(`[PaymentDetail:${componentIdRef.current}] fetchData #${fetchId} - COMPLETE`, {
        duration: `${totalDuration}ms`,
        isMounted: isMountedRef.current,
      })
    }
  }, [id, context.orgId, context.userId, isReady, navigate])

  useEffect(() => {
    effectRunCountRef.current++
    const effectId = effectRunCountRef.current
    console.log(`[PaymentDetail:${componentIdRef.current}] Effect #${effectId} - Trigger fetchData`, {
      timestamp: new Date().toISOString(),
      isReady,
      id,
      isMounted: isMountedRef.current,
    })
    if (isReady && id) {
      console.log(`[PaymentDetail:${componentIdRef.current}] Effect #${effectId} - Calling fetchData`)
      fetchData()
    } else {
      console.log(`[PaymentDetail:${componentIdRef.current}] Effect #${effectId} - Skipping fetchData`, {
        reason: !isReady ? 'not ready' : 'no id',
      })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isReady, id])

  const handleDownloadPDF = async () => {
    if (!assignment || actionLoading !== null) return
    if (assignment.status !== 'paid') return
    setActionLoading('download')
    try {
      const { data, error } = await generateReceiptPDF(context, assignment.id)
      if (error) {
        showError(error.message || 'Failed to generate receipt')
        return
      }
      if (data?.url) {
        if (data.url.startsWith('http') || data.url.startsWith('https')) {
          window.open(data.url, '_blank')
          showSuccess('Receipt opened in new tab')
        } else {
          showError('Receipt URL is not available')
        }
      }
    } catch (err) {
      showError(err instanceof Error ? err.message : 'Failed to download receipt')
    } finally {
      setActionLoading(null)
    }
  }

  const handleContactRegistrar = async () => {
    if (actionLoading !== null) return
    setActionLoading('contact')
    try {
      const { data: contact } = await getContactForCategory(context.orgId, 'billing')

      // Fallback to org email if no contact found (though service should handle fallback to default)
      let to = contact?.email ?? ''
      if (!to) {
          const { data: org } = await getOrganizationDetails(context.orgId)
          to = org?.email ?? ''
      }

      const subject = encodeURIComponent(`Question about payment${assignment?.fee?.title ? `: ${assignment.fee.title}` : ''}`)
      const body = encodeURIComponent(
        `Payment reference: ${assignment?.id ?? id}\n\n[Your message here]`
      )
      const mailto = `mailto:${to}?subject=${subject}&body=${body}`
      window.location.href = mailto
      showSuccess('Opening email client')
    } catch {
      const subject = encodeURIComponent(`Question about payment`)
      window.location.href = `mailto:?subject=${subject}`
      showSuccess('Opening email client')
    } finally {
      setActionLoading(null)
    }
  }

  if (loading) {
    return (
      <PortalLayout
        breadcrumbs={[
          { label: 'Home', path: getLink('portal.dashboard') },
          { label: 'Payments', path: getLink('portal.payments') },
          { label: 'Payment Details' },
        ]}
      >
        <div className="flex justify-center py-12">
          <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-slate-900 dark:border-white"></div>
        </div>
      </PortalLayout>
    )
  }

  if (error || !assignment) {
    return (
      <PortalLayout
        breadcrumbs={[
          { label: 'Home', path: getLink('portal.dashboard') },
          { label: 'Payments', path: getLink('portal.payments') },
          { label: 'Payment Details' },
        ]}
      >
        <Card className="text-center py-12">
          <p className="text-red-600 dark:text-red-400 text-sm font-bold mb-4">{error || 'Payment not found'}</p>
          <div className="flex flex-wrap justify-center gap-3">
            <Button variant="primary" onClick={() => (setError(null), fetchData())}>
              Retry
            </Button>
            <Button variant="secondary" onClick={() => navigate(getLink('portal.payments'))}>
              Back to Payments
            </Button>
          </div>
        </Card>
      </PortalLayout>
    )
  }

  const totalPaid = assignment.paid_cents_total
  const isPaid = assignment.status === 'paid'
  const pageTitle = assignment.fee?.title ?? 'Payment Details'
  const paymentDate = assignment.payments && assignment.payments.length > 0
    ? new Date(assignment.payments[0].created_at)
    : new Date(assignment.created_at)

  return (
    <PortalLayout
      breadcrumbs={[
        { label: 'Home', path: getLink('portal.dashboard') },
        { label: 'Payments', path: getLink('portal.payments') },
        { label: 'Payment Details' },
      ]}
    >
      <div className="mb-12">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <button
              onClick={() => navigate(getLink('portal.payments'))}
              className="size-10 flex items-center justify-center rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-400 hover:text-[var(--org-link-color)] transition-colors"
            >
              <Icon name="arrow_back" />
            </button>
            <PageTitle className="text-3xl">{pageTitle}</PageTitle>
          </div>
          <Button
            variant="primary"
            onClick={handleDownloadPDF}
            disabled={!isPaid || actionLoading !== null}
            className="flex items-center gap-2 uppercase tracking-widest"
          >
            {actionLoading === 'download' ? (
              <span className="animate-spin size-5 border-2 border-white border-t-transparent rounded-full" />
            ) : (
              <Icon name="download" />
            )}
            DOWNLOAD PDF
          </Button>
        </div>

        {/* Payment Status Card */}
        <Card className="mb-12 text-center relative overflow-hidden" highlight>
          <div className="relative z-10">
            <div className={`inline-flex items-center justify-center size-16 rounded-full mb-6 ${
              isPaid 
                ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400'
                : 'bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400'
            }`}>
              <Icon name={isPaid ? 'check_circle' : 'pending'} size="text-4xl" />
            </div>
            <p className="text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-sm mb-2">
              {isPaid ? 'Total Amount Paid' : 'Amount Due'}
            </p>
            <h2 className="text-7xl font-black text-slate-900 dark:text-white tracking-tighter mb-4">
              {formatCurrency(isPaid ? totalPaid : assignment.balance_cents)}
            </h2>
            <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-full font-black text-xs uppercase tracking-widest ${
              isPaid
                ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400'
                : assignment.status === 'partial'
                ? 'bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400'
                : 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400'
            }`}>
              {isPaid && <span className="size-2 bg-green-500 rounded-full animate-pulse"></span>}
              STATUS: {assignment.status.toUpperCase()}
            </div>
          </div>
          <div className="absolute top-0 right-0 w-32 h-32 bg-[var(--org-btn-primary-bg, #137fec)]/5 -mr-16 -mt-16 rounded-full"></div>
        </Card>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* Left Column - Main Content */}
          <div className="md:col-span-2 space-y-8">
            {/* Payer and For Section */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <div className="space-y-4">
                <SectionHeader>PAYER</SectionHeader>
                <div className="flex items-center gap-4">
                  <div className="size-12 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center">
                    <Icon name="person" className="text-slate-500" />
                  </div>
                  <div>
                    <p className="font-bold text-slate-900 dark:text-white">
                      {assignment.parent?.display_name || assignment.parent?.email || 'Unknown'}
                    </p>
                    <p className="text-sm text-slate-500 dark:text-slate-400">
                      {assignment.parent?.email || 'No email'}
                    </p>
                  </div>
                </div>
              </div>
              <div className="space-y-4">
                <SectionHeader>FOR</SectionHeader>
                <div className="flex items-center gap-4">
                  <div className="size-12 rounded-full border-2 border-[var(--org-btn-primary-bg, #137fec)] overflow-hidden bg-slate-200 dark:bg-slate-800 flex items-center justify-center">
                    {assignment.athlete ? (
                      <span className="text-slate-500 text-xs font-bold">
                        {assignment.athlete.first_name[0]}{assignment.athlete.last_name[0]}
                      </span>
                    ) : (
                      <Icon name="person" className="text-slate-500" />
                    )}
                  </div>
                  <div>
                    <p className="font-bold text-slate-900 dark:text-white">
                      {assignment.athlete 
                        ? `${assignment.athlete.first_name} ${assignment.athlete.last_name}`
                        : 'Unknown Athlete'}
                    </p>
                    <p className="text-sm text-slate-500 dark:text-slate-400">
                      Athlete #{assignment.athlete?.id.slice(-4) || 'N/A'}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {/* Itemization */}
            <Card noPadding>
              <div className="px-6 py-4 bg-slate-50 dark:bg-slate-800/50 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center rounded-t-2xl">
                <SectionHeader>ITEMIZATION</SectionHeader>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  {paymentDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })} • {paymentDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', timeZoneName: 'short' })}
                </span>
              </div>
              <div className="divide-y divide-slate-100 dark:divide-slate-800">
                {assignment.fee && (
                  <div className="p-6 flex justify-between items-center">
                    <div>
                      <p className="font-bold text-slate-900 dark:text-white">{assignment.fee.title}</p>
                      <p className="text-xs text-slate-500 dark:text-slate-400">
                        {assignment.fee.description || 'Fee payment'}
                      </p>
                    </div>
                    <p className="font-bold text-slate-900 dark:text-white">
                      {formatCurrency(assignment.fee.amount_cents)}
                    </p>
                  </div>
                )}
                {assignment.payments && assignment.payments.length > 0 && (
                  <>
                    {assignment.payments.map((p) => (
                      <div key={p.id} className="p-6 flex justify-between items-center">
                        <div>
                          <p className="font-medium text-slate-900 dark:text-white">Payment</p>
                          <p className="text-xs text-slate-500 dark:text-slate-400">
                            {new Date(p.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })} • {formatCurrency(p.amount_cents)}
                          </p>
                        </div>
                        <p className="font-bold text-slate-900 dark:text-white">
                          {formatCurrency(p.amount_cents)}
                        </p>
                      </div>
                    ))}
                    <div className="p-6 bg-slate-50 dark:bg-slate-800/30 flex justify-between items-center">
                      <p className="font-black text-slate-900 dark:text-white uppercase tracking-widest text-sm">
                        Grand Total
                      </p>
                      <p className="text-2xl font-black text-[var(--org-btn-primary-bg, #137fec)]">
                        {formatCurrency(totalPaid)}
                      </p>
                    </div>
                  </>
                )}
              </div>
            </Card>
          </div>

          {/* Right Column - Sidebar */}
          <div className="space-y-8">
            {/* Destination */}
            <div className="space-y-4">
              <SectionHeader>DESTINATION</SectionHeader>
              <Card className="p-5 hover:border-[var(--org-btn-primary-bg, #137fec)] transition-all group cursor-pointer">
                <div className="flex items-center gap-4">
                  <div className="size-10 bg-[var(--org-btn-primary-bg, #137fec)]/10 text-[var(--org-btn-primary-bg, #137fec)] rounded-lg flex items-center justify-center group-hover:bg-[var(--org-btn-primary-bg, #137fec)] group-hover:text-white transition-colors">
                    <Icon name="sports_soccer" />
                  </div>
                  <div className="flex-1">
                    <p className="font-bold text-slate-900 dark:text-white leading-tight">
                      {assignment.fee?.title || 'Fee'}
                    </p>
                    <p className="text-xs text-slate-500 dark:text-slate-400">
                      {context.organizationName || 'Organization'}
                    </p>
                  </div>
                  <Icon name="open_in_new" className="text-slate-300 group-hover:text-[var(--org-btn-primary-bg, #137fec)]" />
                </div>
              </Card>
            </div>

            {/* Payment Method */}
            {assignment.payments && assignment.payments.length > 0 && (
              <div className="space-y-4">
                <SectionHeader>PAYMENT METHOD</SectionHeader>
                <Card className="p-5">
                  <div className="flex items-center gap-4">
                    <div className="size-10 flex items-center justify-center">
                      <Icon name="credit_card" className="text-slate-500" />
                    </div>
                    <div>
                      <p className="font-bold text-slate-900 dark:text-white leading-tight">
                        {assignment.payments[0].stripe_payment_intent_id 
                          ? `Payment #${assignment.payments[0].stripe_payment_intent_id.slice(-4)}`
                          : 'Payment Processed'}
                      </p>
                      <p className="text-xs text-slate-500 dark:text-slate-400">
                        Authorization: #{assignment.payments[0].id.slice(-8).toUpperCase()}
                      </p>
                    </div>
                  </div>
                </Card>
              </div>
            )}

            {/* Contact Registrar */}
            <Card className="p-6 bg-slate-100 dark:bg-slate-800/30 border-dashed border-slate-300 dark:border-slate-700">
              <p className="text-xs font-medium text-slate-500 dark:text-slate-400 text-center mb-4">
                Questions about this payment?
              </p>
              <Button
                variant="secondary"
                onClick={handleContactRegistrar}
                disabled={actionLoading !== null}
                className="w-full h-10 border-2 border-slate-300 dark:border-slate-700 text-slate-600 dark:text-slate-400 text-xs font-bold tracking-widest uppercase"
              >
                {actionLoading === 'contact' ? (
                  <span className="animate-spin size-4 border-2 border-slate-500 border-t-transparent rounded-full inline-block" />
                ) : (
                  'CONTACT REGISTRAR'
                )}
              </Button>
            </Card>
          </div>
        </div>
      </div>
    </PortalLayout>
  )
}

/**
 * Gallery View Page
 *
 * Displays a single gallery with photos in a grid layout, with selection, tagging,
 * and yet-another-react-lightbox for full-size viewing.
 */

import { useEffect, useState, useRef, useMemo, useCallback } from 'react'
import { useParams, Link, useLocation } from 'react-router-dom'
import Lightbox from 'yet-another-react-lightbox'
import { useDebugLifecycle } from '../lib/debug/integrations/useDebugLifecycle'
import { debug } from '../lib/debug'
import 'yet-another-react-lightbox/styles.css'
import { useUserContext } from '../hooks/useUserContext'
import {
  getGalleryById,
  getAlbumsForGallery,
  getPhotosForGallery,
  getGalleryPhotoUrl,
  checkCanModerateGallery,
  checkCanUploadToGallery,
  getPhotoBookmarks,
  type Gallery,
  type GalleryPhoto,
  type GalleryAlbum,
  type KeysetCursor,
} from '../data/services/galleryService'
import PortalLayout from '../components/portal/PortalLayout'
import Card from '../components/portal/Card'
import Icon from '../components/portal/Icon'
import Button from '../components/portal/Button'
import { PhotoUploader } from '../components/gallery/PhotoUploader'
import { ParentPhotoUpload } from '../components/gallery/ParentPhotoUpload'
import { ModerationQueue } from '../components/gallery/ModerationQueue'
import { TaggingSlideout } from '../components/gallery/TaggingSlideout'
import { BulkTaggingModal } from '../components/gallery/BulkTaggingModal'
import { GalleryEditModal } from '../components/admin/galleries/GalleryEditModal'
import { PhotoFilterBar } from '../components/gallery/PhotoFilterBar'
import { AlbumManager } from '../components/gallery/AlbumManager'
import { BulkDownloadButton } from '../components/gallery/BulkDownloadButton'
import { PortalGalleryView } from '../components/portal/PortalGalleryView'
import { usePhotoFilters } from '../hooks/usePhotoFilters'
import { useInfinitePhotos } from '../hooks/useInfinitePhotos'
import { buildPhotoQuery } from '../utils/buildPhotoQuery'
import { showError } from '../utils/toast'
import { getLink } from '../utils/routes'
import { useI18n } from '../i18n/useI18n'
import { USE_FAKE_DATA } from '../data/config'
import { getMockGalleryById, getMockPhotosForGallery } from '../data/fake/mockGalleries'

const GRID_PAGE_SIZE_MOBILE = 30
const GRID_PAGE_SIZE_DESKTOP = 48
const getGridPageSize = () =>
  typeof window !== 'undefined' && window.innerWidth < 768 ? GRID_PAGE_SIZE_MOBILE : GRID_PAGE_SIZE_DESKTOP

export default function PhotosGallery() {
  const { id } = useParams<{ id: string }>()
  const location = useLocation()

  // Add lifecycle logging
  useDebugLifecycle('PhotosGallery', { galleryId: id })
  const isManageMode = location.pathname.includes('/manage')
  const { context, isReady, isLoading: isContextLoading, hasOrganization } = useUserContext()
  const { t } = useI18n()
  const viewKey = isManageMode ? `photosGalleryManage:${id || 'unknown'}` : `photosGallery:${id || 'unknown'}`
  const { filters, setFilters, clearFilters, setDensity } = usePhotoFilters({
    viewKey,
    defaultSort: 'recent',
    allowedSorts: ['recent', 'oldest'],
    defaultStatus: 'all',
    allowedStatuses: ['all', 'approved', 'pending', 'rejected'],
    persistDensity: true,
  })
  const [gallery, setGallery] = useState<Gallery | null>(null)
  const [photos, setPhotos] = useState<GalleryPhoto[]>([])
  const [loading, setLoading] = useState(true)
  const [loadingMore, setLoadingMore] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [lightboxIndex, setLightboxIndex] = useState(-1)
  const [canModerate, setCanModerate] = useState(false)
  const [canUpload, setCanUpload] = useState(false)
  const [showParentUpload, setShowParentUpload] = useState(false)
  const [showEditModal, setShowEditModal] = useState(false)
  const [taggingPhoto, setTaggingPhoto] = useState<GalleryPhoto | null>(null)
  const [taggingPhotoIndex, setTaggingPhotoIndex] = useState<number>(-1)
  const [bulkTaggingPhotos, setBulkTaggingPhotos] = useState<GalleryPhoto[]>([])
  const [selectedPhotos, setSelectedPhotos] = useState<Set<string>>(new Set())
  const [albums, setAlbums] = useState<GalleryAlbum[]>([])
  const [bookmarkedIds, setBookmarkedIds] = useState<Set<string>>(new Set())
  const [hasMore, setHasMore] = useState(true)
  const [gridPageSize, setGridPageSize] = useState(getGridPageSize)
  const cursorRef = useRef<KeysetCursor | null>(null)
  const loadingMoreRef = useRef(false)
  const mountedRef = useRef(true)

  useEffect(() => {
    return () => {
      mountedRef.current = false
    }
  }, [])

  useEffect(() => {
    const handleResize = () => {
      setGridPageSize(getGridPageSize())
    }
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  const athleteOptions = useMemo(() => {
    const map = new Map<string, { id: string; name: string }>()
    photos.forEach((photo) => {
      photo.tagged_athletes?.forEach((athlete) => {
        const name = `${athlete.first_name} ${athlete.last_name}`.trim()
        map.set(athlete.id, { id: athlete.id, name })
      })
    })
    return Array.from(map.values()).map((athlete) => ({ value: athlete.id, label: athlete.name }))
  }, [photos])

  const sortOptions = useMemo(
    () => [
      { value: 'recent', label: t('common.mostRecent') },
      { value: 'oldest', label: t('photos.filters.oldest') },
    ],
    [t],
  )

  const statusOptions = useMemo(
    () => [
      { value: 'all', label: t('photos.filters.statusAll') },
      { value: 'approved', label: t('common.approved') },
      { value: 'pending', label: t('photos.pendingApproval.badge') },
      { value: 'rejected', label: t('photos.filters.statusRejected') },
    ],
    [t],
  )

  const albumOptions = useMemo(() => {
    const options = albums.map((album) => ({ value: album.id, label: album.name }))
    return [{ value: 'favorites', label: t('photos.bookmarks.favorites') }, ...options]
  }, [albums, t])

  const isFavoritesView = filters.album === 'favorites'

  const displayPhotos = useMemo(() => {
    if (!isFavoritesView) return photos
    return photos.filter((photo) => bookmarkedIds.has(photo.id))
  }, [photos, bookmarkedIds, isFavoritesView])

  const displayIndexMap = useMemo(
    () => new Map(displayPhotos.map((photo, index) => [photo.id, index])),
    [displayPhotos],
  )
  void displayIndexMap

  const photosByAlbum = useMemo(() => {
    if (filters.album || isFavoritesView || albums.length === 0) return null
    const byAlbum = new Map<string, GalleryPhoto[]>()
    const unassigned: GalleryPhoto[] = []
    displayPhotos.forEach((photo) => {
      if (photo.album_id) {
        const list = byAlbum.get(photo.album_id) || []
        list.push(photo)
        byAlbum.set(photo.album_id, list)
      } else {
        unassigned.push(photo)
      }
    })
    return { byAlbum, unassigned }
  }, [albums, displayPhotos, filters.album, isFavoritesView])

  const gridClass =
    filters.density === 'compact'
      ? 'grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-6'
      : 'grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-12'
  void gridClass

  const selectedDownloadIds = useMemo(() => {
    if (!gallery?.can_download) return []
    const photoMap = new Map(photos.map((photo) => [photo.id, photo]))
    return Array.from(selectedPhotos).filter((id) => photoMap.get(id)?.can_download !== false)
  }, [gallery, photos, selectedPhotos])

  const showingLabel = displayPhotos.length === 1 ? t('photos.photo') : t('photos.photos')
  const selectedLabel = selectedPhotos.size === 1 ? t('photos.selection.photo') : t('photos.selection.photos')
  const canLoadGalleryData = Boolean(id && (isReady || USE_FAKE_DATA))



  const loadGallery = useCallback(async () => {
    if (!canLoadGalleryData || !id) return

    debug.flow('PhotosGallery', 'Loading gallery', { galleryId: id })
    debug.perf.start('photosGallery.loadGallery')

    setError(null)

    if (USE_FAKE_DATA) {
      const mockGallery = getMockGalleryById(id)
      if (!mountedRef.current) return
      if (mockGallery) {
        setGallery({ ...mockGallery, can_download: mockGallery.can_download ?? undefined } as Gallery)
        setCanModerate(true)
        setCanUpload(true)
      } else {
        setGallery(null)
      }
      debug.perf.end('photosGallery.loadGallery')
      return
    }

    const galleryResult = await getGalleryById(context, id)

    if (!mountedRef.current) return

    if (galleryResult.error) {
      setError(galleryResult.error.message)
      return
    }

    setGallery(galleryResult.data)

    if (galleryResult.data) {
      const [moderateResult, uploadResult] = await Promise.all([
        checkCanModerateGallery(context, galleryResult.data.id),
        checkCanUploadToGallery(context, galleryResult.data.id),
      ])
      if (!mountedRef.current) return
      setCanModerate(moderateResult.allowed)
      setCanUpload(uploadResult.allowed)
    }
    debug.perf.end('photosGallery.loadGallery')
  }, [context, canLoadGalleryData, id])

  const loadAlbums = useCallback(async () => {
    if (!canLoadGalleryData || !id) return
    if (USE_FAKE_DATA) {
      setAlbums([])
      return
    }
    const { data, error: albumsError } = await getAlbumsForGallery(context, id)
    if (!mountedRef.current) return
    if (albumsError) {
      debug.perf.end('photosGallery.loadGallery')
      debug.error('PhotosGallery', 'Failed to load albums', { galleryId: id, error: albumsError })
      showError(albumsError.message)
      return
    }

    debug.perf.end('photosGallery.loadGallery')
    debug.flow('PhotosGallery', 'Gallery loaded successfully', { galleryId: id, galleryName: gallery?.name, albumCount: data?.length })
    setAlbums(data)
  }, [context, canLoadGalleryData, id])

  const loadPhotos = useCallback(async (reset: boolean): Promise<GalleryPhoto[] | null> => {
    // #region agent log
    fetch('http://127.0.0.1:7249/ingest/60db3259-e52f-44db-9b11-aee7014e1393',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'PhotosGallery.tsx:loadPhotos',message:'loadPhotos called',data:{reset,canLoadGalleryData,id,isContextLoading},timestamp:Date.now(),hypothesisId:'H1-H3'})}).catch(()=>{});
    // #endregion
    if (!canLoadGalleryData || !id) {
      if (reset && !isContextLoading) {
        setLoading(false)
      }
      return null
    }
    if (loadingMoreRef.current && !reset) return null

    debug.data('PhotosGallery', 'Loading photos', { galleryId: id, reset, filters })
    debug.perf.start(`photosGallery.loadPhotos-${reset ? 'reset' : 'more'}`)

    if (reset && !USE_FAKE_DATA) {
      setLoading(true)
    }
    if (reset) {
      cursorRef.current = null
      setHasMore(true)
    } else if (!USE_FAKE_DATA) {
      loadingMoreRef.current = true
      setLoadingMore(true)
    }

    try {
      if (USE_FAKE_DATA) {
        // #region agent log
        fetch('http://127.0.0.1:7249/ingest/60db3259-e52f-44db-9b11-aee7014e1393',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'PhotosGallery.tsx:USE_FAKE_DATA',message:'USE_FAKE_DATA branch',data:{id,mockCount:getMockPhotosForGallery(id).length},timestamp:Date.now(),hypothesisId:'H6'})}).catch(()=>{});
        // #endregion
        const mockPhotosDb = getMockPhotosForGallery(id)
        const mockPhotos = mockPhotosDb.map(
          (p) => ({ ...p, can_download: p.can_download ?? undefined } as GalleryPhoto),
        )
        if (!mountedRef.current) return null
        if (reset) {
          setPhotos(mockPhotos)
        } else {
          setPhotos((prev) => [...prev, ...mockPhotos])
        }
        setHasMore(false)
        setLoading(false)
        loadingMoreRef.current = false
        setLoadingMore(false)
        debug.perf.end(`photosGallery.loadPhotos-${reset ? 'reset' : 'more'}`)
        return mockPhotos
      }

      const albumId = filters.album && filters.album !== 'favorites' ? filters.album : undefined
      const statusFilter = canModerate && filters.status !== 'all' ? (filters.status as any) : undefined

      const query = buildPhotoQuery(filters, {
        gallery_id: id,
        album_id: albumId,
        status: statusFilter,
        limit: gridPageSize,
      })

      const { data, error: photosError } = await getPhotosForGallery(context, {
        ...query,
        cursor: !reset ? cursorRef.current || undefined : undefined,
      })

      if (!mountedRef.current) return null

      // #region agent log
      fetch('http://127.0.0.1:7249/ingest/60db3259-e52f-44db-9b11-aee7014e1393',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'PhotosGallery.tsx:afterGetPhotos',message:'getPhotosForGallery returned',data:{photoCount:data?.length,error:photosError?.message},timestamp:Date.now(),hypothesisId:'H5',runId:'post-fix-2'})}).catch(()=>{});
      // #endregion
      if (photosError) {
        setError(photosError.message)
        return null
      }

      if (reset) {
        setPhotos(data || [])
      } else {
        setPhotos((prev) => [...prev, ...(data || [])])
      }

      const last = data && data.length > 0 ? data[data.length - 1] : null
      cursorRef.current = last ? { created_at: last.created_at, id: last.id } : cursorRef.current
      setHasMore((data || []).length === gridPageSize)

      if (data && data.length > 0 && context.userId) {
        const bookmarkResult = await getPhotoBookmarks(context, data.map((photo) => photo.id))
        if (bookmarkResult.error) {
          showError(bookmarkResult.error.message)
        } else {
          setBookmarkedIds((prev) => {
            const next = reset ? new Set<string>() : new Set(prev)
            bookmarkResult.data.forEach((id) => next.add(id))
            return next
          })
        }
      } else if (reset) {
        setBookmarkedIds(new Set())
      }

      debug.perf.end(`photosGallery.loadPhotos-${reset ? 'reset' : 'more'}`)
      debug.data('PhotosGallery', 'Photos loaded', { galleryId: id, photoCount: data?.length || 0, reset, hasMore })
      return data || null
    } catch (err) {
      if (mountedRef.current) {
        const message = err instanceof Error ? err.message : t('photos.errors.galleryNotFound')
        setError(message)
      }
      debug.error('PhotosGallery', 'Unexpected error while loading photos', { galleryId: id, error: err })
      return null
    } finally {
      // #region agent log
      fetch('http://127.0.0.1:7249/ingest/60db3259-e52f-44db-9b11-aee7014e1393',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'PhotosGallery.tsx:finally',message:'loadPhotos finally',data:{mounted:mountedRef.current,photoCount:photos.length},timestamp:Date.now(),hypothesisId:'H5',runId:'post-fix-2'})}).catch(()=>{});
      // #endregion
      if (mountedRef.current) {
        setLoading(false)
        loadingMoreRef.current = false
        setLoadingMore(false)
      }
    }
  }, [context, canLoadGalleryData, id, filters, gridPageSize, canModerate, isContextLoading, t])

  useEffect(() => {
    if (canLoadGalleryData || isContextLoading) return
    setLoading(false)
    if (!id) {
      setError(t('photos.errors.galleryNotFound'))
      return
    }
    if (!USE_FAKE_DATA && !hasOrganization) {
      setError('No organization assigned to your account.')
    }
  }, [canLoadGalleryData, hasOrganization, id, isContextLoading, t])

  useEffect(() => {
    // #region agent log
    fetch('http://127.0.0.1:7249/ingest/60db3259-e52f-44db-9b11-aee7014e1393',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'PhotosGallery.tsx:336',message:'loadGallery effect fired',data:{id,canLoadGalleryData,contextUserId:context?.userId,contextOrgId:context?.orgId},timestamp:Date.now(),hypothesisId:'H1-H2',runId:'post-fix'})}).catch(()=>{});
    // #endregion
    loadGallery()
    loadAlbums()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, context?.userId, context?.orgId, isReady])

  useEffect(() => {
    // #region agent log
    fetch('http://127.0.0.1:7249/ingest/60db3259-e52f-44db-9b11-aee7014e1393',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'PhotosGallery.tsx:345',message:'loadPhotos effect fired',data:{id,canLoadGalleryData,loading},timestamp:Date.now(),hypothesisId:'H1',runId:'post-fix'})}).catch(()=>{});
    // #endregion
    loadPhotos(true)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, context?.userId, context?.orgId, isReady, filters.q, filters.album, filters.athlete, filters.sort, filters.status, filters.from, filters.to, gridPageSize])

  useEffect(() => {
    setSelectedPhotos(new Set())
  }, [filters.q, filters.album, filters.athlete, filters.sort, filters.status, filters.from, filters.to])

  useInfinitePhotos({
    hasMore,
    isLoading: loading || loadingMore,
    onLoadMore: () => loadPhotos(false),
  })

  if (loading) {
    // #region agent log
    fetch('http://127.0.0.1:7249/ingest/60db3259-e52f-44db-9b11-aee7014e1393',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'PhotosGallery.tsx:skeleton',message:'rendering skeleton',data:{loading,hasGallery:!!gallery,photoCount:photos.length,canLoadGalleryData},timestamp:Date.now(),hypothesisId:'H6'})}).catch(()=>{});
    // #endregion
    return (
      <PortalLayout
        breadcrumbs={[
          { label: t('common.home'), path: getLink('portal.dashboard') },
          { label: t('nav.photos'), path: getLink('portal.photos') },
          { label: t('common.loading') },
        ]}
      >
        <div className="animate-pulse">
          <div className="h-8 bg-slate-200 dark:bg-slate-700 rounded w-64 mb-4"></div>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (
              <div key={i} className="aspect-square bg-slate-200 dark:bg-slate-700 rounded"></div>
            ))}
          </div>
        </div>
      </PortalLayout>
    )
  }

  if (error || !gallery) {
    return (
      <PortalLayout
        breadcrumbs={[
          { label: t('common.home'), path: getLink('portal.dashboard') },
          { label: t('nav.photos'), path: getLink('portal.photos') },
          { label: t('common.error.label') },
        ]}
      >
        <Card className="border-red-200 dark:border-red-800 bg-red-50 dark:bg-red-900/20">
          <p className="text-red-600 dark:text-red-400">
            {error || t('photos.errors.galleryNotFound')}
          </p>
        </Card>
      </PortalLayout>
    )
  }

  return (
    <PortalLayout
      breadcrumbs={[
        { label: t('common.home'), path: getLink('portal.dashboard') },
        { label: t('nav.photos'), path: getLink('portal.photos') },
        { label: gallery.name },
      ]}
    >
      {/* Header Section */}
      <section className="mb-16">
        <div className="flex flex-col gap-4">
          <h1 className="text-6xl md:text-7xl font-[900] tracking-tighter text-slate-900 dark:text-white leading-none">
            {gallery.name}
          </h1>

          <div className="flex items-center justify-between mt-8 pt-8 border-t border-slate-200 dark:border-slate-700">
            <div className="flex items-center gap-8">
              {/* Action buttons */}
              {gallery.require_approval && (
                <span className="px-3 py-1 text-xs font-semibold rounded-full bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200">
                  {t('photos.galleryView.moderationRequired')}
                </span>
              )}
              {!isManageMode && canModerate && (
                <Link to={getLink('portal.photosGalleryManage', { id: gallery.id })}>
                  <button className="flex items-center gap-2 text-sm font-semibold text-slate-500 hover:text-black dark:hover:text-white transition-colors">
                    <Icon name="edit" size="text-sm" />
                    {t('photos.galleryView.manage')}
                  </button>
                </Link>
              )}
              {!isManageMode && gallery.allow_contributions && canUpload && (
                <button
                  onClick={() => setShowParentUpload(!showParentUpload)}
                  className="flex items-center gap-2 text-sm font-semibold text-slate-500 hover:text-black dark:hover:text-white transition-colors"
                >
                  <Icon name="add" size="text-sm" />
                  {t('photos.galleryView.addYourPhotos')}
                </button>
              )}
              {canModerate && (
                <button
                  onClick={() => setShowEditModal(true)}
                  className="flex items-center gap-2 text-sm font-semibold text-slate-500 hover:text-black dark:hover:text-white transition-colors"
                >
                  <Icon name="edit" size="text-sm" />
                  {t('photos.galleryView.updateAlbum')}
                </button>
              )}
            </div>

            <div className="text-sm font-medium text-slate-400 italic">
              {t('photos.galleryView.showingCount', { count: displayPhotos.length, label: showingLabel })}
            </div>
          </div>

          <div className="mt-6">
            <PhotoFilterBar
              filters={filters}
              onFiltersChange={setFilters}
              onClear={clearFilters}
              sortOptions={sortOptions}
              showStatus={canModerate}
              statusOptions={statusOptions}
              albumOptions={albumOptions}
              athleteOptions={athleteOptions}
              showDensity
              onDensityChange={setDensity}
            />
          </div>
        </div>
      </section>

      {/* Parent upload (shown in view mode when allow_contributions is true) */}
      {!isManageMode && showParentUpload && gallery && gallery.allow_contributions && (
        <Card className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold">{t('photos.galleryView.shareHighlights')}</h2>
            <Button
              variant="secondary"
              onClick={() => setShowParentUpload(false)}
            >
              <Icon name="close" size="text-sm" />
            </Button>
          </div>
          <ParentPhotoUpload
            gallery={gallery}
            onUploadComplete={() => {
              setShowParentUpload(false)
              loadPhotos(true)
            }}
          />
        </Card>
      )}

      {/* Coach/admin upload and moderation (shown in manage mode) */}
      {isManageMode && gallery && canModerate && (
        <>
          {/* Moderation Queue */}
          {gallery.require_approval && (
            <Card className="mb-8">
              <h2 className="text-xl font-bold mb-4">{t('gallery.moderationQueue.title')}</h2>
              <ModerationQueue
                galleryId={gallery.id}
                onModerationComplete={() => {
                  loadPhotos(true)
                }}
              />
            </Card>
          )}

          <Card className="mb-8">
            <AlbumManager
              galleryId={gallery.id}
              onAlbumsUpdated={(next) => setAlbums(next)}
            />
          </Card>

          {/* Upload Photos */}
          <Card className="mb-8">
            <h2 className="text-xl font-bold mb-4">{t('photos.upload.title')}</h2>
            <PhotoUploader
              gallery={gallery}
              albumId={filters.album && filters.album !== 'favorites' ? filters.album : null}
              onUploadComplete={() => {
                loadPhotos(true)
              }}
            />
          </Card>
        </>
      )}

      {displayPhotos.length === 0 ? (
        <Card>
          <div className="text-center py-12">
            <Icon name="photo_library" size="text-6xl" className="text-slate-300 dark:text-slate-600 mb-4 mx-auto" />
            <p className="text-slate-500 dark:text-slate-400 text-lg">
              {t('photos.galleryView.empty')}
            </p>
          </div>
        </Card>
      ) : (
        <>
          {/* Photo Grid */}
          {photosByAlbum ? (
            <div className="space-y-12 mb-32">
              {photosByAlbum.unassigned.length > 0 && (
                <div>
                  <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-widest mb-4">
                    {t('photos.albums.unassigned')}
                  </h3>
                  <PortalGalleryView
                    gallery={gallery}
                    photos={photosByAlbum.unassigned}
                    bookmarkedIds={bookmarkedIds}
                    onBookmarkChange={(id, isBookmarked) => {
                      setBookmarkedIds((prev) => {
                        const next = new Set(prev)
                        if (isBookmarked) next.add(id)
                        else next.delete(id)
                        return next
                      })
                    }}
                    onPhotoClick={(photo) => {
                      const idx = displayPhotos.findIndex((p) => p.id === photo.id)
                      setLightboxIndex(idx)
                    }}
                    selectedIds={Array.from(selectedPhotos)}
                    onSelectionChange={(ids) => setSelectedPhotos(new Set(ids))}
                  />
                </div>
              )}
              {albums.map((album) => {
                const items = photosByAlbum.byAlbum.get(album.id) || []
                if (items.length === 0) return null
                return (
                  <div key={album.id}>
                    <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-widest mb-4">
                      {album.name}
                    </h3>
                    <PortalGalleryView
                      gallery={gallery}
                      photos={items}
                      bookmarkedIds={bookmarkedIds}
                      onBookmarkChange={(id, isBookmarked) => {
                        setBookmarkedIds((prev) => {
                          const next = new Set(prev)
                          if (isBookmarked) next.add(id)
                          else next.delete(id)
                          return next
                        })
                      }}
                      onPhotoClick={(photo) => {
                        const idx = displayPhotos.findIndex((p) => p.id === photo.id)
                        setLightboxIndex(idx)
                      }}
                      selectedIds={Array.from(selectedPhotos)}
                      onSelectionChange={(ids) => setSelectedPhotos((prev) => {
                         // Merging selection from multiple grids is tricky if they overwrite
                         // But PortalGalleryView controlled mode just emits the ids.
                         // We need to merge.
                         // Actually the prompt says "Replace manual grid", implying one grid.
                         // But PhotosGallery supports grouping by album.
                         // The existing code iterates albums and renders grid for each.
                         // We are replacing `renderPhotoGrid` call.
                         
                         // If we have multiple PortalGalleryView instances, they need to share selection state properly.
                         // `onSelectionChange` typically returns the *new* full list.
                         // If I use it here, I might overwrite selection from other albums.
                         // I need to be careful.
                         
                         // Better approach:
                         // Keep `renderPhotoGrid` logic but make IT render PortalGalleryView?
                         
                         const newSet = new Set(prev)
                         // Determine which items were in this album's view to toggle them?
                         // The PortalGalleryView doesn't give us delta. It gives us "selectedIds".
                         // This is a limitation of the controlled component pattern when used in multiple instances sharing one state.
                         
                         // WORKAROUND:
                         // Since `PortalGalleryView` is now the fundamental block, 
                         // and we have multiple blocks share one state `selectedPhotos`.
                         // We need `onSelectionChange` to support merging.
                         
                         // Actually, if `PortalGalleryView` receives `selectedIds`, it displays them.
                         // When it emits `onSelectionChange`, it emits `[...ids]`.
                         // If I click one item in Album A, it emits [id].
                         // If I had items selected in Album B, they are missing from Album A's view probably?
                         // wait, `items` prop in `PortalGalleryView` determines scope.
                         // useGallerySelection is scoped to `items`.
                         // So it only knows about Album A items.
                         // So it spits out only Album A selections.
                         
                         // So we need to merge.
                         // We can take the emitted IDs, find which ones belong to this Album.
                         // Update `selectedPhotos` by replacing Album A's matches with new matches, keeping Album B's matches.
                         
                         const albumItemIds = new Set(items.map(i => i.id))
                         ids.forEach(id => newSet.add(id))
                         // Remove ones no longer in ids BUT were in albumItemIds
                         for (const id of albumItemIds) {
                            if (!ids.includes(id)) newSet.delete(id)
                         }
                         return newSet
                      })}
                    />
                  </div>
                )
              })}
            </div>
          ) : (
            <div className="mb-32">
              <PortalGalleryView
                gallery={gallery}
                photos={displayPhotos}
                bookmarkedIds={bookmarkedIds}
                onBookmarkChange={(id, isBookmarked) => {
                  setBookmarkedIds((prev) => {
                    const next = new Set(prev)
                    if (isBookmarked) next.add(id)
                    else next.delete(id)
                    return next
                  })
                }}
                onPhotoClick={(photo) => {
                  const idx = displayPhotos.findIndex((p) => p.id === photo.id)
                  setLightboxIndex(idx)
                }}
                selectedIds={Array.from(selectedPhotos)}
                onSelectionChange={(ids) => setSelectedPhotos(new Set(ids))}
              />
            </div>
          )}

          {loadingMore && (
            <div className="text-center text-sm text-slate-500 mb-12">
              {t('common.loading')}
            </div>
          )}

          {/* Bottom Action Bar - Fixed when photos are selected */}
          {selectedPhotos.size > 0 && (
            <div className="fixed bottom-12 left-1/2 -translate-x-1/2 z-[60]">
              <div className="bg-white/90 dark:bg-slate-800/90 backdrop-blur-2xl px-8 py-4 rounded-full shadow-[0_32px_64px_-16px_rgba(0,0,0,0.15)] border border-slate-200 dark:border-slate-700 flex items-center gap-10">
                <div className="flex items-center gap-4 border-r border-slate-200 dark:border-slate-700 pr-10">
                  <span className="text-black dark:text-white font-black text-sm">
                    {t('photos.selection.count', { count: selectedPhotos.size, label: selectedLabel })}
                  </span>
                  <button
                    onClick={() => setSelectedPhotos(new Set())}
                    className="text-slate-400 hover:text-red-500 transition-colors"
                  >
                    <span className="material-symbols-outlined text-xl">close</span>
                  </button>
                </div>

                <div className="flex items-center gap-6">
                  <button className="flex items-center gap-2 text-sm font-bold hover:text-primary transition-colors">
                    <span className="material-symbols-outlined text-xl">ios_share</span>
                    {t('common.share')}
                  </button>
                  {gallery.can_download && (
                    <BulkDownloadButton
                      galleryId={gallery.id}
                      photoIds={selectedDownloadIds}
                      disabled={selectedDownloadIds.length === 0}
                      label={t('photos.download.selected')}
                      onComplete={() => setSelectedPhotos(new Set())}
                    />
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Lightbox */}
          <Lightbox
            open={lightboxIndex >= 0}
            close={() => setLightboxIndex(-1)}
            index={lightboxIndex}
            slides={displayPhotos.map((photo) => ({
              src: getGalleryPhotoUrl(photo.storage_path),
              alt: photo.caption || t('photos.galleryView.photoAlt'),
            }))}
          />
        </>
      )}
      {/* Tagging slideout */}
      {taggingPhoto && gallery && (
        <TaggingSlideout
          photo={taggingPhoto}
          gallery={gallery}
          isOpen={!!taggingPhoto}
          onClose={() => {
            setTaggingPhoto(null)
            setTaggingPhotoIndex(-1)
          }}
          onOpenLightbox={() => {
            setLightboxIndex(taggingPhotoIndex >= 0 ? taggingPhotoIndex : 0)
            setTaggingPhoto(null)
            setTaggingPhotoIndex(-1)
          }}
          onSave={async ({ advanceToNext }) => {
            const refreshed = await loadPhotos(true)
            if (refreshed && advanceToNext && taggingPhotoIndex >= 0) {
              const nextIndex = taggingPhotoIndex + 1
              if (nextIndex < refreshed.length) {
                setTaggingPhoto(refreshed[nextIndex])
                setTaggingPhotoIndex(nextIndex)
                return
              }
            }
            setTaggingPhoto(null)
            setTaggingPhotoIndex(-1)
          }}
        />
      )}

      {/* Bulk tagging modal */}
      {bulkTaggingPhotos.length > 0 && (
        <BulkTaggingModal
          photos={bulkTaggingPhotos}
          isOpen={bulkTaggingPhotos.length > 0}
          onClose={() => {
            setBulkTaggingPhotos([])
            setSelectedPhotos(new Set())
          }}
          onComplete={() => {
            loadPhotos(true)
          }}
        />
      )}

      {/* Gallery Edit Modal */}
      {gallery && (
        <GalleryEditModal
          open={showEditModal}
          gallery={gallery}
          photos={photos}
          onClose={() => setShowEditModal(false)}
          onSaved={(updatedGallery) => {
            setGallery(updatedGallery)
            setShowEditModal(false)
          }}
        />
      )}
    </PortalLayout>
  )
}

/**
 * SharedVideoPage - Public video sharing via token
 * 
 * Displays a video that was shared via a link token.
 * - Validates the share token
 * - Handles password protection if enabled
 * - Tracks view analytics
 * - Supports download if allowed
 * 
 * URL: /share/video/:token
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { useParams, Link } from 'react-router-dom'
import { supabase } from '@/lib/supabase'
import { useDebugLifecycle } from '@/lib/debug/integrations/useDebugLifecycle'
import Icon from '@/components/portal/Icon'
import Button from '@/components/portal/Button'
import { cn } from '@/utils/cn'

interface ShareValidation {
  video_id: string
  is_valid: boolean
  allow_download: boolean
  requires_password: boolean
}

interface VideoData {
  id: string
  title: string
  description: string | null
  mux_playback_id: string | null
  duration_seconds: number | null
  thumbnail_url: string | null
  category: string
  team_name: string | null
  org_name: string | null
  recorded_at: string | null
  created_at: string
}

interface PlaybackData {
  stream_url: string
  thumbnail_url: string
  token: string
}

// Load Mux Player script
function loadMuxPlayerScript(): Promise<void> {
  return new Promise((resolve, reject) => {
    if (document.querySelector('script[src*="mux-player"]')) {
      resolve()
      return
    }
    
    const script = document.createElement('script')
    script.src = 'https://cdn.jsdelivr.net/npm/@mux/mux-player@2'
    script.async = true
    script.onload = () => resolve()
    script.onerror = () => reject(new Error('Failed to load Mux Player script'))
    document.head.appendChild(script)
  })
}

export default function SharedVideoPage() {
  const { token } = useParams<{ token: string }>()
  useDebugLifecycle('SharedVideoPage', { token })
  
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [shareValidation, setShareValidation] = useState<ShareValidation | null>(null)
  const [video, setVideo] = useState<VideoData | null>(null)
  const [playbackData, setPlaybackData] = useState<PlaybackData | null>(null)
  const [scriptLoaded, setScriptLoaded] = useState(false)
  
  // Password protection state
  const [requiresPassword, setRequiresPassword] = useState(false)
  const [passwordInput, setPasswordInput] = useState('')
  const [passwordError, setPasswordError] = useState<string | null>(null)
  const [verifyingPassword, setVerifyingPassword] = useState(false)
  const [passwordVerified, setPasswordVerified] = useState(false)
  
  // Download state
  const [downloading, setDownloading] = useState(false)
  
  // Ref to avoid stale closure in validateToken
  const loadVideoRef = useRef<(videoId: string) => Promise<void>>(() => Promise.resolve())

  // Load Mux Player script
  useEffect(() => {
    loadMuxPlayerScript()
      .then(() => setScriptLoaded(true))
      .catch((err) => console.error('Failed to load Mux Player:', err))
  }, [])

  // Validate the share token
  const validateToken = useCallback(async () => {
    if (!token) {
      setError('Invalid share link')
      setLoading(false)
      return
    }

    try {
      // Call the RPC function to validate the token - use type assertion since function is added via migration
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data, error: rpcError } = await (supabase as any)
        .rpc('validate_video_share_token', { p_token: token })
        .single()

      if (rpcError) throw rpcError

      if (!data || !data.is_valid) {
        setError('This share link has expired or been revoked')
        setLoading(false)
        return
      }

      const validation = data as ShareValidation
      setShareValidation(validation)
      
      if (validation.requires_password) {
        setRequiresPassword(true)
        setLoading(false)
        return
      }

      // No password required, proceed to load video
      await loadVideoRef.current(validation.video_id)
    } catch (err) {
      console.error('Error validating share token:', err)
      setError('Failed to validate share link')
      setLoading(false)
    }
  }, [token])

  // Load video data
  const loadVideo = useCallback(async (videoId: string) => {
    try {
      // Fetch video details (using service role via RPC or direct query)
      const { data: videoData, error: videoError } = await supabase
        .from('videos')
        .select(`
          id,
          title,
          description,
          mux_playback_id,
          duration_seconds,
          thumbnail_url,
          category,
          recorded_at,
          created_at,
          team:teams!videos_team_id_fkey(name),
          organization:organizations!videos_org_id_fkey(name)
        `)
        .eq('id', videoId)
        .single()

      if (videoError || !videoData) {
        throw new Error('Video not found')
      }

      const transformedVideo: VideoData = {
        id: videoData.id,
        title: videoData.title,
        description: videoData.description,
        mux_playback_id: videoData.mux_playback_id,
        duration_seconds: videoData.duration_seconds,
        thumbnail_url: videoData.thumbnail_url,
        category: videoData.category,
        team_name: (videoData.team as { name?: string } | null)?.name || null,
        org_name: (videoData.organization as { name?: string } | null)?.name || null,
        recorded_at: videoData.recorded_at,
        created_at: videoData.created_at,
      }

      setVideo(transformedVideo)

      // Get signed playback URL
      if (videoData.mux_playback_id) {
        const supabaseUrl = import.meta.env.VITE_SUPABASE_URL
        const response = await fetch(`${supabaseUrl}/functions/v1/mux-signed-playback`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            video_id: videoId,
            type: 'video',
            expiration: 7200, // 2 hours for shared video
            share_token: token, // Pass share token for validation
          }),
        })

        if (response.ok) {
          const data = await response.json()
          setPlaybackData(data)
        }
      }

      // Increment access count - use type assertion since function is added via migration
      if (token) {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        await (supabase as any).rpc('increment_share_access', { p_token: token })
      }

      setLoading(false)
    } catch (err) {
      console.error('Error loading video:', err)
      setError('Failed to load video')
      setLoading(false)
    }
  }, [token])
  
  // Keep ref updated
  loadVideoRef.current = loadVideo

  // Handle password verification
  const handlePasswordSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault()
    if (!passwordInput.trim() || !shareValidation) return

    setVerifyingPassword(true)
    setPasswordError(null)

    try {
      // Verify password via RPC - use type assertion since function is added via migration
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data, error: verifyError } = await (supabase as any)
        .rpc('verify_video_share_password', { 
          p_token: token, 
          p_password: passwordInput 
        })

      if (verifyError) throw verifyError

      if (data === true) {
        setPasswordVerified(true)
        setRequiresPassword(false)
        await loadVideo(shareValidation.video_id)
      } else {
        setPasswordError('Incorrect password')
      }
    } catch (err) {
      console.error('Error verifying password:', err)
      setPasswordError('Failed to verify password')
    } finally {
      setVerifyingPassword(false)
    }
  }, [passwordInput, shareValidation, token, loadVideo])

  // Handle download
  const handleDownload = useCallback(async () => {
    if (!video || !playbackData || !shareValidation?.allow_download) return

    setDownloading(true)
    try {
      // Create download link
      const downloadUrl = playbackData.stream_url.replace('/stream.m3u8', '/high.mp4')
      
      const link = document.createElement('a')
      link.href = downloadUrl
      link.download = `${video.title}.mp4`
      link.target = '_blank'
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
    } catch (err) {
      console.error('Download failed:', err)
    } finally {
      setDownloading(false)
    }
  }, [video, playbackData, shareValidation])

  // Initial load
  useEffect(() => {
    validateToken()
  }, [validateToken])

  // Format duration helper
  const formatDuration = (seconds: number | null): string => {
    if (!seconds) return ''
    const hrs = Math.floor(seconds / 3600)
    const mins = Math.floor((seconds % 3600) / 60)
    const secs = Math.floor(seconds % 60)
    if (hrs > 0) {
      return `${hrs}:${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`
    }
    return `${mins}:${String(secs).padStart(2, '0')}`
  }

  // Loading state
  if (loading) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center">
        <div className="text-center">
          <div className="size-12 border-4 border-white/20 border-t-white rounded-full animate-spin mx-auto mb-4" />
          <p className="text-white/60">Loading video...</p>
        </div>
      </div>
    )
  }

  // Error state
  if (error) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center p-4">
        <div className="text-center max-w-md">
          <div className="size-16 bg-red-500/10 rounded-full flex items-center justify-center mx-auto mb-4">
            <Icon name="error" size="text-4xl" className="text-red-500" />
          </div>
          <h1 className="text-xl font-bold text-white mb-2">Unable to Load Video</h1>
          <p className="text-white/60 mb-6">{error}</p>
          <Link to="/">
            <Button variant="secondary">
              Return Home
            </Button>
          </Link>
        </div>
      </div>
    )
  }

  // Password protection screen
  if (requiresPassword && !passwordVerified) {
    return (
      <div className="min-h-screen bg-gray-950 flex items-center justify-center p-4">
        <div className="w-full max-w-md">
          <div className="bg-gray-900 rounded-2xl p-8 shadow-xl">
            <div className="text-center mb-6">
              <div className="size-16 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-4">
                <Icon name="lock" size="text-4xl" className="text-blue-500" />
              </div>
              <h1 className="text-xl font-bold text-white mb-2">Password Protected</h1>
              <p className="text-white/60">
                This video requires a password to view.
              </p>
            </div>

            <form onSubmit={handlePasswordSubmit}>
              <div className="mb-4">
                <input
                  type="password"
                  value={passwordInput}
                  onChange={(e) => setPasswordInput(e.target.value)}
                  placeholder="Enter password"
                  className="w-full px-4 py-3 rounded-lg bg-gray-800 border border-gray-700 text-white placeholder-gray-500 focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  autoFocus
                />
                {passwordError && (
                  <p className="text-red-400 text-sm mt-2">{passwordError}</p>
                )}
              </div>

              <Button
                type="submit"
                variant="primary"
                className="w-full"
                disabled={verifyingPassword || !passwordInput.trim()}
              >
                {verifyingPassword ? 'Verifying...' : 'Unlock Video'}
              </Button>
            </form>
          </div>
        </div>
      </div>
    )
  }

  // Video player screen
  return (
    <div className="min-h-screen bg-gray-950">
      {/* Header */}
      <header className="bg-gray-900 border-b border-gray-800 px-4 py-3">
        <div className="max-w-5xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Icon name="play_circle" size="text-2xl" className="text-blue-500" />
            <span className="text-white font-bold">Shared Video</span>
          </div>
          {video?.org_name && (
            <span className="text-white/40 text-sm">{video.org_name}</span>
          )}
        </div>
      </header>

      {/* Main content */}
      <main className="max-w-5xl mx-auto px-4 py-6">
        {/* Video Player */}
        <div className="relative w-full bg-black rounded-xl overflow-hidden shadow-2xl" style={{ aspectRatio: '16/9' }}>
          {playbackData && scriptLoaded ? (
            <mux-player
              playback-id={playbackData.stream_url.split('/')[4]}
              playback-token={playbackData.token}
              stream-type="on-demand"
              primary-color="#3b82f6"
              secondary-color="#1e293b"
              style={{ width: '100%', height: '100%' }}
            />
          ) : video?.thumbnail_url ? (
            <div 
              className="absolute inset-0 bg-center bg-cover"
              style={{ backgroundImage: `url(${video.thumbnail_url})` }}
            >
              <div className="absolute inset-0 flex items-center justify-center bg-black/50">
                <div className="size-12 border-4 border-white/30 border-t-white rounded-full animate-spin" />
              </div>
            </div>
          ) : (
            <div className="absolute inset-0 flex items-center justify-center bg-gray-900">
              <Icon name="videocam" size="text-5xl" className="text-gray-600" />
            </div>
          )}
        </div>

        {/* Video Info */}
        <div className="mt-6">
          <h1 className="text-2xl font-bold text-white mb-2">{video?.title}</h1>
          
          <div className="flex flex-wrap items-center gap-3 text-sm text-white/60 mb-4">
            {video?.team_name && (
              <span className="flex items-center gap-1">
                <Icon name="groups" size="text-base" />
                {video.team_name}
              </span>
            )}
            {video?.category && (
              <span className="px-2 py-0.5 bg-blue-500/20 text-blue-400 rounded text-xs uppercase font-bold">
                {video.category}
              </span>
            )}
            {video?.duration_seconds && (
              <span className="flex items-center gap-1">
                <Icon name="schedule" size="text-base" />
                {formatDuration(video.duration_seconds)}
              </span>
            )}
            {video?.recorded_at && (
              <span className="flex items-center gap-1">
                <Icon name="calendar_today" size="text-base" />
                {new Date(video.recorded_at).toLocaleDateString()}
              </span>
            )}
          </div>

          {video?.description && (
            <p className="text-white/70 mb-6">{video.description}</p>
          )}

          {/* Download button */}
          {shareValidation?.allow_download && (
            <Button
              variant="secondary"
              onClick={handleDownload}
              disabled={downloading || !playbackData}
              className="flex items-center gap-2"
            >
              <Icon name={downloading ? 'sync' : 'download'} className={cn(downloading && 'animate-spin')} />
              {downloading ? 'Downloading...' : 'Download Video'}
            </Button>
          )}
        </div>
      </main>

      {/* Footer */}
      <footer className="border-t border-gray-800 mt-12 py-6 text-center text-white/40 text-sm">
        Powered by YouthSports.team
      </footer>
    </div>
  )
}

import { useState, useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { useUserContext } from '../hooks/useUserContext'
import { 
  getTravelPlans,
  formatDateRange
} from '../data/services/travelService'
import type { FakeTravelPlan } from '../data/fake/fakeTravel'
import { getSportFromTeam, type SportInfo } from '../utils/sportContext'
import PortalLayout from '../components/portal/PortalLayout'
import { PageTitle, CardTitle } from '../components/portal/Typography'
// SportCardImage removed
import Card from '../components/portal/Card'
import Icon from '../components/portal/Icon'
import Button from '../components/portal/Button'
import { cn } from '../utils/cn'
import { useT } from '../i18n/useI18n'

// ----------------------------------------------------------------------------
// Types & Helpers
// ----------------------------------------------------------------------------

type TabType = 'upcoming' | 'past' | 'all'

interface GroupedPlans {
    key: string
    label: string
    items: FakeTravelPlan[]
    year: number
    seasonId?: string
}

function getGroupKey(plan: FakeTravelPlan): string {
    if (plan.season?.id) return `season-${plan.season.id}`
    // Fallback to year if no season
    const year = new Date(plan.start_date).getFullYear()
    return `year-${isNaN(year) ? 'unknown' : year}`
}

function getGroupLabel(plan: FakeTravelPlan): string {
    if (plan.season?.name) return plan.season.name
    const year = new Date(plan.start_date).getFullYear()
    return isNaN(year) ? 'Unknown Date' : `${year}`
}

// Note: status badge labels are translated inside the component via `useT()`.

// ----------------------------------------------------------------------------
// Components
// ----------------------------------------------------------------------------

import { useDebugLifecycle } from '../lib/debug/integrations/useDebugLifecycle'

export default function Travel() {
  useDebugLifecycle('Travel')
    const t = useT()
    const navigate = useNavigate()
    const { context, isReady } = useUserContext()

    const toLocalDateOnlyFromDate = (d: Date): string => {
        const y = String(d.getFullYear())
        const m = String(d.getMonth() + 1).padStart(2, '0')
        const day = String(d.getDate()).padStart(2, '0')
        return `${y}-${m}-${day}`
    }

    const toDateOnly = (value: string): string => {
        // Normalizes various backend formats to YYYY-MM-DD.
        // - YYYY-MM-DD
        // - YYYY-MM-DDTHH:mm:ssZ
        // - YYYY-MM-DD HH:mm:ss+00
        // - Other parseable date strings
        const v = value.trim()
        if (/^\d{4}-\d{2}-\d{2}$/.test(v)) return v
        if (/^\d{4}-\d{2}-\d{2}/.test(v)) return v.slice(0, 10)
        const parsed = new Date(v)
        if (!Number.isNaN(parsed.getTime())) return toLocalDateOnlyFromDate(parsed)
        return v
    }

    const getTodayLocalDateOnly = (): string => {
        // Use local date parts so timezone/UTC offsets don't affect comparisons.
        return toLocalDateOnlyFromDate(new Date())
    }

    const getDisplayStatus = (plan: FakeTravelPlan): { label: string; color: string } => {
        if (plan.status === 'cancelled') {
            return { label: t('portal.travel.badges.cancelled'), color: 'bg-red-500' }
        }

        // Normalize in case the backend returns timestamps.
        const startDate = toDateOnly(plan.start_date)
        const endDate = toDateOnly(plan.end_date)
        const todayStr = getTodayLocalDateOnly()

        if (endDate < todayStr) {
            return { label: t('portal.travel.badges.completed'), color: 'bg-slate-500' }
        }

        // If the trip starts today, call it out.
        if (startDate === todayStr) {
            return { label: t('portal.travel.badges.today'), color: 'bg-emerald-600' }
        }

        // If today's date is between start and end (inclusive), show Active (green).
        if (startDate <= todayStr && todayStr <= endDate) {
            return { label: t('portal.travel.badges.active'), color: 'bg-emerald-600' }
        }

        return { label: t('portal.travel.badges.upcoming'), color: 'bg-[var(--org-btn-primary-bg)]' }
    }
    
    // -- State --
    const [activeTab, setActiveTab] = useState<TabType>('upcoming')
    
    // Data stores
    const [upcomingPlans, setUpcomingPlans] = useState<FakeTravelPlan[] | null>(null)
    const [allPlans, setAllPlans] = useState<FakeTravelPlan[] | null>(null)
    
    // Loading/Error
    const [isLoadingUpcoming, setIsLoadingUpcoming] = useState(true)
    const [isLoadingAll, setIsLoadingAll] = useState(false)
    const [error, setError] = useState<Error | null>(null)
    const [retryCount, setRetryCount] = useState(0)
    
    // Plan metadata (sports info)
    const [planSports, setPlanSports] = useState<Record<string, SportInfo | null>>({})
    
    // UI State
    const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set())
    const [filtersOpen, setFiltersOpen] = useState(false)
    
    // -- Filters --
    const [searchQuery, setSearchQuery] = useState('')
    const [seasonFilter, setSeasonFilter] = useState<string>('')
    const [teamFilter, setTeamFilter] = useState<string>('')

    // -- Effects --

    // 1. Initial Load: Upcoming Plans
    useEffect(() => {
        if (!isReady) return

        let mounted = true
        const loadUpcoming = async () => {
            try {
                setIsLoadingUpcoming(true)
                // Use getTravelPlans with upcomingOnly: true
                const { data, error } = await getTravelPlans(context, { upcomingOnly: true })
                if (mounted) {
                    if (error) throw error
                    const resolved = Array.isArray(data) ? data : []
                    setUpcomingPlans(resolved)
                    loadSports(resolved)
                }
            } catch (err) {
                if (mounted) setError(err instanceof Error ? err : new Error('Failed to load travel plans'))
            } finally {
                if (mounted) setIsLoadingUpcoming(false)
            }
        }

        loadUpcoming()
        return () => { mounted = false }
    }, [context, isReady, retryCount])

    // 2. Load "All Plans" when tab switches to Past or All (if not loaded)
    useEffect(() => {
        console.log('Effect running - activeTab:', activeTab, 'isReady:', isReady, 'allPlans:', allPlans?.length, 'isLoadingAll:', isLoadingAll)
        
        if (!isReady) {
            console.log('Not ready yet')
            return
        }
        if (activeTab === 'upcoming') {
            console.log('Active tab is upcoming, skipping')
            return
        }
        if (Array.isArray(allPlans)) {
            console.log('allPlans already loaded')
            return
        }
        if (isLoadingAll) {
            console.log('Already loading')
            return
        }

        let mounted = true
        const loadAll = async () => {
            try {
                setIsLoadingAll(true)
                console.log('Loading all travel plans...')
                // Use getTravelPlans without upcomingOnly (fetches everything)
                // We rely on service caching or just simple fetch here. 
                // Since this is a redesign, we assume we fetch fresh if not in state.
                const { data, error } = await getTravelPlans(context, {})
                console.log('All travel plans loaded:', data?.length, 'plans', data)
                if (mounted) {
                    if (error) throw error
                    const resolved = Array.isArray(data) ? data : []
                    setAllPlans(resolved)
                    loadSports(resolved)
                }
            } catch (err) {
                console.error('Error loading all plans:', err)
                if (mounted) {
                    setError(err instanceof Error ? err : new Error('Failed to load travel plans'))
                    setAllPlans([])
                }
            } finally {
                if (mounted) setIsLoadingAll(false)
            }
        }

        loadAll()
        return () => { mounted = false }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [activeTab, isReady, context, retryCount])

    // Helper to load sports for new plans
    const loadSports = async (plans: FakeTravelPlan[]) => {
        const newSports: Record<string, SportInfo | null> = {}
        const uniqueTeamIds = [...new Set(plans.map(p => p.team_id).filter(Boolean))]
        
        // Check which ones we don't have yet? Or just reload to be safe/simple
        await Promise.all(uniqueTeamIds.map(async (teamId) => {
            try {
                const sport = await getSportFromTeam(context, teamId)
                // Map sport to all plans with this team
                plans.filter(p => p.team_id === teamId).forEach(p => {
                    newSports[p.id] = sport
                })
            } catch (e) {
                console.error(e)
            }
        }))
        
        setPlanSports(prev => ({ ...prev, ...newSports }))
    }

    // -- Derived Data --
    
    // Source plans based on tab
    const sourcePlans = useMemo(() => {
        console.log('sourcePlans recalculating:', { 
            activeTab, 
            upcomingPlansCount: upcomingPlans?.length, 
            allPlansCount: allPlans?.length 
        })
        
        if (activeTab === 'upcoming') return Array.isArray(upcomingPlans) ? upcomingPlans : []
        // For Past/All, we need the "allPlans" dataset
        // If not loaded yet, default to empty or upcoming (if sensible) 
        // But better to wait for allPlans. 
        if (!Array.isArray(allPlans)) {
            console.log('allPlans is null, returning empty array')
            return []
        }
        
        const today = getTodayLocalDateOnly()
        console.log('Today:', today)
        
        if (activeTab === 'past') {
            const pastPlans = allPlans.filter(p => {
                const endDate = toDateOnly(p.end_date)
                const isPast = endDate < today
                console.log('Plan:', p.title, 'end_date:', p.end_date, 'isPast:', isPast)
                return isPast
            })
            console.log('Past plans count:', pastPlans.length)
            return pastPlans
        }
        
        console.log('Returning all plans:', allPlans.length)
        return allPlans // 'all' tab
    }, [activeTab, upcomingPlans, allPlans])

    // Filter Logic
    const filteredPlans = useMemo(() => {
        return sourcePlans.filter(plan => {
            // Search
            if (searchQuery) {
                const q = searchQuery.toLowerCase()
                const matchTitle = plan.title.toLowerCase().includes(q)
                const matchLoc = (plan.location || '').toLowerCase().includes(q)
                const matchCity = (plan.destination_city || '').toLowerCase().includes(q)
                const matchTeam = (plan.team?.name || '').toLowerCase().includes(q)
                if (!matchTitle && !matchLoc && !matchCity && !matchTeam) return false
            }
            // Season Filter
            if (seasonFilter) {
                if (plan.season?.id !== seasonFilter && plan.season?.name !== seasonFilter) return false
            }
            // Team Filter
            if (teamFilter) {
                if (plan.team?.id !== teamFilter && plan.team?.name !== teamFilter) return false
            }
            return true
        })
    }, [sourcePlans, searchQuery, seasonFilter, teamFilter])

    // Grouping
    const groupedPlans = useMemo(() => {
        const groups: Record<string, GroupedPlans> = {}
        
        filteredPlans.forEach(plan => {
            const key = getGroupKey(plan)
            if (!groups[key]) {
                groups[key] = {
                    key,
                    label: getGroupLabel(plan),
                    items: [],
                    year: new Date(plan.start_date).getFullYear(),
                    seasonId: plan.season?.id
                }
            }
            groups[key].items.push(plan)
        })

        // Sort items within groups (chronological)
        Object.values(groups).forEach(g => {
            g.items.sort((a, b) => a.start_date.localeCompare(b.start_date))
        })

        // Sort groups
        const sortedGroups = Object.values(groups).sort((a, b) => {
            // Sort logic: 
            // Upcoming tab: Soonest season/year first
            // Past tab: Most recent season/year first
            // All tab: Upcoming block first (soonest), then Past block (recent) -- complex. 
            // Simplified All: Recent (descending) or Chronological (ascending)? 
            // Requirement: "All: Upcoming block first... then Past block (most recent first)."
            
            // Let's implement simpler sort first:
            // If Upcoming tab -> Ascending date (Year/Season)
            // If Past/All tab -> Descending date
            
            if (activeTab === 'upcoming') {
                return a.year - b.year // Ascending year roughly, better to look at first item start date
                    || (a.items[0]?.start_date.localeCompare(b.items[0]?.start_date) ?? 0)
            } else {
                return b.year - a.year // Descending
                    || (b.items[0]?.start_date.localeCompare(a.items[0]?.start_date) ?? 0)
            }
        })
        
        return sortedGroups
    }, [filteredPlans, activeTab])

    // Initialization of expanded groups
    // Reset when tab changes? No, requirement says: "Upcoming always expanded. Past: collapse if large."
    useEffect(() => {
        // Build a set of keys to expand by default
        const newExpanded = new Set<string>()
        
        if (activeTab === 'upcoming') {
            groupedPlans.forEach(g => newExpanded.add(g.key))
        } else {
            // Past/All
            groupedPlans.forEach((g, idx) => {
                // Expand first group or if small
                if (idx === 0 || g.items.length < 5) {
                    newExpanded.add(g.key)
                }
            })
        }
        setExpandedGroups(newExpanded)
    }, [activeTab, groupedPlans.length]) // Only re-calc defaults when tab/plans change meaningfully


    const toggleGroup = (key: string) => {
        setExpandedGroups(prev => {
            const next = new Set(prev)
            if (next.has(key)) next.delete(key)
            else next.add(key)
            return next
        })
    }
    
    // Filter Options
    const seasonOptions = useMemo(() => {
        const unique = new Map<string, string>()
        // Use allPlans if available for better filter list, or just sourcePlans
        const pool = allPlans || upcomingPlans || []
        pool.forEach(p => {
             if (p.season) unique.set(p.season.id, p.season.name)
        })
        return Array.from(unique.entries()).map(([id, name]) => ({ id, name }))
    }, [allPlans, upcomingPlans])

    const teamOptions = useMemo(() => {
        const unique = new Map<string, string>()
        const pool = allPlans || upcomingPlans || []
        pool.forEach(p => {
             if (p.team) unique.set(p.team.id, p.team.name)
        })
        return Array.from(unique.entries()).map(([id, name]) => ({ id, name }))
    }, [allPlans, upcomingPlans])


    // -- Render --

    if (error) {
        return (
            <PortalLayout breadcrumbs={[{ label: 'Home', path: '/portal/dashboard' }, { label: 'Travel' }]}>
                <div className="flex justify-center py-12">
                   <Card className="text-center py-12 max-w-lg w-full">
                       <Icon name="error" size="text-6xl" className="text-red-400 mb-4 mx-auto" />
                       <CardTitle className="mb-2">Error loading plans</CardTitle>
                       <p className="text-slate-500 mb-6">{error.message}</p>
                       <Button onClick={() => {
                           setError(null)
                           setRetryCount(c => c + 1)
                       }}>Retry</Button>
                   </Card>
                </div>
            </PortalLayout>
        )
    }

    return (
        <PortalLayout breadcrumbs={[{ label: 'Home', path: '/portal/dashboard' }, { label: 'Travel' }]}>
            
            {/* Header */}
            <div className="mb-8">
                <PageTitle>Travel</PageTitle>
                <p className="text-slate-500 dark:text-slate-400 text-lg font-light tracking-wide mt-2">
                    Manage upcoming trips and view past travel history.
                </p>
            </div>

            {/* Tabs & Controls */}
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6">
                
                {/* Tabs */}
                <div className="flex bg-slate-100 dark:bg-slate-800 p-1 rounded-xl self-start">
                    {(['upcoming', 'past', 'all'] as TabType[]).map(tab => (
                        <button
                            key={tab}
                            onClick={() => setActiveTab(tab)}
                            className={cn(
                                "px-4 py-2 rounded-lg text-sm font-bold uppercase tracking-wide transition-all",
                                activeTab === tab 
                                    ? "bg-white dark:bg-slate-700 text-[var(--org-btn-primary-bg)] shadow-sm"
                                    : "text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200"
                            )}
                        >
                            {tab === 'upcoming'
                                ? t('portal.travel.tabs.current')
                                : tab === 'past'
                                    ? t('portal.travel.tabs.past')
                                    : t('portal.travel.tabs.all')}
                        </button>
                    ))}
                </div>
                
                {/* Filter Toggle / Search */}
                <div className="flex gap-2">
                   <div className="relative">
                       <input 
                          type="text" 
                          placeholder="Search..." 
                          value={searchQuery}
                          onChange={e => setSearchQuery(e.target.value)}
                          className="form-input pl-9 pr-4 w-40 sm:w-64"
                       />
                       <Icon name="search" className="absolute left-3 top-2.5 text-slate-400 text-sm" />
                   </div>
                   <Button 
                       variant="secondary" 
                       onClick={() => setFiltersOpen(!filtersOpen)}
                       className={cn(filtersOpen && "bg-slate-100 dark:bg-slate-800")}
                   >
                       <Icon name="filter_list" />
                   </Button>
                </div>
            </div>

            {/* Filters Bar */}
            {filtersOpen && (
                <Card className="mb-6 p-4 animate-in fade-in slide-in-from-top-2 duration-200">
                    <div className="flex flex-wrap gap-4">
                        <div className="flex-1 min-w-[200px]">
                            <label className="form-label">Season</label>
                            <select 
                                value={seasonFilter} 
                                onChange={e => setSeasonFilter(e.target.value)}
                                className="form-select"
                            >
                                <option value="">All Seasons</option>
                                {seasonOptions.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                            </select>
                        </div>
                        <div className="flex-1 min-w-[200px]">
                            <label className="form-label">Team</label>
                            <select 
                                value={teamFilter} 
                                onChange={e => setTeamFilter(e.target.value)}
                                className="form-select"
                            >
                                <option value="">All Teams</option>
                                {teamOptions.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
                            </select>
                        </div>
                        <div className="flex items-end">
                            <Button 
                                variant="secondary" 
                                className="text-red-500 hover:text-red-600 text-sm px-0"
                                onClick={() => {
                                    setSeasonFilter('')
                                    setTeamFilter('')
                                    setSearchQuery('')
                                }}
                            >
                                Clear All
                            </Button>
                        </div>
                    </div>
                </Card>
            )}

            {/* Content State */}
            {isLoadingUpcoming && !upcomingPlans ? (
                 <div className="flex justify-center py-20">
                    <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-[var(--org-btn-primary-bg)]"></div>
                 </div>
            ) : (activeTab !== 'upcoming' && isLoadingAll && !allPlans) ? (
                 <div className="flex justify-center py-20">
                    <div className="animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-[var(--org-btn-primary-bg)]"></div>
                 </div>
            ) : filteredPlans.length === 0 ? (
                 <div className="text-center py-20 opacity-60">
                     <Icon name="flight_takeoff" size="text-6xl" className="mb-4 mx-auto text-slate-300" />
                     <h3 className="text-xl font-bold text-slate-500">No travel plans found</h3>
                     <p className="text-slate-400">Try adjusting your filters or check back later.</p>
                 </div>
            ) : (
                <div className="space-y-8">
                    {groupedPlans.map(group => (
                        <div key={group.key} className="space-y-4">
                            {/* Group Header */}
                            <div 
                                className="flex items-center gap-4 cursor-pointer group select-none"
                                onClick={() => toggleGroup(group.key)}
                            >
                                <button className="p-1 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
                                    <Icon name={expandedGroups.has(group.key) ? "expand_less" : "expand_more"} className="text-slate-400" />
                                </button>
                                <h2 className="text-xl font-black uppercase text-slate-700 dark:text-slate-200 tracking-wide">
                                    {group.label}
                                </h2>
                                <div className="h-px flex-1 bg-slate-200 dark:bg-slate-700"></div>
                                <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">
                                    {group.items.length} {group.items.length === 1 ? 'Trip' : 'Trips'}
                                </span>
                            </div>

                            {/* Group Content */}
                            {expandedGroups.has(group.key) && (
                                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-4 animate-in fade-in slide-in-from-top-2 duration-300 pl-2 sm:pl-0">
                                    {group.items.map(plan => {
                                        const status = getDisplayStatus(plan)
                                        const sport = planSports[plan.id]
                                        
                                        return (
                                            <div 
                                                key={plan.id}
                                                onClick={() => navigate(`/portal/travel/${plan.id}`)}
                                                className="group relative bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-xl shadow-sm hover:shadow-lg hover:border-[var(--org-btn-primary-bg)]/30 transition-all duration-200 cursor-pointer overflow-hidden p-4 sm:p-5 flex flex-col gap-3"
                                            >
                                                {/* Top Row: Team + Status */}
                                                <div className="flex justify-between items-start gap-2">
                                                    <div className="flex items-center gap-2">
                                                        {sport && (
                                                            <div 
                                                                className="w-2 h-8 rounded-full"
