function ProfileSettings({ 
  firstName, 
  setFirstName,
  lastName,
  setLastName,
  phone, 
  setPhone, 
  timezone, 
  setTimezone, 
  timezoneOptions,
  profile,
  displayEmail,
  onSave,
  saving,
  onShowEmailModal
