      </div>
      
      <div className="oa-form-actions">
        <Button
          onClick={onSave}
          disabled={saving}
          variant="primary"
        >
          {saving ? 'Saving...' : 'Save Profile'}
        </Button>
      </div>
    </Card>
  )
}

