          helper="Adjust spacing and sizing of interface elements"
        />
      </div>
      
      <div className="oa-form-actions">
        <Button
          onClick={onSave}
          disabled={saving}
          variant="primary"
        >
          {saving ? 'Saving...' : 'Save Advanced'}
        </Button>
      </div>
    </Card>
  )
}

