import { showSuccess, showError } from '../../utils/toast'
import { 
  AdminPageHeader, 
  Card, 
  Button, 
  Input, 
  Select,
  DatePicker 
} from '../../components/admin'
import { OrgAdminButton } from '../../components/admin/OrgAdminButton'
import { FileUpload } from '../../components/common/FileUpload'
import { LocationAutocomplete } from '../../components/common/LocationAutocomplete'
import type { StructuredAddress } from '../../types/location'
import { useT } from '../../i18n/useI18n'
import type { TranslationKey } from '../../i18n'
import PlanTravelContacts from '../../components/admin/travel/PlanTravelContacts'
import { getOrganizationTravelContacts } from '../../data/services/organizationTravelContactsService'
import { TRAVEL_CONTACT_CATEGORIES, type TravelContactCategory, type OrganizationTravelContactRow, type TravelContactCategoryOrg } from '../../types/travelContacts'
import { upsertTravelPlanContacts } from '../../data/services/travelService'
import '../../styles/orgAdmin.css'

interface Team { id: string; name: string }
interface Season { id: string; name: string }
interface TravelFormData { 
  team_id: string
  season_id: string
  title: string
  location: string
  destination_city: string
  destination_state: string
  destination_state_code: string
  destination_country: string
  destination_place_id: string | null
  destination_lat: number | null
  destination_lng: number | null
  start_date: string
  end_date: string
  venue_name: string
  venue_address: string
  venue_place_id: string | null
  venue_lat: number | null
  venue_lng: number | null
  hotel_name: string
  hotel_address: string
  hotel_place_id: string | null
  hotel_lat: number | null
  hotel_lng: number | null
  hotel_phone: string
  hotel_confirmation: string
  maps_url: string
  notes: string
  contacts: {
    category: string
    is_custom: boolean
    first_name: string
    last_name: string
    email: string
    phone: string
  }[]
}

// Helper to extract state code from Google Place result
const extractStateCode = (placeResult?: google.maps.places.PlaceResult): string => {
  if (!placeResult?.address_components) return ''
  const stateComponent = placeResult.address_components.find(
    c => c.types?.includes('administrative_area_level_1')
  )
  return stateComponent?.short_name || ''
}

// Helper to validate and round coordinates
const validateCoordinate = (value: number | string | null | undefined): number | null => {
  if (value === null || value === undefined) return null
  const num = typeof value === 'string' ? parseFloat(value) : value
  if (isNaN(num)) return null
  // Round to 6 decimal places (≈0.1 meter precision)
  return Math.round(num * 1e6) / 1e6
}

// Helper to get today's date in YYYY-MM-DD format
const getTodayDate = (): string => {
  const today = new Date()
  const year = today.getFullYear()
  const month = String(today.getMonth() + 1).padStart(2, '0')
  const day = String(today.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

// Helper to add days to a date string (YYYY-MM-DD format)
const addDaysToDate = (dateString: string, days: number): string => {
  const date = new Date(dateString)
  date.setDate(date.getDate() + days)
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

export default function CreateTravelPlan() {
  const [teams, setTeams] = useState<Team[]>([])
  const [seasons, setSeasons] = useState<Season[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [itineraryFile, setItineraryFile] = useState<File | null>(null)
  const [orgContacts, setOrgContacts] = useState<Record<TravelContactCategoryOrg, OrganizationTravelContactRow | null> | null>(null)
  
  const t = useT()

  // UI State for Overrides
  const [destinationOverride, setDestinationOverride] = useState(false)
  
  const isMountedRef = useRef(true)
  // Refs to track previous place IDs to detect manual clearing
  const prevDestinationPlaceIdRef = useRef<string | null>(null)
  const prevVenuePlaceIdRef = useRef<string | null>(null)
  const prevHotelPlaceIdRef = useRef<string | null>(null)

  const { context, isReady, isLoading: contextLoading } = useUserContext()
  const navigate = useNavigate()

  // Debug logging
  useEffect(() => {
    console.log('[CreateTravelPlan] State:', { 
      isReady, 
      contextLoading, 
      loading, 
      hasContext: !!context,
      orgId: context?.orgId,
      userId: context?.userId 
    })
  }, [isReady, contextLoading, loading, context])

  const { control, handleSubmit, watch, setValue, formState: { errors } } = useForm<TravelFormData>({
    defaultValues: { 
      team_id: '', season_id: '', title: '', location: '', 
      destination_city: '', destination_state: '', destination_state_code: '', destination_country: '',
      destination_place_id: null, destination_lat: null, destination_lng: null,
      start_date: '', end_date: '', 
      venue_name: '', venue_address: '', venue_place_id: null, venue_lat: null, venue_lng: null,
      hotel_name: '', hotel_address: '', hotel_place_id: null, hotel_lat: null, hotel_lng: null,
      hotel_phone: '', hotel_confirmation: '', 
      maps_url: '', notes: '',
      contacts: TRAVEL_CONTACT_CATEGORIES.map(cat => ({
        category: cat,
        is_custom: false,
        first_name: '',
        last_name: '',
        email: '',
        phone: '',
      }))
    },
  })

  const watchTeamId = watch('team_id')
  const watchSeasonId = watch('season_id')
  
  // Watch inputs to detect clearing
  const watchLocation = watch('location')
  const watchVenueName = watch('venue_name')
  const watchHotelName = watch('hotel_name')
  const watchDestinationPlaceId = watch('destination_place_id')
  const watchVenuePlaceId = watch('venue_place_id')
  const watchHotelPlaceId = watch('hotel_place_id')

  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
    }
  }, [])

  // Handle clearing of places when input text is cleared
  useEffect(() => {
    // Destination
    if (prevDestinationPlaceIdRef.current && !watchLocation && watchDestinationPlaceId) {
      if (isMountedRef.current) {
        setValue('destination_place_id', null)
        setValue('destination_city', '')
        setValue('destination_state', '')
        setValue('destination_state_code', '')
        setValue('destination_country', '')
        setValue('destination_lat', null)
        setValue('destination_lng', null)
        setDestinationOverride(false)
      }
      prevDestinationPlaceIdRef.current = null
    } else if (watchDestinationPlaceId) {
      prevDestinationPlaceIdRef.current = watchDestinationPlaceId
    }

    // Venue
    if (prevVenuePlaceIdRef.current && !watchVenueName && watchVenuePlaceId) {
      if (isMountedRef.current) {
        setValue('venue_place_id', null)
        setValue('venue_address', '')
        setValue('venue_lat', null)
        setValue('venue_lng', null)
      }
      prevVenuePlaceIdRef.current = null
    } else if (watchVenuePlaceId) {
      prevVenuePlaceIdRef.current = watchVenuePlaceId
    }

    // Hotel
    if (prevHotelPlaceIdRef.current && !watchHotelName && watchHotelPlaceId) {
      if (isMountedRef.current) {
        setValue('hotel_place_id', null)
        setValue('hotel_address', '')
        setValue('hotel_lat', null)
        setValue('hotel_lng', null)
        // Also clear derived hotel fields if they were auto-populated
        setValue('hotel_phone', '')
        setValue('maps_url', '')
      }
      prevHotelPlaceIdRef.current = null
    } else if (watchHotelPlaceId) {
      prevHotelPlaceIdRef.current = watchHotelPlaceId
    }
  }, [watchLocation, watchVenueName, watchHotelName, watchDestinationPlaceId, watchVenuePlaceId, watchHotelPlaceId, setValue])

  const fetchTeams = useCallback(async () => {
    console.log('[CreateTravelPlan] fetchTeams called:', { isReady, hasContext: !!context, orgId: context?.orgId })
    
    if (!isReady || !context) {
      console.log('[CreateTravelPlan] fetchTeams early return - not ready')
      // Set loading to false even if we can't fetch - prevents infinite loading
      if (isMountedRef.current) {
        setLoading(false)
      }
      return
    }
    
    try {
      console.log('[CreateTravelPlan] Fetching teams...')
      const { data, error } = await getTeams(context, { activeOnly: true })
      console.log('[CreateTravelPlan] Teams response:', { data, error })
      if (!isMountedRef.current) return
      
      if (!error && data) {
        const teamList = data.map(t => ({ id: t.id, name: t.name }))
        setTeams(teamList)
      }
    } catch (err) {
      if (isMountedRef.current) {
        console.error('Error fetching teams:', err)
      }
    } finally {
      if (isMountedRef.current) {
        console.log('[CreateTravelPlan] Setting loading to false')
        setLoading(false)
      }
    }
  }, [context, isReady])

  const fetchSeasons = useCallback(async (teamId: string) => {
    if (!isReady || !teamId || !context) return
    
    try {
      const { data, error } = await getTeamDetails(context, teamId)
      if (!isMountedRef.current) return
      
      if (!error && data?.seasons) {
        setSeasons(data.seasons.map(s => ({ id: s.id, name: s.name })))
      }
    } catch (err) {
      if (isMountedRef.current) {
        console.error('Error fetching seasons:', err)
      }
    }
  }, [context, isReady])

  // Fetch org contacts for preview
  useEffect(() => {
    if (isReady && context) {
        getOrganizationTravelContacts(context).then(res => {
            if (res.data) setOrgContacts(res.data)
        })
    }
  }, [isReady, context])

  useEffect(() => { 
    console.log('[CreateTravelPlan] useEffect triggered:', { isReady, hasContext: !!context, orgId: context?.orgId })
    if (isReady && context) {
      fetchTeams()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isReady, context?.orgId]) // Only re-run when orgId changes, not on every context object change

  // Handle case where context never becomes ready - stop loading state
  useEffect(() => {
    const timeout = setTimeout(() => {
      if (loading && !isReady) {
        console.warn('[CreateTravelPlan] Context not ready after timeout, stopping loader')
        setLoading(false)
      }
    }, 5000) // 5 second timeout
    return () => clearTimeout(timeout)
  }, [loading, isReady])

  // Auto-select team if there's only one and none is selected
  useEffect(() => {
    if (teams.length === 1 && !watchTeamId && isReady && context) {
      console.log('[CreateTravelPlan] Auto-selecting single team:', teams[0].id)
      setValue('team_id', teams[0].id, { shouldValidate: false })
    }
  }, [teams, watchTeamId, isReady, context, setValue])

  // Fetch seasons when team is selected
  useEffect(() => { 
    if (watchTeamId && isReady && context) { 
      console.log('[CreateTravelPlan] Team selected, fetching seasons:', watchTeamId)
      fetchSeasons(watchTeamId)
      setValue('season_id', '')
    }
    // Only depend on watchTeamId, isReady, and context - fetchSeasons is stable when these don't change
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [watchTeamId, isReady, context])

  // Auto-select season if there's only one and none is selected
  useEffect(() => {
    if (seasons.length === 1 && !watchSeasonId && isReady && context) {
      console.log('[CreateTravelPlan] Auto-selecting single season:', seasons[0].id)
      setValue('season_id', seasons[0].id, { shouldValidate: false })
    }
  }, [seasons, watchSeasonId, isReady, context, setValue])

  const onSubmit = async (data: TravelFormData) => {
    if (!isMountedRef.current) return
    setSaving(true)
    setError(null)
    
    try {
      // Map form data to DTO
      const createData: CreateTravelPlanDTO = {
        team_id: data.team_id,
        season_id: data.season_id,
        title: data.title,
        location: data.location,
        destination_city: data.destination_city || null,
        destination_state: data.destination_state || null,
        destination_state_code: data.destination_state_code || null,
        destination_country: data.destination_country || null,
        destination_place_id: data.destination_place_id || null,
        destination_lat: data.destination_lat || null,
        destination_lng: data.destination_lng || null,
        start_date: data.start_date,
        end_date: data.end_date,
        venue_name: data.venue_name || null,
        venue_address: data.venue_address || null,
        venue_place_id: data.venue_place_id || null,
        venue_lat: data.venue_lat || null,
        venue_lng: data.venue_lng || null,
        hotel_name: data.hotel_name || null,
        hotel_address: data.hotel_address || null,
        hotel_place_id: data.hotel_place_id || null,
        hotel_lat: data.hotel_lat || null,
        hotel_lng: data.hotel_lng || null,
        hotel_phone: data.hotel_phone || null,
        hotel_confirmation: data.hotel_confirmation || null,
        maps_url: data.maps_url || null,
        notes: data.notes || null,
        itinerary_file: itineraryFile,
      }

      const { data: createdPlan, error: createError } = await createTravelPlan(context, createData)

      if (!isMountedRef.current) return

      if (createError || !createdPlan) {
        const errorMessage = createError?.message || 'Failed to create travel plan'
        setError(errorMessage)
        showError(errorMessage)
        return
      }

      
      // Save travel contacts
      if (data.contacts && createdPlan?.id) {
         await upsertTravelPlanContacts(
             context, 
             createdPlan.id, 
             data.contacts.map(c => ({
                 category: c.category as TravelContactCategory,
                 is_custom: c.is_custom,
                 first_name: c.first_name,
                 last_name: c.last_name,
                 email: c.email,
                 phone: c.phone
             }))
         )
      }

      showSuccess('Travel plan created successfully!')
      if (isMountedRef.current) {
        navigate('/admin/travel')
      }
    } catch (err: unknown) { 
      if (!isMountedRef.current) return
      const errorMessage = getErrorMessage(err) || 'Failed to create travel plan'
      setError(errorMessage)
      showError(errorMessage)
    } finally { 
      if (isMountedRef.current) {
        setSaving(false)
      }
    }
  }

  if (loading) return <div className="oa-skeleton" style={{ height: '500px' }} />

  if (!isReady || !context?.orgId) {
    return (
      <div className="oa-root">
        <AdminPageHeader 
          title="Create Travel Plan" 
          breadcrumbs={[
            { label: 'Travel Plans', path: '/admin/travel' },
            { label: 'Create Travel Plan' },
          ]}
        />
        <Card>
          <div className="oa-text-center oa-p-8">
            <p className="oa-text-danger">Unable to load organization context. Please make sure you have an organization selected.</p>
            <OrgAdminButton variant="primary" onClick={() => navigate('/admin/travel')} className="oa-mt-4">Back to Travel Plans</OrgAdminButton>
          </div>
        </Card>
      </div>
    )
  }

  return (
    <div className="oa-root">
      <AdminPageHeader 
        title="Create Travel Plan" 
        subtitle={t('admin.travel.createSubtitle' as TranslationKey)}
        breadcrumbs={[
          { label: 'Travel Plans', path: '/admin/travel' },
          { label: 'Create Travel Plan' },
        ]}
      />
      <div className="oa-form-container">
        <Card>
          <form onSubmit={handleSubmit(onSubmit)}>
            {error && <div className="oa-card oa-mb-4 oa-text-danger" style={{ background: 'var(--oa-danger-bg)', border: 'none' }}>{error}</div>}
            
            <div className="oa-form-grid oa-form-grid-2 oa-gap-4 oa-mb-4">
              <Controller name="team_id" control={control} rules={{ required: 'Team is required' }} render={({ field }) => <Select {...field} label="Team" options={teams.map(t => ({value:t.id, label:t.name}))} required />} />
              <Controller name="season_id" control={control} rules={{ required: 'Season is required' }} render={({ field }) => <Select {...field} label="Season" options={seasons.map(s => ({value:s.id, label:s.name}))} required disabled={!watchTeamId} />} />
            </div>

            <div className="oa-mb-4">
              <Controller name="title" control={control} rules={{ required: 'Title is required' }} render={({ field }) => <Input {...field} label="Trip Title" required />} />
            </div>

            <div className="oa-mb-4">
              <Controller 
                name="location" 
                control={control} 
                rules={{ 
                    required: 'Location is required',
                    validate: (_value, formValues) => {
                        // User can enter text manually OR select a place.
                        // If they selected a place (place_id exists), we should have coordinates.
                        // If no place_id, we accept just text (manual entry fallback)
                        if (formValues.destination_place_id && (!formValues.destination_lat || !formValues.destination_lng)) {
                            return 'Invalid location data. Please re-select from the list or enter manually.'
                        }
                        return true
                    }
                }} 
                render={({ field }) => (
                  <LocationAutocomplete
                    value={field.value || ''}
                    onInputChange={field.onChange}
                    onChange={(address: StructuredAddress, placeResult?: google.maps.places.PlaceResult) => {
                      startTransition(() => {
                        // 1. Set main text value
                        setValue('location', address.formatted_address, { shouldValidate: true, shouldDirty: true })
                        
                        // 2. Set derived fields
                        setValue('destination_place_id', address.place_id || null)
                        setValue('destination_city', address.city || '')
                        setValue('destination_state', address.state || '')
                        setValue('destination_country', address.country || '')
                        
                        // 3. Extract and set coordinates
                        setValue('destination_lat', validateCoordinate(address.latitude))
                        setValue('destination_lng', validateCoordinate(address.longitude))
                        
                        // 4. Extract state code from raw place result
                        const stateCode = extractStateCode(placeResult)
                        setValue('destination_state_code', stateCode)
                      })
                    }}
                    label="Location (city/state or details)"
                    placeholder="Search for a city or location..."
                    types={['geocode']} // Allow cities, regions, and addresses
                    required
                    error={errors.location?.message}
                  />
                )} 
              />
            </div>

            <div className="oa-form-grid oa-form-grid-2 oa-gap-4 oa-mb-4">
              {/* Destination City - Read Only with Override */}
              <Controller 
                name="destination_city" 
                control={control} 
                render={({ field }) => (
                  <div className="oa-form-group">
                      <label className="oa-label">Destination City</label>
                      {destinationOverride || !watchDestinationPlaceId ? (
                        <input {...field} className="oa-input" placeholder="City" style={{ minHeight: '44px' }} />
                      ) : (
                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', minHeight: '44px' }}>
                            <span className="oa-text-body">{field.value || '—'}</span>
                            <button 
                                type="button" 
                                className="oa-link-button" 
                                style={{ fontSize: '12px', minHeight: '44px', padding: '0 8px' }}
                                onClick={() => setDestinationOverride(true)}
                            >
                                Override
                            </button>
                        </div>
                      )}
                  </div>
                )} 
              />
              
              {/* Destination State - Read Only with Override */}
              <Controller 
                name="destination_state" 
                control={control} 
                render={({ field }) => (
                  <div className="oa-form-group">
                      <label className="oa-label">Destination State</label>
                      {destinationOverride || !watchDestinationPlaceId ? (
                        <input {...field} className="oa-input" placeholder="State/Province" style={{ minHeight: '44px' }} />
                      ) : (
                        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', minHeight: '44px' }}>
                            <span className="oa-text-body">{field.value || '—'}</span>
                            {destinationOverride && (
                                <button type="button" onClick={() => setDestinationOverride(false)} style={{ minHeight: '44px', padding: '0 8px' }}>Cancel</button>
                            )}
                        </div>
                      )}
                  </div>
                )} 
              />
              
              <Controller 
                name="start_date" 
                control={control} 
                rules={{ required: 'Start date is required' }} 
                render={({ field }) => (
                  <DatePicker 
                    {...field} 
                    label="Start Date" 
                    required 
                    min={getTodayDate()}
                  />
                )} 
              />
              <Controller 
                name="end_date" 
                control={control} 
                rules={{ 
                  required: 'End date is required',
                  validate: (value) => {
                    const startDate = watch('start_date')
                    if (startDate && value) {
                      const minEndDate = addDaysToDate(startDate, 1)
                      if (value < minEndDate) {
                        return 'End date must be at least one day after start date'
                      }
                    }
                    return true
                  }
                }} 
                render={({ field, fieldState }) => {
                  const startDate = watch('start_date')
                  // Minimum end date is start date + 1 day, or today + 1 if no start date
                  const minEndDate = startDate 
                    ? addDaysToDate(startDate, 1)
                    : addDaysToDate(getTodayDate(), 1)
                  
                  return (
                    <DatePicker 
                      {...field} 
                      label="End Date" 
                      required 
                      min={minEndDate}
                      error={fieldState.error?.message}
                    />
                  )
                }} 
              />
            </div>

            <h3 className="oa-h3 oa-mb-4 oa-mt-6">VENUE & HOTEL</h3>
            <div className="oa-grid oa-grid-2 oa-gap-4 oa-mb-4">
              <Controller 
                name="venue_name" 
                control={control} 
                rules={{
                    // Optional field, but if place selected, validate coordinates often implies good data
                    validate: (_value, formValues) => {
                        if (formValues.venue_place_id && (!formValues.venue_lat || !formValues.venue_lng)) {
                             // This is a soft warning really, maybe we don't block
                             // But it's good to ensure data integrity
                             console.warn('Venue place selected but coordinates missing')
                        }
                        return true
                    }
                }}
                render={({ field }) => (
                    <LocationAutocomplete
                        value={field.value || ''}
                        onInputChange={field.onChange}
                        onChange={(address: StructuredAddress, placeResult?: google.maps.places.PlaceResult) => {
                            startTransition(() => {
                                // Use place name from PlaceResult if it exists and is not the same as the address
                                // If no name is available, leave it empty so user can enter a proper name
                                const placeName = placeResult?.name && placeResult.name !== address.formatted_address
                                    ? placeResult.name
                                    : ''

                                setValue('venue_name', placeName, { shouldValidate: true, shouldDirty: true })
                                setValue('venue_address', address.formatted_address)
                                setValue('venue_place_id', address.place_id || null)
                                setValue('venue_lat', validateCoordinate(address.latitude))
                                setValue('venue_lng', validateCoordinate(address.longitude))
                                
                                // Update the input display to show the place name (not address)
                                if (placeName) {
                                    field.onChange(placeName)
                                }
                            })
                        }}
                        label="Venue Name"
                        placeholder="Search for venue..."
                        types={['establishment', 'geocode']}
                    />
                )} 
              />
              
              <Controller
                name="venue_address"
                control={control}
                render={({ field }) => <Input {...field} label="Venue Address" />}
              />
              
              <Controller 
                name="hotel_name" 
                control={control} 
                render={({ field }) => (
                    <LocationAutocomplete
                        value={field.value || ''}
                        onInputChange={field.onChange}
                        onChange={(address: StructuredAddress, placeResult?: google.maps.places.PlaceResult) => {
                            startTransition(() => {
                                // Use place name from PlaceResult if it exists and is not the same as the address
                                // If no name is available, leave it empty so user can enter a proper name
                                const placeName = placeResult?.name && placeResult.name !== address.formatted_address
                                    ? placeResult.name
                                    : ''
                                
                                setValue('hotel_name', placeName, { shouldValidate: true, shouldDirty: true })
                                setValue('hotel_address', address.formatted_address)
                                setValue('hotel_place_id', address.place_id || null)
                                setValue('hotel_lat', validateCoordinate(address.latitude))
                                setValue('hotel_lng', validateCoordinate(address.longitude))
                                
                                // Update the input display to show the place name (not address)
                                if (placeName) {
                                    field.onChange(placeName)
                                }
                                
                                // Extract phone if available (PlaceResult might have it if requested)
                                if (placeResult?.formatted_phone_number) {
                                    setValue('hotel_phone', placeResult.formatted_phone_number)
                                }
                                
                                // Generate map URL
                                if (placeResult?.url) {
                                    setValue('maps_url', placeResult.url)
                                }
                            })
                        }}
                        label="Hotel Name"
                        placeholder="Search for hotel..."
                        types={['lodging']}
                    />
                )} 
              />
              
              <Controller
                name="hotel_address"
                control={control}
                render={({ field }) => <Input {...field} label="Hotel Address" />}
              />
              
              <Controller name="hotel_confirmation" control={control} render={({ field }) => <Input {...field} label="Hotel Confirmation" />} />
            </div>



            <h3 className="oa-h3 oa-mb-4">ITINERARY FILE</h3>
            <div className="oa-mb-6">
              <FileUpload
                label="Itinerary File"
                value={itineraryFile}
                onFileSelect={setItineraryFile}
                buttonText="Choose file"
                replaceText="Replace file"
                accept=".pdf,application/pdf"
                maxSize={10 * 1024 * 1024}
                fullWidth
              />
            </div>

            <div className="oa-mb-8">
              <textarea className="oa-input oa-textarea" placeholder="Trip Notes..." style={{ minHeight: '120px' }} value={watch('notes')} onChange={e => setValue('notes', e.target.value)} />
              <div className="oa-label">Notes</div>
            </div>

            <PlanTravelContacts 
                control={control} 
                name="contacts" 
                orgContacts={orgContacts} 
            />

            <div className="oa-form-actions">
              <OrgAdminButton variant="primary" onClick={() => navigate('/admin/travel')} disabled={saving} className="w-full sm:w-auto">Cancel</OrgAdminButton>
              <Button type="submit" loading={saving} disabled={saving} className="oa-form-submit-btn w-full sm:w-auto">Create Draft Plan</Button>
            </div>
          </form>
        </Card>
      </div>
    </div>
  )
}

/**
 * EditAthlete Component
 *
 * Admin version of athlete editing for org admins and coaches.
 * Allows updating athlete information, sports preferences, and profile photo.
 */

import { useState, useEffect, useRef, useCallback, memo } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { AdminPageHeader, Card, Input, Button, Select, DatePicker, ErrorState } from '../../components/admin'
import AdminLoadingSpinner from '../../components/admin/AdminLoadingSpinner'
import { useUserContext } from '../../hooks/useUserContext'
import { useT } from '../../i18n/useI18n'
import { getAthleteById, updateAthlete } from '../../data/services/familyService'
import { updateAthleteSports } from '../../data/services/athleteSportsService'
import { getSystemSports } from '../../data/services/sportsService'
import { AthletePhotoUpload } from '../../components/admin/AthletePhotoUpload'
import { uploadAthletePhoto, deleteAthletePhoto, getAthletePhotoUrl } from '../../data/services/athletePhotoService'
import { validatePhoneFormat } from '../../utils/phoneValidation'
import { validateGuardianEmail } from '../../data/services/guardianService'
import type { Gender, UpdateAthleteDTO } from '../../types/family'
import type { Sport } from '../../data/types/organization'
import { AlertCircle } from 'lucide-react'
import { getLink } from '../../utils/routes'
import '../../styles/orgAdmin.css'

type SportType = 'plays' | 'interested'

// Memoized Sport Item Component
const SportItem = memo(({ 
    sport, 
    selectedSports, 
    onToggle 
}: { 
    sport: Sport
    selectedSports: Array<{ sport_id: string; sport_type: SportType }>
    onToggle: (sportId: string, sportType: SportType) => void
}) => {
    const isPlaysSelected = selectedSports.some(s => s.sport_id === sport.id && s.sport_type === 'plays')
    const isInterestedSelected = selectedSports.some(s => s.sport_id === sport.id && s.sport_type === 'interested')

    return (
        <div className="flex items-center justify-between p-3 bg-gray-50 dark:bg-gray-900/30 rounded-lg border border-gray-200 dark:border-gray-700">
            <span className="text-sm font-medium text-gray-900 dark:text-white">{sport.name}</span>
            <div className="flex gap-4">
                <label className="flex items-center gap-2 cursor-pointer">
                    <input
                        type="checkbox"
                        checked={isPlaysSelected}
                        onChange={() => onToggle(sport.id, 'plays')}
                        className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                    />
                    <span className="text-sm text-gray-700 dark:text-gray-300">Plays</span>
                </label>
                <label className="flex items-center gap-2 cursor-pointer">
                    <input
                        type="checkbox"
                        checked={isInterestedSelected}
                        onChange={() => onToggle(sport.id, 'interested')}
                        className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                    />
                    <span className="text-sm text-gray-700 dark:text-gray-300">Interested</span>
                </label>
            </div>
        </div>
    )
})

SportItem.displayName = 'SportItem'

const initialFormData = {
    first_name: '',
    last_name: '',
    date_of_birth: '',
    gender: '' as Gender | '',
    preferred_name: '',
    jersey_number: '',
    medical_notes: '',
    allergies: '',
    emergency_contact_name: '',
    emergency_contact_phone: '',
    phone: '',  // Athlete phone number
    email: ''   // Athlete email address
}

export default function EditAthlete() {
    const navigate = useNavigate()
    const { id: athleteId } = useParams<{ id: string }>()
    const { context, isReady } = useUserContext()
    const t = useT()
    const [loading, setLoading] = useState(true)
    const [isSubmitting, setIsSubmitting] = useState(false)
    const [error, setError] = useState<Error | null>(null)
    const [validationErrors, setValidationErrors] = useState<string[]>([])
    const [notFound, setNotFound] = useState(false)

    // Form state
    const [formData, setFormData] = useState(initialFormData)

    // Photo state
    const [photoFile, setPhotoFile] = useState<File | null>(null)
    const [photoUrl, setPhotoUrl] = useState<string | null>(null)
    const [photoPath, setPhotoPath] = useState<string | null>(null)
    const [photoError, setPhotoError] = useState<string | null>(null)
    const [photoRemoved, setPhotoRemoved] = useState(false)

    // Sports state
    const [sports, setSports] = useState<Sport[]>([])
    const [isLoadingSports, setIsLoadingSports] = useState(false)
    const [selectedSports, setSelectedSports] = useState<Array<{ sport_id: string; sport_type: SportType }>>([])

    // Refs for race condition and memory leak prevention
    const requestIdRef = useRef(0)
    const isMountedRef = useRef(true)
    const isLoadingSportsRef = useRef(false)
    const redirectTimeoutRef = useRef<NodeJS.Timeout | null>(null)

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            isMountedRef.current = false
            if (redirectTimeoutRef.current) {
                clearTimeout(redirectTimeoutRef.current)
            }
        }
    }, [])

    // Reset form state and load athlete data when athleteId changes
    useEffect(() => {
        if (!isReady || !athleteId || !context.orgId) return

        // Reset all form state
        setFormData(initialFormData)
        setSelectedSports([])
        setValidationErrors([])
        setError(null)
        setNotFound(false)
        setLoading(true)
        setPhotoFile(null)
        setPhotoUrl(null)
        setPhotoPath(null)
        setPhotoError(null)
        setPhotoRemoved(false)

        const currentRequestId = ++requestIdRef.current

        // Load athlete data
        getAthleteById(context, athleteId)
            .then(({ data, error: fetchError }) => {
                // Only update if this is the latest request and component is mounted
                if (currentRequestId !== requestIdRef.current || !isMountedRef.current) return

                if (fetchError) {
                    setError(fetchError)
                    setLoading(false)
                    return
                }

                if (!data) {
                    setNotFound(true)
                    setLoading(false)
                    // Auto-redirect after 3 seconds
                    redirectTimeoutRef.current = setTimeout(() => {
                        if (isMountedRef.current) {
                            navigate(getLink('admin.athletes.list'))
                        }
                    }, 3000)
                    return
                }

                // Pre-populate form with athlete data - include all form fields including phone/email
                setFormData({
                    first_name: data.first_name || '',
                    last_name: data.last_name || '',
                    date_of_birth: data.date_of_birth || '',
                    gender: data.gender || '',
                    preferred_name: data.preferred_name || '',
                    jersey_number: data.jersey_number || '',
                    medical_notes: data.medical_notes || '',
                    allergies: data.allergies || '',
                    emergency_contact_name: data.emergency_contact_name || '',
                    emergency_contact_phone: data.emergency_contact_phone || '',
                    phone: data.phone || '',  // NEW - explicit mapping
                    email: data.email || ''   // NEW - explicit mapping
                })

                // Load photo if exists (using new photo system)
                if (data.has_profile_photo && data.org_id && data.id) {
                    setPhotoPath('exists') // Flag that photo exists
                    // Get public URL (no signed URL needed)
                    const url = getAthletePhotoUrl(data.org_id, data.id, '512')
                    setPhotoUrl(url)
                } else {
                    setPhotoPath(null)
                    setPhotoUrl(null)
                }

                // Pre-populate sports
                if (data.sports && data.sports.length > 0) {
                    setSelectedSports(data.sports.map(s => ({
                        sport_id: s.sport_id,
                        sport_type: s.sport_type
                    })))
                }

                setLoading(false)
            })
            .catch((err) => {
                if (currentRequestId === requestIdRef.current && isMountedRef.current) {
                    console.error('Error loading athlete:', err)
                    setError(err instanceof Error ? err : new Error('Failed to load athlete'))
                    setLoading(false)
                }
            })
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [athleteId, isReady])

    // Load system sports on mount
    useEffect(() => {
        if (!isReady || isLoadingSportsRef.current) return

        isLoadingSportsRef.current = true
        setIsLoadingSports(true)

        getSystemSports()
            .then(({ data, error }) => {
                if (error) {
                    console.error('Error loading sports:', error)
                    return
                }
                if (isMountedRef.current && data) {
                    setSports(data)
                }
            })
            .finally(() => {
                if (isMountedRef.current) {
                    setIsLoadingSports(false)
                    isLoadingSportsRef.current = false
                }
            })
    }, [isReady])

    // Memoized toggle handler for sports
    const handleSportToggle = useCallback((sportId: string, sportType: SportType) => {
        setSelectedSports(prev => {
            const exists = prev.some(s => s.sport_id === sportId && s.sport_type === sportType)
            if (exists) {
                return prev.filter(s => !(s.sport_id === sportId && s.sport_type === sportType))
            } else {
                return [...prev, { sport_id: sportId, sport_type: sportType }]
            }
        })
    }, [])

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()

        // Validate form
        const errors: string[] = []

        if (!formData.first_name.trim()) {
            errors.push('First name is required.')
        }
        if (!formData.last_name.trim()) {
            errors.push('Last name is required.')
        }
        if (!formData.date_of_birth) {
            errors.push('Date of birth is required.')
        }

        // Date of birth validation
        if (formData.date_of_birth) {
            const dob = new Date(formData.date_of_birth)
            const today = new Date()
            const age = today.getFullYear() - dob.getFullYear()

            if (dob > today) {
                errors.push('Date of birth must be in the past.')
            } else if (age > 120) {
                errors.push('Date of birth must be reasonable (not more than 120 years ago).')
            }
        }

        // Phone validation - only if provided
        if (formData.phone.trim()) {
            const phoneValidation = validatePhoneFormat(formData.phone.trim())
            if (!phoneValidation.valid) {
                errors.push(phoneValidation.error || 'Invalid phone number')
            }
        }

        // Email validation - only if provided
        if (formData.email.trim()) {
            if (!validateGuardianEmail(formData.email.trim())) {
                errors.push('Invalid email address')
            }
        }

        if (errors.length > 0) {
            setValidationErrors(errors)
            return
        }

        if (!athleteId || !context.orgId) {
            setError(new Error('Missing required information. Please refresh and try again.'))
            return
        }

        setIsSubmitting(true)
        setError(null)
        setValidationErrors([])

        try {
            // Handle photo upload/removal
            // If photo was removed
            if (photoRemoved && photoPath) {
                // Delete from storage
                const { error: deleteError } = await deleteAthletePhoto(context, athleteId)
                if (deleteError) {
                    console.error('Error deleting photo:', deleteError)
                    setPhotoError(deleteError.message)
                    // Continue with update - photo deletion can be retried
                }
            }
            // If new photo was selected
            else if (photoFile) {
                // Upload new photo (includes resizing and DB update)
                const { error: uploadError } = await uploadAthletePhoto(
                    context,
                    athleteId,
                    photoFile
                )

                if (uploadError) {
                    // Log error but don't fail athlete update
                    console.error('Error uploading photo:', uploadError)
                    setPhotoError(uploadError.message)
                    // Continue with athlete update - photo can be fixed later
                } else {
                    setPhotoError(null)
                }
            }

            // Normalize form data before submission - include all updatable fields including phone/email
            // Note: photo_url is no longer stored - derived from storage
            const normalizedData: UpdateAthleteDTO = {
                first_name: formData.first_name.trim(),
                last_name: formData.last_name.trim(),
                date_of_birth: formData.date_of_birth || undefined,
                gender: formData.gender || null,
                preferred_name: formData.preferred_name.trim() || null,
                jersey_number: formData.jersey_number.trim() || null,
                medical_notes: formData.medical_notes.trim() || null,
                allergies: formData.allergies.trim() || null,
                emergency_contact_name: formData.emergency_contact_name.trim() || null,
                emergency_contact_phone: formData.emergency_contact_phone.trim() || null,
                phone: formData.phone.trim() || null,  // NEW - explicit
                email: formData.email.trim() || null   // NEW - explicit
            }

            // Sequential updates: athlete first, then sports
            const { error: athleteError } = await updateAthlete(context, athleteId, normalizedData)
            if (athleteError) {
                // Check for constraint violation (database-level validation)
                if ((athleteError as any).code === '23514') { // CHECK constraint violation
                    const errorMessage = (athleteError as any).message || ''
                    if (errorMessage.includes('email')) {
                        setValidationErrors(['Invalid email format'])
                    } else if (errorMessage.includes('phone')) {
                        setValidationErrors(['Invalid phone number format'])
                    } else {
                        throw athleteError
                    }
                    setIsSubmitting(false)
                    return
                }
                throw athleteError
            }

            // Then update sports
            const { error: sportsError } = await updateAthleteSports(
              athleteId,
              context.orgId,
              selectedSports
            )
            if (sportsError) throw sportsError

            // Success - navigate back to athletes list
            navigate('/admin/athletes')
        } catch (err) {
            console.error('Error updating athlete:', err)
            setError(err instanceof Error ? err : new Error('Failed to update athlete'))
            setIsSubmitting(false)
        }
    }

    // Loading state
    if (!isReady || loading) {
        return <AdminLoadingSpinner />
    }

    // Not found or access denied
    if (notFound) {
        return (
            <div className="oa-root">
                <AdminPageHeader
                    title="Athlete Not Found"
                    subtitle="The athlete you're looking for doesn't exist or you don't have access."
                    breadcrumbs={[
                        { label: 'Organizations', path: getLink('admin.organization.structure') },
                        { label: 'Athletes', path: getLink('admin.athletes.list') },
                        { label: 'Edit Athlete', path: '#' }
                    ]}
                />
                <div className="oa-form-container">
                    <Card>
                        <div className="text-center py-12">
                            <p className="text-red-600 dark:text-red-400 font-bold mb-4">
                                Athlete not found or you don't have access.
                            </p>
                            <p className="text-gray-500 dark:text-gray-400 mb-6">
                                Redirecting to Athletes...
                            </p>
                            <Button variant="primary" onClick={() => navigate('/admin/athletes')}>
                                Back to Athletes
                            </Button>
                        </div>
                    </Card>
                </div>
            </div>
        )
    }

    return (
        <div className="oa-root">
            <AdminPageHeader
                title="Edit Athlete"
                subtitle={t('admin.athletes.editSubtitle')}
                breadcrumbs={[
                    { label: 'Organizations', path: getLink('admin.organization.structure') },
                    { label: 'Athletes', path: getLink('admin.athletes.list') },
                    { label: 'Edit Athlete', path: '#' }
                ]}
            />

            <div className="oa-form-container">
                <form onSubmit={handleSubmit}>
                    {error && (
                        <ErrorState
                            title="Update Failed"
                            message={error.message}
                            onRetry={() => setError(null)}
                        />
                    )}

                    {validationErrors.length > 0 && (
                        <Card className="mb-6">
                            <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                                <div className="flex items-start gap-3">
                                    <AlertCircle className="w-5 h-5 text-red-600 mt-0.5" />
                                    <div>
                                        <h3 className="text-sm font-semibold text-red-800 mb-2">
                                            Please fix the following errors:
                                        </h3>
                                        <ul className="list-disc list-inside space-y-1">
                                            {validationErrors.map((err, idx) => (
                                                <li key={idx} className="text-sm text-red-700">
                                                    {err}
                                                </li>
                                            ))}
                                        </ul>
                                    </div>
                                </div>
                            </div>
                        </Card>
                    )}

                    {/* Profile Photo */}
                    <Card className="mb-6">
                        <h2 className="oa-h2 oa-mb-6">Profile Photo</h2>
                        <AthletePhotoUpload
                            photoFile={photoFile}
                            photoUrl={photoUrl}
                            onPhotoSelect={(file) => {
                                setPhotoFile(file)
                                setPhotoRemoved(false)
                                setPhotoError(null)
                            }}
                            onPhotoRemove={() => {
                                setPhotoFile(null)
                                setPhotoUrl(null)
                                setPhotoRemoved(true)
                                setPhotoError(null)
                            }}
                            disabled={isSubmitting}
                            error={photoError}
                        />
                    </Card>

                    {/* Athlete Information */}
                    <Card>
                        <h2 className="oa-h2 oa-mb-6">Athlete Information</h2>

                        <div className="oa-form-grid oa-form-grid-2 oa-gap-4 oa-mb-4">
                            <Input
                                label="First Name"
                                value={formData.first_name}
                                onChange={(e) => setFormData({ ...formData, first_name: e.target.value })}
                                required
                            />
                            <Input
                                label="Last Name"
                                value={formData.last_name}
                                onChange={(e) => setFormData({ ...formData, last_name: e.target.value })}
                                required
                            />
                        </div>

                        <div className="oa-form-grid oa-form-grid-2 oa-gap-4 oa-mb-4">
                            <DatePicker
                                label="Date of Birth"
                                value={formData.date_of_birth}
                                onChange={(value) => setFormData({ ...formData, date_of_birth: value.target.value })}
                                required
                            />
                            <Select
                                label="Gender"
                                value={formData.gender}
                                onChange={(e) => setFormData({ ...formData, gender: e.target.value as Gender })}
                                options={[
                                    { value: '', label: 'Select...' },
                                    { value: 'male', label: 'Male' },
                                    { value: 'female', label: 'Female' },
                                    { value: 'other', label: 'Other/Prefer not to say' }
                                ]}
                            />
                        </div>

                        <div className="oa-mb-6">
                            <Input
                                label="Preferred Name / Goes By (Optional)"
                                value={formData.preferred_name}
                                onChange={(e) => setFormData({ ...formData, preferred_name: e.target.value })}
                                placeholder="e.g. Mike, Johnny, etc."
                            />
                        </div>

                        <div className="oa-mb-6">
                            <Input
                                label="Jersey Number (Optional)"
                                value={formData.jersey_number}
                                onChange={(e) => setFormData({ ...formData, jersey_number: e.target.value })}
                                placeholder="e.g. 23"
                            />
                        </div>

                        <div className="oa-form-grid oa-form-grid-2 oa-gap-4 oa-mb-6">
                            <Input
                                label="Phone Number (Optional)"
                                type="tel"
                                value={formData.phone}
                                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                                placeholder="(555) 123-4567"
                            />
                            <Input
                                label="Email Address (Optional)"
                                type="email"
                                value={formData.email}
                                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                placeholder="athlete@example.com"
                            />
                        </div>

                        <h3 className="oa-h3 oa-mt-8 oa-mb-4">Medical & Emergency</h3>

                        <div className="oa-mb-4">
                            <Input
                                label="Medical Notes (Optional)"
                                value={formData.medical_notes}
                                onChange={(e) => setFormData({ ...formData, medical_notes: e.target.value })}
                                placeholder="Any medical conditions coaches should know about"
                                multiple
                            />
                        </div>

                        <div className="oa-mb-4">
                            <Input
                                label="Allergies (Optional)"
                                value={formData.allergies}
                                onChange={(e) => setFormData({ ...formData, allergies: e.target.value })}
                                placeholder="List any allergies"
                            />
                        </div>

                        <div className="oa-form-grid oa-form-grid-2 oa-gap-4">
                            <Input
                                label="Emergency Contact Name (Optional)"
                                value={formData.emergency_contact_name}
                                onChange={(e) =>
                                    setFormData({ ...formData, emergency_contact_name: e.target.value })
                                }
                                placeholder="Contact name"
                            />
                            <Input
                                label="Emergency Contact Phone (Optional)"
                                value={formData.emergency_contact_phone}
                                onChange={(e) =>
                                    setFormData({ ...formData, emergency_contact_phone: e.target.value })
                                }
                                placeholder="(555) 123-4567"
                            />
                        </div>
                    </Card>

                    {/* Sports Interests */}
                    <Card className="mt-6">
                        <h2 className="oa-h2 oa-mb-2">Sports Interests</h2>
                        <p className="text-sm text-gray-600 mb-6">
                            Select sports this athlete plays or is interested in playing. This is optional.
                        </p>

                        {isLoadingSports ? (
                            <div className="flex justify-center py-8">
                                <div className="animate-spin rounded-full h-6 w-6 border-t-2 border-b-2 border-gray-900 dark:border-white"></div>
                            </div>
                        ) : sports.length === 0 ? (
                            <p className="text-sm text-gray-500 dark:text-gray-400">No sports available.</p>
                        ) : (
                            <div className="space-y-3">
                                {sports.map((sport) => (
                                    <SportItem
                                        key={sport.id}
                                        sport={sport}
                                        selectedSports={selectedSports}
                                        onToggle={handleSportToggle}
                                    />
                                ))}
                            </div>
                        )}
                    </Card>

                    {/* Submit Buttons */}
                    <div className="oa-form-actions mt-6">
                        <Button
                            type="button"
                            variant="ghost"
                            onClick={() => navigate(getLink('admin.athletes.list'))}
                            disabled={isSubmitting}
                            className="w-full sm:w-auto"
                        >
                            Cancel
                        </Button>
                        <Button type="submit" disabled={isSubmitting} className="oa-form-submit-btn w-full sm:w-auto">
                            {isSubmitting ? 'Saving...' : 'Save Changes'}
                        </Button>
                    </div>
                </form>
            </div>
        </div>
    )
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useForm, Controller } from 'react-hook-form'
import { startTransition } from 'react'
import { useQueryClient } from '@tanstack/react-query'

import { useUserContext } from '../../hooks/useUserContext'
import { useT } from '../../i18n/useI18n'
import { getTravelPlanById, updateTravelPlan, type UpdateTravelPlanDTO } from '../../data/services/travelService'
import { getErrorMessage } from '../../utils/errorUtils'
import { showSuccess, showError } from '../../utils/toast'
import { isValidUUID } from '../../utils/uuid'
import { 
  AdminPageHeader, 
  Card, 
  Button, 
  Input,
  DatePicker 
} from '../../components/admin'
import { OrgAdminButton } from '../../components/admin/OrgAdminButton'
import { LocationAutocomplete } from '../../components/common/LocationAutocomplete'
import { FileUpload } from '../../components/common/FileUpload'
import PlanTravelContacts from '../../components/admin/travel/PlanTravelContacts'
import { getOrganizationTravelContacts } from '../../data/services/organizationTravelContactsService'
import { TRAVEL_CONTACT_CATEGORIES, type TravelContactCategory, type OrganizationTravelContactRow, type TravelContactCategoryOrg } from '../../types/travelContacts'
import { getTravelPlanContacts, deleteTravelPlanContactsForPlan, insertTravelPlanContacts } from '../../data/services/travelService'
import '../../styles/orgAdmin.css'

interface TravelFormData { 
  title: string
  location: string
  destination_city: string
  destination_state: string
  start_date: string
  end_date: string
  venue_name: string
  venue_address: string
  venue_place_id: string
  venue_lat: number | ''
  venue_lng: number | ''
  hotel_name: string
  hotel_address: string
  hotel_phone: string
  hotel_confirmation: string
  maps_url: string
  notes: string
  contacts: {
    category: string
    is_custom: boolean
    first_name: string
    last_name: string
    email: string
    phone: string
  }[]
}

export default function EditTravelPlan() {
  const { id } = useParams<{ id: string }>()
  const componentIdRef = useRef(`EditTravelPlan-${Date.now()}-${Math.random()}`)
  const renderCountRef = useRef(0)
  const effectRunCountRef = useRef(0)
  const fetchPlanCountRef = useRef(0)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [itineraryFile, setItineraryFile] = useState<File | null>(null)
  const [isPastPlan, setIsPastPlan] = useState(false)
  const isMountedRef = useRef(true)

  const { context, isReady } = useUserContext()
  const t = useT()
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const [orgContacts, setOrgContacts] = useState<Record<TravelContactCategoryOrg, OrganizationTravelContactRow | null> | null>(null)

  renderCountRef.current++
  console.log(`[EditTravelPlan:${componentIdRef.current}] RENDER #${renderCountRef.current}`, {
    timestamp: new Date().toISOString(),
    id,
    isReady,
    contextOrgId: context?.orgId,
  })

  const defaultFormValues: TravelFormData = {
    title: '',
    location: '',
    destination_city: '',
    destination_state: '',
    start_date: '',
    end_date: '',
    venue_name: '',
    venue_address: '',
    venue_place_id: '',
    venue_lat: '',
    venue_lng: '',
    hotel_name: '',
    hotel_address: '',
    hotel_phone: '',
    hotel_confirmation: '',
    maps_url: '',
    notes: '',
    contacts: TRAVEL_CONTACT_CATEGORIES.map(cat => ({
      category: cat,
      is_custom: false,
      first_name: '',
      last_name: '',
      email: '',
      phone: '',
    })),
  }

  const { control, handleSubmit, reset, setValue, watch } = useForm<TravelFormData>({
    defaultValues: defaultFormValues,
  })

  const [hasFormData, setHasFormData] = useState(false)

  useEffect(() => {
    const mountTime = new Date().toISOString()
    console.log(`[EditTravelPlan:${componentIdRef.current}] MOUNT`, { timestamp: mountTime })
    isMountedRef.current = true
    return () => {
      const unmountTime = new Date().toISOString()
      console.log(`[EditTravelPlan:${componentIdRef.current}] UNMOUNT`, {
        timestamp: unmountTime,
        mountTime,
        renderCount: renderCountRef.current,
        effectRuns: effectRunCountRef.current,
        fetchPlanCalls: fetchPlanCountRef.current,
      })
      isMountedRef.current = false
    }
  }, [])

  const fetchPlan = useCallback(async () => {
    fetchPlanCountRef.current++
    const fetchId = fetchPlanCountRef.current
    const fetchStartTime = Date.now()
    console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} START`, {
      timestamp: new Date().toISOString(),
      id,
      isReady,
      contextOrgId: context?.orgId,
      isMounted: isMountedRef.current,
    })

    if (!isReady || !id) {
      console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Early return`, {
        reason: !isReady ? 'not ready' : 'no id',
      })
      return
    }

    if (!context) {
      if (isMountedRef.current) setLoading(false)
      return
    }

    // Validate UUID format
    if (!isValidUUID(id)) {
      console.warn(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Invalid UUID, navigating away`)
      if (isMountedRef.current) {
        navigate('/admin/travel')
      }
      return
    }
    
    if (!isMountedRef.current) {
      console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Aborted (unmounted)`)
      return
    }
    
    if (isMountedRef.current) {
      setLoading(true)
    }
    
    try {
      console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Calling getTravelPlanById`)
      const apiStartTime = Date.now()
      const { data, error } = await getTravelPlanById(context, id)
      const apiDuration = Date.now() - apiStartTime
      console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - getTravelPlanById completed`, {
        duration: `${apiDuration}ms`,
        hasData: !!data,
        hasError: !!error,
        errorMessage: error?.message,
      })
      
      if (!isMountedRef.current) {
        console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Aborted after API (unmounted)`)
        return
      }

      if (error || !data) {
        console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Error or no data, navigating away`)
        navigate('/admin/travel')
        return
      }

      // Fetch contacts
      const { data: contactsData, error: contactsError } = await getTravelPlanContacts(context, id)
      if (contactsError) {
          console.error('Error fetching plan contacts', contactsError)
      }

      console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Resetting form with data`)
      // Populate form with existing data
      reset({
        title: data.title,
        location: data.location,
        destination_city: data.destination_city ?? '',
        destination_state: data.destination_state ?? '',
        start_date: data.start_date,
        end_date: data.end_date,
        venue_name: data.venue_name ?? '',
        venue_address: data.venue_address ?? '',
        venue_place_id: data.venue_place_id ?? '',
        venue_lat: data.venue_lat ?? '',
        venue_lng: data.venue_lng ?? '',
        hotel_name: data.hotel_name ?? '',
        hotel_address: data.hotel_address ?? '',
        hotel_phone: data.hotel_phone ?? '',
        hotel_confirmation: data.hotel_confirmation ?? '',
        maps_url: data.maps_url ?? '',
        notes: data.notes ?? '',
        contacts: TRAVEL_CONTACT_CATEGORIES.map(cat => {
            const existing = contactsData?.[cat]
            return {
                category: cat,
                is_custom: existing?.is_custom ?? false,
                first_name: existing?.first_name || '',
                last_name: existing?.last_name || '',
                email: existing?.email || '',
                phone: existing?.phone || '',
            }
        })
      })
      setIsPastPlan(new Date(data.end_date) < new Date())
      if (isMountedRef.current) {
        setHasFormData(true)
        setError(null)
      }
    } catch (err) {
      if (!isMountedRef.current) return
      console.error(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - Caught error:`, err)
      setError(getErrorMessage(err) || 'Failed to load travel plan')
    } finally {
      const totalDuration = Date.now() - fetchStartTime
      console.log(`[EditTravelPlan:${componentIdRef.current}] fetchPlan #${fetchId} - COMPLETE`, {
        duration: `${totalDuration}ms`,
        isMounted: isMountedRef.current,
      })
      if (isMountedRef.current) {
        setLoading(false)
      }
    }
  }, [id, context.orgId, isReady, navigate, reset, context])
  
  // Fetch org contacts for preview
  useEffect(() => {
    if (isReady && context) {
        getOrganizationTravelContacts(context).then(res => {
            if (res.data) setOrgContacts(res.data)
        })
    }
  }, [isReady, context])

  useEffect(() => {
    effectRunCountRef.current++
    const effectId = effectRunCountRef.current
    console.log(`[EditTravelPlan:${componentIdRef.current}] Effect #${effectId} - Trigger fetchPlan`, {
      timestamp: new Date().toISOString(),
      isReady,
      id,
      isMounted: isMountedRef.current,
    })
    if (!isReady) {
      return
    }
    if (!id) {
      setLoading(false)
      navigate('/admin/travel', { replace: true })
      return
    }
    if (!isValidUUID(id)) {
      setLoading(false)
      navigate('/admin/travel', { replace: true })
      return
    }
    console.log(`[EditTravelPlan:${componentIdRef.current}] Effect #${effectId} - Calling fetchPlan`)
    fetchPlan()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isReady, id, navigate])

  const onSubmit = async (data: TravelFormData) => {
    const submitStartTime = Date.now()
    console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit START`, {
      timestamp: new Date().toISOString(),
      id,
      isMounted: isMountedRef.current,
    })

    if (!context) {
      setError('You must be signed in to save changes.')
      showError('You must be signed in to save changes.')
      return
    }

    if (!id || !isValidUUID(id)) {
      console.warn(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Invalid plan ID`)
      if (isMountedRef.current) {
        setError('Invalid plan ID')
      }
      return
    }

    if (!isMountedRef.current) {
      console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Aborted (unmounted)`)
      return
    }
    
    if (isMountedRef.current) {
      setSaving(true)
      setError(null)
    }
    
    try {
      // Map form data to DTO
      const updateData: UpdateTravelPlanDTO = {
        title: data.title,
        location: data.location,
        destination_city: data.destination_city || null,
        destination_state: data.destination_state || null,
        start_date: data.start_date,
        end_date: data.end_date,
        venue_name: data.venue_name || null,
        venue_address: data.venue_address || null,
        venue_place_id: data.venue_place_id || null,
        venue_lat: data.venue_lat !== '' && data.venue_lat != null && Number.isFinite(Number(data.venue_lat)) ? Number(data.venue_lat) : null,
        venue_lng: data.venue_lng !== '' && data.venue_lng != null && Number.isFinite(Number(data.venue_lng)) ? Number(data.venue_lng) : null,
        hotel_name: data.hotel_name || null,
        hotel_address: data.hotel_address || null,
        hotel_phone: data.hotel_phone || null,
        hotel_confirmation: data.hotel_confirmation || null,
        maps_url: data.maps_url || null,
        notes: data.notes || null,
        itinerary_file: itineraryFile,
      }

      console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Calling updateTravelPlan`)
      const apiStartTime = Date.now()
      const { data: updatedPlan, error: updateError } = await updateTravelPlan(context, id, updateData)
      const apiDuration = Date.now() - apiStartTime
      console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - updateTravelPlan completed`, {
        duration: `${apiDuration}ms`,
        hasData: !!updatedPlan,
        hasError: !!updateError,
        errorMessage: updateError?.message,
      })

      if (!isMountedRef.current) {
        console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Aborted after API (unmounted)`)
        return
      }

      if (updateError || !updatedPlan) {
        const errorMessage = updateError?.message || 'Failed to update travel plan'
        console.error(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Error:`, errorMessage)
        if (isMountedRef.current) {
          setError(errorMessage)
          showError(errorMessage)
        }
        
        // Handle optimistic locking error
        if (errorMessage.includes('modified by another user')) {
          console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Refreshing plan data due to optimistic locking error`)
          // Refresh plan data
          await fetchPlan()
        }
        return
      }

      // Save travel contacts (CRUD: delete all, then insert only custom overrides)
      if (data.contacts && id) {
        const { error: deleteError } = await deleteTravelPlanContactsForPlan(context, id)
        if (deleteError && isMountedRef.current) {
          setSaving(false)
          setError(deleteError.message)
          showError(deleteError.message)
          return
        }

        const customContacts = data.contacts.filter(
          c => c.is_custom && c.first_name?.trim() && c.last_name?.trim() && c.email?.trim()
        )
        if (customContacts.length > 0) {
          const { error: insertError } = await insertTravelPlanContacts(context, id, customContacts.map(c => ({
            category: c.category as TravelContactCategory,
            first_name: c.first_name!.trim(),
            last_name: c.last_name!.trim(),
            email: c.email!.trim(),
            phone: c.phone?.trim() || null,
          })))
          if (insertError && isMountedRef.current) {
            setSaving(false)
            setError(insertError.message)
            showError(insertError.message)
            return
          }
        }
      }

      console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Success, navigating away`)
      
      // Invalidate nearby amenities cache so it refetches with new location
      queryClient.invalidateQueries({ queryKey: ['nearbyAmenities'] })
      
      showSuccess('Travel plan updated successfully!')
      if (isMountedRef.current) {
        navigate('/admin/travel')
      }
    } catch (err: unknown) { 
      if (!isMountedRef.current) {
        console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Aborted during error handling (unmounted)`)
        return
      }
      console.error(`[EditTravelPlan:${componentIdRef.current}] onSubmit - Caught error:`, err)
      const errorMessage = getErrorMessage(err) || 'Failed to update travel plan'
      setError(errorMessage)
      showError(errorMessage)
    } finally {
      const totalDuration = Date.now() - submitStartTime
      console.log(`[EditTravelPlan:${componentIdRef.current}] onSubmit - COMPLETE`, {
        duration: `${totalDuration}ms`,
        isMounted: isMountedRef.current,
      })
      if (isMountedRef.current) {
        setSaving(false)
      }
    }
  }

  if (loading) {
    return <div className="oa-root"><div className="oa-skeleton" style={{ height: '500px' }} /></div>
  }

  if (error && !hasFormData) {
    return (
      <div className="oa-root">
        <AdminPageHeader
          title="Edit Travel Plan"
          subtitle={t('admin.travel.editSubtitle')}
          breadcrumbs={[
            { label: 'Travel Plans', path: '/admin/travel' },
            { label: 'Edit Travel Plan' },
          ]}
        />
        <div className="oa-form-container">
          <Card>
            <div className="oa-card oa-mb-4 oa-text-danger" style={{ background: 'var(--oa-danger-bg)', border: 'none' }}>{error}</div>
            <div className="oa-form-actions">
              <Button variant="secondary" onClick={() => navigate('/admin/travel')}>Back to Travel Plans</Button>
              <OrgAdminButton variant="primary" onClick={() => { setError(null); fetchPlan(); setLoading(true); }}>Retry</OrgAdminButton>
            </div>
          </Card>
        </div>
      </div>
    )
  }

  return (
    <div className="oa-root">
      <AdminPageHeader 
        title="Edit Travel Plan" 
        subtitle={t('admin.travel.editSubtitle')}
        breadcrumbs={[
          { label: 'Travel Plans', path: '/admin/travel' },
          { label: 'Edit Travel Plan' },
        ]}
      />
      <div className="oa-form-container">
        <Card>
          <form onSubmit={handleSubmit(onSubmit)}>
            <fieldset disabled={isPastPlan}>
            {error && <div className="oa-card oa-mb-4 oa-text-danger" style={{ background: 'var(--oa-danger-bg)', border: 'none' }}>{error}</div>}
            
            <div className="oa-mb-4">
              <Controller name="title" control={control} rules={{ required: 'Title is required' }} render={({ field }) => <Input {...field} label="Trip Title" required />} />
            </div>

            <div className="oa-mb-4">
              <Controller name="location" control={control} rules={{ required: 'Location is required' }} render={({ field }) => <Input {...field} label="Location (city/state or details)" required />} />
            </div>

            <div className="oa-form-grid oa-form-grid-2 oa-gap-4 oa-mb-4">
              <Controller name="destination_city" control={control} render={({ field }) => <Input {...field} label="Destination City" />} />
              <Controller name="destination_state" control={control} render={({ field }) => <Input {...field} label="Destination State" />} />
              <Controller 
                name="start_date" 
                control={control} 
                rules={{ required: 'Start date is required' }} 
                render={({ field }) => <DatePicker {...field} label="Start Date" required />} 
              />
              <Controller 
                name="end_date" 
                control={control} 
                rules={{ 
                  required: 'End date is required',
                  validate: (value) => {
                    const startDate = watch('start_date')
                    if (startDate && value && value < startDate) {
                      return 'End date must be on or after start date'
                    }
                    return true
                  }
                }} 
                render={({ field, fieldState }) => (
                  <DatePicker 
                    {...field} 
                    label="End Date" 
                    required 
                    error={fieldState.error?.message}
                  />
                )} 
              />
            </div>

            <h3 className="oa-h3 oa-mb-4 oa-mt-6">VENUE & HOTEL</h3>
            <div className="oa-form-grid oa-form-grid-2 oa-gap-4 oa-mb-4">
              <Controller
                name="venue_name"
                control={control}
                render={({ field }) => (
                  <LocationAutocomplete
                    value={field.value || ''}
                    onInputChange={field.onChange}
                    onChange={(address, placeResult) => {
                      startTransition(() => {
                        // Use place name from PlaceResult if it exists and is not the same as the address
                        const placeName = placeResult?.name && placeResult.name !== address.formatted_address
                            ? placeResult.name
                            : ''

                        setValue('venue_name', placeName, { shouldValidate: false, shouldDirty: true })
                        setValue('venue_address', address.formatted_address, { shouldValidate: false, shouldDirty: true })
                        // Persist venue coords/place_id so Nearby Amenities refetches for the new location
                        const loc = placeResult?.geometry?.location as { lat?: () => number; lng?: () => number } | { lat?: number; lng?: number } | undefined
                        const lat = loc && typeof (loc as { lat: () => number }).lat === 'function' ? (loc as { lat: () => number; lng: () => number }).lat() : (loc as { lat?: number })?.lat
                        const lng = loc && typeof (loc as { lng: () => number }).lng === 'function' ? (loc as { lat: () => number; lng: () => number }).lng() : (loc as { lng?: number })?.lng
                        setValue('venue_place_id', placeResult?.place_id ?? '', { shouldValidate: false, shouldDirty: true })
                        setValue('venue_lat', lat != null && Number.isFinite(lat) ? Number(lat) : '', { shouldValidate: false, shouldDirty: true })
                        setValue('venue_lng', lng != null && Number.isFinite(lng) ? Number(lng) : '', { shouldValidate: false, shouldDirty: true })
                        // Update the input display to show the place name (not address)
                        if (placeName) {
                          field.onChange(placeName)
                        }
                      })
                    }}
                    label="Venue Name"
                    placeholder="Search for venue..."
                    types={['establishment', 'geocode']}
                  />
                )}
              />
              <Controller name="venue_address" control={control} render={({ field }) => <Input {...field} label="Venue Address" />} />
              <Controller
                name="hotel_name"
                control={control}
                render={({ field }) => (
                  <LocationAutocomplete
                    value={field.value || ''}
                    onInputChange={field.onChange}
                    onChange={(address, placeResult) => {
                      startTransition(() => {
                        // Use place name from PlaceResult if it exists and is not the same as the address
                        const placeName = placeResult?.name && placeResult.name !== address.formatted_address
                            ? placeResult.name
                            : ''
                        
                        setValue('hotel_name', placeName, { shouldValidate: false, shouldDirty: true })
                        setValue('hotel_address', address.formatted_address, { shouldValidate: false, shouldDirty: true })
                        
                        // Update the input display to show the place name (not address)
                        if (placeName) {
                          field.onChange(placeName)
                        }
                      })
                    }}
                    label="Hotel Name"
                    placeholder="Search for hotel..."
                    types={['lodging']}
                  />
                )}
              />
              <Controller name="hotel_address" control={control} render={({ field }) => <Input {...field} label="Hotel Address" />} />
              <Controller name="hotel_confirmation" control={control} render={({ field }) => <Input {...field} label="Hotel Confirmation" />} />
            </div>

            <h3 className="oa-h3 oa-mb-4">ITINERARY FILE</h3>
            <div className="oa-mb-6">
              <FileUpload
                label="Itinerary File"
                value={itineraryFile}
                onFileSelect={setItineraryFile}
                buttonText="Choose file"
                replaceText="Replace file"
                accept=".pdf,application/pdf"
                maxSize={10 * 1024 * 1024}
                fullWidth
              />
            </div>

            <PlanTravelContacts 
                control={control} 
                name="contacts" 
                orgContacts={orgContacts} 
            />

            <div className="oa-form-actions">
              <OrgAdminButton variant="primary" onClick={() => navigate('/admin/travel')} disabled={saving} className="w-full sm:w-auto">Cancel</OrgAdminButton>
              <Button type="submit" loading={saving} disabled={isPastPlan || saving} className="oa-form-submit-btn w-full sm:w-auto">Save Changes</Button>
            </div>
            </fieldset>
          </form>
        </Card>
      </div>
    </div>
  )
}

import { useEffect, useState, useMemo, useRef, useCallback } from 'react'
import { Link, useNavigate, useParams } from 'react-router-dom'
import Lightbox from 'yet-another-react-lightbox'
import 'yet-another-react-lightbox/styles.css'
import { Button, Card, InlineNotice } from '@/components/platformAdmin'
import { AdminPageHeader } from '@/components/admin/AdminPageHeader'
import { ConfirmDialog } from '@/components/admin/ConfirmDialog'
import {
  deleteGallery,
  deletePhotos,
  getGalleryById,
  getAlbumsForGallery,
  getPhotosForGallery,
  getGalleryPhotoUrl,
  getGalleryPhotoCounts,
  moderatePhotos,
  type Gallery,
  type GalleryPhoto,
  type GalleryAlbum,
  type KeysetCursor,
} from '@/data/services/galleryService'
import { getMockGalleryById, getMockPhotosForGallery } from '@/data/fake/mockGalleries'
import { FAKE_DATA_DELAY_MS } from '@/data/config'
import { useUserContext } from '@/hooks/useUserContext'
import { useI18n } from '@/i18n/useI18n'
import { usePhotoFilters } from '@/hooks/usePhotoFilters'
import { PhotoFilterBar } from '@/components/gallery/PhotoFilterBar'
import { useInfinitePhotos } from '@/hooks/useInfinitePhotos'
import { buildPhotoQuery } from '@/utils/buildPhotoQuery'
import { USE_FAKE_DATA } from '@/data/config'
import { showError, showSuccess } from '@/utils/toast'
import { PhotoUploadZone } from '@/components/admin/galleries/PhotoUploadZone'
import { OrgAdminGalleryView } from '@/components/orgAdmin/OrgAdminGalleryView'
import { GalleryEditModal } from '@/components/admin/galleries/GalleryEditModal'
import { TaggingSlideout } from '@/components/gallery/TaggingSlideout'
import { BulkTaggingModal } from '@/components/gallery/BulkTaggingModal'
import { AlbumManager } from '@/components/gallery/AlbumManager'
import { getLink } from '@/utils/routes'
import '../../styles/orgAdmin.css'

const MAX_PHOTOS_PER_GALLERY = 25
const GRID_PAGE_SIZE_MOBILE = 30
const GRID_PAGE_SIZE_DESKTOP = 48

const getGridPageSize = () =>
  typeof window !== 'undefined' && window.innerWidth < 768 ? GRID_PAGE_SIZE_MOBILE : GRID_PAGE_SIZE_DESKTOP

export default function GalleryDetail() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { context } = useUserContext()
  const { t } = useI18n()

  

  const { filters, setFilters, clearFilters, setDensity } = usePhotoFilters({
    viewKey: `adminGallery:${id || 'unknown'}`,
    defaultSort: 'recent',
    allowedSorts: ['recent', 'oldest'],
    defaultStatus: 'all',
    allowedStatuses: ['all', 'approved', 'pending', 'rejected'],
    persistDensity: true,
  })
  void setDensity

  // Local state for immediate UI updates (debounced URL sync)
  const [localSearchQuery, setLocalSearchQuery] = useState(filters.q)

  const [gallery, setGallery] = useState<Gallery | null>(null)
  const [galleryFetched, setGalleryFetched] = useState(false)
  const [photoCounts, setPhotoCounts] = useState({ total: 0, pending: 0, approved: 0, rejected: 0 })
  const [photos, setPhotos] = useState<GalleryPhoto[]>([])
  const [loading, setLoading] = useState(true)
  const [loadingMore, setLoadingMore] = useState(false)
  const [editOpen, setEditOpen] = useState(false)
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid')
  const [albums, setAlbums] = useState<GalleryAlbum[]>([])
  const cursorRef = useRef<KeysetCursor | null>(null)
  const [hasMore, setHasMore] = useState(true)
  const [gridPageSize, setGridPageSize] = useState(getGridPageSize)
  const [rowsPerPage, setRowsPerPage] = useState(25)
  const [page, setPage] = useState(1)
  const [taggingPhoto, setTaggingPhoto] = useState<GalleryPhoto | null>(null)
  const [taggingPhotoIndex, setTaggingPhotoIndex] = useState<number>(-1)
  const [lightboxIndex, setLightboxIndex] = useState(-1)
  const [bulkTaggingPhotos, setBulkTaggingPhotos] = useState<GalleryPhoto[]>([])
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [showDeleteGalleryConfirm, setShowDeleteGalleryConfirm] = useState(false)
  const [showApproveAllConfirm, setShowApproveAllConfirm] = useState(false)
  const mountedRef = useRef(true)
  const loadingMoreRef = useRef(false)
  const photoFeedRef = useRef<HTMLDivElement>(null)
  const initializedRef = useRef(false)

  useEffect(() => {
    // Reset on mount (important for React Strict Mode which unmounts/remounts)
    mountedRef.current = true
    // Mark component initialized after first render
    initializedRef.current = true
    return () => {
      mountedRef.current = false
    }
  }, [])

  // Sync local search query with URL filter when URL changes externally
  useEffect(() => {
    setLocalSearchQuery(filters.q)
  }, [filters.q])

  // Debounce search query updates to URL (prevent reload on every keystroke)
  useEffect(() => {
    const timer = setTimeout(() => {
      if (localSearchQuery !== filters.q) {
        setFilters({ q: localSearchQuery })
      }
    }, 400)

    return () => clearTimeout(timer)
  }, [localSearchQuery, filters.q, setFilters])

  // Scroll to photo feed when filters change (better UX)
  useEffect(() => {
    if (photoFeedRef.current && initializedRef.current) {
      photoFeedRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' })
    }
  }, [filters.q, filters.album, filters.athlete, filters.sort, filters.status, filters.from, filters.to])

  useEffect(() => {
    const handleResize = () => {
      setGridPageSize(getGridPageSize())
    }
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  const loadGallery = useCallback(async () => {
    if (!id || !context) {
      if (mountedRef.current) setGalleryFetched(true)
      return
    }
    if (USE_FAKE_DATA) {
      const mockGalleryDb = getMockGalleryById(id)
      const mockPhotosDb = getMockPhotosForGallery(id)
      if (mountedRef.current) {
        setGallery(
          mockGalleryDb
            ? ({ ...mockGalleryDb, can_download: mockGalleryDb.can_download ?? undefined } as unknown as Gallery)
            : null,
        )
        const status = (p: typeof mockPhotosDb[0]) => ((p as GalleryPhoto).approval_status ?? (p as { status?: string }).status) as string
        setPhotoCounts({
          total: mockPhotosDb.length,
          pending: mockPhotosDb.filter((p) => status(p) === 'pending').length,
          approved: mockPhotosDb.filter((p) => status(p) === 'approved').length,
          rejected: mockPhotosDb.filter((p) => status(p) === 'rejected').length,
        })
        setGalleryFetched(true)
      }
      return
    }

    const { data, error } = await getGalleryById(context, id)
    if (!mountedRef.current) return
    if (error) {
      showError(error.message)
    }
    if (mountedRef.current) {
      setGallery(data || null)
      setGalleryFetched(true)
    }

    const { data: counts } = await getGalleryPhotoCounts(context, id)
    if (mountedRef.current && counts) {
      setPhotoCounts(counts)
    }
  }, [id, context])

  const loadAlbums = useCallback(async () => {
    if (!id || !context || USE_FAKE_DATA) return
    const { data, error } = await getAlbumsForGallery(context, id)
    if (!mountedRef.current) return
    if (error) {
      showError(error.message)
      return
    }
    setAlbums(data)
  }, [id, context])

  const loadPhotos = useCallback(async (reset: boolean): Promise<GalleryPhoto[] | null> => {
    if (!id || !context) return null
    if (loadingMoreRef.current && !reset) return null

    if (reset) {
      setLoading(true)
      loadingMoreRef.current = false
      cursorRef.current = null
      setHasMore(true)
    } else {
      loadingMoreRef.current = true
      setLoadingMore(true)
    }

    if (USE_FAKE_DATA) {
      if (FAKE_DATA_DELAY_MS > 0) {
        await new Promise((resolve) => setTimeout(resolve, FAKE_DATA_DELAY_MS))
      }
      const mockPhotosDb = getMockPhotosForGallery(id)
      const mockPhotos = mockPhotosDb.map(
        (p) => ({ ...p, can_download: p.can_download ?? undefined }) as unknown as GalleryPhoto,
      )
      if (mountedRef.current) {
        setPhotos(mockPhotos)
        setHasMore(false)
        setLoading(false)
        loadingMoreRef.current = false
        setLoadingMore(false)
      }
      return mockPhotos
    }

    const albumId = filters.album && filters.album !== 'favorites' ? filters.album : undefined
    const limit = viewMode === 'grid' ? gridPageSize : rowsPerPage
    const offset = viewMode === 'list' ? (page - 1) * rowsPerPage : undefined

    const query = buildPhotoQuery(filters, {
      gallery_id: id,
      album_id: albumId,
      limit,
      offset,
    })

    const { data, error } = await getPhotosForGallery(context, {
      ...query,
      cursor: viewMode === 'grid' && !reset ? cursorRef.current || undefined : undefined,
    })

    if (!mountedRef.current) return null

    if (error) {
      showError(error.message)
    } else {
      if (viewMode === 'grid') {
        setPhotos((prev) => (reset ? data : [...prev, ...data]))
        const last = data[data.length - 1]
        cursorRef.current = last ? { created_at: last.created_at, id: last.id } : cursorRef.current
        setHasMore(data.length === limit)
      } else {
        setPhotos(data)
        setHasMore(data.length === limit)
      }
    }

    
    setLoading(false)
    loadingMoreRef.current = false
    setLoadingMore(false)
    return data || null
  }, [id, context, filters, viewMode, gridPageSize, rowsPerPage, page])

  useEffect(() => {
    setGalleryFetched(false)
    setPhotoCounts({ total: 0, pending: 0, approved: 0, rejected: 0 })
  }, [id])

  useEffect(() => {
    loadGallery()
    loadAlbums()
    // Use stable deps so effect doesn't re-run on every render (context reference changes frequently)
  }, [loadGallery, loadAlbums])

  useEffect(() => {
    if (viewMode === 'list') {
      setPage(1)
    }
  }, [viewMode, filters.q, filters.album, filters.athlete, filters.sort, filters.status, filters.from, filters.to])

  useEffect(() => {
    loadPhotos(true)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, context?.userId, context?.orgId, viewMode, filters.q, filters.album, filters.athlete, filters.sort, filters.status, filters.from, filters.to, gridPageSize, rowsPerPage, page])

  useInfinitePhotos({
    hasMore: viewMode === 'grid' ? hasMore : false,
    isLoading: loading || loadingMore,
    onLoadMore: () => loadPhotos(false),
  })

  // Wrapped filter setter that updates local search immediately
  const handleFilterChange = useCallback(
    (updates: Parameters<typeof setFilters>[0]) => {
      if ('q' in updates) {
        // Update local state immediately for instant UI feedback
        setLocalSearchQuery(updates.q || '')
        // Remove 'q' from updates as it will be handled by debounce effect
        const { q: _q, ...otherUpdates } = updates
        if (Object.keys(otherUpdates).length > 0) {
          setFilters(otherUpdates)
        }
      } else {
        setFilters(updates)
      }
    },
    [setFilters]
  )

  // Wrapped clear filters that also resets local search
  const handleClearFilters = useCallback(() => {
    setLocalSearchQuery('')
    clearFilters()
  }, [clearFilters])

  const photoStats = useMemo(() => {
    const { total, pending, approved, rejected } = photoCounts
    const remaining = Math.max(0, MAX_PHOTOS_PER_GALLERY - total)
    const limitReached = total >= MAX_PHOTOS_PER_GALLERY
    return { total, pending, approved, flagged: rejected, remaining, limitReached }
  }, [photoCounts])

  const sortOptions = useMemo(
    () => [
      { value: 'recent', label: t('common.mostRecent') },
      { value: 'oldest', label: t('photos.filters.oldest') },
    ],
    [t],
  )

  const statusOptions = useMemo(
    () => [
      { value: 'all', label: t('photos.filters.statusAll') },
      { value: 'approved', label: t('common.approved') },
      { value: 'pending', label: t('photos.pendingApproval.badge') },
      { value: 'rejected', label: t('photos.filters.statusRejected') },
    ],
    [t],
  )

  const albumOptions = useMemo(
    () => albums.map((album) => ({ value: album.id, label: album.name })),
    [albums],
  )

  const athleteOptions = useMemo(() => {
    const map = new Map<string, { id: string; name: string }>()
    photos.forEach((photo) => {
      photo.tagged_athletes?.forEach((athlete) => {
        const name = `${athlete.first_name} ${athlete.last_name}`.trim()
        map.set(athlete.id, { id: athlete.id, name })
      })
    })
    return Array.from(map.values()).map((athlete) => ({ value: athlete.id, label: athlete.name }))
  }, [photos])

  
  

  

  const entityMeta = useMemo(() => {
    if (!gallery) return null
    const label = gallery.entity_name || t(`photos.galleryType.${gallery.gallery_type}`)
    if (!gallery.entity_id) {
      if (gallery.gallery_type === 'org') {
        return { label: gallery.org_name || label, link: getLink('admin.organization.base') }
      }
      return { label }
    }

    switch (gallery.gallery_type) {
      case 'team':
        return { label, link: getLink('admin.teams.detail', { id: gallery.entity_id }) }
      case 'event':
        return { label, link: getLink('admin.events.detail', { id: gallery.entity_id }) }
      case 'season':
        return { label, link: getLink('admin.seasons.detail', { id: gallery.entity_id }) }
      case 'program':
        return { label, link: getLink('admin.programs.detail', { id: gallery.entity_id }) }
      case 'athlete':
        return { label, link: getLink('admin.athletes.detail', { id: gallery.entity_id }) }
      case 'travel':
        return { label, link: getLink('admin.travel.edit', { id: gallery.entity_id }) }
      default:
        return { label }
    }
  }, [gallery, t])

  const handleDeleteGallery = () => {
    if (USE_FAKE_DATA) {
      showError(t('photos.demoMode.deleteBlocked'))
      return
    }

    if (!context || !gallery) return
    setShowDeleteGalleryConfirm(true)
  }

  const confirmDeleteGallery = async () => {
    if (!context || !gallery) return
    const { error } = await deleteGallery(context, gallery.id)
    if (error) {
      showError(error.message)
      return
    }
    showSuccess(t('photos.success.galleryDeleted'))
    navigate(getLink('admin.photos.list'))
  }

  const handleDeletePhotos = async (ids: string[]) => {
    if (USE_FAKE_DATA) {
      showError(t('photos.demoMode.deleteBlocked'))
      return
    }

    if (!context || !gallery) return
    const { error } = await deletePhotos(context, gallery.id, ids)
    if (error) {
      showError(error.message)
      return
    }
    showSuccess(t('photos.success.photosDeleted', { count: ids.length }))
    loadPhotos(true)
    loadGallery()
  }

  const handleEdit = () => {
    if (USE_FAKE_DATA) {
      showError(t('photos.demoMode.editBlocked'))
      return
    }
    setEditOpen(true)
  }

  
  

  if (!id) return null

  const handleApproveAll = () => {
    if (USE_FAKE_DATA) {
      showError(t('photos.demoMode.deleteBlocked'))
      return
    }
    if (photoCounts.pending <= 0) {
      showError(t('photos.noPendingPhotos'))
      return
    }
    setShowApproveAllConfirm(true)
  }

  const confirmApproveAll = async () => {
    if (!id || !context) return
    const { data: pendingPhotos } = await getPhotosForGallery(context, {
      gallery_id: id,
      status: 'pending',
      limit: 500,
      order_by: 'created_at',
      order_direction: 'asc',
    })
    const pendingIds = (pendingPhotos || []).map((p) => p.id)
    if (pendingIds.length === 0) {
      loadGallery()
      return
    }
    const { error } = await moderatePhotos(context, pendingIds, 'approve')
    if (error) {
      showError(t('gallery.moderationQueue.approveError'))
    } else {
      showSuccess(t('photos.success.photosApproved'))
      loadPhotos(true)
      loadGallery()
    }
  }

  

  // Show loading skeleton while gallery is still being fetched or photos are loading
  if (!galleryFetched || loading) {
    return (
      <div className="oa-root">
        <div style={{ padding: '24px' }}>
          <div className="oa-skeleton" style={{ height: '60px', marginBottom: '24px' }} />
          <div className="oa-skeleton" style={{ height: '400px', borderRadius: '8px', marginBottom: '32px' }} />
          <div style={{ display: 'flex', gap: '12px', marginBottom: '24px' }}>
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '40px', width: '100px' }} />
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))', gap: '12px' }}>
            {Array.from({ length: 12 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '150px' }} />
            ))}
          </div>
        </div>
      </div>
    )
  }

  // Show error only after we know the gallery fetch completed and returned no gallery
  if (!gallery) {
    return (
      <div className="org-structure-page">
        <div className="oa-p-6">
          <InlineNotice
            tone="error"
            title={t('photos.errors.galleryNotFound')}
            message={t('photos.errors.galleryNotFound')}
          />
          <div className="oa-mt-4">
            <Button variant="secondary" onClick={() => navigate(getLink('admin.photos.list'))}>
              {t('common.goBack')}
            </Button>
          </div>
        </div>
      </div>
