        title={gallery?.name || t('photos.allGalleries')}
        subtitle={entityMeta?.label}
        breadcrumbs={[
          { label: t('photos.title'), path: getLink('admin.photos.list') },
          { label: gallery?.name || t('photos.allGalleries') },
