  const levelId = id?.trim() || ''

  const { context, isReady } = useUserContext()
  const { isOffline } = useOffline()
  const location = useLocation()

  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [actionError, setActionError] = useState<string | null>(null)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)

  const [level, setLevel] = useState<Level | null>(null)
  const [program, setProgram] = useState<Program | null>(null)
  const [sport, setSport] = useState<Sport | null>(null)
  const [teams, setTeams] = useState<Team[]>([])
  const [totalAthletes, setTotalAthletes] = useState<number | null>(null)

  const isMountedRef = useRef(true)

  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
    }
  }, [])

  // Navigation state success message (e.g. returning from forms)
  useEffect(() => {
    if (location.state?.successMessage) {
      setSuccessMessage(location.state.successMessage)
      window.history.replaceState({}, document.title)
      // Refresh data after successful form submission
      if (levelId && isReady) {
        setRefreshing(true)
        loadData()
      }
    }
  }, [location.state, levelId, isReady])

  const levelsRoute = getLink('admin.levels.list')
  const programsRoute = getLink('admin.programs.list')
  const structureRoute = getLink('admin.organization.structure')
  const formsRoute = getLink('admin.organization.forms')
  const detailRoute = getLink('admin.levels.detail', { id: levelId })

  const heroImage = useMemo(() => getRandomSportImagePath(sport?.name ?? null, 'hero'), [sport?.name])
  const updatedLabel = useMemo(() => formatUpdatedRelative(level?.updated_at), [level?.updated_at])

  const statusLabel = useMemo(() => {
    const activeTeams = teams.filter((t) => t.is_active !== false)
    if (activeTeams.length > 0) return 'In Season'
    if (teams.length > 0) return 'Active'
    return 'Planning'
  }, [teams])

  const heroStats = useMemo(
    () => [
      { label: 'Total Teams', value: teams.length },
      { label: 'Total Athletes', value: totalAthletes },
    ],
    [teams.length, totalAthletes]
  )

  const loadData = useCallback(async () => {
    if (!isReady || !levelId) {
      if (!levelId && isReady) {
        setError('Level ID is required.')
        setLoading(false)
      }
      return
    }

    if (!refreshing) {
      setLoading(true)
    }
    setError(null)
    setActionError(null)

    try {
      const [levelRes, sportsRes, teamsRes] = await Promise.all([
        getLevel(context, levelId),
        getSports(context),
        getTeams(context, { levelId }),
      ])

      if (!isMountedRef.current) return

      if (levelRes.error) throw levelRes.error
      if (sportsRes.error) throw sportsRes.error
      if (teamsRes.error) throw teamsRes.error

      const foundLevel = levelRes.data as Level | null
      if (!foundLevel) {
        setLevel(null)
        setProgram(null)
        setSport(null)
        setTeams([])
        setError('Level not found (or you may not have access).')
        return
      }

      setLevel(foundLevel)

      // Load program if we have a program_id
      if (foundLevel.program_id) {
        const programRes = await getProgram(context, foundLevel.program_id)
        if (!isMountedRef.current) return
        if (!programRes.error && programRes.data) {
          const foundProgram = programRes.data as Program
          setProgram(foundProgram)

          // Load sport if we have a sport_id
          if (foundProgram.sport_id) {
            const allSports = Array.isArray(sportsRes.data) ? (sportsRes.data as Sport[]) : []
            const foundSport = allSports.find((s) => s.id === foundProgram.sport_id) ?? null
            setSport(foundSport)
          }
        }
      }

      setTeams(Array.isArray(teamsRes.data) ? teamsRes.data : [])
    } catch (err) {
      if (!isMountedRef.current) return
      setError(err instanceof Error ? err.message : 'Failed to load level.')
    } finally {
      if (isMountedRef.current) {
        setLoading(false)
        setRefreshing(false)
      }
    }
  }, [context, isReady, levelId, refreshing])

  useEffect(() => {
    loadData()
  }, [loadData])

  // Compute athlete counts (best effort). If offline, show as unavailable.
  useEffect(() => {
    const compute = async () => {
      setTotalAthletes(null)

      if (!level || !levelId) return
      if (isOffline) return

      if (teams.length === 0) {
        setTotalAthletes(0)
        return
      }

      const teamIds = teams.map((t) => t.id)

      // Fake data: derive counts from active season + roster per team
      if (USE_FAKE_DATA) {
        let total = 0

        for (const team of teams) {
          const seasonRes = await getActiveSeason(context, team.id)
          if (seasonRes.error || !seasonRes.data) continue
          const rosterRes = await getTeamRoster(context, team.id, seasonRes.data.id)
          if (rosterRes.error) continue
          total += rosterRes.data.length
        }

        setTotalAthletes(total)
        return
      }

      // Real data: count active memberships for teams in this level.
      try {
        const { data: memberships, error: memErr } = await supabase
          .from('team_memberships' as any)
          .select('athlete_id')
          .in('team_id', teamIds as any)
          .eq('status', 'active')

        if (memErr) throw memErr

        const distinctAthletes = new Set<string>()

        for (const row of (memberships as any[]) ?? []) {
          const athleteId = row.athlete_id as string | undefined
          if (athleteId) distinctAthletes.add(athleteId)
        }

        setTotalAthletes(distinctAthletes.size)
      } catch {
        // Keep counts unavailable if query fails
        setTotalAthletes(null)
      }
    }

    void compute()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [level, levelId, teams, isOffline])

  const teamRows: TeamRow[] = useMemo(() => {
    return teams.map((t) => ({
      id: t.id,
      name: t.name,
      athletes: null, // Will be computed per team if needed
      status: t.is_active !== false ? 'active' : 'inactive',
    }))
  }, [teams])

  const columns = useMemo<any>(() => {
    return [
      {
        id: 'name',
        label: 'TEAM NAME',
        cellType: 'primary',
        render: (row: any) => {
          if (!row.id) {
            return <span className="oa-body-m" style={{ fontWeight: 700, color: 'var(--oa-n900)' }}>{row.name}</span>
          }
          return (
            <Link
              to={getLink('admin.teams.detail', { id: row.id })}
              className="oa-body-m"
              style={{ fontWeight: 700, color: 'var(--oa-n900)', textDecoration: 'none' }}
              onClick={(e) => {
                if (!row.id) {
                  e.preventDefault()
                  setActionError('Invalid team ID')
                }
              }}
            >
              {row.name}
            </Link>
          )
        },
      },
      {
        id: 'athletes',
        label: 'ATHLETES',
        align: 'center',
        cellType: 'numeric',
        render: (row: any) => (row.athletes === null ? '—' : row.athletes),
      },
      {
        id: 'status',
        label: 'STATUS',
        render: (row: any) => (
          <span
            className="oa-body-s"
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              padding: 'calc(var(--oa-space-1) + 1px) var(--oa-space-2)',
              borderRadius: 'var(--oa-radius-pill)',
              background: row.status === 'active' ? 'var(--oa-theme-surface-highlight)' : 'var(--oa-surface-panel)',
              color: row.status === 'active' ? 'var(--oa-theme-text-accent)' : 'var(--oa-n500)',
              fontWeight: 800,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
            }}
          >
            {row.status}
          </span>
        ),
      },
      {
        id: 'action',
        label: 'ACTION',
        align: 'right',
        render: (row: any) => {
          if (!row.id) {
            return (
              <Button variant="ghost" size="dense" disabled title="Invalid team ID">
                View
              </Button>
            )
          }
          return (
            <Link to={getLink('admin.teams.detail', { id: row.id })}>
              <Button variant="ghost" size="dense">
                View
              </Button>
            </Link>
          )
        },
      },
    ]
  }, [])

  if (loading) {
    return (
      <div className="oa-root">
        <OfflineBanner />
        <div style={{ padding: '24px' }}>
          <div className="oa-skeleton" style={{ height: '60px', marginBottom: '24px' }} />
          <div className="oa-skeleton" style={{ height: '280px', borderRadius: '8px', marginBottom: '32px' }} />
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '32px' }}>
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '160px' }} />
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
            {Array.from({ length: 2 }).map((_, i) => (
              <div key={i}>
                <div className="oa-skeleton" style={{ height: '40px', marginBottom: '16px' }} />
                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  {Array.from({ length: 3 }).map((_, j) => (
                    <div key={j} className="oa-skeleton" style={{ height: '60px' }} />
                  ))}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    )
  }

  if (!level) {
    return (
      <div className="oa-root">
        <OfflineBanner />
        <AdminPageHeader
          title="Level Not Found"
          breadcrumbs={[
            { label: 'Organizations', path: structureRoute },
            { label: 'Levels', path: levelsRoute },
            { label: 'Not Found' },
          ]}
        />
        {error && (
          <Card className="oa-mb-4" style={{ borderLeft: '3px solid var(--oa-danger)' }}>
            <div className="oa-body-m oa-text-danger" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)' }}>
              {error}
            </div>
          </Card>
        )}
      </div>
    )
  }

  return (
    <div className="oa-root">
      <OfflineBanner />

      <div
        style={{
          maxWidth: 'calc(var(--oa-space-9) * 22.5)',
          margin: '0 auto',
          padding: 'var(--oa-space-6) var(--oa-space-4)',
        }}
      >
        <AdminPageHeader
          title={level.name}
          subtitle="Level details, teams, and eligibility."
          breadcrumbs={[
            { label: 'Organizations', path: structureRoute },
            { label: 'Levels', path: levelsRoute },
            { label: level.name },
          ]}
          actions={
            <div className="oa-flex oa-flex-col sm:oa-flex-row oa-gap-2">
              <Link to={levelsRoute} className="w-full sm:w-auto">
                <Button variant="ghost" disabled={loading} className="w-full sm:w-auto min-h-[44px]">
                  Back to Levels
                </Button>
              </Link>
              {program && program.id ? (
                <Link
                  to={getLink('admin.programs.detail', { id: program.id })}
                  onClick={(e) => {
                    if (!program.id) {
                      e.preventDefault()
                      setActionError('Program ID is required')
                    }
                  }}
                  className="w-full sm:w-auto"
                >
                  <Button variant="secondary" disabled={!program.id || loading} className="w-full sm:w-auto min-h-[44px]">
                    View Program
                  </Button>
                </Link>
              ) : (
                <Link to={programsRoute} className="w-full sm:w-auto">
                  <Button variant="secondary" disabled={loading} className="w-full sm:w-auto min-h-[44px]">
                    View Programs
                  </Button>
                </Link>
              )}
            </div>
          }
        />

        {successMessage && (
          <Card className="oa-mb-6" style={{ borderLeft: '3px solid var(--oa-success)' }}>
            <div className="oa-body-m" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)', color: 'var(--oa-n900)' }}>
              {successMessage}
            </div>
          </Card>
        )}

        {actionError && (
          <Card className="oa-mb-6" style={{ borderLeft: '3px solid var(--oa-danger)' }}>
            <div className="oa-body-m oa-text-danger" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)' }}>
              {actionError}
            </div>
          </Card>
        )}

        {error && (
          <Card className="oa-mb-6" style={{ borderLeft: '3px solid var(--oa-danger)' }}>
            <div className="oa-body-m oa-text-danger" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)' }}>
              {error}
            </div>
          </Card>
        )}

        {/* Hero band */}
        <div
          style={{
            height: 'calc(var(--oa-space-9) * 3)',
            borderRadius: 'var(--oa-radius-l)',
            overflow: 'hidden',
            position: 'relative',
            background: 'var(--oa-n900)',
            marginBottom: 'var(--oa-space-6)',
            border: '1px solid var(--oa-n100)',
          }}
          aria-label="Level hero"
        >
          <div
            style={{
              position: 'absolute',
              inset: 0,
              backgroundImage: `url(${heroImage})`,
              backgroundSize: 'cover',
              backgroundPosition: 'center',
              opacity: 0.35,
            }}
          />
          <div
            style={{
              position: 'absolute',
              inset: 0,
              background: 'linear-gradient(to top, var(--oa-n900), transparent)',
              opacity: 0.9,
            }}
          />
          <div
            className="oa-flex oa-items-center"
            style={{
              position: 'absolute',
              inset: 0,
              padding: '0 var(--oa-space-6)',
            }}
          >
            <div
              className="oa-grid"
              style={{
                width: '100%',
                gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
                gap: 'var(--oa-space-6)',
              }}
            >
              {heroStats.map((stat) => (
                <div
                  key={stat.label}
                  className="oa-display-xl"
                  style={{
                    display: 'flex',
                    alignItems: 'baseline',
                    color: 'var(--oa-white)',
                    fontWeight: 900,
                    letterSpacing: '-0.03em',
                    lineHeight: 1,
                    gap: '0.4em',
                  }}
                >
                  <span style={{ textAlign: 'right' }}>
                    {stat.value === null ? '—' : stat.value.toLocaleString()}
                  </span>
                  <span style={{ fontWeight: 400, opacity: 0.7 }}>{stat.label}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Main grid */}
        <div
          className="oa-grid"
          style={{
            gridTemplateColumns: 'minmax(0, 1fr)',
            alignItems: 'start',
          }}
        >
          <div
            className="oa-grid"
            style={{
              gridTemplateColumns: 'minmax(0, 1fr)',
              gap: 'var(--oa-space-6)',
            }}
          >
            {/* Action bar */}
            <Card className="oa-card">
              <div className="oa-flex oa-justify-between oa-items-center" style={{ gap: 'var(--oa-space-4)' }}>
                <div className="oa-flex oa-items-center" style={{ gap: 'var(--oa-space-3)' }}>
                  <span
                    className="oa-body-s"
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      padding: 'var(--oa-space-2) var(--oa-space-3)',
                      borderRadius: 'var(--oa-radius-pill)',
                      background: 'var(--oa-theme-action-primary)',
                      color: 'var(--oa-theme-text-on-action)',
                      fontWeight: 900,
                      letterSpacing: '0.14em',
                      textTransform: 'uppercase',
                    }}
                  >
                    Status: {statusLabel}
                  </span>
                  <span className="oa-body-m" style={{ color: 'var(--oa-n500)' }}>
                    {updatedLabel}
                  </span>
                </div>

                <div className="oa-flex oa-items-center oa-gap-2" style={{ flexWrap: 'wrap', justifyContent: 'flex-end' }}>
                  {levelId ? (
                    <Link
                      to={`${getLink('admin.levels.update', { id: levelId })}?returnUrl=${encodeURIComponent(detailRoute)}`}
                      onClick={(e) => {
                        if (!levelId) {
                          e.preventDefault()
                          setActionError('Level ID is required to edit')
                        }
                      }}
                    >
                      <Button
                        variant="ghost"
                        icon="edit"
                        disabled={!levelId || loading}
                        style={{
                          border: '2px solid var(--oa-theme-action-primary)',
                          color: 'var(--oa-theme-text-accent)',
                          background: 'transparent',
                        }}
                        title={!levelId ? 'Level ID is required' : undefined}
                      >
                        Edit Level
                      </Button>
                    </Link>
                  ) : (
                    <Button
                      variant="ghost"
                      icon="edit"
                      disabled
                      style={{
                        border: '2px solid var(--oa-theme-action-primary)',
                        color: 'var(--oa-theme-text-accent)',
                        background: 'transparent',
                      }}
                      title="Level ID is required"
                    >
                      Edit Level
                    </Button>
                  )}
                  {program && program.id && program.sport_id ? (
                    <Link
                      to={`${formsRoute}?type=team&program_id=${program.id}&level_id=${levelId}&sport_id=${program.sport_id}&returnUrl=${encodeURIComponent(detailRoute)}`}
                      className={isOffline || USE_FAKE_DATA ? 'oa-disabled-link' : ''}
                      onClick={(e) => {
                        if (isOffline || USE_FAKE_DATA) {
                          e.preventDefault()
                        } else if (!program.id || !program.sport_id || !levelId) {
                          e.preventDefault()
                          setActionError('Missing required information to add team')
                        }
                      }}
                    >
                      <OrgAdminButton
                        variant="primary"
                        icon="add_circle"
                        disabled={isOffline || USE_FAKE_DATA || !program.id || !program.sport_id || !levelId || loading}
                        title={
                          !levelId
                            ? 'Level ID is required'
                            : !program.id
                              ? 'Program ID is required'
                              : !program.sport_id
                                ? 'Sport ID is required'
                                : isOffline
                                  ? 'Offline - cannot add teams'
                                  : USE_FAKE_DATA
                                    ? 'Sign in to add teams'
                                    : undefined
                        }
                      >
                        Add Team
                      </OrgAdminButton>
                    </Link>
                  ) : (
                    <OrgAdminButton
                      variant="primary"
                      icon="add_circle"
                      disabled
                      title="Program information is required to add teams"
                    >
                      Add Team
                    </OrgAdminButton>
                  )}
                </div>
              </div>
            </Card>

            {/* Level details */}
            <Card title="Level Information" className="oa-card">
              <div style={{ display: 'grid', gap: 'var(--oa-space-4)' }}>
                <div>
                  <div className="oa-overline" style={{ color: 'var(--oa-n500)', marginBottom: 'var(--oa-space-1)' }}>
                    Level Type
                  </div>
                  <div className="oa-body-m" style={{ fontWeight: 700, color: 'var(--oa-n900)' }}>
                    {level.level_type === 'age_based'
                      ? 'Age-based'
                      : level.level_type === 'grade_based'
                        ? 'Grade-based'
                        : level.level_type === 'skill_based'
                          ? 'Skill-based'
                          : level.level_type}
                  </div>
                </div>

                <div>
                  <div className="oa-overline" style={{ color: 'var(--oa-n500)', marginBottom: 'var(--oa-space-1)' }}>
                    Eligibility Criteria
                  </div>
                  <div className="oa-body-m" style={{ color: 'var(--oa-n900)' }}>
                    {formatEligibility(level)}
                  </div>
                </div>

                {level.description && (
                  <div>
                    <div className="oa-overline" style={{ color: 'var(--oa-n500)', marginBottom: 'var(--oa-space-1)' }}>
                      Description
                    </div>
                    <div className="oa-body-m" style={{ color: 'var(--oa-n700)' }}>
                      {level.description}
                    </div>
                  </div>
                )}
              </div>
            </Card>

            {/* Teams table */}
            <AnyCard
              title="Teams in This Level"
              className="oa-card oa-card--no-padding"
              actions={
                <Button
                  variant="ghost"
                  size="dense"
                  onClick={() => {
                    const rows = teamRows.map((r) => ({
                      team_id: r.id,
                      team_name: r.name,
                      athletes: r.athletes ?? '',
                      status: r.status,
                    }))
                    downloadCsv(`${level.name}-teams.csv`, rows)
                  }}
                  disabled={teamRows.length === 0}
                >
                  Export CSV
                </Button>
              }
             
            >
              <AnyTable
                columns={columns}
                data={teamRows}
                emptyState={
                  <div style={{ padding: 'var(--oa-space-8) var(--oa-space-5)' }}>
                    <div className="oa-h3" style={{ textAlign: 'center', marginBottom: 'var(--oa-space-2)' }}>
                      No teams yet
                    </div>
                    <div className="oa-body-m" style={{ textAlign: 'center', color: 'var(--oa-n600)' }}>
                      Add a team to this level to start organizing rosters.
                    </div>
                  </div>
                }
              />
            </AnyCard>
          </div>

          {/* Right panel (stacks below on small screens) */}
          <div
            className="oa-grid"
            style={{
              gridTemplateColumns: 'minmax(0, 1fr)',
              gap: 'var(--oa-space-6)',
            }}
          >
            {/* Totals */}
            <Card
              className="oa-card"
              style={{
                background: 'var(--oa-theme-action-primary)',
                color: 'var(--oa-theme-text-on-action)',
                borderColor: 'var(--oa-theme-border-accent)',
              }}
            >
              <div
                className="oa-overline"
                style={{
                  color: 'rgba(255,255,255,0.75)',
                  letterSpacing: '0.18em',
                  marginBottom: 'var(--oa-space-4)',
                }}
              >
                Level Totals
              </div>

              <div style={{ display: 'grid', gap: 'var(--oa-space-4)' }}>
                <div>
                  <div className="oa-display-xl" style={{ color: 'var(--oa-theme-text-on-action)' }}>
                    {teams.length.toLocaleString()}
                  </div>
                  <div className="oa-overline" style={{ color: 'rgba(255,255,255,0.75)' }}>
                    Total Teams
                  </div>
                </div>

                <div style={{ height: '1px', background: 'rgba(255,255,255,0.18)' }} />

                <div>
                  <div className="oa-display-xl" style={{ color: 'var(--oa-theme-text-on-action)' }}>
                    {totalAthletes === null ? '—' : totalAthletes.toLocaleString()}
                  </div>
                  <div className="oa-overline" style={{ color: 'rgba(255,255,255,0.75)' }}>
                    Total Athletes
                  </div>
                </div>

                {isOffline && (
                  <div className="oa-body-s" style={{ color: 'rgba(255,255,255,0.75)' }}>
                    Offline: roster totals may be unavailable.
                  </div>
                )}
              </div>
            </Card>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useUserContext } from '../../hooks/useUserContext'
import { 
  getFeeAssignmentById, 
  formatCurrency,
  markFeeAssignmentAsPaidOffline,
  issueRefundForFeeAssignment,
  voidFeeAssignment,
  sendPaymentReminder,
  generateReceiptPDF
} from '../../data/services/paymentsService'
import { supabase } from '../../lib/supabase'
import { getLink } from '../../utils/routes'
import { AdminPageHeader, Card, Button, ConfirmDialog } from '../../components/admin'
import { OrgAdminButton } from '../../components/admin/OrgAdminButton'
import { showSuccess, showError } from '../../utils/toast'
import '../../styles/orgAdmin.css'

interface PaymentDetailData {
  id: string
  amount_cents: number
  balance_cents: number
  paid_cents_total: number
  status: 'unpaid' | 'partial' | 'paid' | 'waived' | 'overdue'
  due_date: string | null
  created_at: string
  fee?: {
    id: string
    title: string
    description: string | null
    amount_cents: number
    season?: { id: string; name: string } | null
  } | null
  athlete?: {
    id: string
    first_name: string
    last_name: string
  } | null
  parent?: {
    id: string
    email: string
    display_name: string | null
  } | null
  payments?: Array<{
    id: string
    amount_cents: number
    status: string
    created_at: string
    stripe_payment_intent_id: string | null
  }>
  team?: {
    id: string
    name: string
  } | null
  season?: {
    id: string
    name: string
  } | null
  created_by?: {
    id: string
    display_name: string | null
    email: string
  } | null
}

export default function PaymentDetail() {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const { context, isReady } = useUserContext()
  const componentIdRef = useRef(`PaymentDetail-Admin-${Date.now()}-${Math.random()}`)
  const renderCountRef = useRef(0)
  const effectRunCountRef = useRef(0)
  const fetchDataCountRef = useRef(0)

  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [assignment, setAssignment] = useState<PaymentDetailData | null>(null)

  renderCountRef.current++
  console.log(`[PaymentDetail-Admin:${componentIdRef.current}] RENDER #${renderCountRef.current}`, {
    timestamp: new Date().toISOString(),
    id, 
    isReady, 
    loading, 
    hasAssignment: !!assignment,
    error,
    contextUserId: context.userId,
    contextOrgId: context.orgId,
    contextRoles: context.roles 
  })
  const [actionLoading, setActionLoading] = useState<string | null>(null)
  const isMountedRef = useRef(true)
  const receiptInProgressRef = useRef(false)
  
  // Confirmation dialog state
  const [confirmDialog, setConfirmDialog] = useState<{
    open: boolean
    action: 'markPaid' | 'refund' | 'void' | null
    title: string
    description: string
    variant: 'info' | 'warning' | 'danger'
    requireReason: boolean
    error: string | null
  }>({
    open: false,
    action: null,
    title: '',
    description: '',
    variant: 'info',
    requireReason: false,
    error: null,
  })

  useEffect(() => {
    const mountTime = new Date().toISOString()
    console.log(`[PaymentDetail-Admin:${componentIdRef.current}] MOUNT`, { timestamp: mountTime })
    isMountedRef.current = true
    return () => {
      const unmountTime = new Date().toISOString()
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] UNMOUNT`, {
        timestamp: unmountTime,
        mountTime,
        renderCount: renderCountRef.current,
        effectRuns: effectRunCountRef.current,
        fetchDataCalls: fetchDataCountRef.current,
      })
      isMountedRef.current = false
    }
  }, [])

  const fetchData = useCallback(async () => {
    fetchDataCountRef.current++
    const fetchId = fetchDataCountRef.current
    console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} START`, {
      timestamp: new Date().toISOString(),
      id, 
      isReady, 
      contextOrgId: context.orgId,
      isMounted: isMountedRef.current,
    })

    if (!isReady) {
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Not ready yet, waiting...`)
      return
    }

    if (!id) {
      console.warn(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - No ID provided, navigating back to list`)
      if (isMountedRef.current) {
        setLoading(false)
      }
      navigate(getLink('admin.payments.list'), { replace: true })
      return
    }

    if (!isMountedRef.current) {
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Aborted (unmounted)`)
      return
    }

    setLoading(true)
    setError(null)

    try {
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Calling getFeeAssignmentById`)
      const apiStartTime = Date.now()
      const { data, error: fetchError } = await getFeeAssignmentById(context, id)
      const apiDuration = Date.now() - apiStartTime
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - getFeeAssignmentById completed`, {
        duration: `${apiDuration}ms`,
        hasData: !!data, 
        hasError: !!fetchError,
        errorMessage: fetchError?.message,
        dataId: data?.id 
      })

      if (!isMountedRef.current) {
        console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Aborted after API (unmounted)`)
        return
      }

      if (fetchError) {
        console.error(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Fetch error:`, fetchError)
        if (isMountedRef.current) {
          setLoading(false)
          if (fetchError.message?.includes('Access denied') || fetchError.message?.includes('not found')) {
            console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Access denied or not found, navigating back`)
            navigate(getLink('admin.payments.list'), { replace: true })
          } else {
            console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Setting error state:`, fetchError.message)
            setError(fetchError.message || 'Failed to load payment details')
          }
        }
        return
      }

      if (!data) {
        console.warn(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - No data returned for payment:`, id)
        if (isMountedRef.current) {
          setLoading(false)
          setError('Payment not found')
        }
        return
      }

      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Fetched data:`, data)

      // Transform to component format
      const rawAmount = (data as any).amount_cents ?? (data as any).amount_due_cents ?? 0
      const rawBalance = (data as any).balance_cents
      const rawPaid = (data as any).paid_cents_total ?? (data as any).amount_paid_cents ?? 0
      
      const amountCents = Number(rawAmount) || 0
      const paidCentsTotal = Number(rawPaid) || 0
      const balanceCents = rawBalance !== undefined && rawBalance !== null 
        ? Number(rawBalance) 
        : Math.max(0, amountCents - paidCentsTotal)

      const transformed: PaymentDetailData = {
        id: data.id,
        amount_cents: amountCents,
        balance_cents: balanceCents,
        paid_cents_total: paidCentsTotal,
        status: (data.status || 'unpaid') as PaymentDetailData['status'],
        due_date: (data as any).due_date ?? null,
        created_at: (data as any).created_at || new Date().toISOString(),
        fee: data.fee ? {
          id: data.fee.id,
          title: data.fee.title || 'Fee',
          description: (data.fee as any).description ?? null,
          amount_cents: (data.fee as any).amount_cents ?? amountCents,
          season: (data.fee as any).season ? {
            id: (data.fee as any).season.id,
            name: (data.fee as any).season.name,
          } : null,
        } : null,
        athlete: (data as any).athlete ? {
          id: (data as any).athlete.id,
          first_name: (data as any).athlete.first_name || '',
          last_name: (data as any).athlete.last_name || '',
        } : null,
        parent: (data as any).parent ? {
          id: (data as any).parent.id,
          email: (data as any).parent.email || '',
          display_name: (data as any).parent.display_name || null,
        } : null,
        payments: (data as any).payments ?? [],
      }

      // Fetch team and season info if available
      if (transformed.fee?.season?.id) {
        try {
          console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Fetching team info`)
          const teamStartTime = Date.now()
          const { data: teamSeasons } = await supabase
            .from('team_seasons')
            .select('team_id, team:teams(id, name)')
            .eq('season_id', transformed.fee.season.id)
            .limit(1)
          const teamDuration = Date.now() - teamStartTime
          console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Team fetch completed`, {
            duration: `${teamDuration}ms`,
            hasData: !!teamSeasons,
            dataLength: teamSeasons?.length,
          })
          
          if (!isMountedRef.current) {
            console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Aborted after team fetch (unmounted)`)
            return
          }
          
          if (teamSeasons && teamSeasons.length > 0 && (teamSeasons[0] as any).team) {
            transformed.team = {
              id: (teamSeasons[0] as any).team.id,
              name: (teamSeasons[0] as any).team.name,
            }
          }
          transformed.season = transformed.fee.season
        } catch (err) {
          if (!isMountedRef.current) return
          console.error(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Team fetch error:`, err)
        }
      }

      if (!isMountedRef.current) {
        console.log('[PaymentDetail] Component unmounted after team fetch, aborting')
        return
      }
      
      // Validate transformed data has required fields
      if (!transformed.id) {
        console.error(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Invalid payment data: missing ID`)
        if (isMountedRef.current) {
          setError('Invalid payment data: missing ID')
          setLoading(false)
        }
        return
      }
      
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] fetchData #${fetchId} - Setting assignment state`)
      if (isMountedRef.current) {
        setAssignment(transformed)
        setLoading(false)
      }
    } catch (err) {
      if (!isMountedRef.current) {
        console.log('[PaymentDetail] Component unmounted during error handling')
        return
      }
      console.error('[PaymentDetail] Caught error in fetchData:', err)
      setError(err instanceof Error ? err.message : 'Failed to load payment details')
      setLoading(false)
    }
  }, [id, context.orgId, context.userId, isReady, navigate])

  useEffect(() => {
    effectRunCountRef.current++
    const effectId = effectRunCountRef.current
    console.log(`[PaymentDetail-Admin:${componentIdRef.current}] Effect #${effectId} - Trigger fetchData`, {
      timestamp: new Date().toISOString(),
      isReady, 
      id,
      isMounted: isMountedRef.current,
    })
    if (isReady && id) {
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] Effect #${effectId} - Calling fetchData`)
      fetchData()
    } else {
      console.log(`[PaymentDetail-Admin:${componentIdRef.current}] Effect #${effectId} - Skipping fetchData`, {
        reason: !isReady ? 'not ready' : 'no id',
      })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isReady, id])

  const handleSendReminder = async () => {
    if (!assignment || !isMountedRef.current || actionLoading !== null) return
    
    setActionLoading('reminder')
    try {
      const { data, error } = await sendPaymentReminder(context, assignment.id)
      
      if (!isMountedRef.current) return
      
      if (error) {
        showError(error.message || 'Failed to send reminder')
        setError(error.message || 'Failed to send reminder')
      } else if (data?.sent) {
        showSuccess('Payment reminder sent successfully')
      }
    } catch (err) {
      if (isMountedRef.current) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to send reminder'
        showError(errorMessage)
        setError(errorMessage)
      }
    } finally {
      if (isMountedRef.current) {
        setActionLoading(null)
      }
    }
  }

  const handleDownloadReceipt = async (e?: React.MouseEvent) => {
    if (e && !e.isTrusted) return
    if (!assignment || actionLoading !== null || receiptInProgressRef.current) return
    receiptInProgressRef.current = true
    setActionLoading('download')
    try {
      const { data, error } = await generateReceiptPDF(context, assignment.id)
      if (!isMountedRef.current) return
      if (error) {
        showError(error.message || 'Failed to generate receipt')
        return
      }
      if (data?.url) {
        if (data.url.startsWith('http') || data.url.startsWith('https')) {
          window.open(data.url, '_blank')
          showSuccess('Receipt opened in new tab')
        } else {
          showError('Receipt URL is not available')
        }
      }
    } catch (err) {
      if (isMountedRef.current) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to download receipt'
        showError(errorMessage)
      }
    } finally {
      receiptInProgressRef.current = false
      if (isMountedRef.current) setActionLoading(null)
    }
  }

  const handleMarkAsPaidClick = () => {
    if (!assignment) return
    setConfirmDialog({
      open: true,
      action: 'markPaid',
      title: 'Mark as Paid (Offline)',
      description: `Mark this payment as paid offline? This will update the status to "paid" and set the balance to $0. Amount: ${formatCurrency(assignment.amount_cents)}`,
      variant: 'info',
      requireReason: false,
      error: null,
    })
  }

  const handleMarkAsPaid = async (_reason: string) => {
    if (!assignment || !isMountedRef.current) return
    
    setActionLoading('markPaid')
    try {
      const { data, error } = await markFeeAssignmentAsPaidOffline(context, assignment.id)
      
      if (!isMountedRef.current) return
      
      if (error) {
        const errorMessage = error.message || 'Failed to mark as paid'
        showError(errorMessage)
        setConfirmDialog(prev => ({ ...prev, error: errorMessage }))
      } else if (data) {
        showSuccess('Payment marked as paid successfully')
        setConfirmDialog(prev => ({ ...prev, open: false, error: null }))
        // Refresh data
        await fetchData()
      }
    } catch (err) {
      if (isMountedRef.current) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to mark as paid'
        showError(errorMessage)
        setConfirmDialog(prev => ({ ...prev, error: errorMessage }))
      }
    } finally {
      if (isMountedRef.current) {
        setActionLoading(null)
      }
    }
  }

  const handleIssueRefundClick = () => {
    if (!assignment) return
    setConfirmDialog({
      open: true,
      action: 'refund',
      title: 'Issue Refund',
      description: `Issue a refund for this payment? Amount paid: ${formatCurrency(assignment.paid_cents_total)}. You will be able to specify the refund amount.`,
      variant: 'warning',
      requireReason: true,
      error: null,
    })
  }

  const handleIssueRefund = async (reason: string) => {
    if (!assignment || !isMountedRef.current || !reason.trim()) return
    
    setActionLoading('refund')
    try {
      // For now, refund the full amount. In production, you might want a dialog to specify amount
      const refundAmount = assignment.paid_cents_total
      const { data, error } = await issueRefundForFeeAssignment(
        context, 
        assignment.id, 
        refundAmount,
        reason
      )
      
      if (!isMountedRef.current) return
      
      if (error) {
        const errorMessage = error.message || 'Failed to issue refund'
        showError(errorMessage)
        setConfirmDialog(prev => ({ ...prev, error: errorMessage }))
      } else if (data) {
        showSuccess(`Refund of ${formatCurrency(refundAmount)} issued successfully`)
        setConfirmDialog(prev => ({ ...prev, open: false, error: null }))
        // Refresh data
        await fetchData()
      }
    } catch (err) {
      if (isMountedRef.current) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to issue refund'
        showError(errorMessage)
        setConfirmDialog(prev => ({ ...prev, error: errorMessage }))
      }
    } finally {
      if (isMountedRef.current) {
        setActionLoading(null)
      }
    }
  }

  const handleVoidPaymentClick = () => {
    if (!assignment) return
    setConfirmDialog({
      open: true,
      action: 'void',
      title: 'Void Payment',
      description: `Void this payment assignment? This will mark it as waived and set the balance to $0. This action cannot be undone. Amount: ${formatCurrency(assignment.amount_cents)}`,
      variant: 'danger',
      requireReason: true,
      error: null,
    })
  }

  const handleVoidPayment = async (reason: string) => {
    if (!assignment || !isMountedRef.current || !reason.trim()) return
    
    setActionLoading('void')
    try {
      const { data, error } = await voidFeeAssignment(context, assignment.id, reason)
      
      if (!isMountedRef.current) return
      
      if (error) {
        const errorMessage = error.message || 'Failed to void payment'
        showError(errorMessage)
        setConfirmDialog(prev => ({ ...prev, error: errorMessage }))
      } else if (data) {
        showSuccess('Payment voided successfully')
        setConfirmDialog(prev => ({ ...prev, open: false, error: null }))
        // Refresh data
        await fetchData()
      }
    } catch (err) {
      if (isMountedRef.current) {
        const errorMessage = err instanceof Error ? err.message : 'Failed to void payment'
        showError(errorMessage)
        setConfirmDialog(prev => ({ ...prev, error: errorMessage }))
      }
    } finally {
      if (isMountedRef.current) {
        setActionLoading(null)
      }
    }
  }

  const handleConfirmDialogConfirm = (reason: string) => {
    if (confirmDialog.action === 'markPaid') {
      handleMarkAsPaid(reason)
    } else if (confirmDialog.action === 'refund') {
      handleIssueRefund(reason)
    } else if (confirmDialog.action === 'void') {
      handleVoidPayment(reason)
    }
  }

  const handleConfirmDialogCancel = () => {
    setConfirmDialog(prev => ({ ...prev, open: false }))
  }

  if (loading) {
    return (
      <div className="oa-root">
        <div style={{ padding: '24px' }}>
          <div className="oa-skeleton" style={{ height: '60px', marginBottom: '24px' }} />
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '32px' }}>
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '100px' }} />
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
            {Array.from({ length: 2 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '300px' }} />
            ))}
          </div>
        </div>
      </div>
    )
  }

  if (error || !assignment) {
    console.log('[PaymentDetail] Rendering error state:', { error, hasAssignment: !!assignment })
    return (
      <div className="oa-root">
        <AdminPageHeader title="Payment" />
        <Card className="oa-text-center oa-py-12">
          <p className="oa-text-red-600 dark:oa-text-red-400 oa-text-sm oa-font-bold oa-mb-4">{error || 'Payment not found'}</p>
          <div className="oa-flex oa-flex-wrap oa-justify-center oa-gap-3">
            <Button variant="primary" onClick={() => { setError(null); fetchData() }}>
              Retry
            </Button>
            <Button variant="secondary" onClick={() => navigate(getLink('admin.payments.list'))}>
              Back to Payments
            </Button>
          </div>
        </Card>
      </div>
    )
  }

  console.log('[PaymentDetail] Rendering main content with assignment:', assignment.id)

  const isPaid = assignment.status === 'paid'
  const isUnpaid = assignment.status === 'unpaid' || assignment.status === 'overdue'
  const pageTitle = assignment.fee?.title ?? 'Payment Details'
  const paymentDate = assignment.payments && assignment.payments.length > 0
    ? new Date(assignment.payments[0].created_at)
    : new Date(assignment.created_at)

  return (
    <div className="oa-root">
      <div
        style={{
          maxWidth: '1200px',
          margin: '0 auto',
          padding: 'var(--oa-space-8) var(--oa-space-5)',
        }}
      >
        {/* Custom Header with Back Button and Title */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-6">
          <div className="flex items-center gap-3">
            <button
              onClick={() => navigate(getLink('admin.payments.list'))}
              className="size-10 flex items-center justify-center rounded-lg bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-400 hover:text-[var(--org-btn-primary-bg, #137fec)] transition-colors min-h-[44px] min-w-[44px]"
            >
              <span className="material-symbols-outlined">arrow_back</span>
            </button>
            <h1 className="text-2xl sm:text-3xl font-black text-slate-900 dark:text-white uppercase tracking-tight">
              {pageTitle}
            </h1>
          </div>
          <OrgAdminButton
            variant="primary"
            onClick={handleDownloadReceipt}
            disabled={!isPaid || actionLoading !== null}
            loading={actionLoading === 'download'}
            icon="download"
            className="flex items-center gap-2 uppercase tracking-widest w-full sm:w-auto min-h-[44px]"
          >
            DOWNLOAD PDF
          </OrgAdminButton>
        </div>

        {error && (
          <Card className="mb-6" style={{ borderLeft: '3px solid var(--oa-danger)' }}>
            <div className="text-sm font-medium text-red-600 dark:text-red-400" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)' }}>
              {error}
            </div>
          </Card>
        )}

        {/* Payment Status Card */}
        <Card className="mb-12 text-center relative overflow-hidden">
          <div className="relative z-10">
            <div className={`inline-flex items-center justify-center size-16 rounded-full mb-6 ${
              isPaid 
                ? 'bg-green-100 dark:bg-green-900/30 text-green-600 dark:text-green-400'
                : 'bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400'
            }`}>
              <span className="material-symbols-outlined text-4xl font-bold">
                {isPaid ? 'check_circle' : 'pending'}
              </span>
            </div>
            <p className="text-slate-500 dark:text-slate-400 font-bold uppercase tracking-[0.2em] text-sm mb-2">
              {isPaid ? 'Total Amount Paid' : 'Amount Due'}
            </p>
            <h2 className="text-7xl font-black text-slate-900 dark:text-white tracking-tighter mb-4">
              {formatCurrency(isPaid ? assignment.paid_cents_total : assignment.balance_cents)}
            </h2>
            <div className={`inline-flex items-center gap-2 px-4 py-2 rounded-full font-black text-xs uppercase tracking-widest ${
              isPaid
                ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400'
                : assignment.status === 'partial'
                ? 'bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400'
                : 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400'
            }`}>
              {isPaid && <span className="size-2 bg-green-500 rounded-full animate-pulse"></span>}
              STATUS: {assignment.status.toUpperCase()}
            </div>
          </div>
          <div className="absolute top-0 right-0 w-32 h-32 bg-[var(--org-btn-primary-bg, #137fec)]/5 -mr-16 -mt-16 rounded-full"></div>
        </Card>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Left Column - Main Content */}
          <div className="lg:col-span-2 space-y-8">
            {/* Payer and For Section */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 sm:gap-8">
              <div className="space-y-4">
                <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-900 dark:text-white">PAYER</h3>
                <div className="flex items-center gap-4">
                  <div className="size-12 rounded-full bg-slate-200 dark:bg-slate-800 flex items-center justify-center">
                    <span className="material-symbols-outlined text-slate-500">person</span>
                  </div>
                  <div>
                    <p className="font-bold text-slate-900 dark:text-white">
                      {assignment.parent?.display_name || assignment.parent?.email || 'Unknown'}
                    </p>
                    <p className="text-sm text-slate-500 dark:text-slate-400">
                      {assignment.parent?.email || 'No email'}
                    </p>
                  </div>
                </div>
              </div>
              <div className="space-y-4">
                <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-900 dark:text-white">FOR</h3>
                <div className="flex items-center gap-4">
                  <div className="size-12 rounded-full border-2 border-[var(--org-btn-primary-bg, #137fec)] overflow-hidden bg-slate-200 dark:bg-slate-800 flex items-center justify-center">
                    {assignment.athlete ? (
                      <span className="text-slate-500 text-xs font-bold">
                        {assignment.athlete.first_name[0]}{assignment.athlete.last_name[0]}
                      </span>
                    ) : (
                      <span className="material-symbols-outlined text-slate-500">person</span>
                    )}
                  </div>
                  <div>
                    <p className="font-bold text-slate-900 dark:text-white">
                      {assignment.athlete 
                        ? `${assignment.athlete.first_name} ${assignment.athlete.last_name}`
                        : 'Unknown Athlete'}
                    </p>
                    <p className="text-sm text-slate-500 dark:text-slate-400">
                      Athlete #{assignment.athlete?.id.slice(-4) || 'N/A'}
                    </p>
                  </div>
                </div>
              </div>
            </div>

            {/* Itemization */}
            <Card>
              <div className="px-6 py-4 bg-slate-50 dark:bg-slate-800/50 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center rounded-t-2xl">
                <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-900 dark:text-white">ITEMIZATION</h3>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                  {paymentDate.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })} • {paymentDate.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', timeZoneName: 'short' })}
                </span>
              </div>
              <div className="divide-y divide-slate-100 dark:divide-slate-800">
                {assignment.fee && (
                  <div className="p-6 flex justify-between items-center">
                    <div>
                      <p className="font-bold text-slate-900 dark:text-white">{assignment.fee.title}</p>
                      <p className="text-xs text-slate-500 dark:text-slate-400">
                        {assignment.fee.description || 'Fee payment'}
                      </p>
                    </div>
