import { useI18n } from '../../i18n/useI18n'
import '../../styles/orgAdmin.css'

type LevelRow = {
  id: string
  name: string
  teams: number
  athletes: number | null
  status: 'active' | 'inactive'
}

function formatUpdatedRelative(iso: string | null | undefined): string {
  if (!iso) return 'Updated recently'
  const dt = new Date(iso)
  if (Number.isNaN(dt.valueOf())) return 'Updated recently'

  const diffMs = Date.now() - dt.valueOf()
  const diffSec = Math.floor(diffMs / 1000)
  const absSec = Math.abs(diffSec)

  const rtf = new Intl.RelativeTimeFormat(undefined, { numeric: 'auto' })

  if (absSec < 60) return `Updated ${rtf.format(-diffSec, 'second')}`
  const diffMin = Math.floor(diffSec / 60)
  const absMin = Math.abs(diffMin)
  if (absMin < 60) return `Updated ${rtf.format(-diffMin, 'minute')}`
  const diffHr = Math.floor(diffMin / 60)
  const absHr = Math.abs(diffHr)
  if (absHr < 24) return `Updated ${rtf.format(-diffHr, 'hour')}`
  const diffDay = Math.floor(diffHr / 24)
  return `Updated ${rtf.format(-diffDay, 'day')}`
}

function formatMetric(value: number | null): string {
  return value === null ? '—' : value.toLocaleString()
}

function downloadCsv(filename: string, rows: Array<Record<string, unknown>>): boolean {
  if (rows.length === 0) return false
  try {
    const headers = Object.keys(rows[0])
    const escape = (value: unknown) => {
      const s = value === null || value === undefined ? '' : String(value)
      if (/[,"\n]/.test(s)) return `"${s.replace(/"/g, '""')}"`
      return s
    }
    const csv = [headers.join(','), ...rows.map((r) => headers.map((h) => escape(r[h])).join(','))].join('\n')
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = filename
    document.body.appendChild(a)
    a.click()
    a.remove()
    URL.revokeObjectURL(url)
    return true
  } catch (err) {
    console.error('[ProgramDetail] CSV export failed:', err)
    return false
  }
}

export default function ProgramDetail() {
  const AnyCard = Card as any
  const AnyTable = Table as any
  const { id } = useParams<{ id: string }>()
  const programId = id?.trim() || ''

  const { context, isReady } = useUserContext()
  const { isOffline } = useOffline()
  const location = useLocation()
  const navigate = useNavigate()
  const { t } = useI18n()

  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [actionError, setActionError] = useState<string | null>(null)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)
  const [exportingCsv, setExportingCsv] = useState(false)

  const [program, setProgram] = useState<Program | null>(null)
  const [sport, setSport] = useState<Sport | null>(null)
  const [levels, setLevels] = useState<Level[]>([])
  const [teams, setTeams] = useState<Team[]>([])
  const [athleteCountByLevel, setAthleteCountByLevel] = useState<Record<string, number> | null>(null)
  const [totalAthletes, setTotalAthletes] = useState<number | null>(null)
  const [totalCoaches, setTotalCoaches] = useState<number | null>(null)

  // Navigation state success message (e.g. returning from forms)
  useEffect(() => {
    if (location.state?.successMessage) {
      setSuccessMessage(location.state.successMessage)
      window.history.replaceState({}, document.title)
    }
  }, [location.state])

  const programsRoute = getLink('admin.programs.list')
  const sportsRoute = getLink('admin.sports.list')
  const levelsRoute = getLink('admin.levels.list')
  const formsRoute = getLink('admin.organization.forms')
  const structureRoute = getLink('admin.organization.structure')
  const detailRoute = getLink('admin.programs.detail', { id: programId })

  const heroImage = useMemo(() => getRandomSportImagePath(sport?.name ?? null, 'hero'), [sport?.name])
  const _updatedLabel = useMemo(() => formatUpdatedRelative(program?.updated_at), [program?.updated_at])
  void _updatedLabel

  const statusLabel = useMemo(() => {
    const activeTeams = teams.filter((t) => t.is_active !== false)
    if (activeTeams.length > 0) return 'In Season'
    if (levels.length > 0) return 'Active'
    return 'Planning'
  }, [levels.length, teams])

  const heroStats = useMemo(
    () => [
      { label: t('admin.programs.stats.levels'), value: levels.length },
      { label: t('admin.programs.stats.teams'), value: teams.length },
      { label: t('admin.programs.stats.athletes'), value: totalAthletes },
      { label: t('admin.programs.stats.coaches'), value: totalCoaches },
    ],
    [levels.length, teams.length, totalAthletes, totalCoaches, t]
  )

  const loadProgramData = useCallback(async () => {
    if (!isReady) return
    if (!programId) {
      setError('Program ID is required.')
      setLoading(false)
      return
    }

    setLoading(true)
    setError(null)
    setActionError(null)

    try {
      const [programRes, sportsRes, levelsRes, teamsRes] = await Promise.all([
        getProgram(context, programId),
        getSports(context),
        getLevels(context, programId),
        getTeams(context, { programId }),
      ])

      if (programRes.error) throw programRes.error
      if (sportsRes.error) throw sportsRes.error
      if (levelsRes.error) throw levelsRes.error
      if (teamsRes.error) throw teamsRes.error

      const foundProgram = programRes.data as Program | null
      if (!foundProgram) {
        setProgram(null)
        setSport(null)
        setLevels([])
        setTeams([])
        setError('Program not found (or you may not have access).')
        return
      }

      const allSports = Array.isArray(sportsRes.data) ? (sportsRes.data as Sport[]) : []
      const foundSport = allSports.find((s) => s.id === foundProgram.sport_id) ?? null

      setProgram(foundProgram)
      setSport(foundSport)
      setLevels(Array.isArray(levelsRes.data) ? levelsRes.data : [])
      setTeams(Array.isArray(teamsRes.data) ? teamsRes.data : [])
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load program.')
    } finally {
      setLoading(false)
    }
  }, [context, isReady, programId])

  useEffect(() => {
    loadProgramData()
  }, [loadProgramData])

  // Compute athlete counts (best effort). If offline, show as unavailable.
  useEffect(() => {
    const compute = async () => {
      setAthleteCountByLevel(null)
      setTotalAthletes(null)
      setTotalCoaches(null)

      if (!program || !programId) return
      if (isOffline) return

      // Coaches count: org coaches (program-specific assignments are not modeled in schema yet)
      try {
        const usersRes = await getOrganizationUsers(context)
        if (usersRes.error) throw usersRes.error
        const coaches = usersRes.data.filter((u) => u.roles.includes('coach')).length
        setTotalCoaches(coaches)
      } catch {
        setTotalCoaches(null)
      }

      if (teams.length === 0) {
        setAthleteCountByLevel({})
        setTotalAthletes(0)
        return
      }

      const teamsById = new Map(teams.map((t) => [t.id, t]))
      const teamIds = teams.map((t) => t.id)

      // Fake data: derive counts from active season + roster per team
      if (USE_FAKE_DATA) {
        const countsByLevel: Record<string, number> = {}
        let total = 0

        for (const team of teams) {
          const seasonRes = await getActiveSeason(context, team.id)
          if (seasonRes.error || !seasonRes.data) continue
          const rosterRes = await getTeamRoster(context, team.id, seasonRes.data.id)
          if (rosterRes.error) continue
          const count = rosterRes.data.length
          const levelId = team.level_id ?? ''
          if (levelId) countsByLevel[levelId] = (countsByLevel[levelId] || 0) + count
          total += count
        }

        setAthleteCountByLevel(countsByLevel)
        setTotalAthletes(total)
        return
      }

      // Real data: count active memberships for teams in this program.
      try {
        const { data: memberships, error: memErr } = await supabase
          .from('team_memberships' as any)
          .select('team_id, athlete_id')
          .in('team_id', teamIds as any)
          .eq('status', 'active')

        if (memErr) throw memErr

        const countsByLevel: Record<string, number> = {}
        const distinctAthletes = new Set<string>()

        for (const row of (memberships as any[]) ?? []) {
          const teamId = row.team_id as string | undefined
          const athleteId = row.athlete_id as string | undefined
          if (!teamId) continue
          const team = teamsById.get(teamId)
          const levelId = team?.level_id ?? null
          if (levelId) countsByLevel[levelId] = (countsByLevel[levelId] || 0) + 1
          if (athleteId) distinctAthletes.add(athleteId)
        }

        setAthleteCountByLevel(countsByLevel)
        setTotalAthletes(distinctAthletes.size)
      } catch {
        // Keep counts unavailable if query fails
        setAthleteCountByLevel(null)
        setTotalAthletes(null)
      }
    }

    void compute()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [program, programId, teams, isOffline])

  const levelRows: LevelRow[] = useMemo(() => {
    const teamsByLevel = new Map<string, number>()
    for (const t of teams) {
      if (!t.level_id) continue
      teamsByLevel.set(t.level_id, (teamsByLevel.get(t.level_id) || 0) + 1)
    }

    return levels.map((l) => {
      const teamCount = teamsByLevel.get(l.id) || 0
      const athleteCount = athleteCountByLevel ? athleteCountByLevel[l.id] ?? 0 : null
      return {
        id: l.id,
        name: l.name,
        teams: teamCount,
        athletes: athleteCount,
        status: teamCount > 0 ? 'active' : 'inactive',
      }
    })
  }, [athleteCountByLevel, levels, teams])

  // Navigation handlers with validation
  const handleNavigateToLevel = useCallback(
    (levelIdOrRow: string | LevelRow) => {
      const levelId = typeof levelIdOrRow === 'string' ? levelIdOrRow : levelIdOrRow.id
      if (!levelId || !levelId.trim()) {
        setActionError('Level ID is required to view level details.')
        return
      }
      const levelDetailRoute = getLink('admin.levels.detail', { id: levelId.trim() })
      navigate(levelDetailRoute)
    },
    [navigate]
  )

  const handleExportCsv = useCallback(() => {
    if (levelRows.length === 0) {
      setActionError('No levels to export.')
      return
    }

    setExportingCsv(true)
    setActionError(null)
    setSuccessMessage(null)

    try {
      const rows = levelRows.map((r) => ({
        level_id: r.id,
        level_name: r.name,
        teams: r.teams,
        athletes: r.athletes ?? '',
        status: r.status,
      }))
      const filename = `${program?.name || 'program'}-levels.csv`.replace(/[^a-z0-9.-]/gi, '_')
      const success = downloadCsv(filename, rows)
      if (success) {
        setSuccessMessage(`Exported ${levelRows.length} level(s) to ${filename}`)
        setTimeout(() => setSuccessMessage(null), 5000)
      } else {
        setActionError('Failed to export CSV. Please try again.')
      }
    } catch (err) {
      setActionError(err instanceof Error ? err.message : 'Failed to export CSV.')
    } finally {
      setExportingCsv(false)
    }
  }, [levelRows, program?.name])


  const columns = useMemo<any>(() => {
    return [
      {
        id: 'name',
        label: 'LEVEL NAME',
        cellType: 'primary',
        render: (row: any) => (
          <div className="oa-flex oa-items-center oa-gap-2">
            <span
              className="oa-body-s"
              style={{
                display: 'inline-flex',
                alignItems: 'center',
                justifyContent: 'center',
                width: 'var(--oa-space-6)',
                height: 'var(--oa-space-6)',
                borderRadius: 'var(--oa-radius-xs)',
                background: 'var(--oa-surface-panel)',
                color: 'var(--oa-theme-text-accent)',
                fontWeight: 800,
                fontStyle: 'italic',
              }}
              aria-hidden="true"
            >
              {row.name.split(' ')[0]?.slice(0, 4).toUpperCase() || 'LVL'}
            </span>
            <span className="oa-body-m" style={{ fontWeight: 700, color: 'var(--oa-n900)' }}>
              {row.name}
            </span>
          </div>
        ),
      },
      { id: 'teams', label: 'TEAMS', align: 'center', cellType: 'numeric' },
      {
        id: 'athletes',
        label: 'ATHLETES',
        align: 'center',
        cellType: 'numeric',
        render: (row: any) => (row.athletes === null ? '—' : row.athletes),
      },
      {
        id: 'status',
        label: 'STATUS',
        render: (row: any) => (
          <span
            className="oa-body-s"
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              padding: 'calc(var(--oa-space-1) + 1px) var(--oa-space-2)',
              borderRadius: 'var(--oa-radius-pill)',
              background: row.status === 'active' ? 'var(--oa-theme-surface-highlight)' : 'var(--oa-surface-panel)',
              color: row.status === 'active' ? 'var(--oa-theme-text-accent)' : 'var(--oa-n500)',
              fontWeight: 800,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
            }}
          >
            {row.status}
          </span>
        ),
      },
      {
        id: 'action',
        label: 'ACTION',
        align: 'right',
        render: (row: any) => (
          <Button
            variant="ghost"
            size="dense"
            onClick={(e: React.MouseEvent) => {
              e.stopPropagation()
              handleNavigateToLevel(row.id)
            }}
            aria-label={`View details for ${row.name}`}
          >
            View
          </Button>
        ),
      },
    ]
  }, [handleNavigateToLevel])

  if (loading) {
    return (
      <div className="oa-root">
        <OfflineBanner />
        <div style={{ padding: '24px' }}>
          <div className="oa-skeleton" style={{ height: '60px', marginBottom: '24px' }} />
          <div className="oa-skeleton" style={{ height: '300px', borderRadius: '8px', marginBottom: '32px' }} />
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px' }}>
            <div>
              <div className="oa-skeleton" style={{ height: '40px', marginBottom: '16px' }} />
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {Array.from({ length: 4 }).map((_, i) => (
                  <div key={i} className="oa-skeleton" style={{ height: '80px' }} />
                ))}
              </div>
            </div>
            <div>
              <div className="oa-skeleton" style={{ height: '40px', marginBottom: '16px' }} />
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
                {Array.from({ length: 4 }).map((_, i) => (
                  <div key={i} className="oa-skeleton" style={{ height: '100px' }} />
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="oa-root">
      <OfflineBanner />

      <div
        style={{
          maxWidth: 'calc(var(--oa-space-9) * 22.5)',
          margin: '0 auto',
          padding: 'var(--oa-space-6) var(--oa-space-4)',
        }}
      >
        <AdminPageHeader
          title={program?.name || 'Program'}
          subtitle="Program details, levels, and structure."
          breadcrumbs={[
            { label: 'Organizations', path: structureRoute },
            { label: 'Programs', path: programsRoute },
            { label: program?.name || 'Program' },
          ]}
          actions={
            <div className="oa-flex oa-flex-col sm:oa-flex-row oa-gap-2">
              <Link to={programsRoute} className="w-full sm:w-auto">
                <Button variant="ghost" disabled={loading} aria-label="Navigate back to programs list" className="w-full sm:w-auto min-h-[44px]">
                  Back to Programs
                </Button>
              </Link>
              {sport?.id ? (
                <Link
                  to={getLink('admin.sports.detail', { sport_slug: sport.slug ?? sport.id })}
                  onClick={(e: React.MouseEvent) => {
                    if (!sport.id) {
                      e.preventDefault()
                      setActionError('Sport ID is required to view sport details.')
                    }
                  }}
                  className="w-full sm:w-auto"
                >
                  <Button variant="secondary" disabled={loading || !sport.id} aria-label={`View ${sport.name} sport details`} className="w-full sm:w-auto min-h-[44px]">
                    View {sport.name}
                  </Button>
                </Link>
              ) : (
                <Link to={sportsRoute} className="w-full sm:w-auto">
                  <Button variant="secondary" disabled={loading} aria-label="Navigate to sports list" className="w-full sm:w-auto min-h-[44px]">
                    View Sports
                  </Button>
                </Link>
              )}
            </div>
          }
        />

        {successMessage && (
          <Card className="oa-mb-6" style={{ borderLeft: '3px solid var(--oa-success)' }}>
            <div className="oa-body-m" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)', color: 'var(--oa-n900)' }}>
              {successMessage}
            </div>
          </Card>
        )}

        {actionError && (
          <Card className="oa-mb-6" style={{ borderLeft: '3px solid var(--oa-danger)' }}>
            <div className="oa-body-m oa-text-danger" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)' }}>
              {actionError}
            </div>
          </Card>
        )}

        {error && (
          <Card className="oa-mb-6" style={{ borderLeft: '3px solid var(--oa-danger)' }}>
            <div className="oa-body-m oa-text-danger" style={{ padding: 'var(--oa-space-3) var(--oa-space-4)' }}>
              {error}
            </div>
            <div style={{ padding: '0 var(--oa-space-4) var(--oa-space-3)' }}>
              <Button variant="ghost" size="dense" onClick={loadProgramData} disabled={loading}>
                Retry
              </Button>
            </div>
          </Card>
        )}

        {!program ? null : (
          <>
            {/* Hero band */}
            <div
              style={{
                height: 'calc(var(--oa-space-9) * 3)',
                borderRadius: 'var(--oa-radius-l)',
                overflow: 'hidden',
                position: 'relative',
                background: 'var(--oa-n900)',
                marginBottom: 'var(--oa-space-6)',
                border: '1px solid var(--oa-n100)',
              }}
              aria-label="Program hero"
            >
              <div
                style={{
                  position: 'absolute',
                  inset: 0,
                  backgroundImage: `url(${heroImage})`,
                  backgroundSize: 'cover',
                  backgroundPosition: 'center',
                  opacity: 0.35,
                }}
              />
              <div
                style={{
                  position: 'absolute',
                  inset: 0,
                  background: 'linear-gradient(to top, var(--oa-n900), transparent)',
                  opacity: 0.9,
                }}
              />
              <div
                className="oa-flex oa-items-center"
                style={{
                  position: 'absolute',
                  inset: 0,
                  padding: '0 var(--oa-space-6)',
                }}
              >
                <div
                  className="oa-grid"
                  style={{
                    width: '100%',
                    gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
                    gap: 'var(--oa-space-6)',
                  }}
                >
                  {heroStats.map((stat) => (
                    <div
                      key={stat.label}
                      className="oa-display-xl"
                      style={{
                        display: 'flex',
                        alignItems: 'baseline',
                        color: 'var(--oa-white)',
                        fontWeight: 900,
                        letterSpacing: '-0.03em',
                        lineHeight: 1,
                        gap: '0.4em',
                      }}
                    >
                      <span style={{ textAlign: 'right' }}>
                        {formatMetric(stat.value)}
                      </span>
                      <span style={{ fontWeight: 400, opacity: 0.7 }}>{stat.label}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Main grid */}
            <div
              className="oa-grid"
              style={{
                gridTemplateColumns: 'minmax(0, 1fr)',
                alignItems: 'start',
              }}
            >
              <div
                className="oa-grid"
                style={{
                  gridTemplateColumns: 'minmax(0, 1fr)',
                  gap: 'var(--oa-space-6)',
                }}
              >
                {/* Action bar */}
                <Card className="oa-card">
                  <div className="oa-flex oa-flex-col oa-gap-4">
                    <div className="oa-flex oa-justify-between oa-items-center oa-gap-2">
                      <span className="oa-badge oa-badge--info" style={{ fontWeight: 700 }}>
                        {t('admin.programs.statusCard.statusLabel')}: {statusLabel}
                      </span>
                    </div>
                    <div className="oa-flex oa-justify-between oa-gap-2 oa-flex-wrap">
                      <div className="oa-flex oa-gap-2 oa-flex-wrap">
                        <Link
                          to={`${getLink('admin.programs.update', { id: programId })}?returnUrl=${encodeURIComponent(detailRoute)}`}
                          onClick={(e) => {
                            if (!programId) {
                              e.preventDefault()
                              setActionError('Program ID is required to edit program.')
                            }
                          }}
                          className="w-full sm:w-auto"
                        >
                          <Button
                            variant="ghost"
                            icon="edit"
                            disabled={loading || !programId}
                            aria-label={`Edit ${program?.name || 'program'}`}
                            className="w-full sm:w-auto min-h-[44px]"
                          >
                            Edit Program
                          </Button>
                        </Link>

                        <Link to={levelsRoute} className="w-full sm:w-auto">
                          <Button
                            variant="ghost"
                            disabled={loading}
                            aria-label="Navigate to all levels"
                            className="w-full sm:w-auto min-h-[44px]"
                          >
                            View Levels
                          </Button>
                        </Link>
                      </div>

                      <div className="oa-flex oa-gap-2 oa-flex-wrap">
                        <Link
                          to={`${formsRoute}?type=level&program_id=${programId}&sport_id=${program.sport_id}&returnUrl=${encodeURIComponent(detailRoute)}`}
                          className={cn(isOffline || USE_FAKE_DATA ? 'oa-disabled-link' : '', 'w-full sm:w-auto')}
                          onClick={(e) => {
                            if (isOffline || USE_FAKE_DATA) {
                              e.preventDefault()
                              setActionError(
                                isOffline
                                  ? 'You appear to be offline. Please reconnect and try again.'
                                  : 'This action is not available in demo mode. Please sign in to add levels.'
                              )
                            } else if (!programId || !program.sport_id) {
                              e.preventDefault()
                              setActionError('Program and sport information is required to add a level.')
                            }
                          }}
                        >
                          <OrgAdminButton
                            variant="primary"
                            icon="add_circle"
                            disabled={loading || isOffline || USE_FAKE_DATA || !programId || !program.sport_id}
                            title={
                              isOffline
                                ? 'Offline - cannot add levels'
                                : USE_FAKE_DATA
                                  ? 'Sign in to add levels'
                                  : !programId || !program.sport_id
                                    ? 'Missing required information'
                                    : undefined
                            }
                            aria-label="Add a new level to this program"
                            className="w-full sm:w-auto min-h-[44px]"
                          >
                            Add Level
                          </OrgAdminButton>
                        </Link>

                        <Link
                          to={`${formsRoute}?type=team&program_id=${programId}&sport_id=${program.sport_id}&returnUrl=${encodeURIComponent(detailRoute)}`}
                          className="w-full sm:w-auto"
                          onClick={(e) => {
                            if (isOffline || USE_FAKE_DATA) {
                              e.preventDefault()
                              setActionError(
                                isOffline
                                  ? 'You appear to be offline. Please reconnect and try again.'
                                  : 'This action is not available in demo mode. Please sign in to add teams.'
                              )
                            } else if (!programId || !program.sport_id) {
                              e.preventDefault()
                              setActionError('Program and sport information is required to add a team.')
                            }
                          }}
                        >
                          <Button
                            variant="secondary"
                            disabled={loading || isOffline || USE_FAKE_DATA || !programId || !program.sport_id}
                            title={
                              isOffline
                                ? 'Offline - cannot add teams'
                                : USE_FAKE_DATA
                                  ? 'Sign in to add teams'
                                  : !programId || !program.sport_id
                                    ? 'Missing required information'
                                    : undefined
                            }
                            aria-label="Add a new team to this program"
                            className="w-full sm:w-auto min-h-[44px]"
                          >
                            Add Team
                          </Button>
                        </Link>
                      </div>
                    </div>
                  </div>
                </Card>

                {/* Levels table */}
                <AnyCard
                  title="Program Levels"
                  className="oa-card oa-card--no-padding"
                  actions={
                    <Button
                      variant="ghost"
                      size="dense"
                      onClick={handleExportCsv}
                      disabled={levelRows.length === 0 || exportingCsv}
                      loading={exportingCsv}
                      title={levelRows.length === 0 ? 'No levels to export' : 'Export levels data as CSV'}
                    >
                      Export CSV
                    </Button>
                  }
                 
                >
                  <AnyTable
                    columns={columns}
                    data={levelRows}
                    onRowClick={handleNavigateToLevel}
                    emptyState={
                      <div style={{ padding: 'var(--oa-space-8) var(--oa-space-5)' }}>
                        <div className="oa-h3" style={{ textAlign: 'center', marginBottom: 'var(--oa-space-2)' }}>
                          No levels yet
                        </div>
                        <div className="oa-body-m" style={{ textAlign: 'center', color: 'var(--oa-n600)' }}>
                          Add a level to start organizing teams and eligibility.
                        </div>
                      </div>
                    }
                  />
                </AnyCard>

                <Card>
                  <h3 className="oa-card-title" style={{ marginBottom: 'var(--oa-space-3)' }}>Photos</h3>
                  <PhotoSection
                    entityType="program"
                    entityId={programId}
                    title="Program Photos"
                    context="admin"
                  />
                </Card>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { useUserContext } from '../../hooks/useUserContext'
import { useOffline } from '../../hooks/useOffline'
import { USE_FAKE_DATA } from '../../data/config'
import { getPrograms, getSportIconUrl, getSports, deleteSportIcon, updateSportCustomization, uploadSportIcon } from '../../data/services/sportsService'
import type { Program, Sport } from '../../data/types/organization'
import OfflineBanner from '../../components/admin/OfflineBanner'
import { AdminPageHeader, Button, Card } from '../../components/admin'
import { OrgAdminButton } from '../../components/admin/OrgAdminButton'
import { FileUpload } from '../../components/common/FileUpload'
import { getLink } from '../../utils/routes'
import './SportDetail.css'
import '../../styles/orgAdmin.css'

const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

// Helper to get sport cover image with fallback
const getSportCoverUrl = (sportSlug: string | null | undefined): string => {
  if (sportSlug) {
    return `/images/sports/${sportSlug}/covers/sport-cover.png`
  }
  return '/images/sports/default/covers/sport-cover.png'
}

import { useDebugLifecycle } from '../../lib/debug/integrations/useDebugLifecycle'

export default function SportDetail() {
  useDebugLifecycle('SportDetail')
  
  const { sport_slug } = useParams<{ sport_slug: string }>()
  const sportSlugParam = sport_slug?.trim() || ''

  const { context, isReady } = useUserContext()
  const { isOffline } = useOffline()

  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [actionError, setActionError] = useState<string | null>(null)
  const [successMessage, setSuccessMessage] = useState<string | null>(null)

  const [sport, setSport] = useState<Sport | null>(null)
  const [programs, setPrograms] = useState<Program[]>([])

  const [pendingColor, setPendingColor] = useState<string>('var(--org-btn-primary-bg, #137fec)')
  const [iconFile, setIconFile] = useState<File | null>(null)
  const [savingColor, setSavingColor] = useState(false)
  const [uploadingIcon, setUploadingIcon] = useState(false)
  const [deletingIcon, setDeletingIcon] = useState(false)

  const sportId = sport?.id ?? ''
  const sportsRoute = getLink('admin.sports.list')
  const programsRoute = getLink('admin.programs.list')
  const structureRoute = getLink('admin.organization.structure')
  const formsRoute = getLink('admin.organization.forms')
  const detailRoute = getLink('admin.sports.detail', { sport_slug: sport?.slug ?? sport?.id ?? sportSlugParam })

  const iconUrl = useMemo(() => getSportIconUrl(sport?.icon ?? null), [sport?.icon])
  // Check if the icon is a Material Icon name (no slashes or dots)
  const isMaterialIcon = sport?.icon && !sport.icon.includes('/') && !sport.icon.includes('.')
  const isColorDirty = useMemo(() => (sport?.color ?? 'var(--org-btn-primary-bg, #137fec)') !== pendingColor, [sport?.color, pendingColor])

  useEffect(() => {
    if (!isReady) return
    if (!sportSlugParam) {
      setError('Sport is required.')
      setLoading(false)
      return
    }

    const load = async () => {
      setLoading(true)
      setError(null)

      try {
        const sportsResult = await getSports(context)
        if (sportsResult.error) throw sportsResult.error

        const allSports = Array.isArray(sportsResult.data) ? (sportsResult.data as Sport[]) : []
        const isUuid = UUID_REGEX.test(sportSlugParam)
        const found =
          allSports.find((s) => s.slug === sportSlugParam || s.id === sportSlugParam) ??
          (isUuid ? allSports.find((s) => s.id === sportSlugParam) : null)
        if (!found) {
          setSport(null)
          setPrograms([])
          setError('Sport not found (or you may not have access).')
          return
        }

        const programsResult = await getPrograms(context, found.id)
        if (programsResult.error) throw programsResult.error

        setSport(found)
        setPendingColor(found.color || 'var(--org-btn-primary-bg, #137fec)')
        setPrograms(Array.isArray(programsResult.data) ? (programsResult.data as Program[]) : [])
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load sport.')
      } finally {
        setLoading(false)
      }
    }

    load()
  }, [context, isReady, sportSlugParam])

  // Cover image URL with fallback
  const [coverError, setCoverError] = useState(false)
  const coverUrl = useMemo(() => {
    if (coverError) return '/images/sports/default/covers/sport-cover.png'
    return getSportCoverUrl(sport?.slug)
  }, [sport?.slug, coverError])

  const refreshSport = async () => {
    if (!sport?.id) return
    const sportsResult = await getSports(context)
    if (sportsResult.error) throw sportsResult.error
    const allSports = Array.isArray(sportsResult.data) ? (sportsResult.data as Sport[]) : []
    const found = allSports.find((s) => s.id === sport.id) ?? null
    setSport(found)
    if (found) setPendingColor(found.color || 'var(--org-btn-primary-bg, #137fec)')
  }

  if (loading) {
    return (
      <div className="oa-root sport-detail-page">
        <OfflineBanner />
        <div className="sport-detail-loading">
          <div className="oa-skeleton" style={{ height: '60px' }} />
          <div className="oa-skeleton" style={{ height: '400px' }} />
          <div className="sport-detail-skeleton-grid">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '120px' }} />
            ))}
          </div>
          <div className="sport-detail-skeleton-cards">
            {Array.from({ length: 2 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '300px' }} />
            ))}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="oa-root sport-detail-page">
      <OfflineBanner />
      
      {/* Hero section with cover image — theme overlay for contrast */}
      <div className="sport-detail-hero">
        <div 
          className="sport-detail-hero-background"
          style={{ backgroundImage: `url(${coverUrl})` }}
        >
          <img 
            src={getSportCoverUrl(sport?.slug)} 
            alt="" 
            style={{ display: 'none' }} 
            onError={() => setCoverError(true)}
          />
        </div>
        <div className="sport-detail-hero-overlay" />
        <div className="sport-detail-hero-content"
        >
          <AdminPageHeader
            title={<span className="sport-detail-hero-title">{sport?.name || 'Sport'}</span>}
            subtitle="Sport details, customizations, and related programs."
            breadcrumbs={[
              { label: 'Organizations', path: structureRoute },
              { label: 'Sports', path: sportsRoute },
              { label: sport?.name || 'Sport' },
            ]}
            actions={
              <div className="oa-flex oa-flex-col sm:oa-flex-row oa-gap-2">
                <Link to={sportsRoute} className="sport-detail-hero-link sport-detail-hero-link--ghost w-full sm:w-auto">
                  <Button variant="ghost" className="w-full sm:w-auto min-h-[44px]">Back to Sports</Button>
                </Link>
                <Link to={sport?.slug ? getLink('admin.programs.bySport', { sport_slug: sport.slug }) : `${programsRoute}?sport_id=${sportId}`} className="w-full sm:w-auto">
                  <Button variant="secondary" className="w-full sm:w-auto min-h-[44px]">View {sport?.name || ''} Programs</Button>
                </Link>
                <Link to={`${formsRoute}?type=program&sport_id=${sportId}&returnUrl=${encodeURIComponent(sport?.slug ? getLink('admin.programs.bySport', { sport_slug: sport.slug }) : programsRoute)}`} className="w-full sm:w-auto">
                  <OrgAdminButton variant="primary" className="w-full sm:w-auto min-h-[44px]">Add Program</OrgAdminButton>
                </Link>
              </div>
            }
          />
        </div>
      </div>

      {successMessage && (
        <Card className="oa-mb-6 sport-detail-alert sport-detail-alert--success">
          <div className="oa-body-m sport-detail-alert-text sport-detail-alert-text--success">
            {successMessage}
          </div>
        </Card>
      )}

      {actionError && (
        <Card className="oa-mb-6 sport-detail-alert sport-detail-alert--error">
          <div className="oa-body-m sport-detail-alert-text sport-detail-alert-text--error">
            {actionError}
          </div>
        </Card>
      )}

      {error && (
        <Card className="oa-mb-6 sport-detail-alert sport-detail-alert--error">
          <div className="oa-body-m sport-detail-alert-text sport-detail-alert-text--error">
            {error}
          </div>
        </Card>
      )}

      {!sport ? null : (
        <div className="sport-detail-grid">
          {false && (
          <div className="oa-card sport-detail-card">
            <div className="oa-card-header">
              <h3 className="oa-card-title">Customization</h3>
            </div>
            <div className="oa-flex oa-flex-col sm:oa-flex-row oa-items-start oa-gap-4" style={{ alignItems: 'flex-start' }}>
              <div style={{ width: '96px', flexShrink: 0 }}>
                <div className="oa-text-sm oa-text-muted sport-detail-label" style={{ marginBottom: '8px' }}>Icon</div>
                <div
                  className="sport-detail-icon-box"
                  style={{
                    width: '96px',
                    height: '96px',
                    borderRadius: '12px',
                    border: '1px solid var(--org-border-default, var(--oa-n200))',
                    background: 'var(--org-surface-section, var(--oa-n50))',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    overflow: 'hidden',
                  }}
                >
                  {iconUrl ? (
                    <img src={iconUrl || undefined} alt={`${sport?.name || 'Sport'} icon`} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                  ) : isMaterialIcon ? (
                    <span className="material-symbols-outlined" style={{ fontSize: '48px', color: pendingColor }}>{sport?.icon}</span>
                  ) : (
                    <span className="material-symbols-outlined" style={{ fontSize: '36px', color: 'var(--oa-n400)' }}>sports</span>
                  )}
                </div>
              </div>

              <div className="oa-flex-1">
                <div className="oa-text-sm oa-text-muted sport-detail-label" style={{ marginBottom: '8px' }}>Sport Color</div>
                <div className="oa-flex oa-items-center oa-gap-3" style={{ marginBottom: '12px' }}>
                  <input
                    type="color"
                    value={pendingColor}
                    onChange={(e) => {
                      setPendingColor(e.target.value)
                      setActionError(null)
                      setSuccessMessage(null)
                    }}
                    aria-label="Sport color"
                    style={{ width: '44px', height: '36px' }}
                    disabled={isOffline || USE_FAKE_DATA}
                  />
                  <div className="oa-text-sm oa-text-muted">{pendingColor}</div>
                  <Button
                    variant="secondary"
                    disabled={!isColorDirty || savingColor || isOffline || USE_FAKE_DATA}
                    loading={savingColor}
                    onClick={async () => {
                      setActionError(null)
                      setSuccessMessage(null)

                      if (isOffline) {
                        setActionError('You appear to be offline. Please reconnect and try again.')
                        return
                      }
                      if (USE_FAKE_DATA) {
                        setActionError('This action is not available in demo mode. Please sign in to customize sports.')
                        return
                      }

                      setSavingColor(true)
                      try {
                        const result = await updateSportCustomization(context, sportId, { color: pendingColor })
                        if (result.error) {
                          setActionError(result.error.message || 'Failed to save sport color.')
                        } else {
                          await refreshSport()
                          setSuccessMessage('Sport color updated.')
                        }
                      } catch (err) {
                        setActionError(err instanceof Error ? err.message : 'Failed to save sport color.')
                      } finally {
                        setSavingColor(false)
                      }
                    }}
                    className="min-h-[44px]"
                  >
                    Save Color
                  </Button>
                </div>

                <div className="oa-form-group">
                  <FileUpload
                    label="Upload Icon"
                    accept="image/png,image/jpeg,image/jpg,image/webp,image/svg+xml"
                    maxSize={5 * 1024 * 1024}
                    helperText="Upload a custom icon for this sport. PNG, JPEG, WebP, or SVG. Max 5MB."
                    value={iconFile}
                    onFileSelect={(file) => {
                      setIconFile(file)
                      setActionError(null)
                      setSuccessMessage(null)
                    }}
                    disabled={uploadingIcon || deletingIcon || isOffline || USE_FAKE_DATA}
                    buttonText="Choose file"
                    replaceText="Replace file"
                  />
                </div>

                <div className="oa-flex oa-flex-col sm:oa-flex-row oa-gap-2" style={{ marginTop: '12px' }}>
                  <Button
                    disabled={!iconFile || uploadingIcon || isOffline || USE_FAKE_DATA}
                    loading={uploadingIcon}
                    className="w-full sm:w-auto min-h-[44px]"
                    onClick={async () => {
                      if (!iconFile) return

                      setActionError(null)
                      setSuccessMessage(null)

                      if (isOffline) {
                        setActionError('You appear to be offline. Please reconnect and try again.')
                        return
                      }
                      if (USE_FAKE_DATA) {
                        setActionError('This action is not available in demo mode. Please sign in to customize sports.')
                        return
                      }

                      setUploadingIcon(true)
                      try {
                        const uploadResult = await uploadSportIcon(context, sportId, iconFile)
                        if (uploadResult.error) {
                          setActionError(uploadResult.error.message || 'Failed to upload icon.')
                        } else {
                          await refreshSport()
                          setIconFile(null)
                          setSuccessMessage('Icon uploaded.')
                        }
                      } catch (err) {
                        setActionError(err instanceof Error ? err.message : 'Failed to upload icon.')
                      } finally {
                        setUploadingIcon(false)
                      }
                    }}
                  >
                    Upload Icon
                  </Button>

                  <Button
                    variant="danger"
                    disabled={!sport?.icon || deletingIcon || isOffline || USE_FAKE_DATA}
                    loading={deletingIcon}
                    onClick={async () => {
                      setActionError(null)
                      setSuccessMessage(null)

                      if (isOffline) {
                        setActionError('You appear to be offline. Please reconnect and try again.')
                        return
                      }
                      if (USE_FAKE_DATA) {
                        setActionError('This action is not available in demo mode. Please sign in to customize sports.')
                        return
                      }

                      setDeletingIcon(true)
                      try {
                        const result = await deleteSportIcon(context, sportId)
                        if (result.error) {
                          setActionError(result.error.message || 'Failed to delete icon.')
                        } else {
                          await refreshSport()
                          setSuccessMessage('Icon removed.')
                        }
                      } catch (err) {
                        setActionError(err instanceof Error ? err.message : 'Failed to delete icon.')
                      } finally {
                        setDeletingIcon(false)
                      }
                    }}
                  >
                    Remove Icon
                  </Button>

                  <Link to={`${getLink('admin.sports.update', { sport_id: sport?.id || sportId })}?returnUrl=${encodeURIComponent(detailRoute)}`} className="w-full sm:w-auto">
                    <Button variant="secondary" className="w-full sm:w-auto min-h-[44px]">Edit Sport</Button>
                  </Link>
                </div>
              </div>
            </div>
          </div>
          )}

          <div className="oa-card oa-card--no-padding sport-detail-card">
            <div className="oa-card-header">
              <h3 className="oa-card-title sport-detail-programs-title">
                Programs
                <span className="sport-detail-badge" aria-label={`${programs.length} programs`}>
                  {programs.length}
                </span>
              </h3>
            </div>
            {programs.length === 0 ? (
              <div className="sport-detail-empty oa-p-5">
                No programs yet for this sport. Create one to start building out levels and teams.
              </div>
            ) : (
              <div className="oa-stacked-list sport-detail-program-list">
                {programs.map((p) => (
                  <Link
                    key={p.id}
                    to={getLink('admin.programs.detail', { id: p.id })}
                    className="oa-stacked-list-row sport-detail-program-row"
                  >
                    <div className="oa-stacked-list-row-content">
                      <div>
                        <div className="oa-stacked-list-row-title sport-detail-program-name">{p.name}</div>
                        <div className="oa-stacked-list-row-meta sport-detail-program-meta">{p.gender_category}</div>
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { useNavigate, Link, useSearchParams } from 'react-router-dom'
import { useUserContext } from '../../hooks/useUserContext'
import { useTeamParams } from '../../hooks/useRouteParams'
import { getTeamDetails, getTeamRoster } from '../../data/services/teamsService'
import { supabase } from '../../lib/supabase'
import { getLink } from '../../utils/routes'
import type { FakeTeamMember } from '../../data/fake/fakeTeams'
import { Button } from '../../components/admin'
import { OrgAdminButton } from '../../components/admin/OrgAdminButton'
import { AddExistingAthleteModal } from '../../components/admin/AddExistingAthleteModal'
import { EmptyRosterState } from '../../components/admin/EmptyRosterState'
import OfflineBanner from '../../components/admin/OfflineBanner'
import { TeamOverviewTab } from '../../components/admin/TeamOverviewTab'
import { TeamScheduleTab } from '../../components/admin/TeamScheduleTab'
import { TeamAttendanceTab } from '../../components/admin/TeamAttendanceTab'
import { TeamPaymentsTab } from '../../components/admin/TeamPaymentsTab'
import { TeamSettingsTab } from '../../components/admin/TeamSettingsTab'
import { PhotoSection } from '@/components/galleries/PhotoSection'
import '../../styles/orgAdmin.css'

interface Team {
  id: string
  name: string
  sport?: { name: string; id?: string }
  program?: { name: string; id?: string }
  level?: { name: string; id?: string }
  max_roster_size?: number
}

interface Season {
  id: string
  name: string
  start_date: string
  end_date: string
  is_active: boolean
}

interface RosterMember {
  id: string
  athlete_id: string
  athlete?: {
    id: string
    first_name: string
    last_name: string
    jersey_number: string | null
  }
  jersey_number?: string | null
  position?: string | null
  status: 'active' | 'inactive' | 'pending'
}

import { useDebugLifecycle } from '../../lib/debug/integrations/useDebugLifecycle'

export default function TeamDetail() {
  useDebugLifecycle('TeamDetail')
  const { teamId } = useTeamParams()
  const [team, setTeam] = useState<Team | null>(null)
  const [activeSeason, setActiveSeason] = useState<Season | null>(null)
  const [roster, setRoster] = useState<RosterMember[]>([])
  const [loading, setLoading] = useState(true)
  const [rosterLoading, setRosterLoading] = useState(false)
  const [searchParams, setSearchParams] = useSearchParams()
  const activeTab = searchParams.get('tab') || 'overview'
  const [navigating, setNavigating] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [teamStats, setTeamStats] = useState({
    totalAthletes: 0,
    activeAthletes: 0,
    vacancies: 0,
    rank: 1,
  })
  const [showAddExistingModal, setShowAddExistingModal] = useState(false)

  const { context, isReady } = useUserContext()
  const navigate = useNavigate()
  const isMountedRef = useRef(true)

  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
    }
  }, [])

  const fetchTeamAndSeasons = useCallback(async () => {
    console.log('[TeamDetail] fetchTeamAndSeasons called:', { teamId, isReady, orgId: context.orgId })
    
    if (!teamId || !isReady) {
      console.log('[TeamDetail] Early return - teamId or not ready')
      setLoading(false)
      return
    }

    setLoading(true)
    setError(null)
    try {
      const { data: teamData, error: teamError } = await getTeamDetails(context, teamId)
      
      console.log('[TeamDetail] getTeamDetails response:', { 
        hasTeamData: !!teamData, 
        teamError: teamError ? { message: teamError.message } : null 
      })

      if (teamError || !teamData) {
        console.error('Error fetching team:', {
          teamError,
          teamId,
          orgId: context.orgId,
          hasData: !!teamData,
          errorMessage: teamError?.message
        })
        if (isMountedRef.current) {
          // Provide more specific error message
          const errorMessage = teamError?.message || 'Team not found. The team may not exist or you may not have permission to view it.'
          setError(errorMessage)
          setLoading(false)
        }
        return
      }

      if (!isMountedRef.current) {
        setLoading(false)
        return
      }

      const teamInfo = {
        id: teamData.id,
        name: teamData.name,
        sport: (teamData as any).sport,
        program: (teamData as any).program,
        level: (teamData as any).level,
        max_roster_size: (teamData as any).max_roster_size,
      }
      setTeam(teamInfo)

      // Get seasons for this team
      let activeSeason: Season | null = null
      
      if (teamData.seasons && teamData.seasons.length > 0) {
        const seasonList = teamData.seasons.map((s: any) => ({
          id: s.id,
          name: s.name,
          start_date: s.start_date,
          end_date: s.end_date,
          is_active: s.is_active,
        }))
        activeSeason = seasonList.find((s: Season) => s.is_active) || seasonList[0]
      } else {
        // Try to fetch seasons directly
        const { data: seasonsData, error: seasonsError } = await supabase
          .from('team_seasons')
          .select('season:seasons(id, name, start_date, end_date, is_active)')
          .eq('team_id', teamId)

        if (seasonsError) {
          console.error('Error fetching seasons:', seasonsError)
        } else if (seasonsData && seasonsData.length > 0) {
          const seasonList = seasonsData.map((s: any) => ({
            id: s.season.id,
            name: s.season.name,
            start_date: s.season.start_date,
            end_date: s.season.end_date,
            is_active: s.season.is_active,
          }))
          activeSeason = seasonList.find((s: Season) => s.is_active) || seasonList[0]
        }
      }

      // Set active season - this will trigger the useEffect to fetch roster
      if (activeSeason) {
        setActiveSeason(activeSeason)
      } else {
        // No season found, ensure loading is set to false
        if (isMountedRef.current) {
          setLoading(false)
        }
      }
    } catch (error) {
      console.error('Error in fetchTeamAndSeasons:', error)
      if (isMountedRef.current) {
        setError(error instanceof Error ? error.message : 'An unexpected error occurred')
        setLoading(false)
      }
    }
  }, [teamId, context, isReady])

  const fetchRoster = useCallback(
    async (seasonId: string) => {
      if (!teamId || !isReady || !seasonId) {
        setRosterLoading(false)
        return
      }

      setRosterLoading(true)
      try {
        const { data, error } = await getTeamRoster(context, teamId, seasonId)

        if (error) {
          console.error('Error fetching roster:', error)
          if (isMountedRef.current) {
            setRoster([])
            setRosterLoading(false)
          }
          return
        }

        if (!isMountedRef.current) {
          setRosterLoading(false)
          return
        }

        // Transform roster data
        const rosterMembers: RosterMember[] = (data || []).map((member: FakeTeamMember) => ({
          id: member.id,
          athlete_id: member.athlete_id ?? (member as { child_id?: string }).child_id,
          jersey_number: member.jersey_number,
          position: member.position,
          status: member.status,
        }))

        // Fetch athlete details for each member
        const athleteIds = rosterMembers.map((m) => m.athlete_id).filter(Boolean)
        if (athleteIds.length > 0) {
          const { data: athletesData, error: athletesError } = await supabase
            .from('athletes')
            .select('id, first_name, last_name')
            .in('id', athleteIds)

          if (!athletesError && athletesData && Array.isArray(athletesData)) {
            const athleteMap = new Map(
              (athletesData as any[]).map((a) => [a.id, { id: a.id, first_name: a.first_name, last_name: a.last_name, jersey_number: null }])
            )

            rosterMembers.forEach((member) => {
              const athlete = athleteMap.get(member.athlete_id)
              if (athlete) {
                member.athlete = athlete
                // Use jersey_number from athlete if not in membership
                if (!member.jersey_number && athlete.jersey_number) {
                  member.jersey_number = athlete.jersey_number
                }
              }
            })
          }
        }

        if (isMountedRef.current) {
          setRoster(rosterMembers)

          // Calculate stats - use current team state or fallback
          const currentTeam = team || { max_roster_size: 18 }
          const activeCount = rosterMembers.filter((m) => m.status === 'active').length
          setTeamStats({
            totalAthletes: rosterMembers.length,
            activeAthletes: activeCount,
            vacancies: Math.max(0, (currentTeam.max_roster_size || 18) - activeCount),
            rank: 1, // TODO: Calculate actual rank
          })
        }
      } catch (error) {
        console.error('Error in fetchRoster:', error)
        if (isMountedRef.current) {
          setRoster([])
        }
      } finally {
        if (isMountedRef.current) {
          setRosterLoading(false)
          // Also ensure main loading is false after roster loads
          setLoading(false)
        }
      }
    },
    [teamId, context, isReady, team]
  )

  useEffect(() => {
    if (teamId && isReady) {
      fetchTeamAndSeasons()
    } else if (!isReady) {
      setLoading(true)
    } else {
      setLoading(false)
    }
  }, [teamId, isReady, fetchTeamAndSeasons])

  useEffect(() => {
    if (activeSeason && teamId && isReady) {
      fetchRoster(activeSeason.id)
    }
  }, [activeSeason, teamId, isReady, fetchRoster])

  // Initialize tab from URL on mount
  useEffect(() => {
    const tabParam = searchParams.get('tab')
    if (tabParam && ['overview', 'roster', 'schedule', 'attendance', 'payments', 'settings', 'galleries'].includes(tabParam)) {
      // Tab is already set in URL, no need to update
    } else if (!tabParam) {
      // No tab in URL, set default to overview
      const newSearchParams = new URLSearchParams(searchParams)
      newSearchParams.set('tab', 'overview')
      setSearchParams(newSearchParams, { replace: true })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []) // Only run on mount - intentionally excluding searchParams/setSearchParams to avoid loops

  const getInitials = (firstName: string, lastName: string): string => {
    return `${firstName.charAt(0)}${lastName.charAt(0)}`.toUpperCase()
  }

  const handleAddAthlete = useCallback(() => {
    if (!teamId || navigating) return

    setNavigating(true)
    navigate(`/admin/teams/${teamId}/roster`)
  }, [teamId, navigate, navigating])

  const handleAddExistingAthlete = useCallback(() => {
    if (!teamId || navigating) return
    setShowAddExistingModal(true)
  }, [teamId, navigating])

  const handleAddExistingSuccess = useCallback(() => {
    // Refresh roster after adding athletes
    if (activeSeason) {
      fetchRoster(activeSeason.id)
    }
  }, [activeSeason, fetchRoster])

  // Check if user is org admin
  const isOrgAdmin = context.roles.includes('org_admin')

  const handleAthleteClick = useCallback(
    (athleteId: string) => {
      if (!athleteId || navigating) return

      setNavigating(true)
      navigate(getLink('admin.athletes.detail', { id: athleteId }))
    },
    [navigate, navigating]
  )

  const handleTabChange = useCallback(
    (tab: string) => {
      if (navigating) return

      // Update URL with tab state while preserving team context
      const newSearchParams = new URLSearchParams(searchParams)
      newSearchParams.set('tab', tab)
      setSearchParams(newSearchParams, { replace: true })
    },
    [searchParams, setSearchParams, navigating]
  )

  const handleBreadcrumbClick = useCallback(
    (path: string, id?: string) => {
      if (navigating || !path) return

      setNavigating(true)
      if (id) {
        navigate(`${path}/${id}`)
      } else {
        navigate(path)
      }
    },
    [navigate, navigating]
  )

  if (loading) {
    return (
      <div className="oa-root">
        <OfflineBanner />
        <div style={{ padding: '24px' }}>
          <div className="oa-skeleton" style={{ height: '60px', marginBottom: '24px' }} />
          <div className="oa-skeleton" style={{ height: '200px', borderRadius: '8px', marginBottom: '24px' }} />
          <div style={{ display: 'flex', gap: '12px', marginBottom: '24px' }}>
            {Array.from({ length: 3 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '40px', width: '100px' }} />
            ))}
          </div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))', gap: '16px' }}>
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="oa-skeleton" style={{ height: '250px' }} />
            ))}
          </div>
        </div>
      </div>
    )
  }

  if (!team) {
    return (
      <div className="oa-root">
        <div className="oa-page-header">
          <h1 className="oa-page-title">Team not found</h1>
          {error && <p className="oa-body-m" style={{ color: 'var(--oa-danger)', marginTop: 'var(--oa-space-2)' }}>{error}</p>}
          <div style={{ marginTop: 'var(--oa-space-4)' }}>
            <OrgAdminButton variant="primary" onClick={() => navigate(getLink('admin.teams.list'))}>
              Back to Teams
            </OrgAdminButton>
          </div>
        </div>
      </div>
    )
  }

  const sportName = team.sport?.name || ''
  const programName = team.program?.name || ''
  const levelName = team.level?.name || ''
  const sportId = team.sport?.id
  const programId = team.program?.id

  // Get primary color for court texture and accents
  // Use CSS variable with fallback to ensure it works even if theme not loaded
  const primaryColor = 'var(--oa-theme-action-primary, var(--org-btn-primary-bg, #137fec))'

  return (
    <div className="oa-root">
      {/* Header */}
      <div
        style={{
          width: '100%',
          position: 'relative',
        }}
      >
        {/* Header content constrained to main content width */}
        <div
          style={{
            maxWidth: '1200px',
            margin: '0 auto',
            width: '100%',
            padding: 'var(--oa-space-6) var(--oa-space-4)',
          }}
          className="md:px-8"
        >
          {/* Breadcrumbs */}
          <div
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'center',
              gap: 'var(--oa-space-2)',
              marginBottom: 'var(--oa-space-4)',
            }}
          >
            {sportName && (
              <>
                {sportId ? (
                  <button
                    onClick={() => handleBreadcrumbClick('/admin/sports', sportId)}
                    disabled={navigating}
                    style={{
                      fontSize: '12px',
                      fontWeight: 500,
                      textTransform: 'uppercase',
                      letterSpacing: '0.05em',
                      textDecoration: 'none',
                      background: 'none',
                      border: 'none',
                      cursor: navigating ? 'not-allowed' : 'pointer',
                      opacity: navigating ? 0.6 : 1,
                      padding: 0,
                      lineHeight: 'normal',
                    }}
                    className="text-[var(--org-text-muted)] dark:text-slate-400"
                  >
                    {sportName}
                  </button>
                ) : (
                  <Link
                    to={getLink('admin.sports.list')}
                    style={{
                      fontSize: '12px',
                      fontWeight: 500,
                      textTransform: 'uppercase',
                      letterSpacing: '0.05em',
                      textDecoration: 'none',
                      lineHeight: 'normal',
                    }}
                    className="text-[var(--org-text-muted)] dark:text-slate-400"
                  >
                    {sportName}
                  </Link>
                )}
                <span style={{ fontSize: '12px', fontWeight: 500, lineHeight: 'normal' }} className="text-[var(--org-text-muted)] dark:text-slate-400">/</span>
              </>
            )}
            {programName && (
              <>
                {programId ? (
                  <button
                    onClick={() => handleBreadcrumbClick('/admin/programs', programId)}
                    disabled={navigating}
                    style={{
                      fontSize: '12px',
                      fontWeight: 500,
                      textTransform: 'uppercase',
                      letterSpacing: '0.05em',
                      textDecoration: 'none',
                      background: 'none',
                      border: 'none',
                      cursor: navigating ? 'not-allowed' : 'pointer',
                      opacity: navigating ? 0.6 : 1,
                      padding: 0,
                      lineHeight: 'normal',
                    }}
                    className="text-[var(--org-text-muted)] dark:text-slate-400"
                  >
                    {programName}
                  </button>
                ) : (
                  <Link
                    to={getLink('admin.programs.list')}
                    style={{
                      fontSize: '12px',
                      fontWeight: 500,
                      textTransform: 'uppercase',
                      letterSpacing: '0.05em',
                      textDecoration: 'none',
                      lineHeight: 'normal',
                    }}
                    className="text-[var(--org-text-muted)] dark:text-slate-400"
                  >
                    {programName}
                  </Link>
                )}
                <span style={{ fontSize: '12px', fontWeight: 500, lineHeight: 'normal' }} className="text-[var(--org-text-muted)] dark:text-slate-400">/</span>
              </>
            )}
            {levelName && (
              <>
                <span
                  style={{
                    fontSize: '12px',
                    fontWeight: 500,
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                    lineHeight: 'normal',
                  }}
                  className="text-[var(--org-text-muted)] dark:text-slate-400"
                >
                  {levelName}
                </span>
                <span style={{ fontSize: '12px', fontWeight: 500, lineHeight: 'normal' }} className="text-[var(--org-text-muted)] dark:text-slate-400">/</span>
              </>
            )}
            {team && (
              <span
                style={{
                  fontSize: '12px',
                  fontWeight: 500,
                  textTransform: 'uppercase',
                  letterSpacing: '0.05em',
                  lineHeight: 'normal',
                }}
                className="text-[var(--org-text-muted)] dark:text-slate-400"
              >
                {team.name}
              </span>
            )}
          </div>

          {/* Page title with optional icon */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--oa-space-4)', marginBottom: 'var(--oa-space-6)' }}>
            <span
              className="material-symbols-outlined text-[var(--org-btn-secondary-bg)] dark:text-slate-400"
              style={{
                fontSize: '32px',
                fontVariationSettings: "'FILL' 1"
              }}
            >
              groups
            </span>
            <h1
              style={{
                fontFamily: 'var(--oa-font-display)',
                fontSize: 'clamp(2rem, 4vw, 3rem)',
                fontWeight: 700,
                lineHeight: 1.2,
                margin: 0,
              }}
              className="text-[var(--org-text-primary)] dark:text-white"
            >
              {team.name}
            </h1>
          </div>

          {/* Action buttons */}
          <div style={{ display: 'flex', gap: 'var(--oa-space-3)' }}>
            {isOrgAdmin && (
              <Button
                onClick={handleAddExistingAthlete}
                disabled={!teamId || navigating || loading || !activeSeason}
                variant="secondary"
                icon="group_add"
              >
                ADD EXISTING
              </Button>
            )}
            <Button
              onClick={handleAddAthlete}
              disabled={!teamId || navigating || loading}
              loading={navigating}
              icon="person_add"
            >
              ADD ATHLETE
            </Button>
          </div>
        </div>
      </div>

      {/* Main content area */}
      <div
        style={{
          maxWidth: '1200px',
          margin: '0 auto',
          width: '100%',
          padding: 'var(--oa-space-6) var(--oa-space-4)',
        }}
        className="md:px-8"
      >

        {/* Navigation Tabs */}
        <div style={{ marginBottom: 'var(--oa-space-6)' }}>
          <div
            style={{
              display: 'flex',
              borderBottom: '1px solid var(--oa-n200)',
              gap: 'var(--oa-space-8)',
              overflowX: 'auto',
            }}
            className="dark:border-slate-700"
          >
            {['overview', 'roster', 'schedule', 'attendance', 'payments', 'settings', 'galleries'].map((tab) => (
              <button
                key={tab}
                onClick={() => handleTabChange(tab)}
                disabled={navigating}
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderBottom: activeTab === tab ? `4px solid ${primaryColor}` : '4px solid transparent',
                  paddingBottom: '14px',
                  paddingTop: 'var(--oa-space-4)',
                  fontSize: '14px',
                  fontWeight: 900,
                  textTransform: 'uppercase',
                  letterSpacing: '0.15em',
                  background: 'none',
                  borderTop: 'none',
                  borderLeft: 'none',
                  borderRight: 'none',
                  cursor: navigating ? 'not-allowed' : 'pointer',
                  transition: 'color 200ms',
                  opacity: navigating ? 0.6 : 1,
                }}
