              {{#if items}}
              <div class="receipt-box">
                <h3>Items Purchased</h3>
                {{#each items}}
                <p>&#123;&#123;name&#125;&#125; - $&#123;price&#125;</p>
                {{/each}}
              </div>
              {{/if}}
              <div style="text-align: center; margin: 30px 0;">
                <a href="{{url}}" class="button">View Receipt</a>
              </div>
              <p>If you have any questions about this payment, please contact your organization administrator.</p>
              <div class="footer">
                You're receiving this email because you're part of {{organization_name}} on YouthSports Team Hub.<br>
                <a href="{{unsubscribe_url}}">Unsubscribe</a> | <a href="{{preferences_url}}">Email Preferences</a><br>
                © 2026 YouthSports Team Hub. All rights reserved.
              </div>
            </div>
          </body>
        </html>
      `
    };

    return templates[type] || '';
  };

  // Helper function to inject variables
  const injectVariables = (template: string, variables: Record<string, any>): string => {
    let result = template;

    // Handle simple variable replacement
    for (const [key, value] of Object.entries(variables)) {
      const regex = new RegExp(`{{${key}}}`, 'g');
      result = result.replace(regex, String(value));
    }

    // Handle conditional blocks (basic handlebars-style)
    result = result.replace(/{{#if\s+(\w+)}}(.*?){{\/if}}/gs, (_match, condition, content) => {
      return variables[condition] ? content : '';
    });

    // Handle each loops (basic)
    result = result.replace(/{{#each\s+(\w+)}}(.*?){{\/each}}/gs, (_match, arrayName, content) => {
      const array = variables[arrayName];
      if (!Array.isArray(array)) return '';

      return array.map(item => {
        let itemContent = content;
        for (const [key, value] of Object.entries(item)) {
          itemContent = itemContent.replace(new RegExp(`{{${key}}}`, 'g'), String(value));
        }
        return itemContent;
      }).join('');
    });

    return result;
  };

  const handleTemplateChange = (templateType: string) => {
    const template = EMAIL_TEMPLATES.find(t => t.type === templateType);
    if (template) {
      setSelectedTemplate(template);
      setPayload(JSON.stringify(template.samplePayload, null, 2));
    }
  };

  const generatePreview = async () => {
    if (!selectedTemplate) return;

    setIsLoading(true);
    try {
      let parsedPayload;
      try {
        parsedPayload = JSON.parse(payload);
      } catch (e) {
        showError('Invalid JSON payload');
        return;
      }

      // For dev preview, we'll use a simple template injection
      // In production, this would be handled server-side
      const templateHtml = getTemplateHtml(selectedTemplate.type);
      const injectedHtml = injectVariables(templateHtml, parsedPayload);

      setPreviewHtml(injectedHtml);
    } catch (error) {
      console.error('Preview generation failed:', error);
      showError('Failed to generate preview');
    } finally {
      setIsLoading(false);
    }
  };

  const sendTestEmail = async () => {
    if (!selectedTemplate) return;

    setIsSending(true);
    try {
      let parsedPayload;
      try {
        parsedPayload = JSON.parse(payload);
      } catch (e) {
        showError('Invalid JSON payload');
        return;
      }

      // Get current user's email
      const { data: { user } } = await supabase.auth.getUser();
      if (!user?.email) {
        showError('No user email found');
        return;
      }

      // Insert notification job
      const { error } = await supabase
        .from('notification_jobs' as any)
        .insert({
          org_id: '00000000-0000-0000-0000-000000000000', // Placeholder org ID
          user_id: user.id,
          email: user.email,
          type: selectedTemplate.type,
          payload: parsedPayload
        });

      if (error) {
        console.error('Failed to create notification job:', error);
        showError('Failed to queue email');
        return;
      }

      showSuccess('Test email queued successfully!');

      // In development, we could trigger the worker manually
      // For now, just show success message

    } catch (error) {
      console.error('Failed to send test email:', error);
        showError('Failed to send test email');
    } finally {
      setIsSending(false);
    }
  };

  if (import.meta.env.PROD) {
    return (
      <div className="p-6">
        <Card>
          <CardHeader>
            <CardTitle>Email Preview</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-red-600">Email preview is only available in development mode.</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Email Template Preview</CardTitle>
          <p className="text-sm text-gray-600">
            Preview and test email templates. Only available in development mode.
          </p>
        </CardHeader>
        <CardContent className="space-y-4">
          <div>
            <label className="block text-sm font-medium mb-2">Email Template</label>
            <Select
              value={selectedTemplate?.type || ''}
              onChange={(e) => handleTemplateChange(e.target.value)}
              options={EMAIL_TEMPLATES.map(t => ({ value: t.type, label: t.name }))}
            />
          </div>

          {selectedTemplate && (
            <>
              <div>
                <label className="block text-sm font-medium mb-2">Payload JSON</label>
                <textarea
                  value={payload}
                  onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setPayload(e.target.value)}
                  rows={15}
                  className="pa-input pa-textarea font-mono text-sm"
                />
              </div>

              <div className="flex gap-2">
                <Button onClick={generatePreview} disabled={isLoading}>
                  {isLoading ? (
                    <>
                      <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                      Generating...
                    </>
                  ) : (
                    <>
                      <Eye className="w-4 h-4 mr-2" />
                      Generate Preview
                    </>
                  )}
                </Button>

                <Button onClick={sendTestEmail} disabled={isSending} variant="secondary">
                  {isSending ? (
                    <>
                      <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                      Sending...
                    </>
                  ) : (
                    <>
                      <Send className="w-4 h-4 mr-2" />
                      Send Test Email
                    </>
                  )}
                </Button>
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {previewHtml && (
        <Card>
          <CardHeader>
            <CardTitle>Email Preview</CardTitle>
          </CardHeader>
          <CardContent>
            <div
              className="border rounded-lg p-4 bg-white"
              dangerouslySetInnerHTML={{ __html: previewHtml }}
            />
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import ReactQuill from 'react-quill-new';
import 'react-quill-new/dist/quill.snow.css';
import { toast } from 'react-hot-toast';
import { Save, Eye, AlertTriangle, XCircle } from 'lucide-react';

import { PageHeader, Card, Button, Input, Select, Badge, Switch } from '../../components/platformAdmin';
import { ConfirmDialog } from '../../components/admin/ConfirmDialog';
import { emailTemplatesService } from '../../data/services/emailTemplatesService';
import { EmailTemplate, EmailTemplateFormData, NotificationJobType } from '../../types/emailTemplates.types';
import { EmailTemplateVariables } from '../../components/platformAdmin/EmailTemplateVariables';
import EmailEditorErrorBoundary from '../../components/platformAdmin/EmailEditorErrorBoundary';
import { wrapEmailContent } from '../../utils/emailTemplateWrapper';

// Memoize ReactQuill to prevent unnecessary re-renders
const MemoizedReactQuill = React.memo(ReactQuill);

export default function EmailTemplateEditor() {
  const { slug } = useParams<{ slug: string }>();
  const isCreateMode = !slug; // If no slug, we are creating
  const navigate = useNavigate();
  const isMountedRef = useRef(true);

  const [template, setTemplate] = useState<EmailTemplate | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  
  // Form State
  const [name, setName] = useState('');
  const [newSlug, setNewSlug] = useState('');
  const [type, setType] = useState<NotificationJobType>('new_event');
  const [bodyContent, setBodyContent] = useState('');
  const [subjectTemplate, setSubjectTemplate] = useState('');
  const [previewText, setPreviewText] = useState('');
  const [description, setDescription] = useState('');
  
  // Preview State
  const [showPreview, setShowPreview] = useState(false);
  const [previewHtml, setPreviewHtml] = useState('');
  const [activeToggleDialog, setActiveToggleDialog] = useState<{
    open: boolean;
    checked: boolean;
    action: 'activate' | 'deactivate' | null;
    message: string;
  }>({ open: false, checked: false, action: null, message: '' });

  // Validation State
  const [syntaxErrors, setSyntaxErrors] = useState<string[]>([]);
  const [variableCollisions, setVariableCollisions] = useState<string[]>([]);

  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const loadTemplate = useCallback(async () => {
    if (!slug) return;
    try {
      setLoading(true);
      const data = await emailTemplatesService.getEmailTemplate(slug);
      if (isMountedRef.current) {
        setTemplate(data);
        setBodyContent(data.body_content || '');
        setSubjectTemplate(data.subject_template || '');
        setPreviewText(data.preview_text || '');
        setDescription(data.description || '');
      }
    } catch (error) {
      console.error('Failed to load template', error);
      toast.error('Failed to load template');
      navigate('/platform-admin/emails');
    } finally {
      if (isMountedRef.current) setLoading(false);
    }
  }, [slug, navigate]);

  useEffect(() => {
    if (isCreateMode) {
        setLoading(false);
        setTemplate({
            id: '', 
            slug: '', 
            name: '', 
            type: 'new_event', 
            html_content: '', 
            body_content: '', 
            subject_template: '', 
            variables: [], 
            required_variables: [], 
            is_active: false, 
            created_at: '', 
            updated_at: '' 
        });
    } else {
        loadTemplate();
    }
  }, [loadTemplate, isCreateMode]);

  // Handle body change
  const handleBodyChange = useCallback((value: string) => {
    if (isMountedRef.current) {
      setBodyContent(value);
      
      // Real-time validation (debounced could be better but this is simple)
      const syntaxCheck = emailTemplatesService.validateHandlebarsSyntax(value);
      setSyntaxErrors(syntaxCheck.errors);

      const vars = emailTemplatesService.extractVariablesFromHtml(value);
      const collisions = emailTemplatesService.checkVariableCollisions(vars);
      setVariableCollisions(collisions);
    }
  }, []);

  // Updates preview HTML
  useEffect(() => {
    try {
      const wrapped = wrapEmailContent(bodyContent);
      // Inject dummy variables for preview if needed, or just show raw
      // For now, just show the wrapped HTML.
      // We could try to inject dummy values for {{variables}} to make it look real.
      setPreviewHtml(wrapped);
    } catch (e) {
      // Ignore wrap errors during typing
    }
  }, [bodyContent]);

  const handleSave = async () => {
    if (!template || saving) return;

    // Client-side validation
    const syntaxCheck = emailTemplatesService.validateHandlebarsSyntax(bodyContent);
    if (!syntaxCheck.valid) {
      toast.error(`Syntax Error: ${syntaxCheck.errors.join(', ')}`);
      return;
    }
    
    // Check required variables
    const extractedVars = emailTemplatesService.extractVariablesFromHtml(bodyContent);
    const subjectVars = emailTemplatesService.extractVariablesFromHtml(subjectTemplate);
    const allVars = [...new Set([...extractedVars, ...subjectVars])];
    const missingRequired = (template.required_variables || []).filter(v => !allVars.includes(v));
    
    if (missingRequired.length > 0) {
      toast.error(`Missing required variables: ${missingRequired.join(', ')}`);
      return;
    }

    if (isCreateMode && (!name.trim() || !newSlug.trim())) {
        toast.error('Please provide a name and unique slug');
        return;
    }

    try {
      setSaving(true);
      const extractedVars = emailTemplatesService.extractVariablesFromHtml(bodyContent);
      const subjectVars = emailTemplatesService.extractVariablesFromHtml(subjectTemplate);
      const allVars = [...new Set([...extractedVars, ...subjectVars])];

      if (isCreateMode) {
          await emailTemplatesService.createEmailTemplate({
              name,
              slug: newSlug,
              type,
              body_content: emailTemplatesService.sanitizeHandlebarsContent(bodyContent), // Sanitize before saving
              subject_template: subjectTemplate,
              preview_text: previewText,
              description,
              variables: allVars
          });
          toast.success('Template created successfully');
          navigate('/platform-admin/emails');
      } else {
          const formData: EmailTemplateFormData = {
            body_content: emailTemplatesService.sanitizeHandlebarsContent(bodyContent), // Sanitize before saving
            subject_template: subjectTemplate,
            preview_text: previewText,
            description,
            variables: allVars
          };

          await emailTemplatesService.updateEmailTemplate(template.id, formData, template.updated_at);
          toast.success('Template saved successfully');
          loadTemplate();
      }
    } catch (error: any) {
      console.error('Failed to save', error);
      if (error.message.includes('Conflict') || error.message.includes('unique constraint')) {
        toast.error('Error: Duplicate slug or name conflict.');
      } else {
        toast.error('Failed to save template: ' + error.message);
      }
    } finally {
      if (isMountedRef.current) setSaving(false);
    }
  };

  const handleVariableSelect = (variableCode: string) => {
    // Insert variable at cursor position would be ideal, but for now copying to clipboard is safer/easier
    // or just appending if we can't control cursor easily with ReactQuill ref.
    // The component EmailTemplateVariables copies to clipboard.
    // We can show a toast.
    toast.success(`Copied ${variableCode} to clipboard`);
  };

  const handleConfirmToggleActive = async () => {
    if (isCreateMode || !template || !activeToggleDialog.action) return;

    const action = activeToggleDialog.action;
    const checked = activeToggleDialog.checked;
    setActiveToggleDialog({ open: false, checked: false, action: null, message: '' });

    try {
      await emailTemplatesService.toggleTemplateActive(template.id, checked);
      toast.success(`Template ${action}d`);
      loadTemplate();
    } catch (e) {
      toast.error(`Failed to ${action} template`);
    }
  };

  const quillModules = useMemo(() => ({
    toolbar: [
      [{ 'header': [1, 2, 3, false] }],
      ['bold', 'italic', 'underline', 'strike'],
      [{ 'list': 'ordered'}, { 'list': 'bullet' }],
      [{ 'color': [] }, { 'background': [] }],
      ['link', 'image'],
      ['clean'],
      ['code-block'] // Useful for checking HTML
    ],
  }), []);

  if (loading) return <div className="pa-p-8 pa-text-center">Loading template...</div>;
  if (!template) return <div className="pa-p-8 pa-text-center">Template not found</div>;

  return (
    <div className="pa-max-w-7xl pa-mx-auto">
       <PageHeader
        title={isCreateMode ? 'Create New Template' : template.name}
        subtitle={isCreateMode ? 'Define a new email template' : `Editing ${template.slug}`}
        actions={
          <div className="pa-flex pa-gap-2">
            <Button variant="ghost" onClick={() => setShowPreview(!showPreview)}>
              {showPreview ? <><Eye className="pa-mr-2" size={18} /> Hide Preview</> : <><Eye className="pa-mr-2" size={18} /> Show Preview</>}
            </Button>
            <Button variant="primary" onClick={handleSave} disabled={saving || syntaxErrors.length > 0}>
              {saving ? 'Saving...' : <><Save className="pa-mr-2" size={18} /> Save Changes</>}
            </Button>
          </div>
        }
      />

      <div className="pa-grid pa-grid-cols-1 lg:pa-grid-cols-3 pa-gap-6">
        {/* Main Editor Column */}
        <div className="lg:pa-col-span-2 pa-space-y-6">
          <Card className="pa-p-6">
            <div className="pa-space-y-4">
              <div>
                <label className="pa-block pa-text-sm pa-font-medium pa-text-gray-700 pa-mb-1">Subject Line</label>
                <Input 
                  value={subjectTemplate} 
                  onChange={(e) => setSubjectTemplate(e.target.value)} 
                  placeholder="Subject line (supports {{variables}})"
                />
              </div>

              {isCreateMode && (
                  <>
                    <div>
                        <label className="pa-block pa-text-sm pa-font-medium pa-text-gray-700 pa-mb-1">Template Name</label>
                        <Input 
                            value={name} 
                            onChange={(e) => {
                                setName(e.target.value);
                                if (!newSlug && isCreateMode) {
                                    setNewSlug(e.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''));
                                }
                            }} 
                            placeholder="e.g. Monthly Newsletter v2"
                        />
                    </div>
                    <div>
                        <label className="pa-block pa-text-sm pa-font-medium pa-text-gray-700 pa-mb-1">Slug (Unique ID)</label>
                        <Input 
                            value={newSlug} 
                            onChange={(e) => setNewSlug(e.target.value)} 
                            placeholder="e.g. monthly-newsletter-v2"
                        />
                    </div>
                  </>
              )}
              
              <div>
                <label className="pa-block pa-text-sm pa-font-medium pa-text-gray-700 pa-mb-1">Preview Text (Optional)</label>
                <Input 
                  value={previewText} 
                  onChange={(e) => setPreviewText(e.target.value)} 
                  placeholder="Text shown in email client preview"
                />
              </div>

               <div>
                <label className="pa-block pa-text-sm pa-font-medium pa-text-gray-700 pa-mb-1">Description</label>
                <Input 
                  value={description} 
                  onChange={(e) => setDescription(e.target.value)} 
                  placeholder="Internal description"
                />
              </div>
            </div>
          </Card>

          <Card className="pa-p-6 pa-min-h-[500px] pa-flex pa-flex-col">
            <label className="pa-block pa-text-sm pa-font-medium pa-text-gray-700 pa-mb-2">Email Body Content</label>
            
            {syntaxErrors.length > 0 && (
              <div className="pa-mb-4 pa-p-3 pa-bg-red-50 pa-text-red-700 pa-rounded pa-text-sm pa-flex pa-items-start pa-gap-2">
                <XCircle size={16} className="pa-mt-0.5" />
                <div>
                  <strong>Syntax Error:</strong>
                  <ul className="pa-list-disc pa-pl-4 pa-mt-1">
                    {syntaxErrors.map((err, i) => <li key={i}>{err}</li>)}
                  </ul>
                </div>
              </div>
            )}

            {variableCollisions.length > 0 && (
              <div className="pa-mb-4 pa-p-3 pa-bg-yellow-50 pa-text-yellow-800 pa-rounded pa-text-sm pa-flex pa-items-start pa-gap-2">
                <AlertTriangle size={16} className="pa-mt-0.5" />
                <div>
                  <strong>Warning: Variable Collision</strong>
                  <p>The following variables conflict with universal template variables: {variableCollisions.join(', ')}</p>
                </div>
              </div>
            )}

            <div className="email-template-editor pa-flex-1">
              <EmailEditorErrorBoundary>
                <MemoizedReactQuill
                  theme="snow"
                  value={bodyContent}
                  onChange={handleBodyChange}
                  modules={quillModules}
                  placeholder="Edit email content here..."
                  className="pa-h-[400px]"
                />
              </EmailEditorErrorBoundary>
            </div>
          </Card>
        </div>

        {/* Sidebar Column */}
        <div className="pa-space-y-6">
          <Card className="pa-p-6">
            <h3 className="pa-text-lg pa-font-medium pa-mb-4">Details</h3>
            <div className="pa-space-y-3 pa-text-sm">
              <div className="pa-flex pa-justify-between pa-items-center">
                <span className="pa-text-gray-500">Type</span>
                {isCreateMode ? (
                    <Select
                        value={type}
                        onChange={(e) => setType(e.target.value as NotificationJobType)}
                        options={[
                            { value: 'new_event', label: 'New Event' },
                            { value: 'new_message', label: 'New Message' },
                            { value: 'payment_receipt', label: 'Payment Receipt' },
                            { value: 'event_reminder', label: 'Event Reminder' },
                            { value: 'registration_confirmation', label: 'Registration Confirmation' },
                            { value: 'team_invite', label: 'Team Invite' },
                            { value: 'password_reset', label: 'Password Reset' },
                            { value: 'welcome_email', label: 'Welcome Email' },
                            { value: 'guardian_invite', label: 'Guardian Invite' },
                            { value: 'ticket_receipt', label: 'Ticket Receipt' },
                            { value: 'uniform_notification', label: 'Uniform Notification' },
                            { value: 'travel_notification', label: 'Travel Notification' },
                            { value: 'photo_moderation', label: 'Photo Moderation' },
                            { value: 'rsvp_notification', label: 'RSVP Notification' }
                        ]}
                        className="pa-w-40 pa-text-sm"
                    />
                ) : (
                    <Badge variant="neutral">{template.type}</Badge>
                )}
              </div>
              <div className="pa-flex pa-justify-between">
                <span className="pa-text-gray-500">Slug</span>
                <code className="pa-bg-gray-100 pa-px-1 pa-rounded">{template.slug}</code>
              </div>
              <div className="pa-flex pa-justify-between">
                <span className="pa-text-gray-500">Last Updated</span>
                <span>{new Date(template.updated_at).toLocaleDateString()}</span>
              </div>
              <div className="pa-flex pa-justify-between pa-items-center pa-pt-2 pa-border-t pa-mt-2">
                 <span className="pa-text-gray-700 pa-font-medium">Active Status</span>
                 <Switch 
                    checked={template.is_active}
                    disabled={isCreateMode}
                    onCheckedChange={(checked) => {
                        if (isCreateMode) return;
                        
                        const action = checked ? 'activate' : 'deactivate';
                        const message = checked 
                            ? 'Are you sure you want to activate this template? ensuring it is ready for production use?'
                            : 'Deactivate this template? Emails will fallback to hardcoded defaults.';

                        setActiveToggleDialog({ open: true, checked, action, message });
                    }}
                 />
              </div>
              {isCreateMode && (
                  <p className="pa-text-xs pa-text-gray-400 pa-mt-1">
                      Save the template first to activate it.
                  </p>
              )}
            </div>
          </Card>

          <Card className="pa-p-6">
             <h3 className="pa-text-lg pa-font-medium pa-mb-4">Variables</h3>
             <EmailTemplateVariables 
               type={isCreateMode ? type : template.type} 
               onSelectVariable={handleVariableSelect} 
             />
          </Card>
        </div>
      </div>

      {/* Preview Modal / Drawer (Overlay) */}
      {showPreview && (
        <div className="pa-fixed pa-inset-0 pa-bg-black/50 pa-z-50 pa-flex pa-items-center pa-justify-center pa-p-4">
          <div className="pa-bg-white pa-rounded-lg pa-shadow-xl pa-w-full pa-max-w-4xl pa-h-[90vh] pa-flex pa-flex-col">
            <div className="pa-p-4 pa-border-b pa-flex pa-justify-between pa-items-center">
              <h3 className="pa-text-lg pa-font-bold">Email Preview</h3>
              <Button variant="ghost" onClick={() => setShowPreview(false)}>Close</Button>
            </div>
            <div className="pa-flex-1 pa-bg-gray-100 pa-p-8 pa-overflow-auto">
              <div className="pa-bg-white pa-rounded pa-shadow pa-mx-auto pa-max-w-[600px] pa-min-h-[500px]">
                 {/* Render HTML content inside an iframe to isolate styles */}
                 <iframe 
                   srcDoc={previewHtml}
                   title="preview"
                   className="pa-w-full pa-h-full pa-min-h-[600px] pa-border-0"
                 />
              </div>
            </div>
          </div>
        </div>
      )}

      <ConfirmDialog
        open={activeToggleDialog.open}
        title={activeToggleDialog.message}
        description={activeToggleDialog.message}
        confirmLabel={activeToggleDialog.action === 'activate' ? 'Activate' : 'Deactivate'}
        cancelLabel="Cancel"
        variant={activeToggleDialog.action === 'deactivate' ? 'danger' : 'primary'}
        onConfirm={() => { void handleConfirmToggleActive() }}
        onCancel={() => setActiveToggleDialog({ open: false, checked: false, action: null, message: '' })}
      />
    </div>
  );
}

import { useState, useEffect, useCallback, useRef, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { supabase } from '../../lib/supabase'
import { 
  PageHeader, 
  PlatformDataTable, 
  EnhancedFilterBar,
  BulkActionsToolbar,
  Button, 
  Badge, 
  Select,
  type ColumnConfig,
  DiscoveryStatusBadge,
  FeatureDependencyGraph,
  DiscoveryErrorBoundary,
  MultiStepProgressBar,
  Card,
  ApplyToTiersModal,
  ChangeStatusModal,
  ChangeVisibilityModal,
  UpdateCategoryModal,
  SetAsSystemFeatureModal,
  SetPlatformOnlyModal,
  OfflineBanner,
} from '../../components/platformAdmin'
import type { FeatureEntitlementWithCounts } from '../../types/licenseTiers.types'
import { FEATURE_CATEGORIES, FEATURE_TYPES } from '../../utils/licenseTierConstants'
import { discoverAndReconcile } from '../../utils/featureDiscovery/reconciler'
import type { DiscoveredFeature } from '../../utils/featureDiscovery/types'
import { 
  bulkUpdateStatus, 
  bulkUpdateCategory, 
  bulkApplyToTiers, 
  bulkUpdateRoleVisibility,
  bulkSetSystemFeature,
  bulkSetPlatformOnly
} from '../../data/services/featureBulkOperations'
import { showSuccess, showError, showInfo } from '../../utils/toast'
import type { FeatureCategory } from '../../types/licenseTiers.types'
import { useI18n } from '../../i18n/useI18n'
import { formatToastMessage, formatPlural } from '../../utils/toastMessages'

const CATEGORY_OPTIONS = [
  { value: '', label: 'All Categories' },
  ...FEATURE_CATEGORIES.map(cat => ({ value: cat, label: cat })),
]

const TYPE_OPTIONS = [
  { value: '', label: 'All Types' },
  ...FEATURE_TYPES.map(type => ({ value: type, label: type })),
]

// Helper to normalize array fields from database
function normalizeArrayField(value: unknown): string[] | null {
  if (value === null || value === undefined) return null
  if (Array.isArray(value)) return value
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value)
      return Array.isArray(parsed) ? parsed : null
    } catch {
      return null
    }
  }
  return null
}

import { useDebugLifecycle } from '../../lib/debug/integrations/useDebugLifecycle'

export default function FeatureCatalog() {
  useDebugLifecycle('FeatureCatalog')
  const navigate = useNavigate()
  const { t } = useI18n()
  
  // Data State
  const [features, setFeatures] = useState<FeatureEntitlementWithCounts[]>([])
  const [discoveredFeatures, setDiscoveredFeatures] = useState<DiscoveredFeature[]>([])
  const [availableTiers, setAvailableTiers] = useState<Array<{ id: string; tier_key: string; tier_name: string }>>([])
  const [loading, setLoading] = useState(true)
  const [discoveryLoading, setDiscoveryLoading] = useState(false)
  const [lastDiscoveredAt, setLastDiscoveredAt] = useState<string | null>(null)
  const [syncStatus, setSyncStatus] = useState<'pending' | 'synced' | 'failed' | null>(null)
  
  // Sync Progress State
  const [syncProgress, setSyncProgress] = useState({
    isActive: false,
    currentStep: 0,
    steps: [] as Array<{ label: string; status?: string }>,
    error: null as string | null,
  })

  // Enhanced Filter State
  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [categoryFilter, setCategoryFilter] = useState('')
  const [typeFilter, setTypeFilter] = useState('')
  const [statusFilter, setStatusFilter] = useState<string[]>([])
  const [tierFilter, setTierFilter] = useState<string[]>([])
  const [tierExclusiveMode, setTierExclusiveMode] = useState(false)
  const [roleFilter, setRoleFilter] = useState<string[]>([])
  const [roleExclusiveMode, setRoleExclusiveMode] = useState(false)
  const [integrationFilter, setIntegrationFilter] = useState<string[]>([])
  const [quantifiableFilter, setQuantifiableFilter] = useState<string | null>(null)
  const [sourceFilter, setSourceFilter] = useState<string | null>(null)
  const [systemFeatureFilter, setSystemFeatureFilter] = useState<'all' | 'yes' | 'no'>('all')
  const [platformAdminOnlyFilter, setPlatformAdminOnlyFilter] = useState<'all' | 'yes' | 'no'>('all')
  const [hierarchyFilter, setHierarchyFilter] = useState<'all' | 'parents' | 'children'>('all')

  // Pagination
  const [page, setPage] = useState(0)
  const [rowsPerPage, setRowsPerPage] = useState(50)
  const [totalCount, setTotalCount] = useState(0)

  // Selection State
  const [selectedFeatureIds, setSelectedFeatureIds] = useState<Set<string>>(new Set())
  const [selectAllMode, setSelectAllMode] = useState<'none' | 'page' | 'all'>('none')
  const prevFiltersRef = useRef<{ statusFilter: string[]; tierFilter: string[]; roleFilter: string[]; integrationFilter: string[]; quantifiableFilter: string | null; sourceFilter: string | null; systemFeatureFilter: 'all' | 'yes' | 'no'; platformAdminOnlyFilter: 'all' | 'yes' | 'no'; hierarchyFilter: 'all' | 'parents' | 'children' }>({ 
    statusFilter: [], 
    tierFilter: [], 
    roleFilter: [], 
    integrationFilter: [], 
    quantifiableFilter: null, 
    sourceFilter: null,
    systemFeatureFilter: 'all',
    platformAdminOnlyFilter: 'all',
    hierarchyFilter: 'all'
  })

  // Modal States
  const [showApplyToTiersModal, setShowApplyToTiersModal] = useState(false)
  const [showChangeStatusModal, setShowChangeStatusModal] = useState(false)
  const [showChangeVisibilityModal, setShowChangeVisibilityModal] = useState(false)
  const [showUpdateCategoryModal, setShowUpdateCategoryModal] = useState(false)
  const [showSetSystemFeatureModal, setShowSetSystemFeatureModal] = useState(false)
  const [showSetPlatformOnlyModal, setShowSetPlatformOnlyModal] = useState(false)
  const [bulkOperationLoading, setBulkOperationLoading] = useState(false)

  // Abort Controller for Race Conditions
  const abortControllerRef = useRef<AbortController | null>(null)
  const silentRefreshRef = useRef(false)
  const fetchRequestIdRef = useRef(0)

  // Fetch license tiers for filter
  const fetchTiers = useCallback(async () => {
    try {
      const { data, error } = await supabase
        .from('license_tiers')
        .select('id, tier_key, tier_name')
        .eq('status', 'active')
        .order('tier_key', { ascending: true })

      if (error) {
        console.error('Error fetching tiers:', error)
      } else {
        setAvailableTiers(data || [])
      }
    } catch (err) {
      console.error('Error fetching tiers:', err)
    }
  }, [])

  // Fetch features with enhanced filters
  const fetchFeatures = useCallback(async () => {
    fetchRequestIdRef.current += 1
    const currentRequestId = fetchRequestIdRef.current

    if (!silentRefreshRef.current) {
      setLoading(true)
    }
    try {
      let query = supabase
        .from('admin_feature_entitlements_list')
        .select('*', { count: 'exact' })
        .is('archived_at', null)

      // Search (use debounced value, require at least 2 characters for search)
      if (debouncedSearch && debouncedSearch.length >= 2) {
        query = query.or(`feature_key.ilike.%${debouncedSearch}%,display_name.ilike.%${debouncedSearch}%,description.ilike.%${debouncedSearch}%`)
      }

      // Category filter
      if (categoryFilter) {
        if (categoryFilter === 'Uncategorized') {
          query = query.or('category.is.null,category.eq.')
        } else {
          query = query.eq('category', categoryFilter)
        }
      }

      // Type filter
      if (typeFilter) {
        query = query.eq('feature_type', typeFilter as any)
      }

      // Status filter (map UI to DB values)
      if (statusFilter.length > 0) {
        const dbStatuses = statusFilter.map(s => {
          if (s === 'Live') return 'live'
          if (s === 'Disabled' || s === 'Deprecated') return 'hidden'
          if (s === 'Draft' || s === 'Review') return 'beta'
          return s
        })
        query = query.in('rollout_status', dbStatuses)
      }

      // License tier filter
      if (tierFilter.length > 0) {
        if (tierFilter.includes('unassigned')) {
          query = query.or('tier_assignments_count.is.null,tier_assignments_count.eq.0')
        } else if (tierExclusiveMode && tierFilter.length === 1) {
          // Exclusive mode: only features assigned to ONLY this one tier
          // Use cd (contained by) + cs (contains) to match exactly [tier]
          query = query
            .contains('assigned_tier_keys', [tierFilter[0]])
            .containedBy('assigned_tier_keys', [tierFilter[0]])
        } else {
          // Filter by tier keys - try overlaps operator
          try {
            query = query.overlaps('assigned_tier_keys', tierFilter)
          } catch (err) {
            // Fallback: if overlaps doesn't work, we'll need an RPC
            console.warn('Overlaps operator not supported, using alternative filter')
          }
        }
      }

      // Role visibility filter
      if (roleExclusiveMode && roleFilter.length === 1) {
        // Exclusive mode: only features visible to ONLY this role
        const role = roleFilter[0]
        if (role === 'orgAdmin') {
          query = query.eq('visible_to_admin', true).eq('visible_to_coach', false).eq('visible_to_parent', false)
        } else if (role === 'coach') {
          query = query.eq('visible_to_admin', false).eq('visible_to_coach', true).eq('visible_to_parent', false)
        } else if (role === 'guardian') {
          query = query.eq('visible_to_admin', false).eq('visible_to_coach', false).eq('visible_to_parent', true)
        }
      } else {
        // Inclusive mode: features visible to any of the selected roles
        if (roleFilter.includes('orgAdmin')) {
          query = query.eq('visible_to_admin', true)
        }
        if (roleFilter.includes('coach')) {
          query = query.eq('visible_to_coach', true)
        }
        if (roleFilter.includes('guardian')) {
          query = query.eq('visible_to_parent', true)
        }
      }

      // Integration filter
      if (integrationFilter.length > 0) {
        if (integrationFilter.includes('None')) {
          query = query.or('integrations.is.null,integrations.eq.{}')
        } else {
          try {
            query = query.overlaps('integrations', integrationFilter)
          } catch (err) {
            console.warn('Integration filter overlaps not supported')
          }
        }
      }

      // Quantifiable filter
      if (quantifiableFilter === 'has_limits') {
        query = query.eq('is_quantifiable', true)
      } else if (quantifiableFilter === 'unlimited') {
        query = query.eq('is_quantifiable', false)
      }

      // Source filter
      if (sourceFilter) {
        query = query.eq('discovery_source', sourceFilter)
      }

      // System feature filter
      if (systemFeatureFilter === 'yes') {
        query = query.eq('is_system_feature', true)
      } else if (systemFeatureFilter === 'no') {
        query = query.eq('is_system_feature', false)
      }

      // Platform admin only filter
      if (platformAdminOnlyFilter === 'yes') {
        query = query.eq('platform_admin_only', true)
      } else if (platformAdminOnlyFilter === 'no') {
        query = query.eq('platform_admin_only', false)
      }

      // Hierarchy filter
      if (hierarchyFilter === 'parents') {
        // Show only features that are parents (i.e., features that OTHER features point to as parent)
        // This means we need features whose feature_key appears in other features' parent_feature_key
        // For now, we can do a simple approach: exclude features that have no children
        // We'll need to check if there exists any feature with parent_feature_key = this feature_key
        // Since we can't easily do this in a single query, we'll just show non-null parent_feature_key is NOT the way
        // Actually for "parents" we want to show features that DO NOT have a parent (are root level) but might have children
        // Let's make this simpler: Parents = features with parent_feature_key IS NULL (root features)
        query = query.is('parent_feature_key', null)
      } else if (hierarchyFilter === 'children') {
        // Show only features that are children (have a parent)
        query = query.not('parent_feature_key', 'is', null)
      }

      query = query.order('category', { ascending: true }).order('display_name', { ascending: true })

      const from = page * rowsPerPage
      const to = from + rowsPerPage - 1
      query = query.range(from, to)

      const { data, error, count } = await query

      if (fetchRequestIdRef.current !== currentRequestId) {
        return
      }

      if (error) {
        console.error('Error fetching features:', error)
        setFeatures([])
        setTotalCount(0)
      } else {
        // Normalize array fields and set features
        const normalized = (data || []).map(row => ({
          ...row,
          assigned_tier_keys: normalizeArrayField(row.assigned_tier_keys) || [],
          integrations: normalizeArrayField(row.integrations) || [],
        })) as FeatureEntitlementWithCounts[]
        setFeatures(normalized)
        setTotalCount(count || 0)
      }
    } catch (err: any) {
      if (fetchRequestIdRef.current !== currentRequestId) {
        return
      }
      // Ignore timeout/cancellation errors from rapid typing
      if (err?.code === '57014' || err?.message?.includes('cancel')) {
        console.log('Query cancelled or timed out, likely due to new search')
        return
      }
      console.error('Error:', err)
      setFeatures([])
    } finally {
      if (fetchRequestIdRef.current === currentRequestId) {
        setLoading(false)
        silentRefreshRef.current = false
      }
    }
  }, [page, rowsPerPage, debouncedSearch, categoryFilter, typeFilter, statusFilter, tierFilter, roleFilter, integrationFilter, quantifiableFilter, sourceFilter, systemFeatureFilter, platformAdminOnlyFilter, tierExclusiveMode, roleExclusiveMode])

  // Silent refresh: re-fetches data without showing loading skeleton (preserves scroll/position)
  const silentRefresh = useCallback(async () => {
    silentRefreshRef.current = true
    await fetchFeatures()
  }, [fetchFeatures])

  // Debounce search input (400ms delay)
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search)
    }, 400)
    return () => clearTimeout(timer)
  }, [search])

  // Auto-filter selections when results change
  const prevSelectionCountRef = useRef(0)
  useEffect(() => {
    const currentIds = new Set(features.map(f => f.id))
    setSelectedFeatureIds(prev => {
      const filtered = new Set([...prev].filter(id => currentIds.has(id)))
      const afterCount = filtered.size
      
      // Track count change for filter notification
      prevSelectionCountRef.current = afterCount
      
      // Clear select-all mode if selections no longer match
      if (selectAllMode === 'page' && filtered.size !== features.length) {
        setSelectAllMode('none')
      }
      return filtered
    })
  }, [features, selectAllMode])

  // Track filter changes and notify user when selections are removed
  useEffect(() => {
    const filtersChanged = 
      JSON.stringify(prevFiltersRef.current.statusFilter) !== JSON.stringify(statusFilter) ||
      JSON.stringify(prevFiltersRef.current.tierFilter) !== JSON.stringify(tierFilter) ||
      JSON.stringify(prevFiltersRef.current.roleFilter) !== JSON.stringify(roleFilter) ||
      JSON.stringify(prevFiltersRef.current.integrationFilter) !== JSON.stringify(integrationFilter) ||
      prevFiltersRef.current.quantifiableFilter !== quantifiableFilter ||
      prevFiltersRef.current.sourceFilter !== sourceFilter ||
      prevFiltersRef.current.systemFeatureFilter !== systemFeatureFilter ||
      prevFiltersRef.current.platformAdminOnlyFilter !== platformAdminOnlyFilter

    if (filtersChanged) {
      const beforeCount = prevSelectionCountRef.current || selectedFeatureIds.size
      // The selection filtering effect will run after this, so we check in the next tick
      const timeoutId = setTimeout(() => {
        const afterCount = selectedFeatureIds.size
        if (beforeCount > afterCount && afterCount >= 0) {
          const removed = beforeCount - afterCount
          if (removed > 0) {
            showInfo(`${removed} selection${removed === 1 ? '' : 's'} removed (no longer match filters)`)
          }
        }
        prevSelectionCountRef.current = afterCount
      }, 150)
      
      return () => clearTimeout(timeoutId)
    }
    prevFiltersRef.current = {
      statusFilter,
      tierFilter,
      roleFilter,
      integrationFilter,
      quantifiableFilter,
      sourceFilter,
      systemFeatureFilter,
      platformAdminOnlyFilter,
      hierarchyFilter,
    }
  }, [statusFilter, tierFilter, roleFilter, integrationFilter, quantifiableFilter, sourceFilter, systemFeatureFilter, platformAdminOnlyFilter, hierarchyFilter, selectedFeatureIds.size])

  // Discovery Logic
  const runDiscovery = useCallback(async (force = false) => {
    if (abortControllerRef.current) abortControllerRef.current.abort()
    abortControllerRef.current = new AbortController()

    setDiscoveryLoading(true)
    try {
        const results = await discoverAndReconcile(force)
        setDiscoveredFeatures(results)
        
        const { data: cache } = await supabase.from('feature_discovery_cache').select('*').order('created_at', { ascending: false }).limit(1).single()
        if (cache) {
            setLastDiscoveredAt(cache.last_discovered_at)
            setSyncStatus(cache.sync_status as any)
        }
    } catch (err) {
        console.error('Discovery failed', err)
    } finally {
        setDiscoveryLoading(false)
    }
  }, [])

  const handleSync = async () => {
    const syncSteps = [
      { label: 'Validating features', status: 'Checking feature data...' },
      { label: 'Merging with existing features', status: 'Comparing discovered features...' },
      { label: 'Inserting new features', status: 'Adding new features to database...' },
      { label: 'Updating existing features', status: 'Updating feature metadata...' },
      { label: 'Updating tier assignments', status: 'Syncing license tier assignments...' },
      { label: 'Finalizing', status: 'Completing sync...' },
    ]
    
    setSyncProgress({
      isActive: true,
      currentStep: 0,
      steps: syncSteps,
      error: null,
    })
    setDiscoveryLoading(true)
    
    const updateProgress = (step: number, status?: string) => {
      setSyncProgress(prev => ({
        ...prev,
        currentStep: step,
        steps: prev.steps.map((s, i) => 
          i === step ? { ...s, status } : s
        ),
      }))
    }
    
    try {
      updateProgress(0, 'Validating feature data structure...')
      await new Promise(resolve => setTimeout(resolve, 300))
      
      if (discoveredFeatures.length === 0) {
        throw new Error('No features to sync. Run discovery first.')
      }
      
      updateProgress(1, `Processing ${discoveredFeatures.length} features...`)
      await new Promise(resolve => setTimeout(resolve, 400))
      
      updateProgress(2, 'Inserting new features...')
      await new Promise(resolve => setTimeout(resolve, 500))
      
      updateProgress(3, 'Updating existing features...')
      await new Promise(resolve => setTimeout(resolve, 500))
      
      updateProgress(4, 'Syncing tier assignments...')
      await new Promise(resolve => setTimeout(resolve, 400))
      
      updateProgress(5, 'Finalizing sync...')
      
      const featuresToSync = discoveredFeatures.map(f => ({
        featureKey: f.featureKey,
        displayName: f.displayName,
        category: f.category,
        featureType: f.featureType,
        description: f.description || null,
        rolloutStatus: f.syncStatus === 'synced' ? 'live' : 'live',
      }))
      
      const { data, error } = await supabase.rpc('sync_discovered_features', { 
        p_discovered_features: featuresToSync as any 
      })
      
      if (error) {
        throw new Error(`Sync failed: ${error.message || JSON.stringify(error)}`)
      }
      
      if (!data) {
        throw new Error('Sync returned no data')
      }
      
      const result = typeof data === 'string' ? JSON.parse(data) : data
      
      if (result && typeof result === 'object' && 'code' in result && result.code === 'LOCK_HELD') {
        throw new Error('Sync is already in progress by another process. Please wait.')
      }
      
      if (result && typeof result === 'object' && 'success' in result && !result.success) {
        throw new Error(result.message || 'Sync failed')
      }
      
      if (result && typeof result === 'object' && 'synced' in result) {
        console.log(`Sync completed: ${result.synced} synced, ${result.failed || 0} failed`)
      }
      
      const syncedCount = result?.synced || 0
      const failedCount = result?.failed || 0
      updateProgress(5, `Sync completed: ${syncedCount} synced, ${failedCount} failed`)
      await new Promise(resolve => setTimeout(resolve, 500))
      
      await new Promise(resolve => setTimeout(resolve, 500))
      await runDiscovery(false)
      
      setTimeout(() => {
        setSyncProgress({
          isActive: false,
          currentStep: 0,
          steps: [],
          error: null,
        })
      }, 1000)
      
    } catch (err: any) {
      console.error('Sync failed', err)
      const errorMessage = err?.message || 'Sync failed. Check console for details.'
      
      setSyncProgress(prev => ({
        ...prev,
        error: errorMessage,
      }))
      
      setTimeout(() => {
        setSyncProgress({
          isActive: false,
          currentStep: 0,
          steps: [],
          error: null,
        })
      }, 3000)
    } finally {
      setDiscoveryLoading(false)
    }
  }

  // Selection handlers
  const handleSelectionChange = useCallback((
    updater: Set<string> | ((prev: Set<string>) => Set<string>)
  ) => {
    if (typeof updater === 'function') {
      setSelectedFeatureIds(prev => updater(prev))
    } else {
      setSelectedFeatureIds(updater)
    }
    setSelectAllMode('none') // Clear mode on individual change
  }, [])

  const handleSelectAllChange = useCallback((mode: 'none' | 'page' | 'all') => {
    setSelectAllMode(mode)
    if (mode === 'page') {
      const pageIds = new Set(features.map(f => f.id))
      setSelectedFeatureIds(prev => {
        const next = new Set(prev)
        pageIds.forEach(id => next.add(id))
        return next
      })
    } else if (mode === 'all') {
      // For "select all results", we'd need to fetch all IDs
      // For now, just select all on current page
      const pageIds = new Set(features.map(f => f.id))
      setSelectedFeatureIds(pageIds)
      setSelectAllMode('page')
    }
    // Note: Don't clear selections when mode is 'none' - that's handled by 
    // handleSelectAll in PlatformDataTable when user clicks the header checkbox
  }, [features])

  // Bulk operation handlers
  const selectedFeatures = useMemo(() => {
    return features.filter(f => selectedFeatureIds.has(f.id))
  }, [features, selectedFeatureIds])

  // Filter out locked features for bulk operations
  const getToggleableFeatures = useCallback((featureIds: string[]) => {
    return featureIds.filter(id => {
      const feature = features.find(f => f.id === id)
      return feature && feature.is_toggleable !== false
    })
  }, [features])

  const getLockedFeatures = useCallback((featureIds: string[]) => {
    return features.filter(f => 
      featureIds.includes(f.id) && 
      (f.is_toggleable === false || f.is_removable === false)
    )
  }, [features])

  const handleBulkApplyToTiers = async (tierIds: string[], action: 'add' | 'remove', roleVisibility: { admin: boolean; coach: boolean; parent: boolean }) => {
    setBulkOperationLoading(true)
    try {
      const featureIds = Array.from(selectedFeatureIds)
      // For remove action, filter out non-toggleable features
      const applicableIds = action === 'remove' 
        ? getToggleableFeatures(featureIds)
        : featureIds
      const lockedFeatures = action === 'remove' ? getLockedFeatures(featureIds) : []

      // Warn about locked features when removing
      if (action === 'remove' && lockedFeatures.length > 0) {
        const lockedNames = lockedFeatures.map(f => f.display_name).join(', ')
        showError(
          `${lockedFeatures.length} locked feature${lockedFeatures.length === 1 ? '' : 's'} cannot be removed: ${lockedNames}. ` +
          (lockedFeatures[0]?.lock_reason || 'These features are required for platform functionality.')
        )
      }

      if (action === 'remove' && applicableIds.length === 0) {
        showError(t('toast.error.noToggleableFeaturesForRemoval'))
        throw new Error('ALL_LOCKED')
      }

      const result = await bulkApplyToTiers(
        applicableIds,
        tierIds,
        action,
        roleVisibility
      )

      if (result.success) {
        showSuccess(`${result.processed || 0} feature${result.processed === 1 ? '' : 's'} ${action === 'add' ? 'added to' : 'removed from'} tier${tierIds.length === 1 ? '' : 's'}`)
        setShowApplyToTiersModal(false)
        setSelectedFeatureIds(new Set())
        setBulkOperationLoading(false)
        await silentRefresh()
      } else {
        if (result.code === 'FEATURE_LOCKED') {
          const lockedNames = result.locked_features?.map(f => f.display_name).join(', ') || 'locked features'
          showError(formatToastMessage(t('toast.error.lockedFeaturesCannotModify'), {
            count: result.locked_features?.length || 0,
            plural: formatPlural(result.locked_features?.length || 0),
            names: lockedNames
          }))
          throw new Error('FEATURE_LOCKED')
        } else if (result.code === 'LOCK_HELD') {
          showError('Another bulk operation is in progress. Please wait.')
          throw new Error('LOCK_HELD')
        } else {
          showError(result.error || 'Operation failed')
          throw new Error(result.error || 'Operation failed')
        }
      }
    } catch (err: any) {
      setBulkOperationLoading(false)
      if (err.message !== 'LOCK_HELD' && err.message !== 'Operation failed' && err.message !== 'FEATURE_LOCKED' && err.message !== 'ALL_LOCKED') {
        showError(err.message || t('toast.error.operationFailed'))
      }
      throw err // Re-throw to let modal handle it
    }
  }

  const handleBulkChangeStatus = async (status: 'Live' | 'Disabled' | 'Draft' | 'Deprecated' | 'Review') => {
    setBulkOperationLoading(true)
    try {
      const featureIds = Array.from(selectedFeatureIds)
      const toggleableIds = getToggleableFeatures(featureIds)
      const lockedFeatures = getLockedFeatures(featureIds)

      // Warn about locked features
      if (lockedFeatures.length > 0) {
        const lockedNames = lockedFeatures.map(f => f.display_name).join(', ')
        showError(
          `${lockedFeatures.length} locked feature${lockedFeatures.length === 1 ? '' : 's'} excluded: ${lockedNames}. ` +
          (lockedFeatures[0]?.lock_reason || 'These features cannot be modified.')
        )
      }

      if (toggleableIds.length === 0) {
        showError('No toggleable features selected. All selected features are locked.')
        setBulkOperationLoading(false)
        return
      }

      const result = await bulkUpdateStatus(
        toggleableIds,
        status,
        (_processed, _total) => {
          // Progress callback could update UI
        }
      )

      if (result.success) {
        showSuccess(`${result.updated || 0} feature${result.updated === 1 ? '' : 's'} status updated to ${status}`)
        setShowChangeStatusModal(false)
        await silentRefresh()
        setSelectedFeatureIds(new Set())
      } else {
        if (result.code === 'FEATURE_LOCKED') {
          const lockedNames = result.locked_features?.map(f => f.display_name).join(', ') || 'locked features'
          showError(`Cannot update locked features: ${lockedNames}`)
        } else if (result.code === 'LOCK_HELD') {
          showError('Another bulk operation is in progress. Please wait.')
        } else {
          showError(result.error || 'Operation failed')
        }
      }
    } catch (err: any) {
      showError(err.message || 'Operation failed')
    } finally {
      setBulkOperationLoading(false)
    }
  }

  const handleBulkChangeVisibility = async (roleType: 'admin' | 'coach' | 'parent', visible: boolean) => {
    setBulkOperationLoading(true)
    try {
      const featureIds = Array.from(selectedFeatureIds)
      // When hiding visibility, filter out non-toggleable features
      const applicableIds = visible === false 
        ? getToggleableFeatures(featureIds)
        : featureIds
      const lockedFeatures = visible === false ? getLockedFeatures(featureIds) : []

      // Warn about locked features when hiding
      if (visible === false && lockedFeatures.length > 0) {
        const lockedNames = lockedFeatures.map(f => f.display_name).join(', ')
        showError(
          `${lockedFeatures.length} locked feature${lockedFeatures.length === 1 ? '' : 's'} cannot be hidden: ${lockedNames}. ` +
          (lockedFeatures[0]?.lock_reason || 'These features are required for platform functionality.')
        )
      }

      if (visible === false && applicableIds.length === 0) {
        showError('No toggleable features selected. All selected features are locked and cannot have visibility hidden.')
        setBulkOperationLoading(false)
        return
      }

      const result = await bulkUpdateRoleVisibility(
        applicableIds,
        roleType,
        visible
      )

      if (result.success) {
        const roleName = roleType === 'admin' ? 'Org Admin' : roleType === 'coach' ? 'Coach' : 'Guardian'
        showSuccess(`${result.updated || 0} feature${result.updated === 1 ? '' : 's'} visibility updated for ${roleName}`)
        setShowChangeVisibilityModal(false)
        await silentRefresh()
        setSelectedFeatureIds(new Set())
      } else {
        if (result.code === 'FEATURE_LOCKED') {
          const lockedNames = result.locked_features?.map(f => f.display_name).join(', ') || 'locked features'
          showError(`Cannot hide visibility of locked features: ${lockedNames}`)
        } else {
          showError(result.error || 'Operation failed')
        }
      }
    } catch (err: any) {
      showError(err.message || 'Operation failed')
    } finally {
      setBulkOperationLoading(false)
    }
  }

  const handleBulkUpdateCategory = async (category: FeatureCategory) => {
    setBulkOperationLoading(true)
    try {
      const result = await bulkUpdateCategory(
        Array.from(selectedFeatureIds),
        category
      )

      if (result.success) {
        showSuccess(`${result.updated || 0} feature${result.updated === 1 ? '' : 's'} category updated to ${category}`)
        setShowUpdateCategoryModal(false)
        await silentRefresh()
        setSelectedFeatureIds(new Set())
      } else {
        showError(result.error || 'Operation failed')
      }
    } catch (err: any) {
      showError(err.message || 'Operation failed')
    } finally {
      setBulkOperationLoading(false)
    }
  }

  const handleBulkSetSystemFeature = async () => {
    setBulkOperationLoading(true)
    try {
      const result = await bulkSetSystemFeature(Array.from(selectedFeatureIds))

      if (result.success) {
        showSuccess(`${result.updated || 0} feature${result.updated === 1 ? '' : 's'} set as system feature`)
        setShowSetSystemFeatureModal(false)
        await silentRefresh()
        setSelectedFeatureIds(new Set())
      } else {
        showError(result.error || 'Operation failed')
      }
    } catch (err: any) {
      showError(err.message || 'Operation failed')
    } finally {
      setBulkOperationLoading(false)
    }
  }

  const handleBulkSetPlatformOnly = async () => {
    setBulkOperationLoading(true)
    try {
      const result = await bulkSetPlatformOnly(Array.from(selectedFeatureIds))

      if (result.success) {
        showSuccess(`${result.updated || 0} feature${result.updated === 1 ? '' : 's'} set to platform admin only`)
        setShowSetPlatformOnlyModal(false)
        await silentRefresh()
        setSelectedFeatureIds(new Set())
      } else {
        showError(result.error || 'Operation failed')
      }
    } catch (err: any) {
      showError(err.message || 'Operation failed')
    } finally {
      setBulkOperationLoading(false)
    }
  }

  const handleEnableAll = () => {
    // Enable all is safe - locked features are already enabled
    handleBulkChangeStatus('Live')
  }

  const handleDisableAll = () => {
    // Disable all will filter out locked features automatically
    handleBulkChangeStatus('Disabled')
  }

  const handleClearFilters = () => {
    setSearch('')
    setCategoryFilter('')
    setTypeFilter('')
    setStatusFilter([])
    setTierFilter([])
    setRoleFilter([])
    setIntegrationFilter([])
    setQuantifiableFilter(null)
    setSourceFilter(null)
    setSystemFeatureFilter('all')
    setPlatformAdminOnlyFilter('all')
    setHierarchyFilter('all')
  }

  // Reset to first page when any filter changes so results make sense
  useEffect(() => {
    setPage(0)
  }, [debouncedSearch, categoryFilter, typeFilter, statusFilter, tierFilter, roleFilter, integrationFilter, quantifiableFilter, sourceFilter, systemFeatureFilter, platformAdminOnlyFilter, hierarchyFilter])

  // Initial data fetch on mount
  // Initial mount: fetch tiers and run discovery once
  useEffect(() => {
    fetchTiers()
    runDiscovery(false)
    
    return () => {
        abortControllerRef.current?.abort()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []) // Only run on mount

  // Fetch features when filters change
  useEffect(() => {
    fetchFeatures()
  }, [fetchFeatures])

  // Cleanup AbortController on unmount
  useEffect(() => {
    return () => {
      if (abortControllerRef.current) {
        abortControllerRef.current.abort()
        abortControllerRef.current = null
      }
    }
  }, [])

  const rows = features.map(f => {
      const discovered = discoveredFeatures.find(df => df.featureKey === f.feature_key);
      return { ...f, discovered };
  });

  const columns: ColumnConfig<FeatureEntitlementWithCounts & { discovered?: DiscoveredFeature }>[] = [
    {
      id: 'display_name',
      label: 'Feature',
      sortable: true,
      render: (row) => (
        <div>
          <div className="pa-body-m" style={{ fontWeight: 600, display: 'flex', alignItems: 'center', gap: '8px' }}>
            {(row as any).parent_feature_key && (
              <span
                className="material-symbols-outlined"
                style={{
                  fontSize: '16px',
                  color: 'var(--pa-n500)',
                  cursor: 'help',
                }}
                title={`Child of ${(row as any).parent_feature_key}`}
              >
                subdirectory_arrow_right
              </span>
            )}
            {row.display_name}
            {(row.is_toggleable === false || row.is_removable === false) && (
              <span
                className="material-symbols-outlined"
                style={{
                  fontSize: '18px',
                  color: 'var(--pa-warning, #f59e0b)',
                  cursor: 'help',
                }}
                title={row.lock_reason || 'This feature is locked and cannot be modified'}
              >
                lock
              </span>
            )}
            {row.is_system_feature && (
              <Badge variant="info" size="small" title="Always available for all license tiers, including new tiers">
                System
              </Badge>
            )}
            {row.platform_admin_only && (
              <Badge variant="neutral" size="small" title="Not available to org users; platform admin only">
                Platform Admin
              </Badge>
            )}
            {row.discovered?.confidenceScore && row.discovered.confidenceScore < 70 && (
                <Badge variant="warning" size="small">Review</Badge>
            )}
            {row.integrations?.length ? (
                row.integrations.map((i: string) => <Badge key={i} variant="neutral" size="small">{i}</Badge>)
            ) : null}
          </div>
          <div className="pa-body-s" style={{ color: 'var(--pa-n500)', marginTop: '4px', fontFamily: 'var(--pa-font-mono)' }}>
            {row.feature_key}
          </div>
          <div style={{ display: 'flex', gap: '4px', marginTop: '4px' }}>
             {row.discovered?.discoveredFrom.includes('routes') && <span title="Discovered in Routes">🛣️</span>}
             {row.discovered?.discoveredFrom.includes('schema') && <span title="Discovered in DB Schema">💾</span>}
             {row.discovered?.discoveredFrom.includes('services') && <span title="Discovered in Services">⚙️</span>}
          </div>
        </div>
      ),
    },
    {
      id: 'category',
      label: 'Category',
      sortable: true,
      render: (row) => (
        <div className="pa-body-s" style={{ color: 'var(--pa-n500)' }}>
          {row.category}
        </div>
      ),
    },
    {
      id: 'feature_type',
      label: 'Type',
      render: (row) => (
        <Badge variant="neutral">{row.feature_type}</Badge>
      ),
    },
    {
      id: 'rollout_status',
      label: 'Status',
      render: (row) => {
        // Map DB status to UI status for display
        const statusMap: Record<string, string> = {
          'live': 'Live',
          'beta': row.rollout_status === 'beta' ? 'Draft' : 'Review',
          'hidden': 'Disabled',
        }
        const displayStatus = statusMap[row.rollout_status] || row.rollout_status
        return (
          <Badge variant={row.rollout_status === 'live' ? 'success' : row.rollout_status === 'beta' ? 'warning' : 'neutral'}>
            {displayStatus}
          </Badge>
        )
      },
    },
    {
      id: 'tier_assignments_count',
      label: 'Assignments',
      align: 'center',
      render: (row) => (
        <div className="pa-body-m">{row.tier_assignments_count}</div>
      ),
    },
    {
        id: 'updated_at',
        label: 'Updated',
        render: (row) => <div className="pa-body-s">{new Date(row.updated_at).toLocaleDateString()}</div>
    },
    {
      id: 'actions',
      label: 'Actions',
      align: 'right',
      render: (row) => (
        <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
          <Button
            variant="ghost"
            size="dense"
            onClick={() => navigate(`/platform-admin/licenses/features/${row.id}`)}
          >
            Edit
          </Button>
        </div>
      ),
    },
  ]

  return (
    <DiscoveryErrorBoundary>
        <div>
        <OfflineBanner />
        <PageHeader
            title="Feature Catalog"
            subtitle="Manage all platform features and entitlements"
            actions={
            <div style={{ display: 'flex', gap: '16px', alignItems: 'center' }}>
                <DiscoveryStatusBadge 
                    lastDiscoveredAt={lastDiscoveredAt}
                    syncStatus={syncStatus}
                    loading={discoveryLoading}
                    onRefresh={() => runDiscovery(true)}
                    onSync={handleSync}
                />
                <Button
                    variant="primary"
                    onClick={() => navigate('/platform-admin/licenses/features/new')}
                >
                    Manual Create
                </Button>
            </div>
            }
        />

        {/* Enhanced Filter Bar */}
        <EnhancedFilterBar
          searchValue={search}
          onSearchChange={setSearch}
          searchPlaceholder="Search features..."
          statusFilter={statusFilter}
          onStatusFilterChange={setStatusFilter}
          tierFilter={tierFilter}
          onTierFilterChange={setTierFilter}
          tierExclusiveMode={tierExclusiveMode}
          onTierExclusiveModeChange={setTierExclusiveMode}
          availableTiers={availableTiers}
          roleFilter={roleFilter}
          onRoleFilterChange={setRoleFilter}
          roleExclusiveMode={roleExclusiveMode}
          onRoleExclusiveModeChange={setRoleExclusiveMode}
          integrationFilter={integrationFilter}
          onIntegrationFilterChange={setIntegrationFilter}
          quantifiableFilter={quantifiableFilter}
          onQuantifiableFilterChange={setQuantifiableFilter}
          sourceFilter={sourceFilter}
          onSourceFilterChange={setSourceFilter}
          systemFeatureFilter={systemFeatureFilter}
          onSystemFeatureFilterChange={setSystemFeatureFilter}
          platformAdminOnlyFilter={platformAdminOnlyFilter}
          onPlatformAdminOnlyFilterChange={setPlatformAdminOnlyFilter}
          hierarchyFilter={hierarchyFilter}
          onHierarchyFilterChange={setHierarchyFilter}
          onClearAll={handleClearFilters}
        />

        {/* Category + Type filters */}
        <div style={{ display: 'flex', gap: 'var(--pa-space-3)', marginBottom: 'var(--pa-space-4)', flexWrap: 'wrap', alignItems: 'center' }}>
          <Select
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
            style={{ minWidth: '200px' }}
            options={CATEGORY_OPTIONS}
          />
          <Select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            style={{ minWidth: '150px' }}
            options={TYPE_OPTIONS}
          />
          <div className="pa-body-s" style={{ color: 'var(--pa-n500)', display: 'flex', flexDirection: 'column', gap: '2px' }}>
            <span>module = feature/capability</span>
            <span>permission = access right</span>
            <span>limit = numeric cap (e.g. max teams)</span>
            <span>visibility = who can see it</span>
            <span>integration = external service</span>
          </div>
        </div>

        {/* Bulk Actions Toolbar */}
        <BulkActionsToolbar
          selectedCount={selectedFeatureIds.size}
          totalCount={totalCount}
          onApplyToTiers={() => setShowApplyToTiersModal(true)}
          onChangeStatus={() => setShowChangeStatusModal(true)}
          onChangeVisibility={() => setShowChangeVisibilityModal(true)}
          onUpdateCategory={() => setShowUpdateCategoryModal(true)}
          onSetSystemFeature={() => setShowSetSystemFeatureModal(true)}
          onSetPlatformOnly={() => setShowSetPlatformOnlyModal(true)}
          onEnableAll={handleEnableAll}
          onDisableAll={handleDisableAll}
          onClearSelection={() => {
            setSelectedFeatureIds(new Set())
            setSelectAllMode('none')
          }}
          onSelectAllPage={() => handleSelectAllChange('page')}
          onSelectAllResults={() => handleSelectAllChange('all')}
          isSelectAllPage={selectAllMode === 'page'}
          isSelectAllResults={selectAllMode === 'all'}
        />

        {/* Locked Features Warning */}
        {selectedFeatureIds.size > 0 && (() => {
          const locked = getLockedFeatures(Array.from(selectedFeatureIds))
          if (locked.length > 0) {
            return (
              <div 
                className="pa-card pa-mb-4" 
                style={{ 
                  borderLeft: '3px solid var(--pa-warning)', 
                  background: 'var(--pa-warning-bg)',
                  padding: 'var(--pa-space-3)',
                }}
              >
                <div className="pa-flex pa-items-center pa-gap-2">
                  <span className="material-symbols-outlined" style={{ color: 'var(--pa-warning)' }}>lock</span>
                  <div>
                    <div className="pa-body-s" style={{ fontWeight: 600 }}>
                      {locked.length} locked feature{locked.length === 1 ? '' : 's'} in selection
                    </div>
                    <div className="pa-body-s" style={{ color: 'var(--pa-n700)', marginTop: 'var(--pa-space-1)' }}>
                      {locked.map(f => f.display_name).join(', ')} will be excluded from bulk operations.
                    </div>
                  </div>
                </div>
              </div>
            )
          }
          return null
        })()}

        {syncProgress.isActive && (
            <div style={{ marginBottom: '24px' }}>
                <Card title="Syncing Features">
                    <MultiStepProgressBar
                        currentStep={syncProgress.currentStep}
                        totalSteps={syncProgress.steps.length}
                        steps={syncProgress.steps}
                        error={syncProgress.error || undefined}
                    />
                </Card>
            </div>
        )}

        {discoveredFeatures.some(f => f.dependencyCycles?.length > 0) && (
            <div style={{ marginBottom: '24px' }}>
                <FeatureDependencyGraph features={discoveredFeatures} />
            </div>
        )}

        <PlatformDataTable
            columns={columns}
            rows={rows}
            loading={loading}
            emptyMessage="No features found. Try adjusting your filters or run feature discovery."
            page={page}
            rowsPerPage={rowsPerPage}
            totalCount={totalCount}
            onPageChange={setPage}
            onRowsPerPageChange={setRowsPerPage}
            selectable={true}
            selectedIds={selectedFeatureIds}
            onSelectionChange={handleSelectionChange}
            selectAllMode={selectAllMode}
            onSelectAllChange={handleSelectAllChange}
        />

        {/* Bulk Action Modals */}
        <ApplyToTiersModal
          open={showApplyToTiersModal}
          selectedFeatures={selectedFeatures}
          availableTiers={availableTiers}
          onConfirm={handleBulkApplyToTiers}
          onCancel={() => {
            setShowApplyToTiersModal(false)
            setBulkOperationLoading(false)
          }}
          loading={bulkOperationLoading}
        />

        <ChangeStatusModal
          open={showChangeStatusModal}
          selectedFeatures={selectedFeatures}
          onConfirm={handleBulkChangeStatus}
          onCancel={() => setShowChangeStatusModal(false)}
          loading={bulkOperationLoading}
        />

        <ChangeVisibilityModal
          open={showChangeVisibilityModal}
          selectedFeatures={selectedFeatures}
          onConfirm={handleBulkChangeVisibility}
          onCancel={() => setShowChangeVisibilityModal(false)}
          loading={bulkOperationLoading}
        />

        <UpdateCategoryModal
          open={showUpdateCategoryModal}
          selectedFeatures={selectedFeatures}
          onConfirm={handleBulkUpdateCategory}
          onCancel={() => setShowUpdateCategoryModal(false)}
          loading={bulkOperationLoading}
        />

        <SetAsSystemFeatureModal
          open={showSetSystemFeatureModal}
          selectedFeatures={selectedFeatures}
          onConfirm={handleBulkSetSystemFeature}
          onCancel={() => setShowSetSystemFeatureModal(false)}
          loading={bulkOperationLoading}
        />

        <SetPlatformOnlyModal
          open={showSetPlatformOnlyModal}
          selectedFeatures={selectedFeatures}
          onConfirm={handleBulkSetPlatformOnly}
          onCancel={() => setShowSetPlatformOnlyModal(false)}
          loading={bulkOperationLoading}
        />
        </div>
    </DiscoveryErrorBoundary>
  )
}

import { useState, useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { supabase } from '../../lib/supabase'
import type { SupabaseExtended as Database } from '../../lib/supabase.extended.types'
import { PageHeader, Card, Button, Input, Select, Checkbox, DatePicker, TimePicker, ConfirmDialog } from '../../components/platformAdmin'
import Badge from '../../components/platformAdmin/Badge'
import { EntitySelect } from '../../components/common/EntitySelect'
import { mapFeatureEntitlement } from '../../utils/domainMappers'
import type { FeatureEntitlement, CreateEntitlementOverrideRequest } from '../../types/licenseTiers.types'
import { validateFeatureDependencies, logAuditEvent } from '../../utils/licenseEntitlementsHelpers'
import { showSuccess, showError } from '../../utils/toast'
import { useOffline } from '../../hooks/useOffline'
import { useAuth } from '../../hooks/useAuth'
import { canPerformAction } from '../../utils/platformAdminPermissions'
import type { PlatformAdminRole } from '../../types/platformAdmin.types'

const SESSION_STORAGE_KEY = 'override_create_state'

export default function OverrideCreate() {
  const navigate = useNavigate()
  const { isOffline } = useOffline()
  const { profile } = useAuth()
  
  // Get admin role for permission checks (Issue 7)
  const adminRole = useMemo<PlatformAdminRole | null>(() => {
    return profile?.platformAdminRole ?? null
  }, [profile?.platformAdminRole])
  
  const canCreate = useMemo(() => {
    return adminRole ? canPerformAction(adminRole, 'manage_overrides') : false
  }, [adminRole])
  
  const [step, setStep] = useState(1)
  const [targetType, setTargetType] = useState<'organization' | 'user'>('organization')
  const [selectedTargetId, setSelectedTargetId] = useState<string | null>(null)
  const [selectedTargetOption, setSelectedTargetOption] = useState<{ id: string; name: string } | null>(null)
  const [features, setFeatures] = useState<FeatureEntitlement[]>([])
  const [featuresLoading, setFeaturesLoading] = useState(true)
  const [featuresError, setFeaturesError] = useState<string | null>(null)
  const [selectedFeatureId, setSelectedFeatureId] = useState('')
  const [overrideAction, setOverrideAction] = useState<'enable' | 'disable' | 'set_limit'>('enable')
  const [limitValue, setLimitValue] = useState<number | null>(null)
  const [roleAdmin, setRoleAdmin] = useState<boolean | null>(null)
  const [roleCoach, setRoleCoach] = useState<boolean | null>(null)
  const [roleParent, setRoleParent] = useState<boolean | null>(null)
  const [reason, setReason] = useState('')
  const [expiresAt, setExpiresAt] = useState('')
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [showViewOverrideDialog, setShowViewOverrideDialog] = useState(false)
  const [existingOverrideId, setExistingOverrideId] = useState<string | null>(null)

  // Restore form state from session storage (Issue 10)
  useEffect(() => {
    const saved = sessionStorage.getItem(SESSION_STORAGE_KEY)
    if (saved) {
      try {
        const state = JSON.parse(saved)
        if (state.step) setStep(state.step)
        if (state.targetType) setTargetType(state.targetType)
        if (state.selectedTargetId) setSelectedTargetId(state.selectedTargetId)
        if (state.selectedTargetName) {
          setSelectedTargetOption({ id: state.selectedTargetId, name: state.selectedTargetName })
        }
        if (state.selectedFeatureId) setSelectedFeatureId(state.selectedFeatureId)
        if (state.overrideAction) setOverrideAction(state.overrideAction)
        if (state.limitValue !== undefined) setLimitValue(state.limitValue)
        if (state.roleAdmin !== undefined) setRoleAdmin(state.roleAdmin)
        if (state.roleCoach !== undefined) setRoleCoach(state.roleCoach)
        if (state.roleParent !== undefined) setRoleParent(state.roleParent)
        if (state.reason) setReason(state.reason)
        if (state.expiresAt) setExpiresAt(state.expiresAt)
      } catch (err) {
        console.error('Failed to restore form state:', err)
        sessionStorage.removeItem(SESSION_STORAGE_KEY)
      }
    }
  }, [])

  // Save form state to session storage on changes (Issue 10)
  useEffect(() => {
    const state = {
      step,
      targetType,
      selectedTargetId,
      selectedTargetName: selectedTargetOption?.name,
      selectedFeatureId,
      overrideAction,
      limitValue,
      roleAdmin,
      roleCoach,
      roleParent,
      reason,
      expiresAt,
    }
    sessionStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(state))
  }, [step, targetType, selectedTargetId, selectedTargetOption, selectedFeatureId, overrideAction, limitValue, roleAdmin, roleCoach, roleParent, reason, expiresAt])

  useEffect(() => {
    fetchFeatures()
  }, [])

  const fetchFeatures = async () => {
    if (isOffline) {
      setFeaturesError('You appear to be offline. Please reconnect and try again.')
      setFeaturesLoading(false)
      return
    }

    setFeaturesLoading(true)
    setFeaturesError(null)

    try {
      const { data, error: featuresError } = await supabase
        .from('feature_entitlements')
        .select('*')
        .is('archived_at', null)
        .order('display_name', { ascending: true })

      if (featuresError) {
        throw featuresError
      }
      setFeatures((data || []).map(row => mapFeatureEntitlement(row)) as any)
      setFeaturesError(null)
    } catch (err: any) {
      console.error('Error fetching features:', err)
      setFeaturesError(err.message || 'Failed to load features. Please try again.')
    } finally {
      setFeaturesLoading(false)
    }
  }


  const handleSave = async () => {
    // Block if offline
    if (isOffline) {
      const errorMsg = 'You appear to be offline. Please reconnect and try again.'
      setError(errorMsg)
      showError(errorMsg)
      return
    }

    // Validation
    if (!selectedTargetId || !selectedFeatureId || !reason.trim()) {
      setError('Target, feature, and reason are required')
      return
    }

    // Validate limit value
    if (overrideAction === 'set_limit' && (limitValue === null || limitValue <= 0)) {
      setError('Limit value must be a positive integer')
      return
    }

    // Validate UUID format
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    if (!uuidRegex.test(selectedTargetId!)) {
      setError('Invalid target ID format')
      return
    }
    if (!uuidRegex.test(selectedFeatureId)) {
      setError('Invalid feature ID format')
      return
    }

    // Validate dependencies if enabling
    if (overrideAction === 'enable') {
      try {
        const validation = await validateFeatureDependencies(
          selectedTargetId,
          targetType,
          selectedFeatureId,
          overrideAction
        )

        if (!validation.valid && validation.missingDependencies) {
          setError(`Cannot enable feature: Missing required dependencies: ${validation.missingDependencies.join(', ')}`)
          return
        }
      } catch (err: any) {
        console.error('Error validating dependencies:', err)
        // Continue - dependency validation is best effort
      }
    }

    setSaving(true)
    setError(null)

    try {
      const override: CreateEntitlementOverrideRequest = {
        target_type: targetType,
        target_id: selectedTargetId!,
        feature_entitlement_id: selectedFeatureId,
        override_action: overrideAction,
        limit_value: overrideAction === 'set_limit' ? (limitValue && limitValue > 0 ? limitValue : null) : null,
        role_admin: overrideAction === 'enable' ? roleAdmin : null,
        role_coach: overrideAction === 'enable' ? roleCoach : null,
        role_parent: overrideAction === 'enable' ? roleParent : null,
        reason: reason.trim(),
        expires_at: expiresAt || undefined,
      }

      type OverrideInsert = Database['public']['Tables']['entitlement_overrides']['Insert']
      const overrideData = override as OverrideInsert
      const { data: createdOverride, error: createError } = await supabase
        .from('entitlement_overrides')
        .insert(overrideData)
        .select()
        .single()

      if (createError) throw createError

      // Log audit event
      if (createdOverride) {
        await logAuditEvent({
          action: 'create_entitlement_override',
          targetType: 'override',
          targetId: (createdOverride as any).id,
          afterState: createdOverride,
          reason: reason.trim(),
        })
      }

      // Clear session storage on success (Issue 10)
      sessionStorage.removeItem(SESSION_STORAGE_KEY)
      
      showSuccess('Override created successfully!')
      navigate('/platform-admin/licenses/overrides')
    } catch (err: any) {
      let errorMessage = 'Failed to create override'
      let existingOverrideId: string | null = null
      
      if (err.code === '23505') {
        // Duplicate override (Issue 4) - try to find existing override
        errorMessage = 'An override for this target and feature already exists.'
        
        // Try to find the existing override
        try {
          const { data: existing } = await supabase
            .from('admin_entitlement_overrides_list')
            .select('id')
            .eq('target_type', targetType)
            .eq('target_id', selectedTargetId)
            .eq('feature_entitlement_id', selectedFeatureId)
            .eq('override_action', overrideAction)
            .eq('status', 'active')
            .single()
          
          if (existing) {
            existingOverrideId = existing.id
            errorMessage = 'An override for this target and feature already exists. Would you like to view it?'
          }
        } catch (lookupErr) {
          // Ignore lookup errors
        }
      } else if (err.code === '23503') {
        errorMessage = 'Invalid target or feature. Please verify your selections.'
      } else if (err.code === '23502') {
        errorMessage = 'Missing required fields. Please check your input.'
      } else if (err.message) {
        errorMessage = err.message
      }
      
      setError(errorMessage)
      showError(errorMessage)
      
      // If we found an existing override, show dialog to view it
      if (existingOverrideId) {
        setTimeout(() => {
          setExistingOverrideId(existingOverrideId)
          setShowViewOverrideDialog(true)
        }, 100)
      }
    } finally {
      setSaving(false)
    }
  }

  const handleClearSavedProgress = () => {
    sessionStorage.removeItem(SESSION_STORAGE_KEY)
    setStep(1)
    setTargetType('organization')
    setSelectedTargetId(null)
    setSelectedTargetOption(null)
    setSelectedFeatureId('')
    setOverrideAction('enable')
    setLimitValue(null)
    setRoleAdmin(null)
    setRoleCoach(null)
    setRoleParent(null)
    setReason('')
    setExpiresAt('')
    showSuccess('Saved progress cleared')
  }

  const selectedFeature = features.find(f => f.id === selectedFeatureId)

  return (
    <div>
      {/* Offline indicator */}
      {isOffline && (
        <div
          className="pa-card pa-mb-4"
          style={{
            background: 'var(--pa-warning-bg)',
            border: '1px solid var(--pa-warning)',
            padding: 'var(--pa-space-3)',
          }}
        >
          <div className="pa-flex pa-items-center pa-gap-2">
            <span className="material-symbols-outlined" style={{ fontSize: '20px', color: 'var(--pa-warning)' }}>
              wifi_off
            </span>
            <span className="pa-body-s" style={{ color: 'var(--pa-n900)' }}>
              You appear to be offline. Please reconnect and try again.
            </span>
          </div>
        </div>
      )}

      <PageHeader
        title="Create Override"
        subtitle="Override entitlements for an organization or user"
        actions={
          <div style={{ display: 'flex', gap: 'var(--pa-space-3)' }}>
            <Button variant="blue" onClick={() => navigate('/platform-admin/licenses/overrides')}>
              Cancel
            </Button>
            {sessionStorage.getItem(SESSION_STORAGE_KEY) && (
              <Button variant="ghost" onClick={handleClearSavedProgress}>
                Clear Saved Progress
              </Button>
            )}
            {step === 4 && (
              <Button 
                variant="primary" 
                onClick={handleSave} 
                disabled={saving || isOffline || !canCreate}
                title={!canCreate ? 'You do not have permission to create overrides' : undefined}
              >
                {saving ? 'Creating...' : 'Create Override'}
              </Button>
            )}
          </div>
        }
      />

      {error && (
        <div className="pa-card pa-mb-4" style={{ borderLeft: '3px solid var(--pa-danger)', background: 'var(--pa-danger-bg)' }}>
          <div className="pa-flex pa-items-center pa-gap-2">
            <span className="material-symbols-outlined" style={{ color: 'var(--pa-danger)' }}>error</span>
            <span className="pa-body-m">{error}</span>
          </div>
        </div>
      )}

      {/* Step indicator */}
      <div className="pa-card pa-mb-5">
        <div className="pa-flex pa-items-center pa-gap-4">
          {[1, 2, 3, 4].map((s) => (
            <div key={s} className="pa-flex pa-items-center" style={{ flex: 1 }}>
              <div
                style={{
                  width: '32px',
                  height: '32px',
                  borderRadius: '50%',
                  background: step >= s ? 'var(--pa-n900)' : 'var(--pa-n200)',
                  color: step >= s ? 'var(--pa-white)' : 'var(--pa-n500)',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  fontWeight: 600,
                }}
              >
                {s}
              </div>
              {s < 4 && (
                <div
                  style={{
                    flex: 1,
                    height: '2px',
                    background: step > s ? 'var(--pa-n900)' : 'var(--pa-n200)',
                    margin: '0 var(--pa-space-2)',
                  }}
                />
              )}
            </div>
          ))}
        </div>
      </div>

      <Card>
        {/* Step 1: Choose target */}
        {step === 1 && (
          <div>
            <h3 className="pa-h3" style={{ marginBottom: 'var(--pa-space-4)' }}>Choose Target</h3>
            <div className="pa-form-group">
              <label className="pa-label">Target Type</label>
                <Select
                value={targetType}
                onChange={(e) => {
                  setTargetType(e.target.value as 'organization' | 'user')
                  setSelectedTargetId(null)
                  setSelectedTargetOption(null)
                }}
                options={[
                  { value: 'organization', label: 'Organization' },
                  { value: 'user', label: 'User' },
                ]}
              />
            </div>
            <EntitySelect
              label={`Search ${targetType === 'organization' ? 'Organization' : 'User'}`}
              value={selectedTargetId}
              onChange={(id, option) => {
                setSelectedTargetId(id)
                setSelectedTargetOption(option ? { id: option.id, name: option.label } : null)
              }}
              fetchOptions={async (query) => {
                if (isOffline) return []
                
                if (targetType === 'organization') {
                  const { data, error } = await supabase
                    .from('organizations')
                    .select('id, name')
                    .ilike('name', `%${query}%`)
                    .limit(20)
                  
                  if (error) throw error
                  return (data || []).map((org: any) => ({
                    id: org.id,
                    label: org.name,
                  }))
                } else {
                  const { data, error } = await supabase
                    .from('users')
                    .select('id, email, display_name')
                    .or(`email.ilike.%${query}%,display_name.ilike.%${query}%`)
                    .limit(20)
                  
                  if (error) throw error
                  return (data || []).map((user: any) => ({
                    id: user.id,
                    label: user.display_name || user.email || '',
                  }))
                }
              }}
              getOptionById={async (id) => {
                if (isOffline) return null
                
                if (targetType === 'organization') {
                  const { data, error } = await supabase
                    .from('organizations')
                    .select('id, name')
                    .eq('id', id)
                    .single()
                  
                  if (error || !data) return null
                  return { id: data.id, label: data.name }
                } else {
                  const { data, error } = await supabase
                    .from('users')
                    .select('id, email, display_name')
                    .eq('id', id)
                    .single()
                  
                  if (error || !data) return null
                  return {
                    id: data.id,
                    label: data.display_name || data.email || '',
                  }
                }
              }}
              placeholder={`Search ${targetType === 'organization' ? 'organizations' : 'users'}...`}
              disabled={isOffline}
              required
            />
            {selectedTargetOption && (
              <div className="pa-card" style={{ background: 'var(--pa-success-bg)', marginTop: 'var(--pa-space-3)' }}>
                <div className="pa-body-m">Selected: {selectedTargetOption.name}</div>
              </div>
            )}
            <div style={{ marginTop: 'var(--pa-space-5)' }}>
              <Button
                variant="primary"
                onClick={() => selectedTargetId && setStep(2)}
                disabled={!selectedTargetId}
              >
                Next: Select Feature
              </Button>
            </div>
          </div>
        )}

        {/* Step 2: Select feature */}
        {step === 2 && (
          <div>
            <h3 className="pa-h3" style={{ marginBottom: 'var(--pa-space-4)' }}>Select Feature</h3>
            {featuresLoading && (
              <div className="pa-card pa-mb-4" style={{ padding: 'var(--pa-space-4)', textAlign: 'center' }}>
                <div className="pa-body-m" style={{ color: 'var(--pa-n700)' }}>Loading features...</div>
              </div>
            )}
            {featuresError && (
              <div className="pa-card pa-mb-4" style={{ borderLeft: '3px solid var(--pa-danger)', background: 'var(--pa-danger-bg)', padding: 'var(--pa-space-3)' }}>
                <div className="pa-body-s" style={{ color: 'var(--pa-n900)' }}>{featuresError}</div>
                <Button variant="secondary" size="dense" onClick={fetchFeatures} style={{ marginTop: 'var(--pa-space-2)' }}>
                  Retry
                </Button>
              </div>
            )}
            <div className="pa-form-group">
              <label className="pa-label">Feature</label>
              <Select
                value={selectedFeatureId}
                onChange={(e) => setSelectedFeatureId(e.target.value)}
                disabled={featuresLoading || !!featuresError || isOffline}
                options={[
                  { value: '', label: featuresLoading ? 'Loading...' : 'Select a feature...' },
                  ...features.map(f => ({ value: f.id, label: `${f.display_name} (${f.category})` })),
                ]}
              />
            </div>
            {selectedFeature && (
              <div className="pa-card pa-mt-3" style={{ background: 'var(--pa-n50)' }}>
                <div className="pa-body-m" style={{ fontWeight: 600 }}>{selectedFeature.display_name}</div>
                <div className="pa-body-s" style={{ color: 'var(--pa-n500)', marginTop: '4px' }}>
                  {selectedFeature.description || 'No description'}
                </div>
                <div className="pa-flex pa-gap-2 pa-mt-2">
                  <Badge variant="neutral">{selectedFeature.feature_type}</Badge>
                  <Badge variant="info">{selectedFeature.category}</Badge>
                </div>
              </div>
            )}
            <div style={{ marginTop: 'var(--pa-space-5)', display: 'flex', gap: 'var(--pa-space-3)' }}>
              <Button variant="blue" onClick={() => setStep(1)}>
                Back
              </Button>
              <Button
                variant="primary"
                onClick={() => selectedFeatureId && setStep(3)}
                disabled={!selectedFeatureId}
              >
                Next: Configure Override
              </Button>
            </div>
          </div>
        )}

        {/* Step 3: Configure override */}
        {step === 3 && (
          <div>
            <h3 className="pa-h3" style={{ marginBottom: 'var(--pa-space-4)' }}>Configure Override</h3>
            <div className="pa-form-group">
              <label className="pa-label">Override Action</label>
              <Select
                value={overrideAction}
                onChange={(e) => setOverrideAction(e.target.value as any)}
                options={[
                  { value: 'enable', label: 'Enable' },
                  { value: 'disable', label: 'Disable' },
                  { value: 'set_limit', label: 'Set Limit' },
                ]}
              />
            </div>

            {overrideAction === 'set_limit' && (
              <div className="pa-form-group">
                <label className="pa-label">Limit Value</label>
                <Input
                  type="number"
                  value={limitValue || ''}
                  onChange={(e) => setLimitValue(e.target.value ? parseInt(e.target.value, 10) : null)}
                  placeholder="Enter limit"
                />
              </div>
            )}

            {overrideAction === 'enable' && selectedFeature?.feature_type === 'permission' && (
              <div className="pa-form-group">
                <label className="pa-label">Role Access</label>
                <div className="pa-flex pa-flex-col pa-gap-2">
                  <Checkbox
                    checked={roleAdmin ?? false}
                    onChange={(e) => setRoleAdmin(e.target.checked)}
                    label="Admin"
                  />
                  <Checkbox
                    checked={roleCoach ?? false}
                    onChange={(e) => setRoleCoach(e.target.checked)}
                    label="Coach"
                  />
                  <Checkbox
                    checked={roleParent ?? false}
                    onChange={(e) => setRoleParent(e.target.checked)}
                    label="Parent"
                  />
                </div>
              </div>
            )}

            <div style={{ marginTop: 'var(--pa-space-5)', display: 'flex', gap: 'var(--pa-space-3)' }}>
              <Button variant="blue" onClick={() => setStep(2)}>
                Back
              </Button>
              <Button variant="primary" onClick={() => setStep(4)}>
                Next: Review & Save
              </Button>
            </div>
          </div>
        )}

        {/* Step 4: Review and reason */}
        {step === 4 && (
          <div>
            <h3 className="pa-h3" style={{ marginBottom: 'var(--pa-space-4)' }}>Review & Save</h3>
            <div className="pa-card pa-mb-4" style={{ background: 'var(--pa-n50)' }}>
              <div className="pa-body-s" style={{ color: 'var(--pa-n500)', marginBottom: 'var(--pa-space-2)' }}>Target</div>
              <div className="pa-body-m" style={{ fontWeight: 600 }}>{selectedTargetOption?.name || 'Unknown'}</div>
              <div className="pa-body-s" style={{ color: 'var(--pa-n500)', marginTop: 'var(--pa-space-4)' }}>Feature</div>
              <div className="pa-body-m" style={{ fontWeight: 600 }}>{selectedFeature?.display_name}</div>
              <div className="pa-body-s" style={{ color: 'var(--pa-n500)', marginTop: 'var(--pa-space-4)' }}>Action</div>
              <div className="pa-body-m">{overrideAction}</div>
            </div>

            <div className="pa-form-group">
              <label className="pa-label pa-label--required">Reason</label>
              <textarea
                className="pa-input pa-textarea"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                placeholder="Explain why this override is needed..."
                rows={4}
              />
            </div>

            <div className="pa-form-group">
              <label className="pa-label">Expiration Date (Optional)</label>
              <div className="pa-form-grid pa-form-grid-2 pa-form-grid-tablet-2col">
                <DatePicker
                  value={expiresAt ? expiresAt.split('T')[0] : ''}
                  onChange={(date) => {
                    const time = expiresAt?.split('T')[1] || '23:59'
                    setExpiresAt(date ? `${date}T${time}` : '')
                  }}
                />
                <div className="pa-max-w-xs">
                  <TimePicker
                    value={expiresAt ? expiresAt.split('T')[1]?.substring(0, 5) || '' : ''}
                    onChange={(time) => {
                      const date = expiresAt?.split('T')[0] || new Date().toISOString().split('T')[0]
                      setExpiresAt(time ? `${date}T${time}` : '')
                    }}
                  />
                </div>
              </div>
            </div>

            <div style={{ marginTop: 'var(--pa-space-5)', display: 'flex', gap: 'var(--pa-space-3)' }}>
              <Button variant="blue" onClick={() => setStep(3)}>
                Back
              </Button>
              <Button variant="primary" onClick={handleSave} disabled={saving || !reason.trim()}>
                {saving ? 'Creating...' : 'Create Override'}
              </Button>
            </div>
          </div>
        )}
      </Card>

      {/* View Existing Override Dialog */}
      <ConfirmDialog
        open={showViewOverrideDialog}
        title="Existing Override Found"
        description="Would you like to view the existing override?"
        confirmLabel="View Override"
        cancelLabel="Cancel"
        variant="info"
        onConfirm={() => {
          if (existingOverrideId) {
            navigate(`/platform-admin/licenses/overrides/${existingOverrideId}`)
          }
          setShowViewOverrideDialog(false)
          setExistingOverrideId(null)
        }}
        onCancel={() => {
          setShowViewOverrideDialog(false)
          setExistingOverrideId(null)
        }}
      />
    </div>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { useT } from '../../i18n/useI18n'
import { supabase } from '../../lib/supabase'
import { Card, EmptyState, InlineNotice, PageHeader, StatCard, Table } from '../../components/platformAdmin'
import { formatFileSize, formatNumber } from '../../utils/formatters'

interface OrgUsageRow {
  id: string
  name: string
  bytesUsed: number
  photoCount: number
  galleryCount: number
  updatedAt: string | null
}

interface GalleryUsageRow {
  id: string
  name: string
  orgId: string | null
  orgName: string
  bytesUsed: number
  photoCount: number
}

interface UserUsageRow {
  id: string
  name: string
  email: string | null
  bytesUsed: number
  photoCount: number
}

const PAGE_SIZE = 100
const TOP_ROWS = 10

import { useDebugLifecycle } from '../../lib/debug/integrations/useDebugLifecycle'

export default function PhotosStorage() {
  useDebugLifecycle('PhotosStorage')
  const t = useT()
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [orgRows, setOrgRows] = useState<OrgUsageRow[]>([])
  const [galleryRows, setGalleryRows] = useState<GalleryUsageRow[]>([])
  const [userRows, setUserRows] = useState<UserUsageRow[]>([])
  const [totalBytes, setTotalBytes] = useState(0)
  const [totalPhotos, setTotalPhotos] = useState(0)
  const [totalGalleries, setTotalGalleries] = useState(0)
  const [totalOrgs, setTotalOrgs] = useState(0)
  const [lastUpdated, setLastUpdated] = useState<string | null>(null)
  const mountedRef = useRef(true)

  useEffect(() => {
    return () => {
      mountedRef.current = false
    }
  }, [])

  const loadStorage = useCallback(async () => {
    setLoading(true)
    setError(null)

    const orgMap = new Map<string, { name: string; bytesUsed: number; updatedAt: string | null }>()
    const orgPhotoCounts = new Map<string, number>()
    const orgGallerySets = new Map<string, Set<string>>()
    const orgBytesFromPhotos = new Map<string, number>()
    const galleryMap = new Map<string, GalleryUsageRow>()
    const userMap = new Map<string, UserUsageRow>()
    let latestUpdatedAt: string | null = null
    let photoTotal = 0

    try {
      let orgOffset = 0
      let orgHasMore = true

      while (orgHasMore) {
        const { data: usageData, error: usageError } = await supabase
          .from('org_storage_usage')
          .select('org_id, bytes_used, updated_at, org:organizations(name)')
          .eq('bucket_id', 'public-media')
          .range(orgOffset, orgOffset + PAGE_SIZE - 1)

        if (usageError && usageError.code !== 'PGRST116') {
          if (mountedRef.current) {
            setError(t('platformAdmin.photosStorage.loadError'))
          }
          break
        }

        ;(usageData || []).forEach((row: any) => {
          orgMap.set(row.org_id, {
            name: row.org?.name || t('common.unknown'),
            bytesUsed: Number(row.bytes_used || 0),
            updatedAt: row.updated_at || null,
          })
          if (row.updated_at && (!latestUpdatedAt || row.updated_at > latestUpdatedAt)) {
            latestUpdatedAt = row.updated_at
          }
        })

        const fetched = usageData?.length || 0
        orgOffset += PAGE_SIZE
        orgHasMore = fetched === PAGE_SIZE
        if (fetched === 0) break
      }

      let offset = 0
      let hasMore = true

      while (hasMore) {
        const { data, error: photosError } = await supabase
          .from('gallery_photos')
          .select('gallery_id, uploaded_by_user_id, size_bytes, gallery:galleries(id, name, org_id), uploader:users(id, first_name, last_name, email)')
          .order('created_at', { ascending: false })
          .range(offset, offset + PAGE_SIZE - 1)

        if (photosError) {
          if (mountedRef.current) {
            setError(t('platformAdmin.photosStorage.loadError'))
          }
          break
        }

        const rows = data || []
        if (rows.length === 0) break

        rows.forEach((row: any) => {
          const bytes = Number(row.size_bytes || 0)
          const galleryId = row.gallery?.id || row.gallery_id
          const orgId = row.gallery?.org_id || null
          const galleryName = row.gallery?.name || t('platformAdmin.photosStorage.unknownGallery')
          const uploaderId = row.uploader?.id || row.uploaded_by_user_id
          const uploaderName = [row.uploader?.first_name, row.uploader?.last_name]
            .filter(Boolean)
            .join(' ')
            .trim()
          const resolvedName = uploaderName || row.uploader?.email || t('common.unknown')

          photoTotal += 1

          if (orgId) {
            orgPhotoCounts.set(orgId, (orgPhotoCounts.get(orgId) || 0) + 1)
            orgBytesFromPhotos.set(orgId, (orgBytesFromPhotos.get(orgId) || 0) + bytes)
            if (!orgGallerySets.has(orgId)) {
              orgGallerySets.set(orgId, new Set())
            }
            if (galleryId) {
              orgGallerySets.get(orgId)?.add(galleryId)
            }
            if (!orgMap.has(orgId)) {
              orgMap.set(orgId, { name: t('common.unknown'), bytesUsed: 0, updatedAt: null })
            }
          }

          if (galleryId) {
            const existing = galleryMap.get(galleryId)
            if (existing) {
              existing.bytesUsed += bytes
              existing.photoCount += 1
            } else {
              galleryMap.set(galleryId, {
                id: galleryId,
                name: galleryName,
                orgId,
                orgName: orgId ? orgMap.get(orgId)?.name || t('common.unknown') : t('common.unknown'),
                bytesUsed: bytes,
                photoCount: 1,
              })
            }
          }

          if (uploaderId) {
            const existingUser = userMap.get(uploaderId)
            if (existingUser) {
              existingUser.bytesUsed += bytes
              existingUser.photoCount += 1
            } else {
              userMap.set(uploaderId, {
                id: uploaderId,
                name: resolvedName,
                email: row.uploader?.email || null,
                bytesUsed: bytes,
                photoCount: 1,
              })
            }
          }
        })

        offset += PAGE_SIZE
        hasMore = rows.length === PAGE_SIZE
      }

      const orgRowsResolved: OrgUsageRow[] = Array.from(orgMap.entries()).map(([id, org]) => {
        const photoCount = orgPhotoCounts.get(id) || 0
        const galleryCount = orgGallerySets.get(id)?.size || 0
        const bytesFromPhotos = orgBytesFromPhotos.get(id) || 0
        const bytesUsed = org.bytesUsed > 0 ? org.bytesUsed : bytesFromPhotos
        return {
          id,
          name: org.name,
          bytesUsed,
          photoCount,
          galleryCount,
          updatedAt: org.updatedAt,
        }
      })

      orgRowsResolved.sort((a, b) => b.bytesUsed - a.bytesUsed)

      const galleryRowsResolved = Array.from(galleryMap.values()).map((row) => ({
        ...row,
        orgName: row.orgId ? orgMap.get(row.orgId)?.name || t('common.unknown') : t('common.unknown'),
      }))
      galleryRowsResolved.sort((a, b) => b.bytesUsed - a.bytesUsed)

      const userRowsResolved = Array.from(userMap.values()).sort((a, b) => b.bytesUsed - a.bytesUsed)

      const bytesTotal = orgRowsResolved.reduce((sum, org) => sum + org.bytesUsed, 0)

      if (!mountedRef.current) return

      setOrgRows(orgRowsResolved)
      setGalleryRows(galleryRowsResolved)
      setUserRows(userRowsResolved)
      setTotalBytes(bytesTotal)
      setTotalPhotos(photoTotal)
      setTotalGalleries(galleryMap.size)
      setTotalOrgs(orgRowsResolved.length)
      setLastUpdated(latestUpdatedAt)
    } catch (err) {
      if (!mountedRef.current) return
      setError(t('platformAdmin.photosStorage.loadError'))
    } finally {
      if (mountedRef.current) {
        setLoading(false)
